INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-001', 'diydog', '001', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/001.json', 'Punk IPA 2007 - 2010', 'Post Modern Classic. Spiky. Tropical. Hoppy.', 'ipa', 6, 60, 1.056, 1.01, 17, 20, 'punk ipa 2007 - 2010 post modern classic. spiky. tropical. hoppy. ipa extra pale ahtanum chinook crystal chinook ahtanum chinook crystal motueka wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Punk IPA 2007 - 2010","style":"IPA","description":"Post Modern Classic. Spiky. Tropical. Hoppy.\n\nOur flagship beer that kick started the craft beer revolution. This is James and Martin''s original take on an American IPA, subverted with punchy New Zealand hops. Layered with new world hops to create an all-out riot of grapefruit, pineapple and lychee before a spiky, mouth-puckering bitter finish.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":73,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5.3}],"hops":[{"id":"h1","name":"Ahtanum","amountG":17.5,"use":"boil","timeMin":60},{"id":"h2","name":"Chinook","amountG":15,"use":"boil","timeMin":60},{"id":"h3","name":"Crystal","amountG":17.5,"use":"boil","timeMin":30},{"id":"h4","name":"Chinook","amountG":17.5,"use":"boil","timeMin":30},{"id":"h5","name":"Ahtanum","amountG":17.5,"use":"boil","timeMin":0},{"id":"h6","name":"Chinook","amountG":27.5,"use":"boil","timeMin":0},{"id":"h7","name":"Crystal","amountG":17.5,"use":"boil","timeMin":0},{"id":"h8","name":"Motueka","amountG":17.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.1}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id"