INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-026', 'diydog', '026', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/026.json', '5am Saint', 'Bittersweet Chaos. Malty. Fruity. Bite.', 'other', 5, 30, 1.05, 1.012, 60, 20, '5am saint bittersweet chaos. malty. fruity. bite. annet extra pale caramalt munich crystal 150 dark crystal cascade amarillo nelson sauvin amarillo nelson sauvin simcoe cascade ahtanum nelson sauvin centennial amarillo wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"5am Saint","description":"Bittersweet Chaos. Malty. Fruity. Bite.\n\nOut of order and stability comes the rush of the pack. Berry and caramel riding alongside marmalade and chocolate. Spice and toast jostle with lychee and biscuit. The needle flicks to all points of the compass. It drives you towards the horizon, towards the vanishing point. And it keeps going...","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":2.56},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.88},{"id":"f3","name":"Munich","type":"grain","amountKg":0.63},{"id":"f4","name":"Crystal 150","type":"grain","amountKg":0.38},{"id":"f5","name":"Dark Crystal","type":"grain","amountKg":0.13}],"hops":[{"id":"h1","name":"Cascade","amountG":2.5,"use":"boil","timeMin":60},{"id":"h2","name":"Amarillo","amountG":2.5,"use":"boil","timeMin":60},{"id":"h3","name":"Nelson Sauvin","amountG":2.5,"use":"boil","timeMin":30},{"id":"h4","name":"Amarillo","amountG":12.5,"use":"boil","timeMin":0},{"id":"h5","name":"Nelson Sauvin","amountG":12.5,"use":"boil","timeMin":0},{"id":"h6","name":"Simcoe","amountG":25,"use":"dry_hop"},{"id":"h7","name":"Cascade","amountG":50,"use":"dry_hop"},{"id":"h8","name":"Ahtanum","amountG":25,"use":"dry_hop"},{"id":"h9","name":"Nelson Sauvin","amountG":12.5,"use":"dry_hop"},{"id":"h10","name":"Centennial","amountG":50,"use":"dry_hop"},{"id":"h11","name":"Amarillo","amountG":25,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":76}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":62,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.05,"fg":1.012,"ibu":30,"abvPct":5,"colorEbc":60},"notes":"Bryggetips: Go easy on the crystal and dark crystal malt. Too much will skew the flavour profile away from lychees and citrus towards dried fruit.\n\nFørst brygget: 06/2009"}', '{"id":26,"name":"5am Saint","tagline":"Bittersweet Chaos. Malty. Fruity. Bite.","first_brewed":"06/2009","description":"Out of order and stability comes the rush of the pack. Berry and caramel riding alongside marmalade and chocolate. Spice and toast jostle with lychee and biscuit. The needle flicks to all points of the compass. It drives you towards the horizon, towards the vanishing point. And it keeps going...","image":"026.png","abv":5,"ibu":30,"target_fg":1012,"target_og":1050,"ebc":60,"srm":30.5,"ph":4.4,"attenuation_level":76,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":62,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":2.56,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.88,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.38,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.13,"unit":"kilograms"}}],"hops":[{"name":"Cascade","amount":{"value":2.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Amarillo","amount":{"value":2.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Nelson Sauvin","amount":{"value":2.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Amarillo","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Nelson Sauvin","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Simcoe","amount":{"value":25,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Cascade","amount":{"value":50,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Ahtanum","amount":{"value":25,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Nelson Sauvin","amount":{"value":12.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Centennial","amount":{"value":50,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Amarillo","amount":{"value":25,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Cheddar cheese melt on crisp rye toast","Moroccan chicken tangine","Cheesecake topped with kiwi"],"brewers_tips":"Go easy on the crystal and dark crystal malt. Too much will skew the flavour profile away from lychees and citrus towards dried fruit.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-027', 'diydog', '027', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/027.json', 'Tokyo Rising Sun - Highland', 'A Beautiful Accident.', 'other', 13.2, 85, 1.125, 1.023, 140, 20, 'tokyo rising sun - highland a beautiful accident. annet extra pale dark crystal chocolate roasted barley chinook galena chinook galena galena first gold chinook wlp099 - super high gravity ale', '{"schemaVersion":1,"name":"Tokyo Rising Sun - Highland","description":"A Beautiful Accident.\n\nA forgotten gem in the deepest, darkest corner of the warehouse. Aged in a Highland whisky cask resulting in a viscous slow motion roller coaster of powdered cacao, hints of burning pirate ships, salted caramel, sharp berries and toasted marshmallow.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":84,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":7.6},{"id":"f2","name":"Dark Crystal","type":"grain","amountKg":1.75},{"id":"f3","name":"Chocolate","type":"grain","amountKg":0.5},{"id":"f4","name":"Roasted Barley","type":"grain","amountKg":0.5}],"hops":[{"id":"h1","name":"Chinook","amountG":37.5,"use":"boil","timeMin":60},{"id":"h2","name":"Galena","amountG":37.5,"use":"boil","timeMin":60},{"id":"h3","name":"Chinook","amountG":37.5,"use":"boil","timeMin":60},{"id":"h4","name":"Galena","amountG":37.5,"use":"boil","timeMin":60},{"id":"h5","name":"Galena","amountG":25,"use":"boil","timeMin":0},{"id":"h6","name":"First Gold","amountG":25,"use":"boil","timeMin":0},{"id":"h7","name":"Chinook","amountG":25,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"WLP099 - Super High Gravity Ale","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.2}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatu