INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-035', 'diydog', '035', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/035.json', 'Movember', 'Moustache-Worthy Beer.', 'other', 4.5, 50, 1.047, 1.012, 140, 20, 'movember moustache-worthy beer. annet maris otter extra pale caramalt crystal 150 carafa special malt type 1 carafa special malt type 3 cascade cascade cascade wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Movember","description":"Moustache-Worthy Beer.\n\nA deliciously robust, black malted beer with a decadent dark, dry cocoa flavour that provides an enticing backdrop to the Cascade hops.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":65,"fermentables":[{"id":"f1","name":"Maris Otter Extra Pale","type":"grain","amountKg":3.44},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.63},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.31},{"id":"f4","name":"Carafa Special Malt Type 1","type":"grain","amountKg":0.31},{"id":"f5","name":"Carafa Special Malt Type 3","type":"grain","amountKg":0.31}],"hops":[{"id":"h1","name":"Cascade","amountG":43.8,"use":"boil","timeMin":60},{"id":"h2","name":"Cascade","amountG":81.3,"use":"boil","timeMin":0},{"id":"h3","name":"Cascade","amountG":250,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":74.5}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":68,"durationMin":50}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.047,"fg":1.012,"ibu":50,"abvPct":4.5,"colorEbc":140},"notes":"Bryggetips: If you can’t find really fresh cascade, substitute it for Amarillo or Ahtanum.\n\nFørst brygget: 11/2009"}', '{"id":35,"name":"Movember","tagline":"Moustache-Worthy Beer.","first_brewed":"11/2009","description":"A deliciously robust, black malted beer with a decadent dark, dry cocoa flavour that provides an enticing backdrop to the Cascade hops.","image":"035.png","abv":4.5,"ibu":50,"target_fg":1012,"target_og":1047,"ebc":140,"srm":70,"ph":5.2,"attenuation_level":74.5,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":68,"unit":"celsius"},"duration":50}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Maris Otter Extra Pale","amount":{"value":3.44,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":0.31,"unit":"kilograms"}}],"hops":[{"name":"Cascade","amount":{"value":43.8,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Cascade","amount":{"value":81.3,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Cascade","amount":{"value":250,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Vegetable egg scramble","Margherita pizza","Fresh berry crisp tart"],"brewers_tips":"If you can’t find really fresh cascade, substitute it for Amarillo or Ahtanum.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-036', 'diydog', '036', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/036.json', 'Black Dog', 'Hoppy Black Wheat Stout.', 'stout', 5.5, 60, 1.062, 1.02, 230, 20, 'black dog hoppy black wheat stout. stout og porter extra pale - spring blend caramalt crystal 150 chocolate roasted barley wheat malt columbus columbus simcoe chinook columbus simcoe chinook columbus simcoe chinook wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Black Dog","style":"Stout og porter","description":"Hoppy Black Wheat Stout.\n\nWe thought it would be great if Jeremy Moynier from Stone Brewing Co. brewed his own beer while he was here, with Jeremy deciding everything right down to the name! The result is a special 20HL batch of BlackDog, a 5.5% dark wheat stout with Columbus, Simcoe and Chinook and of course plenty of dry hopping action.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":60,"fermentables":[{"id":"f1","name":"Extra Pale - Spring Blend","type":"grain","amountKg":4.15},{"id":"f2","name":"Caramalt","type":"grain","amountKg":1.12},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.56},{"id":"f4","name":"Chocolate","type":"grain","amountKg":0.38},{"id":"f5","name":"Roasted Barley","type":"grain","amountKg":0.31},{"id":"f6","name":"Wheat Malt","type":"grain","amountKg":0.63}],"hops":[{"id":"h1","name":"Columbus","amountG":31.3,"use":"boil","timeMin":60},{"id":"h2","name":"Columbus","amountG":12.5,"use":"boil","timeMin":30},{"id":"h3","name":"Simcoe","amountG":12.5,"use":"boil","timeMin":30},{"id":"h4","name":"Chinook","amountG":12.5,"use":"boil","timeMin":30},{"id":"h5","name":"Columbus","amountG":25,"use":"boil","timeMin":0},{"id":"h6","name":"Simcoe","amountG":25,"use":"boil","timeMin":0},{"id":