INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-049', 'diydog', '049', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/049.json', 'Santa Paws', 'Christmas Scoth Ale.', 'amber', 4.5, 35, 1.048, 1.013, 44, 20, 'santa paws christmas scoth ale. amber, rød og brun extra pale munich dark crystal wheat flaked oats carafa special malt type 3 amber weyermann beech smoked first gold willamette hallertauer mittelfrüh wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Santa Paws","style":"Amber, rød og brun","description":"Christmas Scoth Ale.\n\nA 4.5% decadent scotch ale brewed with Scottish heather honey. A robust malty beer packed with flavour, at a strength you can drink all (Christmas) day long. Santa Paws is our antidote to the chaos of the festive season. All the flavours of Christmas pudding in liquid form.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":69,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":1.75},{"id":"f2","name":"Munich","type":"grain","amountKg":0.44},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.5},{"id":"f4","name":"Wheat","type":"grain","amountKg":0.56},{"id":"f5","name":"Flaked Oats","type":"grain","amountKg":0.56},{"id":"f6","name":"Carafa Special Malt Type 3","type":"grain","amountKg":0.13},{"id":"f7","name":"Amber","type":"grain","amountKg":0.25},{"id":"f8","name":"Weyermann Beech Smoked","type":"grain","amountKg":0.63}],"hops":[{"id":"h1","name":"First Gold","amountG":18.5,"use":"boil","timeMin":60},{"id":"h2","name":"Willamette","amountG":12.5,"use":"boil","timeMin":60},{"id":"h3","name":"Hallertauer Mittelfrüh","amountG":6.5,"use":"boil","timeMin":60}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":72.9}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":66,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.048,"fg":1.013,"ibu":35,"abvPct":4.5,"colorEbc":44},"notes":"Bryggetips: The addition of Weyermann Beech Smoked malt creates a beer with a delicate smoke character.\n\nFørst brygget: 10/2010"}', '{"id":49,"name":"Santa Paws","tagline":"Christmas Scoth Ale.","first_brewed":"10/2010","description":"A 4.5% decadent scotch ale brewed with Scottish heather honey. A robust malty beer packed with flavour, at a strength you can drink all (Christmas) day long. Santa Paws is our antidote to the chaos of the festive season. All the flavours of Christmas pudding in liquid form.","image":"049.png","abv":4.5,"ibu":35,"target_fg":1013,"target_og":1048,"ebc":44,"srm":22,"ph":4.4,"attenuation_level":72.9,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":66,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":1.75,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.44,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.56,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.56,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":0.13,"unit":"kilograms"}},{"name":"Amber","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Weyermann Beech Smoked","amount":{"value":0.63,"unit":"kilograms"}}],"hops":[{"name":"First Gold","amount":{"value":18.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Willamette","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Hallertauer Mittelfrüh","amount":{"value":6.5,"unit":"grams"},"add":"start","attribute":"bitter"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["French onion soup","Braised pheasant","Caramel sauce and hot fudge"],"brewers_tips":"The addition of Weyermann Beech Smoked malt creates a beer with a delicate smoke character.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-050', 'diydog', '050', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/050.json', 'AB:09', 'Cranachan Imperial Stout.', 'stout', 11.6, 77, 1.11, 1.022, 265, 20, 'ab:09 cranachan imperial stout. stout og porter maris otter extra pale carafa special malt type 1 flaked oats crystal 150 dark crystal 350-400 fuggles fuggles champagne', '{"schemaVersion":1,"name":"AB:09","style":"Stout og porter","description":"Cranachan Imperial Stout.\n\nThis Cranachan Imperial Stout was inspired by the famous Scottish dessert, and brewed with a mountain of dark malts, loads of oats, Scottish heather honey and local raspberries. The beer was then transferred to oak casks to mature for 6 months.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":49,"fermentables":[{"id":"f1","name":"Maris Otter Extra Pale","type":"grain","amountKg":10},{"id":"f2","name":"Carafa Special Malt Type 1","type":"grain","amountKg":1.88},{"id":"f3","name":"Flaked Oats","type":"grain","amountKg":1.88},{"id":"f4","name":"Crystal 150","type":"grain","amountKg":0.94},{"id":"f5","name":"Dark Crystal 350-400","type":"grain","amountKg":0.94}],"hops":[{"id":"h1","name":"Fuggles","amountG":125,"use":"boil","timeMin":60},{"id":"h2","name":"Fuggles","amountG":37.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Champagne","form":"other","amount":1,"unit":"pkg","attenuationPct":80}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":90}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.11,"fg":1.022,"ibu":77,"abvPct":11.6,"colorEbc":265},"notes":"Bryggetips: Lactose - or milk sugar - is un-fermentable. It adds a creamy mouthfeel to the beer. Experiment by using different types of honey for altered flavour profiles.\n\nTwist: Lactose: 125g, Scottish Heather Honey: 125g, Raspberries: 187.5g\n\nFørst brygget: 11/2010"}', '{"id":50,"name":"AB:09","tagline":"Cranachan Imperial Stout.","first_brewed":"11/2010","description":"This Cranachan Imperial Stout was inspired by the famous Scottish dessert, and brewed with a mountain of dark malts, loads of oats, Scottish heather honey and local raspberries. The beer was then transferred to oak casks to mature for 6 months.","image":"050.png","abv":11.6,"ibu":77,"target_fg":1022,"target_og":1110,"ebc":265,"srm":132.5,"ph":5.2,"attenuation_level":80,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":90}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Lactose: 125g, Scottish Heather Honey: 125g, Raspberries: 187.5g"},"ingredients":{"malt":[{"name":"Maris Otter Extra Pale","amount":{"value":10,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":1.88,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":1.88,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.94,"unit":"kilograms"}},{"name":"Dark Crystal 350-400","amount":{"value":0.94,"unit":"kilograms"}}],"hops":[{"name":"Fuggles","amount":{"value":125,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Fuggles","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Champagne"},"food_pairing":["Aged cheddar with honey and raspberry chutney","Rich beef stew with winter vegetables and a dash of honey","Scottish raspberry cranachan parfait"],"brewers_tips":"Lactose - or milk sugar - is un-fermentable. It adds a creamy mouthfeel to the beer. Experiment by using different types of honey for altered flavour profiles.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","15.6 kg malt til 20 L er urealistisk — trolig en feil i kilden."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-051', 'diydog', '051', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/051.json', 'Black Tokyo Horizon (w/ Nøgne Ø & Mikkeller)', 'Imperial Stout Collaboration.', 'stout', 17.2, 75, 1.156, 1.03, 128, 20, 'black tokyo horizon (w/ nøgne ø & mikkeller) imperial stout collaboration. stout og porter extra pale carafa special malt type 1 flaked oats smoked malt crystal 150 columbus columbus first gold motueka hersbrucker first gold motueka hersbrucker wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Black Tokyo Horizon (w/ Nøgne Ø & Mikkeller)","style":"Stout og porter","description":"Imperial Stout Collaboration.\n\nSpecial Collaboration between Nøgne, Mikkeller and BrewDog which is a recipe based on all three brewers’ big stouts; Nøgne Ø Dark Horizon, Mikkeller Black and BrewDog Tokyo*.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":4.38},{"id":"f2","name":"Carafa Special Malt Type 1","type":"grain","amountKg":1.5},{"id":"f3","name":"Flaked Oats","type":"grain","amountKg":0.56},{"id":"f4","name":"Smoked Malt","type":"grain","amountKg":0.25},{"id":"f5","name":"Crystal 150","type":"grain","amountKg":0.25}],"hops":[{"id":"h1","name":"Columbus","amountG":37.5,"use":"boil","timeMin":60},{"id":"h2","name":"Columbus","amountG":37.5,"use":"boil","timeMin":30},{"id":"h3","name":"First Gold","amountG":18.5,"use":"boil","timeMin":30},{"id":"h4","name":"Motueka","amountG":12.5,"use":"boil","timeMin":30},{"id":"h5","name":"Hersbrucker","amountG":12.5,"use":"boil","timeMin":30},{"id":"h6","name":"First Gold","amountG":18.5,"use":"boil","timeMin":0},{"id":"h7","name":"Motueka","amountG":12.5,"use":"boil","timeMin":0},{"id":"h8","name":"Hersbrucker","amountG":12.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":80.8}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":120}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.156,"fg":1.03,"ibu":75,"abvPct":17.2,"colorEbc":128},"notes":"Bryggetips: Extend the mash time as much as possible to create maximum fermentable sugars. Boil for longer in the kettle to help evaporate off the water, and make the sugar concentration stronger.\n\nFørst brygget: 12/2010"}', '{"id":51,"name":"Black Tokyo Horizon (w/ Nøgne Ø & Mikkeller)","tagline":"Imperial Stout Collaboration.","first_brewed":"12/2010","description":"Special Collaboration between Nøgne, Mikkeller and BrewDog which is a recipe based on all three brewers’ big stouts; Nøgne Ø Dark Horizon, Mikkeller Black and BrewDog Tokyo*.","image":"051.png","abv":17.2,"ibu":75,"target_fg":1030,"target_og":1156,"ebc":128,"srm":64,"ph":4.4,"attenuation_level":80.8,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":120}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":4.38,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":1.5,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.56,"unit":"kilograms"}},{"name":"Smoked Malt","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.25,"unit":"kilograms"}}],"hops":[{"name":"Columbus","amount":{"value":37.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Columbus","amount":{"value":37.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"First Gold","amount":{"value":18.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Motueka","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Hersbrucker","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"First Gold","amount":{"value":18.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Motueka","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Hersbrucker","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Truffle oil filet mignon","Sweet sticky beef brisket","Chocolate and dark cherry fondant"],"brewers_tips":"Extend the mash time as much as possible to create maximum fermentable sugars. Boil for longer in the kettle to help evaporate off the water, and make the sugar concentration stronger.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Malt og OG i kilden gir 155 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-052', 'diydog', '052', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/052.json', 'AB:05', 'Belgian Imperial Stout.', 'stout', 12.5, 40, 1.126, 1.03, 180, 20, 'ab:05 belgian imperial stout. stout og porter extra pale carafa special malt type 1 carafa special malt type 3 flaked oats pale crystal dark crystal first gold first gold wyeast 3522 - belgian ardennes™', '{"schemaVersion":1,"name":"AB:05","style":"Stout og porter","description":"Belgian Imperial Stout.\n\nBelgian Imperial Stout aged on toasted coconut and cacao. The Belgian yeast strain introduces a whole new dimension to the Imperial Stout style resulting in a beer that resembles a marshmallow toasted on a smouldering barbeque then smothered in dark chocolate. Massively seductive and encapsulating this blacker than midnight beer pours with coffee brown head so thick you could almost stand on it, and with an epic lacing on your glass.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":56,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":10},{"id":"f2","name":"Carafa Special Malt Type 1","type":"grain","amountKg":0.94},{"id":"f3","name":"Carafa Special Malt Type 3","type":"grain","amountKg":0.94},{"id":"f4","name":"Flaked Oats","type":"grain","amountKg":1.88},{"id":"f5","name":"Pale Crystal","type":"grain","amountKg":1.25},{"id":"f6","name":"Dark Crystal","type":"grain","amountKg":0.63}],"hops":[{"id":"h1","name":"First Gold","amountG":50,"use":"boil","timeMin":60},{"id":"h2","name":"First Gold","amountG":50,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 3522 - Belgian Ardennes™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":76}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":90}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.126,"fg":1.03,"ibu":40,"abvPct":12.5,"colorEbc":180},"notes":"Bryggetips: Add the coconut and cacao nibs after primary fermentation and let infuse for at least 6 months at a low temperature.\n\nTwist: Toasted coconut flakes: 75g, Cacao Nibs: 25g\n\nFørst brygget: 12/2010"}', '{"id":52,"name":"AB:05","tagline":"Belgian Imperial Stout.","first_brewed":"12/2010","description":"Belgian Imperial Stout aged on toasted coconut and cacao. The Belgian yeast strain introduces a whole new dimension to the Imperial Stout style resulting in a beer that resembles a marshmallow toasted on a smouldering barbeque then smothered in dark chocolate. Massively seductive and encapsulating this blacker than midnight beer pours with coffee brown head so thick you could almost stand on it, and with an epic lacing on your glass.","image":"052.png","abv":12.5,"ibu":40,"target_fg":1030,"target_og":1126,"ebc":180,"srm":90,"ph":4.4,"attenuation_level":76,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":90}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Toasted coconut flakes: 75g, Cacao Nibs: 25g"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":10,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":0.94,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":0.94,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":1.88,"unit":"kilograms"}},{"name":"Pale Crystal","amount":{"value":1.25,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.63,"unit":"kilograms"}}],"hops":[{"name":"First Gold","amount":{"value":50,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"First Gold","amount":{"value":50,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 3522 - Belgian Ardennes™"},"food_pairing":["Venison with cacao nibs","Apple upside-down cake","Toffee marshmallow pie"],"brewers_tips":"Add the coconut and cacao nibs after primary fermentation and let infuse for at least 6 months at a low temperature.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","15.6 kg malt til 20 L er urealistisk — trolig en feil i kilden."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-053', 'diydog', '053', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/053.json', 'Hello My Name Is Ingrid', 'Sophisticated Bergmanesque Beer.', 'ipa', 8.2, 42, 1.078, 1.013, 70, 20, 'hello my name is ingrid sophisticated bergmanesque beer. ipa maris otter extra pale caramalt columbus centennial columbus centennial nelson sauvin bramling cross/ first gold nz nelson sauvin bramling cross simcoe wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Hello My Name Is Ingrid","style":"IPA","description":"Sophisticated Bergmanesque Beer.\n\nA Double IPA with cloudberries added to the conditioning tank. One thing is certain – this Swedish inspired Double IPA is not as innocent as she first appears. A seductive body of rich malts and a buxom amount of Citra, Nelson Sauvin and Bramling Cross hops have been added to fresh Scandinavian cloudberries to deliver this beer’s tart finish.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":69,"fermentables":[{"id":"f1","name":"Maris Otter Extra Pale","type":"grain","amountKg":6.86},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.93}],"hops":[{"id":"h1","name":"Columbus","amountG":25,"use":"boil","timeMin":60},{"id":"h2","name":"Centennial","amountG":25,"use":"boil","timeMin":60},{"id":"h3","name":"Columbus","amountG":12.5,"use":"boil","timeMin":0},{"id":"h4","name":"Centennial","amountG":12.5,"use":"boil","timeMin":0},{"id":"h5","name":"Nelson Sauvin","amountG":25,"use":"boil","timeMin":0},{"id":"h6","name":"Bramling Cross/ First Gold","amountG":37.5,"use":"boil","timeMin":0},{"id":"h7","name":"NZ Nelson Sauvin","amountG":71.5,"use":"dry_hop"},{"id":"h8","name":"Bramling Cross","amountG":71.5,"use":"dry_hop"},{"id":"h9","name":"Simcoe","amountG":71.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83.3}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":22}],"targets":{"og":1.078,"fg":1.013,"ibu":42,"abvPct":8.2,"colorEbc":70},"notes":"Bryggetips: Add the cloudberries to your beer when racking the beer after primary fermentation. Grind them into a paste to allow maximum flavour extraction.\n\nTwist: Cloudberries: 1kg\n\nFørst brygget: 12/2010"}', '{"id":53,"name":"Hello My Name Is Ingrid","tagline":"Sophisticated Bergmanesque Beer.","first_brewed":"12/2010","description":"A Double IPA with cloudberries added to the conditioning tank. One thing is certain – this Swedish inspired Double IPA is not as innocent as she first appears. A seductive body of rich malts and a buxom amount of Citra, Nelson Sauvin and Bramling Cross hops have been added to fresh Scandinavian cloudberries to deliver this beer’s tart finish.","image":"053.png","abv":8.2,"ibu":42,"target_fg":1013,"target_og":1078,"ebc":70,"srm":35,"ph":4.4,"attenuation_level":83.3,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":22,"unit":"celsius"}},"twist":"Cloudberries: 1kg"},"ingredients":{"malt":[{"name":"Maris Otter Extra Pale","amount":{"value":6.86,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.93,"unit":"kilograms"}}],"hops":[{"name":"Columbus","amount":{"value":25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Centennial","amount":{"value":25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Columbus","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Centennial","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Nelson Sauvin","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Bramling Cross/ First Gold","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"NZ Nelson Sauvin","amount":{"value":71.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Bramling Cross","amount":{"value":71.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Simcoe","amount":{"value":71.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Crayfish with a chilli, coriander infused butter dip","Smörgås with cream topping","Cardamom cake with powder sugar and cloudberry jam"],"brewers_tips":"Add the cloudberries to your beer when racking the beer after primary fermentation. Grind them into a paste to allow maximum flavour extraction.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-054', 'diydog', '054', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/054.json', 'Bramling X', 'Single Hop IPA Series - 2011.', 'ipa', 7.5, 75, 1.068, 1.013, 22, 20, 'bramling x single hop ipa series - 2011. ipa extra pale crystal 150 caramalt bramling cross bramling cross wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Bramling X","style":"IPA","description":"Single Hop IPA Series - 2011.\n\nGood old Bramling Cross is elegant, refined, assured, (boring) and understated. Understated that is unless you hop the living daylights out of a beer with it. This is Bramling Cross re-invented and re-imagined, and shows just what can be done with English hops if you use enough of them. Poor Bramling Cross normally gets lost in a woeful stream of conformist brown ales made by sleepy cask ale brewers. But not anymore. This beer shows that British hops do have some soul, and is a fruity riot of blackberries, pears, and plums. Reminds me of the bramble, apple and ginger jam my grandmother used to make.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":70,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":6.38},{"id":"f2","name":"Crystal 150","type":"grain","amountKg":0.13},{"id":"f3","name":"Caramalt","type":"grain","amountKg":0.25}],"hops":[{"id":"h1","name":"Bramling Cross","amountG":60,"use":"boil","timeMin":60},{"id":"h2","name":"Bramling Cross","amountG":50,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":80.9}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.068,"fg":1.013,"ibu":75,"abvPct":7.5,"colorEbc":22},"notes":"Bryggetips: Getting good Bramling Cross is key. Most English hops are in leaf form (not pelletised), so getting fresh hops close to harvest (September) will give this beer the right amount of dark berry intensity.\n\nFørst brygget: 01/2011"}', '{"id":54,"name":"Bramling X","tagline":"Single Hop IPA Series - 2011.","first_brewed":"01/2011","description":"Good old Bramling Cross is elegant, refined, assured, (boring) and understated. Understated that is unless you hop the living daylights out of a beer with it. This is Bramling Cross re-invented and re-imagined, and shows just what can be done with English hops if you use enough of them. Poor Bramling Cross normally gets lost in a woeful stream of conformist brown ales made by sleepy cask ale brewers. But not anymore. This beer shows that British hops do have some soul, and is a fruity riot of blackberries, pears, and plums. Reminds me of the bramble, apple and ginger jam my grandmother used to make.","image":"054.png","abv":7.5,"ibu":75,"target_fg":1013,"target_og":1068,"ebc":22,"srm":11,"ph":4.4,"attenuation_level":80.9,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":6.38,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.13,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.25,"unit":"kilograms"}}],"hops":[{"name":"Bramling Cross","amount":{"value":60,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Bramling Cross","amount":{"value":50,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Warm blackberry pie","Vinegar doused fish and chips","Aromatic korma curry with lemon and garlic naan"],"brewers_tips":"Getting good Bramling Cross is key. Most English hops are in leaf form (not pelletised), so getting fresh hops close to harvest (September) will give this beer the right amount of dark berry intensity.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-055', 'diydog', '055', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/055.json', 'Citra', 'Single Hop IPA Series – 2011.', 'ipa', 7.5, 70, 1.068, 1.013, 30, 20, 'citra single hop ipa series – 2011. ipa extra pale crystal 150 caramalt citra citra citra wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Citra","style":"IPA","description":"Single Hop IPA Series – 2011.\n\nThe Pacific North West of America is home to the Citra hop. America is not just about cheer leaders, a silly version of football, elastic top jeans and cheeseburgers. They grow remarkable hops and Citra is a killer example of this, embodying all that is good about American hops and then some. Fearfully hard to resist, this beer is loaded with brash citrus, grapefruit, orange, hints of resinous pine and touches of blackcurrant. Devilishly moreish.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":70,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":6.38},{"id":"f2","name":"Crystal 150","type":"grain","amountKg":0.13},{"id":"f3","name":"Caramalt","type":"grain","amountKg":0.25}],"hops":[{"id":"h1","name":"Citra","amountG":2.5,"use":"boil","timeMin":60},{"id":"h2","name":"Citra","amountG":10,"use":"boil","timeMin":30},{"id":"h3","name":"Citra","amountG":37.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.1}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.068,"fg":1.013,"ibu":70,"abvPct":7.5,"colorEbc":30},"notes":"Bryggetips: Another hop to be treated with respect. Too much in the kettle or dry hop will turn the beer into a garlicky disaster.\n\nFørst brygget: 01/2011"}', '{"id":55,"name":"Citra","tagline":"Single Hop IPA Series – 2011.","first_brewed":"01/2011","description":"The Pacific North West of America is home to the Citra hop. America is not just about cheer leaders, a silly version of football, elastic top jeans and cheeseburgers. They grow remarkable hops and Citra is a killer example of this, embodying all that is good about American hops and then some. Fearfully hard to resist, this beer is loaded with brash citrus, grapefruit, orange, hints of resinous pine and touches of blackcurrant. Devilishly moreish.","image":"055.png","abv":7.5,"ibu":70,"target_fg":1013,"target_og":1068,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":82.1,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":6.38,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.13,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.25,"unit":"kilograms"}}],"hops":[{"name":"Citra","amount":{"value":2.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Citra","amount":{"value":10,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Citra","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Lemon and herb salmon","Sharp cheddar with mango chutney","Shredded chicken tacos with pico de gallo"],"brewers_tips":"Another hop to be treated with respect. Too much in the kettle or dry hop will turn the beer into a garlicky disaster.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-056', 'diydog', '056', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/056.json', 'Nelson Sauvin', 'Single Hop IPA Series – 2011.', 'ipa', 7.5, 75, 1.068, 1.013, 30, 20, 'nelson sauvin single hop ipa series – 2011. ipa extra pale crystal 150 caramalt nelson sauvin nelson sauvin wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Nelson Sauvin","style":"IPA","description":"Single Hop IPA Series – 2011.\n\nNelson is a love it or hate it kinda hop. We are cool with that, if we wanted to keep everyone happy we would be brewing Fosters anyway. Sharp as a razor, this New Zealand hop slices its way through your taste buds and is brutally resinous, almost scraping the intense flavours of passion fruit along your poor tongue. There is a huge depth of tropical fruit flavour with astringent gooseberry balanced against the robust malt base. Throw another shrimp on the barbie mate and you are all set. New Zealand is near Austria, right?","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":70,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":6.38},{"id":"f2","name":"Crystal 150","type":"grain","amountKg":0.13},{"id":"f3","name":"Caramalt","type":"grain","amountKg":0.25}],"hops":[{"id":"h1","name":"Nelson Sauvin","amountG":37.5,"use":"boil","timeMin":60},{"id":"h2","name":"Nelson Sauvin","amountG":50,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.1}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.068,"fg":1.013,"ibu":75,"abvPct":7.5,"colorEbc":30},"notes":"Bryggetips: Nelson is an amazing hop in the correct proportions. Too much and the beer will start to taste like onions and garlic.\n\nFørst brygget: 01/2011"}', '{"id":56,"name":"Nelson Sauvin","tagline":"Single Hop IPA Series – 2011.","first_brewed":"01/2011","description":"Nelson is a love it or hate it kinda hop. We are cool with that, if we wanted to keep everyone happy we would be brewing Fosters anyway. Sharp as a razor, this New Zealand hop slices its way through your taste buds and is brutally resinous, almost scraping the intense flavours of passion fruit along your poor tongue. There is a huge depth of tropical fruit flavour with astringent gooseberry balanced against the robust malt base. Throw another shrimp on the barbie mate and you are all set. New Zealand is near Austria, right?","image":"056.png","abv":7.5,"ibu":75,"target_fg":1013,"target_og":1068,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":82.1,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":6.38,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.13,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.25,"unit":"kilograms"}}],"hops":[{"name":"Nelson Sauvin","amount":{"value":37.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Nelson Sauvin","amount":{"value":50,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Grilled halloumi salad with orange and pomegranate vinaigrette","Baked Camembert with smoked garlic, and salt and pepper wheat crackers","Crab cakes with lemon cream and herb dipping sauce"],"brewers_tips":"Nelson is an amazing hop in the correct proportions. Too much and the beer will start to taste like onions and garlic.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-057', 'diydog', '057', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/057.json', 'Sorachi Ace', 'Single Hop IPA Series - 2011.', 'ipa', 7.5, 75, 1.068, 1.013, 30, 20, 'sorachi ace single hop ipa series - 2011. ipa extra pale crystal 150 caramalt sorachi ace sorachi ace wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Sorachi Ace","style":"IPA","description":"Single Hop IPA Series - 2011.\n\nA hop that tastes of bubble gum? Seriously? No, we did not believe it either. But it does! This is one unique, son of a bitch of a hop. Lemony, deep, musty with a smoothness that belies its power. This hop is lemony like a lemon who was angry earlier but is now tired because of all the rage. This hop of Japanese origin is best enjoyed trying to make sushi from your gold fish, or trying to persuade your girlfriend (or boyfriend maybe) to dress up as a Geisha for Valentine’s Day.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":70,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":6.38},{"id":"f2","name":"Crystal 150","type":"grain","amountKg":0.13},{"id":"f3","name":"Caramalt","type":"grain","amountKg":0.25}],"hops":[{"id":"h1","name":"Sorachi Ace","amountG":14.5,"use":"boil","timeMin":60},{"id":"h2","name":"Sorachi Ace","amountG":20,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.1}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.068,"fg":1.013,"ibu":75,"abvPct":7.5,"colorEbc":30},"notes":"Bryggetips: Sorachi Ace is hop best handled with care. Too much and your beer may taste like dill pickle and lemons.\n\nFørst brygget: 01/2011"}', '{"id":57,"name":"Sorachi Ace","tagline":"Single Hop IPA Series - 2011.","first_brewed":"01/2011","description":"A hop that tastes of bubble gum? Seriously? No, we did not believe it either. But it does! This is one unique, son of a bitch of a hop. Lemony, deep, musty with a smoothness that belies its power. This hop is lemony like a lemon who was angry earlier but is now tired because of all the rage. This hop of Japanese origin is best enjoyed trying to make sushi from your gold fish, or trying to persuade your girlfriend (or boyfriend maybe) to dress up as a Geisha for Valentine’s Day.","image":"057.png","abv":7.5,"ibu":75,"target_fg":1013,"target_og":1068,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":82.1,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":6.38,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.13,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.25,"unit":"kilograms"}}],"hops":[{"name":"Sorachi Ace","amount":{"value":14.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Sorachi Ace","amount":{"value":20,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Sashimi","Grilled salmon with a herb and citrus infused butter","Basil, lemon and pine nut angel hair pasta with grilled chicken"],"brewers_tips":"Sorachi Ace is hop best handled with care. Too much and your beer may taste like dill pickle and lemons.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-058', 'diydog', '058', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/058.json', 'Avery Brown Dredge', 'Bloggers'' Imperial Pilsner.', 'lager', 7.2, 59, 1.069, 1.027, 10, 20, 'avery brown dredge bloggers'' imperial pilsner. lager og pils lager malt wheat saaz saaz saaz wyeast 2007 - pilsen lager™', '{"schemaVersion":1,"name":"Avery Brown Dredge","style":"Lager og pils","description":"Bloggers'' Imperial Pilsner.\n\nAn Imperial Pilsner in collaboration with beer writers. Tradition. Homage. Revolution. We wanted to showcase the awesome backbone of the Czech brewing tradition, the noble Saaz hop, and also tip our hats to the modern beers that rock our world, and the people who make them.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":68,"fermentables":[{"id":"f1","name":"Lager Malt","type":"grain","amountKg":6.63},{"id":"f2","name":"Wheat","type":"grain","amountKg":0.38}],"hops":[{"id":"h1","name":"Saaz","amountG":60,"use":"boil","timeMin":60},{"id":"h2","name":"Saaz","amountG":60,"use":"boil","timeMin":30},{"id":"h3","name":"Saaz","amountG":60,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 2007 - Pilsen Lager™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":67}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":66,"durationMin":70}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":10}],"targets":{"og":1.069,"fg":1.027,"ibu":59,"abvPct":7.2,"colorEbc":10},"notes":"Bryggetips: Make sure you have a big enough yeast starter to ferment through the OG and lager successfully.\n\nFørst brygget: 02/2011"}', '{"id":58,"name":"Avery Brown Dredge","tagline":"Bloggers'' Imperial Pilsner.","first_brewed":"02/2011","description":"An Imperial Pilsner in collaboration with beer writers. Tradition. Homage. Revolution. We wanted to showcase the awesome backbone of the Czech brewing tradition, the noble Saaz hop, and also tip our hats to the modern beers that rock our world, and the people who make them.","image":"058.png","abv":7.2,"ibu":59,"target_fg":1027,"target_og":1069,"ebc":10,"srm":5,"ph":4.4,"attenuation_level":67,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":66,"unit":"celsius"},"duration":70}],"fermentation":{"temp":{"value":10,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Lager Malt","amount":{"value":6.63,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.38,"unit":"kilograms"}}],"hops":[{"name":"Saaz","amount":{"value":60,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Saaz","amount":{"value":60,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Saaz","amount":{"value":60,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 2007 - Pilsen Lager™"},"food_pairing":["Vietnamese squid salad","Chargrilled corn on the cob with paprika butter","Strawberry and rhubarb pie"],"brewers_tips":"Make sure you have a big enough yeast starter to ferment through the OG and lager successfully.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","OG/FG i kilden gir 5.5 % ABV, men oppgitt ABV er 7.2 % — sjekk tallene."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-059', 'diydog', '059', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/059.json', 'Growler', 'Citra Hopped Pilsner', 'lager', 4.5, 38, 1.0429000000000002, 1.008, 18, 20, 'growler citra hopped pilsner lager og pils pale ale caramalt crystal 150 citra citra citra wyeast 2007 - pilsen lager™', '{"schemaVersion":1,"name":"Growler","style":"Lager og pils","description":"Citra Hopped Pilsner\n\nBrewed by Pivovar Group at BrewDog, specifically for thier bars, Pivo in Leeds, Sheffield Tap in Sheffield, and Euston Tap in Euston. It was then lagered for 2 months and dry hopped with citra.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":68,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.25},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.13}],"hops":[{"id":"h1","name":"Citra","amountG":8.5,"use":"boil","timeMin":60},{"id":"h2","name":"Citra","amountG":62.5,"use":"boil","timeMin":0},{"id":"h3","name":"Citra","amountG":31.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 2007 - Pilsen Lager™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":81}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":10}],"targets":{"og":1.0429000000000002,"fg":1.008,"ibu":38,"abvPct":4.5,"colorEbc":18},"notes":"Bryggetips: Dry hop three days before you intend to package to get the freshest hop flavour possible.\n\nFørst brygget: 03/2011"}', '{"id":59,"name":"Growler","tagline":"Citra Hopped Pilsner","first_brewed":"03/2011","description":"Brewed by Pivovar Group at BrewDog, specifically for thier bars, Pivo in Leeds, Sheffield Tap in Sheffield, and Euston Tap in Euston. It was then lagered for 2 months and dry hopped with citra.","image":"keg.png","abv":4.5,"ibu":38,"target_fg":1008,"target_og":1042.9,"ebc":18,"srm":9,"ph":4.4,"attenuation_level":81,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":10,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.13,"unit":"kilograms"}}],"hops":[{"name":"Citra","amount":{"value":8.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Citra","amount":{"value":62.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Citra","amount":{"value":31.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 2007 - Pilsen Lager™"},"food_pairing":["Havarti cheese","Cajun spiced fried chicken","Lemon squares"],"brewers_tips":"Dry hop three days before you intend to package to get the freshest hop flavour possible.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-060', 'diydog', '060', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/060.json', 'Rabiator', 'Imperial Wheat Beer', 'wheat', 10.27, 26, 1.092, 1.014, 24, 20, 'rabiator imperial wheat beer hvete extra pale wheat crystal columbus hersbrucker wyeast 3333 - german wheat™', '{"schemaVersion":1,"name":"Rabiator","style":"Hvete","description":"Imperial Wheat Beer\n\nImperial Wheat beer / Weizenbock brewed by a homesick German in leather trousers. Think banana bread, bubble gum and David Hasselhoff.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":92,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5.63},{"id":"f2","name":"Wheat","type":"grain","amountKg":0.69},{"id":"f3","name":"Crystal","type":"grain","amountKg":0.63}],"hops":[{"id":"h1","name":"Columbus","amountG":12.5,"use":"boil","timeMin":60},{"id":"h2","name":"Hersbrucker","amountG":12.5,"use":"boil","timeMin":30}],"cultures":[{"id":"y1","name":"Wyeast 3333 - German Wheat™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":85}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.092,"fg":1.014,"ibu":26,"abvPct":10.27,"colorEbc":24},"notes":"Bryggetips: If you are struggling to get that authentic head retention increase your mash temperature to about 70°C.\n\nFørst brygget: 03/2011"}', '{"id":60,"name":"Rabiator","tagline":"Imperial Wheat Beer","first_brewed":"03/2011","description":"Imperial Wheat beer / Weizenbock brewed by a homesick German in leather trousers. Think banana bread, bubble gum and David Hasselhoff.","image":"keg.png","abv":10.27,"ibu":26,"target_fg":1014,"target_og":1092,"ebc":24,"srm":12,"ph":4.4,"attenuation_level":85,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":60}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5.63,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.69,"unit":"kilograms"}},{"name":"Crystal","amount":{"value":0.63,"unit":"kilograms"}}],"hops":[{"name":"Columbus","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Hersbrucker","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"}],"yeast":"Wyeast 3333 - German Wheat™"},"food_pairing":["Grilled portabello mushroom burger","Chicken sausages with creamy mash","Caramel and banana meringue pie"],"brewers_tips":"If you are struggling to get that authentic head retention increase your mash temperature to about 70°C.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-061', 'diydog', '061', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/061.json', 'AB:06', 'Imperial Black IPA.', 'ipa', 11.2, 150, 1.098, 1.013, 70, 20, 'ab:06 imperial black ipa. ipa pale ale crystal 150 caramalt carafa special malt type 1 carafa special malt type 3 hop extract amarillo chinook cascade centennial columbus chinook cascade centennial columbus amarillo wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"AB:06","style":"IPA","description":"Imperial Black IPA.\n\nOur sixth Abstrakt, this imperial black IPA combined dark malts with a monumental triple dry-hop, using an all-star team of some of our favourite American hops. Roasty and resinous.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":6.13},{"id":"f2","name":"Crystal 150","type":"grain","amountKg":0.25},{"id":"f3","name":"Caramalt","type":"grain","amountKg":0.38},{"id":"f4","name":"Carafa Special Malt Type 1","type":"grain","amountKg":0.13},{"id":"f5","name":"Carafa Special Malt Type 3","type":"grain","amountKg":0.13}],"hops":[{"id":"h1","name":"Hop Extract","amountG":20,"use":"boil","timeMin":60},{"id":"h2","name":"Amarillo","amountG":25,"use":"boil","timeMin":60},{"id":"h3","name":"Chinook","amountG":25,"use":"boil","timeMin":0},{"id":"h4","name":"Cascade","amountG":25,"use":"boil","timeMin":0},{"id":"h5","name":"Centennial","amountG":25,"use":"boil","timeMin":0},{"id":"h6","name":"Columbus","amountG":25,"use":"boil","timeMin":0},{"id":"h7","name":"Chinook","amountG":25,"use":"dry_hop"},{"id":"h8","name":"Cascade","amountG":25,"use":"dry_hop"},{"id":"h9","name":"Centennial","amountG":25,"use":"dry_hop"},{"id":"h10","name":"Columbus","amountG":25,"use":"dry_hop"},{"id":"h11","name":"Amarillo","amountG":25,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":87}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":90}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":17}],"targets":{"og":1.098,"fg":1.013,"ibu":150,"abvPct":11.2,"colorEbc":70},"notes":"Bryggetips: Boil down to desired OG (about 17 litres).\n\nTwist: White cane sugar: 150g at middle\n\nFørst brygget: 04/2011"}', '{"id":61,"name":"AB:06","tagline":"Imperial Black IPA.","first_brewed":"04/2011","description":"Our sixth Abstrakt, this imperial black IPA combined dark malts with a monumental triple dry-hop, using an all-star team of some of our favourite American hops. Roasty and resinous.","image":"061.png","abv":11.2,"ibu":150,"target_fg":1013,"target_og":1098,"ebc":70,"srm":35,"ph":null,"attenuation_level":87,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":90}],"fermentation":{"temp":{"value":17,"unit":"celsius"}},"twist":"White cane sugar: 150g at middle"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":6.13,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.38,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":0.13,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":0.13,"unit":"kilograms"}}],"hops":[{"name":"Hop Extract","amount":{"value":20,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Amarillo","amount":{"value":25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Chinook","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Cascade","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Centennial","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Columbus","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Chinook","amount":{"value":25,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Cascade","amount":{"value":25,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Centennial","amount":{"value":25,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Columbus","amount":{"value":25,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Amarillo","amount":{"value":25,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Coffee dusted venison loin","Memphis-style beef short ribs","Chocolate orange brownies"],"brewers_tips":"Boil down to desired OG (about 17 litres).","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Malt og OG i kilden gir 97 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-062', 'diydog', '062', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/062.json', 'Juniper Wheat Beer', 'American Style Wheat Ale With Juniper Berries.', 'wheat', 5, 40, 1.047, 1.008, 15, 20, 'juniper wheat beer american style wheat ale with juniper berries. hvete pale ale wheat ahtanum ahtanum juniper berries wyeast 1010 - american wheat™', '{"schemaVersion":1,"name":"Juniper Wheat Beer","style":"Hvete","description":"American Style Wheat Ale With Juniper Berries.\n\nA variant on the 2008 release of Bad Pixie, but hoppier. Substituting the lemon peel for Ahtanum provided a vibrant floral and lemon citrus hit, balancing the slight tartness from the wheat. This dry, effervescent brew is perfect on Scotland''s one day of summer.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":67,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":2.75},{"id":"f2","name":"Wheat","type":"grain","amountKg":2.13}],"hops":[{"id":"h1","name":"Ahtanum","amountG":31.3,"use":"boil","timeMin":60},{"id":"h2","name":"Ahtanum","amountG":31.3,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1010 - American Wheat™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83}],"miscs":[{"id":"x3","name":"Juniper Berries","amount":25,"unit":"g","use":"fermentation"}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":17}],"targets":{"og":1.047,"fg":1.008,"ibu":40,"abvPct":5,"colorEbc":15},"notes":"Bryggetips: Give the juniper berries a quick blast in a food processor to break them up - otherwise they can jam up your fermenter.\n\nFørst brygget: 06/2011"}', '{"id":62,"name":"Juniper Wheat Beer","tagline":"American Style Wheat Ale With Juniper Berries.","first_brewed":"06/2011","description":"A variant on the 2008 release of Bad Pixie, but hoppier. Substituting the lemon peel for Ahtanum provided a vibrant floral and lemon citrus hit, balancing the slight tartness from the wheat. This dry, effervescent brew is perfect on Scotland''s one day of summer.","image":"keg.png","abv":5,"ibu":40,"target_fg":1008,"target_og":1047,"ebc":15,"srm":7.5,"ph":4.1,"attenuation_level":83,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":17,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":2.75,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":2.13,"unit":"kilograms"}}],"hops":[{"name":"Ahtanum","amount":{"value":31.25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Ahtanum","amount":{"value":31.25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Juniper Berries","amount":{"value":25,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1010 - American Wheat™"},"food_pairing":["Herring rollmops","Chicken schnitzel","Gin & elderflower jelly"],"brewers_tips":"Give the juniper berries a quick blast in a food processor to break them up - otherwise they can jam up your fermenter.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-063', 'diydog', '063', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/063.json', 'The End Of History', 'The World''s Strongest Beer.', 'other', 55, NULL, 1.112, 1, NULL, 20, 'the end of history the world''s strongest beer. annet extra pale nelson sauvin centennial nelson sauvin amarillo centennial wyeast 3522 - belgian ardennes™', '{"schemaVersion":1,"name":"The End Of History","description":"The World''s Strongest Beer.\n\nThe End of History: The name derives from the famous work of philosopher Francis Fukuyama, this is to beer what democracy is to history. Complexity defined. Floral, grapefruit, caramel and cloves are intensified by boozy heat.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":62,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":12.5}],"hops":[{"id":"h1","name":"Nelson Sauvin","amountG":6.3,"use":"boil","timeMin":60},{"id":"h2","name":"Centennial","amountG":12.5,"use":"boil","timeMin":60},{"id":"h3","name":"Nelson Sauvin","amountG":12.5,"use":"boil","timeMin":0},{"id":"h4","name":"Amarillo","amountG":12.5,"use":"boil","timeMin":0},{"id":"h5","name":"Centennial","amountG":12.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 3522 - Belgian Ardennes™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":100}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":20}],"targets":{"og":1.112,"fg":1,"abvPct":55},"notes":"Bryggetips: You''ll have to get this one all the way down to -70°C. Taxidermy is not optional.\n\nTwist: Nettles: 25g at end, Juniper: 25g at end\n\nFørst brygget: 06/2011"}', '{"id":63,"name":"The End Of History","tagline":"The World''s Strongest Beer.","first_brewed":"06/2011","description":"The End of History: The name derives from the famous work of philosopher Francis Fukuyama, this is to beer what democracy is to history. Complexity defined. Floral, grapefruit, caramel and cloves are intensified by boozy heat.","image":"063.png","abv":55,"ibu":null,"target_fg":1000,"target_og":1112,"ebc":null,"srm":null,"ph":4.4,"attenuation_level":100,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":20,"unit":"celsius"}},"twist":"Nettles: 25g at end, Juniper: 25g at end"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":12.5,"unit":"kilograms"}}],"hops":[{"name":"Nelson Sauvin","amount":{"value":6.25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Centennial","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Nelson Sauvin","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Amarillo","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Centennial","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 3522 - Belgian Ardennes™"},"food_pairing":["Roasted wood pigeon with black pudding","Pan seared venison fillet with juniper sauce","Apricot coconut cake"],"brewers_tips":"You''ll have to get this one all the way down to -70°C. Taxidermy is not optional.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","12.5 kg malt til 20 L er urealistisk — trolig en feil i kilden."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-064', 'diydog', '064', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/064.json', 'Hops Kill Nazis', 'Imperial Red Ale.', 'strong', 7.6, 70, 1.073, 1.015, 59, 20, 'hops kill nazis imperial red ale. sterkt øl maris otter extra pale caramalt crystal 150 chinook chinook centennial chinook wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Hops Kill Nazis","style":"Sterkt øl","description":"Imperial Red Ale.\n\n5AM Saint''s big brother. Dry- hopping with Chinook gave Hops Kill Nazis a full-on, instantly recognisable US hop character - huge resinous aromas (think giant redwood) with a bitter grapefruit edge. The caramel malts bring flavours of toffee and burnt sugar, which gave Hops Kill Nazis a big, complex malt base supporting the intense hopping.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":61,"fermentables":[{"id":"f1","name":"Maris Otter Extra Pale","type":"grain","amountKg":4.82},{"id":"f2","name":"Caramalt","type":"grain","amountKg":2.5},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.96}],"hops":[{"id":"h1","name":"Chinook","amountG":40,"use":"boil","timeMin":60},{"id":"h2","name":"Chinook","amountG":62.5,"use":"boil","timeMin":0},{"id":"h3","name":"Centennial","amountG":62.5,"use":"boil","timeMin":0},{"id":"h4","name":"Chinook","amountG":178,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79.5}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":68,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":20}],"targets":{"og":1.073,"fg":1.015,"ibu":70,"abvPct":7.6,"colorEbc":59},"notes":"Bryggetips: A red colour is a difficult hue to achieve in beer. Experiment with different amounts of Crystal malt to fine tune the colour.\n\nFørst brygget: 08/2011"}', '{"id":64,"name":"Hops Kill Nazis","tagline":"Imperial Red Ale.","first_brewed":"08/2011","description":"5AM Saint''s big brother. Dry- hopping with Chinook gave Hops Kill Nazis a full-on, instantly recognisable US hop character - huge resinous aromas (think giant redwood) with a bitter grapefruit edge. The caramel malts bring flavours of toffee and burnt sugar, which gave Hops Kill Nazis a big, complex malt base supporting the intense hopping.","image":"064.png","abv":7.6,"ibu":70,"target_fg":1015,"target_og":1073,"ebc":59,"srm":29.5,"ph":4.4,"attenuation_level":79.5,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":68,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":20,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Maris Otter Extra Pale","amount":{"value":4.82,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":2.5,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.96,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":40,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Chinook","amount":{"value":62.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Centennial","amount":{"value":62.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Chinook","amount":{"value":178,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Candied almond and blue cheese rocket salad","Chicken Tikka Madras","Pecan pie"],"brewers_tips":"A red colour is a difficult hue to achieve in beer. Experiment with different amounts of Crystal malt to fine tune the colour.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-065', 'diydog', '065', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/065.json', 'Mr.Miyagi''s Wasabi Stout', 'Spicy Stout Brewed By Aberdeen Bar Staff.', 'stout', 7.5, 90, 1.072, 1.015, 200, 20, 'mr.miyagi''s wasabi stout spicy stout brewed by aberdeen bar staff. stout og porter maris otter extra pale chocolate flaked oats crystal black malt roasted malt chinook sorachi ace wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Mr.Miyagi''s Wasabi Stout","style":"Stout og porter","description":"Spicy Stout Brewed By Aberdeen Bar Staff.\n\nInvented by and brewed by Dan Bloxham, no matter what anyone else says. A medium bodied, bitter, US style stout, with a wasabi warmth, a subtle earthiness and a hint of soy sauce.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":62,"fermentables":[{"id":"f1","name":"Maris Otter Extra Pale","type":"grain","amountKg":6},{"id":"f2","name":"Chocolate","type":"grain","amountKg":0.5},{"id":"f3","name":"Flaked Oats","type":"grain","amountKg":0.5},{"id":"f4","name":"Crystal","type":"grain","amountKg":0.5},{"id":"f5","name":"Black Malt","type":"grain","amountKg":0.25},{"id":"f6","name":"Roasted Malt","type":"grain","amountKg":0.25}],"hops":[{"id":"h1","name":"Chinook","amountG":81.3,"use":"boil","timeMin":60},{"id":"h2","name":"Sorachi Ace","amountG":62.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79.2}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.072,"fg":1.015,"ibu":90,"abvPct":7.5,"colorEbc":200},"notes":"Bryggetips: During mashing in use only pale malts, add flaked oats during the second half of the mashing process. If you can''t get real wasabi, substitute for some horseradish to get the peppery heat in the beer.\n\nTwist: Wasabi Powder: 45g at end, Wasabi Paste: 75g at end\n\nFørst brygget: 09/2011"}', '{"id":65,"name":"Mr.Miyagi''s Wasabi Stout","tagline":"Spicy Stout Brewed By Aberdeen Bar Staff.","first_brewed":"09/2011","description":"Invented by and brewed by Dan Bloxham, no matter what anyone else says. A medium bodied, bitter, US style stout, with a wasabi warmth, a subtle earthiness and a hint of soy sauce.","image":"keg.png","abv":7.5,"ibu":90,"target_fg":1015,"target_og":1072,"ebc":200,"srm":102,"ph":4.4,"attenuation_level":79.2,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Wasabi Powder: 45g at end, Wasabi Paste: 75g at end"},"ingredients":{"malt":[{"name":"Maris Otter Extra Pale","amount":{"value":6,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Crystal","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Black Malt","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Roasted Malt","amount":{"value":0.25,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":81.25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Sorachi Ace","amount":{"value":62.5,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["California sushi rolls with fresh crab and wasabi infused soy sauce","Spicy chilli and coriander Thai beef stew","Carrot and coriander rich cake"],"brewers_tips":"During mashing in use only pale malts, add flaked oats during the second half of the mashing process. If you can''t get real wasabi, substitute for some horseradish to get the peppery heat in the beer.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-066', 'diydog', '066', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/066.json', 'Sunk Punk', 'Ocean Fermented Lager.', 'lager', 7.1, 68, 1.056, 1.01, 14, 20, 'sunk punk ocean fermented lager. lager og pils extra pale chinook ahtanum chinook ahtanum chinook ahtanum simcoe nelson sauvin wyeast 2007 - pilsen lager™', '{"schemaVersion":1,"name":"Sunk Punk","style":"Lager og pils","description":"Ocean Fermented Lager.\n\nIt''s rumoured just a drop can calm the fiercest of storms. A balance of sweet, salt and savoury, citrus, spruce and caramel. Fermented at the bottom of the North Sea, which just so happens to be the perfect temperature for lagers to ferment.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":74,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5.21}],"hops":[{"id":"h1","name":"Chinook","amountG":20,"use":"boil","timeMin":60},{"id":"h2","name":"Ahtanum","amountG":12.5,"use":"boil","timeMin":60},{"id":"h3","name":"Chinook","amountG":20,"use":"boil","timeMin":30},{"id":"h4","name":"Ahtanum","amountG":12.5,"use":"boil","timeMin":30},{"id":"h5","name":"Chinook","amountG":30,"use":"boil","timeMin":0},{"id":"h6","name":"Ahtanum","amountG":12.5,"use":"boil","timeMin":0},{"id":"h7","name":"Simcoe","amountG":12.5,"use":"boil","timeMin":0},{"id":"h8","name":"Nelson Sauvin","amountG":140,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 2007 - Pilsen Lager™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.1}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":10}],"targets":{"og":1.056,"fg":1.01,"ibu":68,"abvPct":7.1,"colorEbc":14},"notes":"Bryggetips: Keep the fermentation temperature as steady as possible to allow the lager yeast to do its thing.\n\nTwist: Seabuckthorn: 25g at end, Sea Salt: 20g at middle, Rum: 25ml at end\n\nFørst brygget: 09/2011"}', '{"id":66,"name":"Sunk Punk","tagline":"Ocean Fermented Lager.","first_brewed":"09/2011","description":"It''s rumoured just a drop can calm the fiercest of storms. A balance of sweet, salt and savoury, citrus, spruce and caramel. Fermented at the bottom of the North Sea, which just so happens to be the perfect temperature for lagers to ferment.","image":"066.png","abv":7.1,"ibu":68,"target_fg":1010,"target_og":1056,"ebc":14,"srm":7,"ph":4.4,"attenuation_level":82.1,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":10,"unit":"celsius"}},"twist":"Seabuckthorn: 25g at end, Sea Salt: 20g at middle, Rum: 25ml at end"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5.21,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":20,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Ahtanum","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Chinook","amount":{"value":20,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Ahtanum","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Chinook","amount":{"value":30,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Ahtanum","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Simcoe","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Nelson Sauvin","amount":{"value":140,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 2007 - Pilsen Lager™"},"food_pairing":["Salt baked cod with lemon and dill butter","Beef, oyster and ale pie","Apple and rosemary tart"],"brewers_tips":"Keep the fermentation temperature as steady as possible to allow the lager yeast to do its thing.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-067', 'diydog', '067', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/067.json', 'AB:10', 'Imperial Brown Ale Aged In Spanish Red Wine Barrels.', 'strong', 11.5, 80, 1.096, 1.02, 115, 20, 'ab:10 imperial brown ale aged in spanish red wine barrels. sterkt øl extra pale - spring blend caramalt dark crystal carafa special malt type 1 chocolate brown flaked oats galena willamette first gold wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"AB:10","style":"Sterkt øl","description":"Imperial Brown Ale Aged In Spanish Red Wine Barrels.\n\nA decadent, robust and encapsulating Imperial Ale. A rollercoaster of devilish berries, smooth vanilla, toasted marshmallow and wine gums; caramel malt balanced with moderate bitterness and a roasty edge.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":57,"fermentables":[{"id":"f1","name":"Extra Pale - Spring Blend","type":"grain","amountKg":8.75},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.94},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.44},{"id":"f4","name":"Carafa Special Malt Type 1","type":"grain","amountKg":0.11},{"id":"f5","name":"Chocolate","type":"grain","amountKg":0.11},{"id":"f6","name":"Brown","type":"grain","amountKg":0.37},{"id":"f7","name":"Flaked Oats","type":"grain","amountKg":0.94}],"hops":[{"id":"h1","name":"Galena","amountG":37.5,"use":"boil","timeMin":60},{"id":"h2","name":"Willamette","amountG":50,"use":"boil","timeMin":0},{"id":"h3","name":"First Gold","amountG":25,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79.2}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":69,"durationMin":45}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":20}],"targets":{"og":1.096,"fg":1.02,"ibu":80,"abvPct":11.5,"colorEbc":115},"notes":"Bryggetips: Be careful of sticking the run-off. There are a lot of specialty malts in this mash that can prove problematic if pulled onto the run-off plates.\n\nTwist: Age in red wine barrels\n\nFørst brygget: 10/2011"}', '{"id":67,"name":"AB:10","tagline":"Imperial Brown Ale Aged In Spanish Red Wine Barrels.","first_brewed":"10/2011","description":"A decadent, robust and encapsulating Imperial Ale. A rollercoaster of devilish berries, smooth vanilla, toasted marshmallow and wine gums; caramel malt balanced with moderate bitterness and a roasty edge.","image":"067.png","abv":11.5,"ibu":80,"target_fg":1020,"target_og":1096,"ebc":115,"srm":57.5,"ph":4.4,"attenuation_level":79.2,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":69,"unit":"celsius"},"duration":45}],"fermentation":{"temp":{"value":20,"unit":"celsius"}},"twist":"Age in red wine barrels"},"ingredients":{"malt":[{"name":"Extra Pale - Spring Blend","amount":{"value":8.75,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.94,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.44,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":0.11,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.11,"unit":"kilograms"}},{"name":"Brown","amount":{"value":0.37,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.94,"unit":"kilograms"}}],"hops":[{"name":"Galena","amount":{"value":37.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Willamette","amount":{"value":50,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"First Gold","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Calves'' liver with onion relish","Coq au vin","S''mores"],"brewers_tips":"Be careful of sticking the run-off. There are a lot of specialty malts in this mash that can prove problematic if pulled onto the run-off plates.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","OG/FG i kilden gir 10.0 % ABV, men oppgitt ABV er 11.5 % — sjekk tallene."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-068', 'diydog', '068', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/068.json', 'AB:18', 'Imperial Brown Ale Aged In Rum Casks.', 'strong', 11.8, 80, 1.096, 1.02, 115, 20, 'ab:18 imperial brown ale aged in rum casks. sterkt øl extra pale - spring blend caramalt dark crystal carafa special malt type 1 chocolate brown flaked oats galena willamette first gold wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"AB:18","style":"Sterkt øl","description":"Imperial Brown Ale Aged In Rum Casks.\n\nAB:18 began life as an Imperial Brown Ale before we bombarded it with Scottish tayberries and Purple raspberries and locked it away in rum barrels for two years, infusing rich dark fruit flavours and oaky warmth into the mix.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":57,"fermentables":[{"id":"f1","name":"Extra Pale - Spring Blend","type":"grain","amountKg":8.75},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.93},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.44},{"id":"f4","name":"Carafa Special Malt Type 1","type":"grain","amountKg":0.11},{"id":"f5","name":"Chocolate","type":"grain","amountKg":0.11},{"id":"f6","name":"Brown","type":"grain","amountKg":0.38},{"id":"f7","name":"Flaked Oats","type":"grain","amountKg":0.94}],"hops":[{"id":"h1","name":"Galena","amountG":37.5,"use":"boil","timeMin":60},{"id":"h2","name":"Willamette","amountG":50,"use":"boil","timeMin":0},{"id":"h3","name":"First Gold","amountG":25,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79.2}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":69,"durationMin":45}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":20}],"targets":{"og":1.096,"fg":1.02,"ibu":80,"abvPct":11.8,"colorEbc":115},"notes":"Bryggetips: Blend aged beer with a fresh brewed black ale in a 70-30 ratio to add bursts of blackcurrant and citrus.\n\nTwist: Age in rum barrels, Tayberries: 500g, Purple Raspberries: 500g\n\nFørst brygget: 10/2011"}', '{"id":68,"name":"AB:18","tagline":"Imperial Brown Ale Aged In Rum Casks.","first_brewed":"10/2011","description":"AB:18 began life as an Imperial Brown Ale before we bombarded it with Scottish tayberries and Purple raspberries and locked it away in rum barrels for two years, infusing rich dark fruit flavours and oaky warmth into the mix.","image":"068.png","abv":11.8,"ibu":80,"target_fg":1020,"target_og":1096,"ebc":115,"srm":57.5,"ph":5.2,"attenuation_level":79.2,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":69,"unit":"celsius"},"duration":45}],"fermentation":{"temp":{"value":20,"unit":"celsius"}},"twist":"Age in rum barrels, Tayberries: 500g, Purple Raspberries: 500g"},"ingredients":{"malt":[{"name":"Extra Pale - Spring Blend","amount":{"value":8.75,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.93,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.44,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":0.11,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.11,"unit":"kilograms"}},{"name":"Brown","amount":{"value":0.38,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.94,"unit":"kilograms"}}],"hops":[{"name":"Galena","amount":{"value":37.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Willamette","amount":{"value":50,"unit":"grams"},"add":"end","attribute":"bitter"},{"name":"First Gold","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Kippers and poached eggs","Slow cooked lamb shoulder with mint sauce","Apple and blackcurrant cobbler"],"brewers_tips":"Blend aged beer with a fresh brewed black ale in a 70-30 ratio to add bursts of blackcurrant and citrus.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","OG/FG i kilden gir 10.0 % ABV, men oppgitt ABV er 11.8 % — sjekk tallene."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-069', 'diydog', '069', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/069.json', 'Old World India Pale Ale', 'English India Pale Ale.', 'ipa', 7.5, 80, 1.069, 1.012, 50, 20, 'old world india pale ale english india pale ale. ipa maris otter extra pale amber crystal 150 bramling cross first gold bramling cross wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Old World India Pale Ale","style":"IPA","description":"English India Pale Ale.\n\nThis recreated the epic IPAs that were sent on monumental ocean voyages from England to India by sea in the 1800s. Medium bodied with a complex malt profile, backed up with intense bitterness and a woodsy, earthy rich English hop character.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":71,"fermentables":[{"id":"f1","name":"Maris Otter Extra Pale","type":"grain","amountKg":6.25},{"id":"f2","name":"Amber","type":"grain","amountKg":0.25},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.25}],"hops":[{"id":"h1","name":"Bramling Cross","amountG":62.5,"use":"boil","timeMin":60},{"id":"h2","name":"First Gold","amountG":50,"use":"boil","timeMin":0},{"id":"h3","name":"Bramling Cross","amountG":50,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.6}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":22}],"targets":{"og":1.069,"fg":1.012,"ibu":80,"abvPct":7.5,"colorEbc":50},"notes":"Bryggetips: In beers like this with a hefty malt bill, it pays to check a spoonful of the mash with some iodine solution. This will indicate if the mash has converted all of the starch into fermentable sugars. If the colour is very dark, just extend the mash rest by 10 mins and check again.\n\nFørst brygget: 10/2011"}', '{"id":69,"name":"Old World India Pale Ale","tagline":"English India Pale Ale.","first_brewed":"10/2011","description":"This recreated the epic IPAs that were sent on monumental ocean voyages from England to India by sea in the 1800s. Medium bodied with a complex malt profile, backed up with intense bitterness and a woodsy, earthy rich English hop character.","image":"069.png","abv":7.5,"ibu":80,"target_fg":1012,"target_og":1069,"ebc":50,"srm":25,"ph":4.4,"attenuation_level":82.6,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":22,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Maris Otter Extra Pale","amount":{"value":6.25,"unit":"kilograms"}},{"name":"Amber","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.25,"unit":"kilograms"}}],"hops":[{"name":"Bramling Cross","amount":{"value":62.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"First Gold","amount":{"value":50,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Bramling Cross","amount":{"value":50,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Honey glazed ham with spicy roasted carrots","Mature cheddar with spicy chutney","Peach cobbler"],"brewers_tips":"In beers like this with a hefty malt bill, it pays to check a spoonful of the mash with some iodine solution. This will indicate if the mash has converted all of the starch into fermentable sugars. If the colour is very dark, just extend the mash rest by 10 mins and check again.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-070', 'diydog', '070', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/070.json', 'Old World Russian Imperial Stout', 'Russian Imperial Stout.', 'stout', 9.5, 80, 1.075, 1.014, 195, 20, 'old world russian imperial stout russian imperial stout. stout og porter extra pale dark crystal 350 carafa special malt type 3 caramalt chocolate magnum galena hercules magnum galena cascade galena wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Old World Russian Imperial Stout","style":"Stout og porter","description":"Russian Imperial Stout.\n\nThis Old World Stout perfectly recreates the export stouts of years gone by; brewed to imperial strength to avoid freezing during its journey across the Baltic Sea to snowy Moscow. Full bodied with huge chocolate, coffee and roast flavours, this imperial stout employs a variety of hops to add enough bitterness and hop complexity to balance the huge malt sweetness and rich mocha and molasses flavours.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":66,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":6.56},{"id":"f2","name":"Dark Crystal 350","type":"grain","amountKg":0.66},{"id":"f3","name":"Carafa Special Malt Type 3","type":"grain","amountKg":0.31},{"id":"f4","name":"Caramalt","type":"grain","amountKg":0.31},{"id":"f5","name":"Chocolate","type":"grain","amountKg":0.07}],"hops":[{"id":"h1","name":"Magnum","amountG":12.5,"use":"boil","timeMin":60},{"id":"h2","name":"Galena","amountG":12.5,"use":"boil","timeMin":60},{"id":"h3","name":"Hercules","amountG":12.5,"use":"boil","timeMin":60},{"id":"h4","name":"Magnum","amountG":6.3,"use":"boil","timeMin":60},{"id":"h5","name":"Galena","amountG":6.3,"use":"boil","timeMin":60},{"id":"h6","name":"Cascade","amountG":25,"use":"boil","timeMin":0},{"id":"h7","name":"Galena","amountG":25,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":81.3}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":90}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.075,"fg":1.014,"ibu":80,"abvPct":9.5,"colorEbc":195},"notes":"Bryggetips: Add the chocolate malt after the mash is complete, at the start of sparging. This will extract flavour and colour, but will prevent the extraction of harsh tannins into the wort.\n\nFørst brygget: 10/2011"}', '{"id":70,"name":"Old World Russian Imperial Stout","tagline":"Russian Imperial Stout.","first_brewed":"10/2011","description":"This Old World Stout perfectly recreates the export stouts of years gone by; brewed to imperial strength to avoid freezing during its journey across the Baltic Sea to snowy Moscow. Full bodied with huge chocolate, coffee and roast flavours, this imperial stout employs a variety of hops to add enough bitterness and hop complexity to balance the huge malt sweetness and rich mocha and molasses flavours.","image":"070.png","abv":9.5,"ibu":80,"target_fg":1014,"target_og":1075,"ebc":195,"srm":97.5,"ph":4.5,"attenuation_level":81.3,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":90}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":6.56,"unit":"kilograms"}},{"name":"Dark Crystal 350","amount":{"value":0.66,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.07,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Galena","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Hercules","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Magnum","amount":{"value":6.25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Galena","amount":{"value":6.25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Cascade","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Galena","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Seared steak with a peppercorn sauce","Strong blue cheese and oatcakes","Chocolate cheesecake"],"brewers_tips":"Add the chocolate malt after the mash is complete, at the start of sparging. This will extract flavour and colour, but will prevent the extraction of harsh tannins into the wort.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-071', 'diydog', '071', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/071.json', 'Lost Dog (w/ Lost Abbey)', 'Rum-Aged Imperial Porter - Lost Abbey Collab.', 'stout', 10, 35, 1.08, 1.012, 80, 20, 'lost dog (w/ lost abbey) rum-aged imperial porter - lost abbey collab. stout og porter extra pale pale chocolate chocolate dark crystal flaked oats caramalt first gold wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Lost Dog (w/ Lost Abbey)","style":"Stout og porter","description":"Rum-Aged Imperial Porter - Lost Abbey Collab.\n\nOur first beer aged in rum casks, Lost Dog saw us brew a collaboration imperial porter with our friends at Lost Abbey. The base beer was packed with toffee, chocolate and roasty notes, balanced with a subtle spicy hop character. The rum casks add a warming, spiced vanilla edge.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":81,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":4.69},{"id":"f2","name":"Pale Chocolate","type":"grain","amountKg":0.23},{"id":"f3","name":"Chocolate","type":"grain","amountKg":0.7},{"id":"f4","name":"Dark Crystal","type":"grain","amountKg":0.35},{"id":"f5","name":"Flaked Oats","type":"grain","amountKg":0.47},{"id":"f6","name":"Caramalt","type":"grain","amountKg":0.35}],"hops":[{"id":"h1","name":"First Gold","amountG":35,"use":"boil","timeMin":60}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":85}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.08,"fg":1.012,"ibu":35,"abvPct":10,"colorEbc":80},"notes":"Bryggetips: Ageing in barrels brings the ABV up. Recreate rum cask ageing by soaking oak chips in rum then adding to the maturing beer.\n\nTwist: Aged in rum casks for 12 months\n\nFørst brygget: 11/2011"}', '{"id":71,"name":"Lost Dog (w/ Lost Abbey)","tagline":"Rum-Aged Imperial Porter - Lost Abbey Collab.","first_brewed":"11/2011","description":"Our first beer aged in rum casks, Lost Dog saw us brew a collaboration imperial porter with our friends at Lost Abbey. The base beer was packed with toffee, chocolate and roasty notes, balanced with a subtle spicy hop character. The rum casks add a warming, spiced vanilla edge.","image":"071.png","abv":10,"ibu":35,"target_fg":1012,"target_og":1080,"ebc":80,"srm":40,"ph":4.4,"attenuation_level":85,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Aged in rum casks for 12 months"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":4.69,"unit":"kilograms"}},{"name":"Pale Chocolate","amount":{"value":0.23,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.7,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.35,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.47,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.35,"unit":"kilograms"}}],"hops":[{"name":"First Gold","amount":{"value":35,"unit":"grams"},"add":"start","attribute":"bitter"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Beef satay skewers","Venison & cranberry pie","Blackberry mocha gateaux"],"brewers_tips":"Ageing in barrels brings the ABV up. Recreate rum cask ageing by soaking oak chips in rum then adding to the maturing beer.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-072', 'diydog', '072', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/072.json', 'AB:08', 'Deconstructed Blonde Imperial Stout.', 'stout', 10.43, 65, 1.095, 1.016, 23, 20, 'ab:08 deconstructed blonde imperial stout. stout og porter maris otter extra pale wheat flaked oats smoked peaty first gold first gold coffee beans wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"AB:08","style":"Stout og porter","description":"Deconstructed Blonde Imperial Stout.\n\nFlavours and aromas you''d expect from a Stout, but brewed without dark malts. The full mouthfeel comes courtesy of wheat and oats, while smoked malt and the twist additions add the complex flavours normally provided by highly kilned malts.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":50,"fermentables":[{"id":"f1","name":"Maris Otter Extra Pale","type":"grain","amountKg":9.25},{"id":"f2","name":"Wheat","type":"grain","amountKg":1.88},{"id":"f3","name":"Flaked Oats","type":"grain","amountKg":1.88},{"id":"f4","name":"Smoked Peaty","type":"grain","amountKg":0.13}],"hops":[{"id":"h1","name":"First Gold","amountG":81.3,"use":"boil","timeMin":60},{"id":"h2","name":"First Gold","amountG":62.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83.2}],"miscs":[{"id":"x3","name":"Coffee Beans","amount":12.5,"unit":"g","use":"boil","timeMin":0}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.095,"fg":1.016,"ibu":65,"abvPct":10.43,"colorEbc":23},"notes":"Bryggetips: Add all twist ingredients to Fermentation Vessel once fermentation is complete. Don’t be afraid to add a little at a time and taste as you go. During mashing in first start with pale malt. Afterwards mix all malts evenly. Go with flaked oats during second half of mashing in process.\n\nTwist: Cacao: 25g at FV, Coffee Beans: 37.5g at FV, Oak Chips: 5g at FV, Vanilla Pods: 10 split pods, Liquorice: 5g at FV\n\nFørst brygget: 11/2011"}', '{"id":72,"name":"AB:08","tagline":"Deconstructed Blonde Imperial Stout.","first_brewed":"11/2011","description":"Flavours and aromas you''d expect from a Stout, but brewed without dark malts. The full mouthfeel comes courtesy of wheat and oats, while smoked malt and the twist additions add the complex flavours normally provided by highly kilned malts.","image":"072.png","abv":10.43,"ibu":65,"target_fg":1016,"target_og":1095,"ebc":23,"srm":11.5,"ph":4.4,"attenuation_level":83.2,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Cacao: 25g at FV, Coffee Beans: 37.5g at FV, Oak Chips: 5g at FV, Vanilla Pods: 10 split pods, Liquorice: 5g at FV"},"ingredients":{"malt":[{"name":"Maris Otter Extra Pale","amount":{"value":9.25,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":1.88,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":1.88,"unit":"kilograms"}},{"name":"Smoked Peaty","amount":{"value":0.13,"unit":"kilograms"}}],"hops":[{"name":"First Gold","amount":{"value":81.25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"First Gold","amount":{"value":62.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Coffee Beans","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Caramelised scallops with burnt apple puree","Blackened Cajun chicken","Blondies with chocolate fudge sauce"],"brewers_tips":"Add all twist ingredients to Fermentation Vessel once fermentation is complete. Don’t be afraid to add a little at a time and taste as you go. During mashing in first start with pale malt. Afterwards mix all malts evenly. Go with flaked oats during second half of mashing in process.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min.","13.1 kg malt til 20 L er urealistisk — trolig en feil i kilden."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-073', 'diydog', '073', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/073.json', 'Sunmaid Stout', 'Rum & Raisin Imperial Stout.', 'stout', 10.2, 50, 1.026, NULL, 197, 20, 'sunmaid stout rum & raisin imperial stout. stout og porter pale ale - tipple chocolate carafa special malt type 3 crystal flaked oats simcoe challenger wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Sunmaid Stout","style":"Stout og porter","description":"Rum & Raisin Imperial Stout.\n\nBrewed by Chris Sartori from Stone Brewing Company in 2010. A dark chocolate stout with dried dark fruit finish. Simcoe provides bitterness with subtle fruity supporting notes, contrasting the chocolate and coffee-laden malt profile. The finish is warming with vanilla and rich dark fruit depth.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Pale Ale - Tipple","type":"grain","amountKg":10},{"id":"f2","name":"Chocolate","type":"grain","amountKg":1.25},{"id":"f3","name":"Carafa Special Malt Type 3","type":"grain","amountKg":0.94},{"id":"f4","name":"Crystal","type":"grain","amountKg":0.94},{"id":"f5","name":"Flaked Oats","type":"grain","amountKg":1.56}],"hops":[{"id":"h1","name":"Simcoe","amountG":37.5,"use":"boil","timeMin":60},{"id":"h2","name":"Challenger","amountG":25,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":74.5}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":55}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.026,"ibu":50,"abvPct":10.2,"colorEbc":197},"notes":"Bryggetips: Take small volume of wort out of the run off and steep the raisins in it, then crush them up. This will help to release the dark fruit aromas into the wort.\n\nTwist: Age in whisky casks with rum soaked raisins\n\nFørst brygget: 12/2011"}', '{"id":73,"name":"Sunmaid Stout","tagline":"Rum & Raisin Imperial Stout.","first_brewed":"12/2011","description":"Brewed by Chris Sartori from Stone Brewing Company in 2010. A dark chocolate stout with dried dark fruit finish. Simcoe provides bitterness with subtle fruity supporting notes, contrasting the chocolate and coffee-laden malt profile. The finish is warming with vanilla and rich dark fruit depth.","image":"keg.png","abv":10.2,"ibu":50,"target_fg":1102,"target_og":1026,"ebc":197,"srm":100,"ph":4.4,"attenuation_level":74.5,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":55}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Age in whisky casks with rum soaked raisins"},"ingredients":{"malt":[{"name":"Pale Ale - Tipple","amount":{"value":10,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":1.25,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":0.94,"unit":"kilograms"}},{"name":"Crystal","amount":{"value":0.94,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":1.56,"unit":"kilograms"}}],"hops":[{"name":"Simcoe","amount":{"value":37.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Challenger","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Lapin aux pruneaux (braised rabbit with prunes)","Gouda cheese","Dark chocolate truffles"],"brewers_tips":"Take small volume of wort out of the run off and steep the raisins in it, then crush them up. This will help to release the dark fruit aromas into the wort.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Malt og OG i kilden gir 12 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %.","14.7 kg malt til 20 L er urealistisk — trolig en feil i kilden."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-074', 'diydog', '074', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/074.json', 'Shareholder Black IPA 2011', 'Shareholder Black IPA.', 'ipa', 7.1, 80, 1.067, 1.014, 71, 20, 'shareholder black ipa 2011 shareholder black ipa. ipa maris otter extra pale caramalt crystal 150 carafa special malt type 1 amarillo columbus chinook columbus cascade centennial centennial cascade amarillo chinook wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Shareholder Black IPA 2011","style":"IPA","description":"Shareholder Black IPA.\n\nBrewed as part of the shareholder brewday at our Fraserburgh brewery. Massively dry hopped and aged on toasted oak chips, this IPA was a riot of lemon, vanilla and roasted malt.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":57,"fermentables":[{"id":"f1","name":"Maris Otter Extra Pale","type":"grain","amountKg":6.57},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.75},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.32},{"id":"f4","name":"Carafa Special Malt Type 1","type":"grain","amountKg":0.5}],"hops":[{"id":"h1","name":"Amarillo","amountG":25,"use":"boil","timeMin":60},{"id":"h2","name":"Columbus","amountG":25,"use":"boil","timeMin":60},{"id":"h3","name":"Chinook","amountG":62.5,"use":"boil","timeMin":0},{"id":"h4","name":"Columbus","amountG":62.5,"use":"boil","timeMin":0},{"id":"h5","name":"Cascade","amountG":62.5,"use":"boil","timeMin":0},{"id":"h6","name":"Centennial","amountG":62.5,"use":"boil","timeMin":0},{"id":"h7","name":"Centennial","amountG":125,"use":"dry_hop"},{"id":"h8","name":"Cascade","amountG":62.5,"use":"dry_hop"},{"id":"h9","name":"Amarillo","amountG":62.5,"use":"dry_hop"},{"id":"h10","name":"Chinook","amountG":62.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":66,"durationMin":90}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.067,"fg":1.014,"ibu":80,"abvPct":7.1,"colorEbc":71},"notes":"Bryggetips: Get as many Equity Punks involved. You can toast the oak chips yourself in an oven.\n\nTwist: Several dozen brewers!, Toasted oak chips: 75g at FV\n\nFørst brygget: 12/2011"}', '{"id":74,"name":"Shareholder Black IPA 2011","tagline":"Shareholder Black IPA.","first_brewed":"12/2011","description":"Brewed as part of the shareholder brewday at our Fraserburgh brewery. Massively dry hopped and aged on toasted oak chips, this IPA was a riot of lemon, vanilla and roasted malt.","image":"keg.png","abv":7.1,"ibu":80,"target_fg":1014,"target_og":1067,"ebc":71,"srm":36,"ph":4.4,"attenuation_level":79,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":66,"unit":"celsius"},"duration":90}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Several dozen brewers!, Toasted oak chips: 75g at FV"},"ingredients":{"malt":[{"name":"Maris Otter Extra Pale","amount":{"value":6.57,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.75,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.32,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":0.5,"unit":"kilograms"}}],"hops":[{"name":"Amarillo","amount":{"value":25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Columbus","amount":{"value":25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Chinook","amount":{"value":62.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Columbus","amount":{"value":62.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Cascade","amount":{"value":62.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Centennial","amount":{"value":62.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Centennial","amount":{"value":125,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Cascade","amount":{"value":62.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Amarillo","amount":{"value":62.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Chinook","amount":{"value":62.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Classic American cheeseburger","Chilli chocolate bars"],"brewers_tips":"Get as many Equity Punks involved. You can toast the oak chips yourself in an oven.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-075', 'diydog', '075', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/075.json', 'AB:13', 'Cask-Aged Cherry Imperial Stout.', 'stout', 11.3, 50, 1.098, 1.02, 164, 20, 'ab:13 cask-aged cherry imperial stout. stout og porter extra pale carafa special malt type 2 flaked oats saaz saaz wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"AB:13","style":"Stout og porter","description":"Cask-Aged Cherry Imperial Stout.\n\nA cherry imperial stout aged in ex- sherry whisky barrels. Based on the classic German Schwarzwald (Black Forest) dessert. Intense dark fruit flavours of cherry, plum, raisin and currant, coupled with deep bitter chocolate, espresso and a full- bodied coffee and cream character.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":49,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":10},{"id":"f2","name":"Carafa Special Malt Type 2","type":"grain","amountKg":1.88},{"id":"f3","name":"Flaked Oats","type":"grain","amountKg":1.88}],"hops":[{"id":"h1","name":"Saaz","amountG":125,"use":"boil","timeMin":60},{"id":"h2","name":"Saaz","amountG":37.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79.6}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":20}],"targets":{"og":1.098,"fg":1.02,"ibu":50,"abvPct":11.3,"colorEbc":164},"notes":"Bryggetips: To mimic the sherry cask ageing character, soak some oak chips in sherry for 48 hours then steep them in the beer after primary fermentation has finished.\n\nTwist: Lactose: 125g at middle, Sour cherries: 187.5g at middle\n\nFørst brygget: 01/2012"}', '{"id":75,"name":"AB:13","tagline":"Cask-Aged Cherry Imperial Stout.","first_brewed":"01/2012","description":"A cherry imperial stout aged in ex- sherry whisky barrels. Based on the classic German Schwarzwald (Black Forest) dessert. Intense dark fruit flavours of cherry, plum, raisin and currant, coupled with deep bitter chocolate, espresso and a full- bodied coffee and cream character.","image":"075.png","abv":11.3,"ibu":50,"target_fg":1020,"target_og":1098,"ebc":164,"srm":83,"ph":4.4,"attenuation_level":79.6,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":20,"unit":"celsius"}},"twist":"Lactose: 125g at middle, Sour cherries: 187.5g at middle"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":10,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 2","amount":{"value":1.88,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":1.88,"unit":"kilograms"}}],"hops":[{"name":"Saaz","amount":{"value":125,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Saaz","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Pheasant paté","Roast duck in a cherry glaze","Chocolate torte with a dark fruit compote"],"brewers_tips":"To mimic the sherry cask ageing character, soak some oak chips in sherry for 48 hours then steep them in the beer after primary fermentation has finished.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min.","13.8 kg malt til 20 L er urealistisk — trolig en feil i kilden."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-076', 'diydog', '076', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/076.json', 'Simcoe', 'Single Hop India Pale Ale.', 'ipa', 6.7, 70, 1.063, 1.012, 30, 20, 'simcoe single hop india pale ale. ipa extra pale caramalt dark crystal munich simcoe simcoe simcoe simcoe wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Simcoe","style":"IPA","description":"Single Hop India Pale Ale.\n\nA special release of our IPA is Dead series - IPA is Dead Simoce. Hopped to hell with citrusy bitter and aroma hops from the West Coast of the USA. Bitter, orange, mandarin, floral, this IPA showcases the best the west has to offer.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":80,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":4.75},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.32},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.06},{"id":"f4","name":"Munich","type":"grain","amountKg":0.32}],"hops":[{"id":"h1","name":"Simcoe","amountG":2.5,"use":"boil","timeMin":60},{"id":"h2","name":"Simcoe","amountG":25,"use":"boil","timeMin":30},{"id":"h3","name":"Simcoe","amountG":37.5,"use":"boil","timeMin":0},{"id":"h4","name":"Simcoe","amountG":250,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":81}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[],"targets":{"og":1.063,"fg":1.012,"ibu":70,"abvPct":6.7,"colorEbc":30},"notes":"Bryggetips: Get the freshest Simcoe for the best profile.\n\nFørst brygget: 01/2012"}', '{"id":76,"name":"Simcoe","tagline":"Single Hop India Pale Ale.","first_brewed":"01/2012","description":"A special release of our IPA is Dead series - IPA is Dead Simoce. Hopped to hell with citrusy bitter and aroma hops from the West Coast of the USA. Bitter, orange, mandarin, floral, this IPA showcases the best the west has to offer.","image":"076.png","abv":6.7,"ibu":70,"target_fg":1012,"target_og":1063,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":81,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":99,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":4.75,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.32,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.06,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.32,"unit":"kilograms"}}],"hops":[{"name":"Simcoe","amount":{"value":2.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Simcoe","amount":{"value":25,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Simcoe","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Simcoe","amount":{"value":250,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Beer roasted chicken","Ham and pineapple pizza","Chocolate cake drizzled with orange"],"brewers_tips":"Get the freshest Simcoe for the best profile.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min.","Gjæringstemperaturen 99 °C i kilden er åpenbart feil; utelatt."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-077', 'diydog', '077', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/077.json', 'Libertine Porter', 'Dry-Hopped Aggressive Porter.', 'stout', 6.1, 45, 1.067, 1.02, 219, 20, 'libertine porter dry-hopped aggressive porter. stout og porter extra pale - spring blend caramalt crystal 150 chocolate roasted barley wheat flaked oats smoked malt columbus columbus willamette galena columbus galena simcoe wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Libertine Porter","style":"Stout og porter","description":"Dry-Hopped Aggressive Porter.\n\nAn avalanche of cross-continental hop varieties give this porter a complex spicy, resinous and citrusy aroma, with a huge malt bill providing a complex roasty counterpoint. Digging deeper into the flavour draws out cinder toffee, bitter chocolate and hints of woodsmoke.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":53,"fermentables":[{"id":"f1","name":"Extra Pale - Spring Blend","type":"grain","amountKg":5},{"id":"f2","name":"Caramalt","type":"grain","amountKg":1.25},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.63},{"id":"f4","name":"Chocolate","type":"grain","amountKg":0.63},{"id":"f5","name":"Roasted Barley","type":"grain","amountKg":0.63},{"id":"f6","name":"Wheat","type":"grain","amountKg":0.31},{"id":"f7","name":"Flaked Oats","type":"grain","amountKg":0.31},{"id":"f8","name":"Smoked Malt","type":"grain","amountKg":0.06}],"hops":[{"id":"h1","name":"Columbus","amountG":31.3,"use":"boil","timeMin":60},{"id":"h2","name":"Columbus","amountG":25,"use":"boil","timeMin":0},{"id":"h3","name":"Willamette","amountG":25,"use":"boil","timeMin":0},{"id":"h4","name":"Galena","amountG":25,"use":"boil","timeMin":0},{"id":"h5","name":"Columbus","amountG":75,"use":"dry_hop"},{"id":"h6","name":"Galena","amountG":75,"use":"dry_hop"},{"id":"h7","name":"Simcoe","amountG":100,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":70.1}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":68,"durationMin":35}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":18}],"targets":{"og":1.067,"fg":1.02,"ibu":45,"abvPct":6.1,"colorEbc":219},"notes":"Bryggetips: Mash in at a higher temperature to leave more unfermentable sugars in the wort. This gives the beer a sweeter porter profile.\n\nFørst brygget: 01/2012"}', '{"id":77,"name":"Libertine Porter","tagline":"Dry-Hopped Aggressive Porter.","first_brewed":"01/2012","description":"An avalanche of cross-continental hop varieties give this porter a complex spicy, resinous and citrusy aroma, with a huge malt bill providing a complex roasty counterpoint. Digging deeper into the flavour draws out cinder toffee, bitter chocolate and hints of woodsmoke.","image":"077.png","abv":6.1,"ibu":45,"target_fg":1020,"target_og":1067,"ebc":219,"srm":109.5,"ph":4.4,"attenuation_level":70.1,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":68,"unit":"celsius"},"duration":35}],"fermentation":{"temp":{"value":18,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale - Spring Blend","amount":{"value":5,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":1.25,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Roasted Barley","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Smoked Malt","amount":{"value":0.06,"unit":"kilograms"}}],"hops":[{"name":"Columbus","amount":{"value":31.25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Columbus","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"bitter"},{"name":"Willamette","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Galena","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Columbus","amount":{"value":75,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Galena","amount":{"value":75,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Simcoe","amount":{"value":100,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Blue cheese beef burger","Glazed short ribs","Chocolate cake"],"brewers_tips":"Mash in at a higher temperature to leave more unfermentable sugars in the wort. This gives the beer a sweeter porter profile.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-078', 'diydog', '078', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/078.json', 'Mixtape 8', 'An Epic Fusion Of Old Belgian, American New Wave, And Scotch Whisky.', 'belgian', 14.5, 50, 1.093, 1.014, 40, 20, 'mixtape 8 an epic fusion of old belgian, american new wave, and scotch whisky. belgisk og saison pale ale - tipple caramalt crystal columbus extract centennial cascade simcoe wyeast 3522 - belgian ardennes™', '{"schemaVersion":1,"name":"Mixtape 8","style":"Belgisk og saison","description":"An Epic Fusion Of Old Belgian, American New Wave, And Scotch Whisky.\n\nThis recipe is for the Belgian Tripel base. A blend of two huge oak aged beers – half a hopped up Belgian Tripel, and half a Triple India Pale Ale. Both aged in single grain whisky barrels for two years and blended, each beer brings its own character to the mix. The Belgian Tripel comes loaded with complex spicy, fruity esters, and punchy citrus hop character.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":52,"fermentables":[{"id":"f1","name":"Pale Ale - Tipple","type":"grain","amountKg":11.1},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.94},{"id":"f3","name":"Crystal","type":"grain","amountKg":0.44}],"hops":[{"id":"h1","name":"Columbus Extract","amountG":12.5,"use":"boil","timeMin":60},{"id":"h2","name":"Centennial","amountG":37.5,"use":"boil","timeMin":0},{"id":"h3","name":"Cascade","amountG":37.5,"use":"boil","timeMin":0},{"id":"h4","name":"Simcoe","amountG":37.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 3522 - Belgian Ardennes™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":85}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":40}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.093,"fg":1.014,"ibu":50,"abvPct":14.5,"colorEbc":40},"notes":"Bryggetips: Brew twice as much Belgian Tripel as you were planning on ageing - it''s awesome on its own too!\n\nTwist: Barrel aged and blended with Anarchist Alchemist\n\nFørst brygget: 01/2012"}', '{"id":78,"name":"Mixtape 8","tagline":"An Epic Fusion Of Old Belgian, American New Wave, And Scotch Whisky.","first_brewed":"01/2012","description":"This recipe is for the Belgian Tripel base. A blend of two huge oak aged beers – half a hopped up Belgian Tripel, and half a Triple India Pale Ale. Both aged in single grain whisky barrels for two years and blended, each beer brings its own character to the mix. The Belgian Tripel comes loaded with complex spicy, fruity esters, and punchy citrus hop character.","image":"078.png","abv":14.5,"ibu":50,"target_fg":1014,"target_og":1093,"ebc":40,"srm":20,"ph":4.4,"attenuation_level":85,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":40}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Barrel aged and blended with Anarchist Alchemist"},"ingredients":{"malt":[{"name":"Pale Ale - Tipple","amount":{"value":11.1,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.94,"unit":"kilograms"}},{"name":"Crystal","amount":{"value":0.44,"unit":"kilograms"}}],"hops":[{"name":"Columbus Extract","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Centennial","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Cascade","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Simcoe","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 3522 - Belgian Ardennes™"},"food_pairing":["Coriander & chilli crab cakes","Goats cheese salad with walnuts, radish and blood orange","Pistachio cake"],"brewers_tips":"Brew twice as much Belgian Tripel as you were planning on ageing - it''s awesome on its own too!","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","OG/FG i kilden gir 10.4 % ABV, men oppgitt ABV er 14.5 % — sjekk tallene.","12.5 kg malt til 20 L er urealistisk — trolig en feil i kilden."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-079', 'diydog', '079', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/079.json', 'Bitch Please (w/ 3 Floyds)', 'Barley Wine - 3 Floyds Collab.', 'strong', 11.5, 50, 1.104, 1.016, 38, 20, 'bitch please (w/ 3 floyds) barley wine - 3 floyds collab. sterkt øl extra pale pinhead oats carahell caraaroma roasted malt peated malt green bullet motueka pacific gem nelson sauvin wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Bitch Please (w/ 3 Floyds)","style":"Sterkt øl","description":"Barley Wine - 3 Floyds Collab.\n\nThis limited edition American Barley Wine was brewed in collaboration with 3 Floyds Brewery. This beer had all the warm, boozy and smoky aspects of an Islay Scotch whisky with the sweet malt and devastatingly bitter attributes of a barley wine. Peat smoke features prominently, backed up with a complex fruity hop profile.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":79,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":8.21},{"id":"f2","name":"Pinhead Oats","type":"grain","amountKg":0.36},{"id":"f3","name":"Carahell","type":"grain","amountKg":0.18},{"id":"f4","name":"CaraAroma","type":"grain","amountKg":0.18},{"id":"f5","name":"Roasted Malt","type":"grain","amountKg":0.09},{"id":"f6","name":"Peated Malt","type":"grain","amountKg":0.09}],"hops":[{"id":"h1","name":"Green Bullet","amountG":50,"use":"boil","timeMin":60},{"id":"h2","name":"Motueka","amountG":35.5,"use":"boil","timeMin":0},{"id":"h3","name":"Pacific Gem","amountG":21.5,"use":"boil","timeMin":0},{"id":"h4","name":"Nelson Sauvin","amountG":7,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":85}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.104,"fg":1.016,"ibu":50,"abvPct":11.5,"colorEbc":38},"notes":"Bryggetips: To add to the smoky nature of this Barley Wine, source some smoked wood or whisky casks to age the beer in.\n\nTwist: Two bars of Highland Toffee at start of boil\n\nFørst brygget: 02/2012"}', '{"id":79,"name":"Bitch Please (w/ 3 Floyds)","tagline":"Barley Wine - 3 Floyds Collab.","first_brewed":"02/2012","description":"This limited edition American Barley Wine was brewed in collaboration with 3 Floyds Brewery. This beer had all the warm, boozy and smoky aspects of an Islay Scotch whisky with the sweet malt and devastatingly bitter attributes of a barley wine. Peat smoke features prominently, backed up with a complex fruity hop profile.","image":"079.png","abv":11.5,"ibu":50,"target_fg":1016,"target_og":1104,"ebc":38,"srm":19,"ph":4.4,"attenuation_level":85,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Two bars of Highland Toffee at start of boil"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":8.21,"unit":"kilograms"}},{"name":"Pinhead Oats","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Carahell","amount":{"value":0.18,"unit":"kilograms"}},{"name":"CaraAroma","amount":{"value":0.18,"unit":"kilograms"}},{"name":"Roasted Malt","amount":{"value":0.09,"unit":"kilograms"}},{"name":"Peated Malt","amount":{"value":0.09,"unit":"kilograms"}}],"hops":[{"name":"Green Bullet","amount":{"value":50,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Motueka","amount":{"value":35.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Pacific Gem","amount":{"value":21.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Nelson Sauvin","amount":{"value":7,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Stilton Blue featured cheese platter","Dark bitter chocolate torte","Scotch bonnet beef chilli"],"brewers_tips":"To add to the smoky nature of this Barley Wine, source some smoked wood or whisky casks to age the beer in.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-080', 'diydog', '080', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/080.json', 'Challenger', 'Single Hop India Pale Ale – 2012.', 'ipa', 6.7, 67, 1.064, 1.013, 19, 20, 'challenger single hop india pale ale – 2012. ipa extra pale - spring blend caramalt crystal 150 challenger challenger challenger wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Challenger","style":"IPA","description":"Single Hop India Pale Ale – 2012.\n\nChallenger is known for its herbal and fruity characteristics. When used alone in a beer like IPA is Dead, Challenger brings light woodsy notes, floral hints, and delicate green tea, alongside more recognisable citrus notes. As a dual-purpose hop, it also yields great bittering potential, which is ideal in a dry bitter IPA.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":69,"fermentables":[{"id":"f1","name":"Extra Pale - Spring Blend","type":"grain","amountKg":5.87},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.37},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.19}],"hops":[{"id":"h1","name":"Challenger","amountG":85,"use":"boil","timeMin":60},{"id":"h2","name":"Challenger","amountG":100,"use":"boil","timeMin":0},{"id":"h3","name":"Challenger","amountG":250,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79.7}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":68,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.064,"fg":1.013,"ibu":67,"abvPct":6.7,"colorEbc":19},"notes":"Bryggetips: Challenger hops come from English hops farms - try getting hold of some fresh, undried hops and make a \"wet hop\" beer.\n\nFørst brygget: 02/2012"}', '{"id":80,"name":"Challenger","tagline":"Single Hop India Pale Ale – 2012.","first_brewed":"02/2012","description":"Challenger is known for its herbal and fruity characteristics. When used alone in a beer like IPA is Dead, Challenger brings light woodsy notes, floral hints, and delicate green tea, alongside more recognisable citrus notes. As a dual-purpose hop, it also yields great bittering potential, which is ideal in a dry bitter IPA.","image":"080.png","abv":6.7,"ibu":67,"target_fg":1013,"target_og":1064,"ebc":19,"srm":9.5,"ph":4.4,"attenuation_level":79.7,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":68,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale - Spring Blend","amount":{"value":5.87,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.37,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.19,"unit":"kilograms"}}],"hops":[{"name":"Challenger","amount":{"value":85,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Challenger","amount":{"value":100,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Challenger","amount":{"value":250,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Caramelized onion and steak pie","Chicken Khua Kling (dry Thai curry)","Lemon drizzle cake"],"brewers_tips":"Challenger hops come from English hops farms - try getting hold of some fresh, undried hops and make a \"wet hop\" beer.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-081', 'diydog', '081', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/081.json', 'Galaxy', 'Single Hop India Pale Ale – 2012.', 'ipa', 6.7, 67, 1.013, NULL, 19, 20, 'galaxy single hop india pale ale – 2012. ipa extra pale - spring blend caramalt crystal 150 galaxy galaxy galaxy wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Galaxy","style":"IPA","description":"Single Hop India Pale Ale – 2012.\n\nWith all the rich tropical flavour you''d expect from Australia''s Galaxy, this beer backs up a strong citrus aroma and flavour with a mellow undercurrent of passion fruit and mango. Zingy and sweet but not too sweet, Galaxy has a soft and inviting fruity hop character.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Extra Pale - Spring Blend","type":"grain","amountKg":5.87},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.37},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.19}],"hops":[{"id":"h1","name":"Galaxy","amountG":75.4,"use":"boil","timeMin":60},{"id":"h2","name":"Galaxy","amountG":75.4,"use":"boil","timeMin":0},{"id":"h3","name":"Galaxy","amountG":250,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79.7}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":68,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.013,"ibu":67,"abvPct":6.7,"colorEbc":19},"notes":"Bryggetips: Use fresh Galaxy for the best flavour profile.\n\nFørst brygget: 02/2012"}', '{"id":81,"name":"Galaxy","tagline":"Single Hop India Pale Ale – 2012.","first_brewed":"02/2012","description":"With all the rich tropical flavour you''d expect from Australia''s Galaxy, this beer backs up a strong citrus aroma and flavour with a mellow undercurrent of passion fruit and mango. Zingy and sweet but not too sweet, Galaxy has a soft and inviting fruity hop character.","image":"081.png","abv":6.7,"ibu":67,"target_fg":1064,"target_og":1013,"ebc":19,"srm":9.5,"ph":4.4,"attenuation_level":79.7,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":68,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale - Spring Blend","amount":{"value":5.87,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.37,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.19,"unit":"kilograms"}}],"hops":[{"name":"Galaxy","amount":{"value":75.4,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Galaxy","amount":{"value":75.4,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Galaxy","amount":{"value":250,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Spicy green chilli and lemongrass chicken thai curry","Sharp cheddar cheese and crackers","Ginger and orange zest cookies"],"brewers_tips":"Use fresh Galaxy for the best flavour profile.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min.","Malt og OG i kilden gir 14 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-082', 'diydog', '082', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/082.json', 'HBC 369', 'Single Hop India Pale Ale – 2012.', 'ipa', 6.7, 67, 1.013, NULL, 19, 20, 'hbc 369 single hop india pale ale – 2012. ipa extra pale - spring blend caramalt crystal 150 hbc 369 hbc 369 hbc 369 wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"HBC 369","style":"IPA","description":"Single Hop India Pale Ale – 2012.\n\nHBC 369 brings rich fruity flavours with the tiniest layer of candy coating on top. HBC 369 (the hop) can bring notes of blueberries, pear, and possibly even sweet potato. HBC 369 (the beer) was balanced, with just one hop providing a complex aroma, and a dry bitterness.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Extra Pale - Spring Blend","type":"grain","amountKg":5.87},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.37},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.19}],"hops":[{"id":"h1","name":"HBC 369","amountG":40,"use":"boil","timeMin":60},{"id":"h2","name":"HBC 369","amountG":100,"use":"boil","timeMin":0},{"id":"h3","name":"HBC 369","amountG":250,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79.7}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":68,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.013,"ibu":67,"abvPct":6.7,"colorEbc":19},"notes":"Bryggetips: HBC 369 is now known as Mosaic!\n\nFørst brygget: 02/2012"}', '{"id":82,"name":"HBC 369","tagline":"Single Hop India Pale Ale – 2012.","first_brewed":"02/2012","description":"HBC 369 brings rich fruity flavours with the tiniest layer of candy coating on top. HBC 369 (the hop) can bring notes of blueberries, pear, and possibly even sweet potato. HBC 369 (the beer) was balanced, with just one hop providing a complex aroma, and a dry bitterness.","image":"082.png","abv":6.7,"ibu":67,"target_fg":1064,"target_og":1013,"ebc":19,"srm":9.5,"ph":4.4,"attenuation_level":79.7,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":68,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale - Spring Blend","amount":{"value":5.87,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.37,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.19,"unit":"kilograms"}}],"hops":[{"name":"HBC 369","amount":{"value":40,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"HBC 369","amount":{"value":100,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"HBC 369","amount":{"value":250,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Spicy jalapeño & seared steak fajitas","Grilled spicy corn with feta crumbles","Blueberry pie"],"brewers_tips":"HBC 369 is now known as Mosaic!","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min.","Malt og OG i kilden gir 14 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-083', 'diydog', '083', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/083.json', 'Motueka', 'Single Hop India Pale Ale – 2012.', 'ipa', 6.7, 67, 1.013, NULL, 19, 20, 'motueka single hop india pale ale – 2012. ipa extra pale - spring blend caramalt crystal 150 motueka motueka motueka wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Motueka","style":"IPA","description":"Single Hop India Pale Ale – 2012.\n\nLemon and lime rise to the top of this hoppy brew, with supporting acts of tropical fruit for a very rounded, thoroughly satisfying flavour. Motueka is a hop we''ve used in loads of recipes; it has enough resin to balance the intense fruity character.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Extra Pale - Spring Blend","type":"grain","amountKg":5.87},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.37},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.19}],"hops":[{"id":"h1","name":"Motueka","amountG":75,"use":"boil","timeMin":60},{"id":"h2","name":"Motueka","amountG":100,"use":"boil","timeMin":0},{"id":"h3","name":"Motueka","amountG":250,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79.7}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":68,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.013,"ibu":67,"abvPct":6.7,"colorEbc":19},"notes":"Bryggetips: Be careful with the Motueka additions. It has an intense citrus character that is often tempered by using in conjunction with other hops.\n\nFørst brygget: 02/2012"}', '{"id":83,"name":"Motueka","tagline":"Single Hop India Pale Ale – 2012.","first_brewed":"02/2012","description":"Lemon and lime rise to the top of this hoppy brew, with supporting acts of tropical fruit for a very rounded, thoroughly satisfying flavour. Motueka is a hop we''ve used in loads of recipes; it has enough resin to balance the intense fruity character.","image":"083.png","abv":6.7,"ibu":67,"target_fg":1064,"target_og":1013,"ebc":19,"srm":9.5,"ph":4.4,"attenuation_level":79.7,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":68,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale - Spring Blend","amount":{"value":5.87,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.37,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.19,"unit":"kilograms"}}],"hops":[{"name":"Motueka","amount":{"value":75,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Motueka","amount":{"value":100,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Motueka","amount":{"value":250,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Tofu pad Thai with fresh lime juice and coriander","Fish tacos with avocado","Key lime pie"],"brewers_tips":"Be careful with the Motueka additions. It has an intense citrus character that is often tempered by using in conjunction with other hops.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min.","Malt og OG i kilden gir 14 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-084', 'diydog', '084', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/084.json', 'Dead Pony Club', 'West Coast Kicks. Citrusy. Zesty. Bright.', 'ipa', 3.8, 35, 1.04, 1.012, 25, 20, 'dead pony club west coast kicks. citrusy. zesty. bright. ipa extra pale caramalt crystal 150 simcoe citra simcoe citra simcoe citra mosaic wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Dead Pony Club","style":"IPA","description":"West Coast Kicks. Citrusy. Zesty. Bright.\n\nOur California style West Coast IPA has light toffee and caramel notes layered on biscuit malt, supporting a huge, fresh citrus aroma, with lemongrass, lime zest, grapefruit peel, alongside some tropical notes, courtesy of some heavy-hitting US hops.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":77,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":2.79},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.63},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.19}],"hops":[{"id":"h1","name":"Simcoe","amountG":5,"use":"boil","timeMin":60},{"id":"h2","name":"Citra","amountG":5,"use":"boil","timeMin":60},{"id":"h3","name":"Simcoe","amountG":5,"use":"boil","timeMin":30},{"id":"h4","name":"Citra","amountG":5,"use":"boil","timeMin":30},{"id":"h5","name":"Simcoe","amountG":50,"use":"dry_hop"},{"id":"h6","name":"Citra","amountG":75,"use":"dry_hop"},{"id":"h7","name":"Mosaic","amountG":62.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":70}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":62,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.04,"fg":1.012,"ibu":35,"abvPct":3.8,"colorEbc":25},"notes":"Bryggetips: It may be tempting to throw extra (extra) hops at Dead Pony Club, but try adding a little at a time to consecutive brews rather than cramming in loads extra on your first time.\n\nFørst brygget: 03/2012"}', '{"id":84,"name":"Dead Pony Club","tagline":"West Coast Kicks. Citrusy. Zesty. Bright.","first_brewed":"03/2012","description":"Our California style West Coast IPA has light toffee and caramel notes layered on biscuit malt, supporting a huge, fresh citrus aroma, with lemongrass, lime zest, grapefruit peel, alongside some tropical notes, courtesy of some heavy-hitting US hops.","image":"084.png","abv":3.8,"ibu":35,"target_fg":1012,"target_og":1040,"ebc":25,"srm":12.7,"ph":4.4,"attenuation_level":70,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":62,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":2.79,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.19,"unit":"kilograms"}}],"hops":[{"name":"Simcoe","amount":{"value":5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Citra","amount":{"value":5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Simcoe","amount":{"value":5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Citra","amount":{"value":5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Simcoe","amount":{"value":50,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Citra","amount":{"value":75,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Mosaic","amount":{"value":62.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Baja style fish tacos","Jerk chicken","Apple crumble"],"brewers_tips":"It may be tempting to throw extra (extra) hops at Dead Pony Club, but try adding a little at a time to consecutive brews rather than cramming in loads extra on your first time.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-085', 'diydog', '085', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/085.json', 'Libertine Black Ale', 'The New Black. Roasty. Hoppy. Fruity.', 'ipa', 7.2, 50, 1.068, 1.013, 150, 20, 'libertine black ale the new black. roasty. hoppy. fruity. ipa extra pale caramalt crystal 150 carafa special malt type 1 carafa special malt type 3 simcoe simcoe simcoe simcoe cascade mosaic wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Libertine Black Ale","style":"IPA","description":"The New Black. Roasty. Hoppy. Fruity.\n\nA dark hop bomb combining the malt-forward indulgences of a stout with the insatiable hopload of an IPA. Rich spiced blackcurrant and caramel up front, with a sharp bitter finish following behind, bringing grapefruit and resin with it. Dry, bitter and intense; this is an IPA first and foremost, given a dark malt makeover. Originally brewed as a Simcoe only single hop IPA, we''ve experimented with adding a little Cascade and Mosaic for extra depth.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":78,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5.3},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.25},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.19},{"id":"f4","name":"Carafa Special Malt Type 1","type":"grain","amountKg":0.13},{"id":"f5","name":"Carafa Special Malt Type 3","type":"grain","amountKg":0.19}],"hops":[{"id":"h1","name":"Simcoe","amountG":18.8,"use":"boil","timeMin":60},{"id":"h2","name":"Simcoe","amountG":18.8,"use":"boil","timeMin":30},{"id":"h3","name":"Simcoe","amountG":37.5,"use":"boil","timeMin":0},{"id":"h4","name":"Simcoe","amountG":175,"use":"dry_hop"},{"id":"h5","name":"Cascade","amountG":37.5,"use":"dry_hop"},{"id":"h6","name":"Mosaic","amountG":37.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":78.6}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.068,"fg":1.013,"ibu":50,"abvPct":7.2,"colorEbc":150},"notes":"Bryggetips: The goal here is to make a black beer that tastes like an IPA. Don''t overload the black or roasted malts to try and achieve the correct colour. Too much roasted malts will suppress far too much of that beautiful citrus and tropical flavour from the Simcoe. It may be hard to get hold of Carafa, but it will allow you to get a great colour, without all of the characteristic roasty astringent flavours.\n\nFørst brygget: 03/2012"}', '{"id":85,"name":"Libertine Black Ale","tagline":"The New Black. Roasty. Hoppy. Fruity.","first_brewed":"03/2012","description":"A dark hop bomb combining the malt-forward indulgences of a stout with the insatiable hopload of an IPA. Rich spiced blackcurrant and caramel up front, with a sharp bitter finish following behind, bringing grapefruit and resin with it. Dry, bitter and intense; this is an IPA first and foremost, given a dark malt makeover. Originally brewed as a Simcoe only single hop IPA, we''ve experimented with adding a little Cascade and Mosaic for extra depth.","image":"085.png","abv":7.2,"ibu":50,"target_fg":1013,"target_og":1068,"ebc":150,"srm":76,"ph":4.4,"attenuation_level":78.6,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5.3,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.19,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":0.13,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":0.19,"unit":"kilograms"}}],"hops":[{"name":"Simcoe","amount":{"value":18.75,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Simcoe","amount":{"value":18.75,"unit":"grams"},"add":"middle","attribute":"bitter"},{"name":"Simcoe","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Simcoe","amount":{"value":175,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Cascade","amount":{"value":37.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Mosaic","amount":{"value":37.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Grilled king prawns with a chilli lime sauce","Blue cheese burger","Flourless chocolate ginger cake"],"brewers_tips":"The goal here is to make a black beer that tastes like an IPA. Don''t overload the black or roasted malts to try and achieve the correct colour. Too much roasted malts will suppress far too much of that beautiful citrus and tropical flavour from the Simcoe. It may be hard to get hold of Carafa, but it will allow you to get a great colour, without all of the characteristic roasty astringent flavours.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-086', 'diydog', '086', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/086.json', 'Anarchist Alchemist', 'Triple Hopped Triple Ipa.', 'ipa', 16.5, 20.5, 1.112, 1, 20, 20, 'anarchist alchemist triple hopped triple ipa. ipa extra pale nelson sauvin centennial nelson sauvin amarillo centennial nelson sauvin amarillo centennial wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Anarchist Alchemist","style":"IPA","description":"Triple Hopped Triple Ipa.\n\nAbout as far as you can push an IPA; Anarchist Alchemist packs in three times the malt and three of our favourite hops. Nelson Sauvin, Amarillo and Centennial bring a range of flavours, touching on tropical fruit, white grape, tangerine, grapefruit, pine, spiced orange... the list goes on!","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":62,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":12.5}],"hops":[{"id":"h1","name":"Nelson Sauvin","amountG":6.3,"use":"boil","timeMin":60},{"id":"h2","name":"Centennial","amountG":12.5,"use":"boil","timeMin":60},{"id":"h3","name":"Nelson Sauvin","amountG":12.5,"use":"boil","timeMin":0},{"id":"h4","name":"Amarillo","amountG":12.5,"use":"boil","timeMin":0},{"id":"h5","name":"Centennial","amountG":12.5,"use":"boil","timeMin":0},{"id":"h6","name":"Nelson Sauvin","amountG":12.5,"use":"dry_hop"},{"id":"h7","name":"Amarillo","amountG":12.5,"use":"dry_hop"},{"id":"h8","name":"Centennial","amountG":12.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":100}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":20}],"targets":{"og":1.112,"fg":1,"ibu":20.5,"abvPct":16.5,"colorEbc":20},"notes":"Bryggetips: The biggest challenge with this beer is getting it to ferment out entirely. Hold mash temp at 65°C for 90 mins to ensure maximum fermentability. Use super high gravity yeast or champagne yeast to achieve the last few gravity points.\n\nFørst brygget: 03/2012"}', '{"id":86,"name":"Anarchist Alchemist","tagline":"Triple Hopped Triple Ipa.","first_brewed":"03/2012","description":"About as far as you can push an IPA; Anarchist Alchemist packs in three times the malt and three of our favourite hops. Nelson Sauvin, Amarillo and Centennial bring a range of flavours, touching on tropical fruit, white grape, tangerine, grapefruit, pine, spiced orange... the list goes on!","image":"086.png","abv":16.5,"ibu":20.5,"target_fg":1000,"target_og":1112,"ebc":20,"srm":10,"ph":4.4,"attenuation_level":100,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":20,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":12.5,"unit":"kilograms"}}],"hops":[{"name":"Nelson Sauvin","amount":{"value":6.25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Centennial","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Nelson Sauvin","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Amarillo","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Centennial","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Nelson Sauvin","amount":{"value":12.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Amarillo","amount":{"value":12.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Centennial","amount":{"value":12.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Blue cheese & onion tart","Goan goat curry","Sugar-poached kumquat rice pudding"],"brewers_tips":"The biggest challenge with this beer is getting it to ferment out entirely. Hold mash temp at 65°C for 90 mins to ensure maximum fermentability. Use super high gravity yeast or champagne yeast to achieve the last few gravity points.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","OG/FG i kilden gir 14.7 % ABV, men oppgitt ABV er 16.5 % — sjekk tallene.","12.5 kg malt til 20 L er urealistisk — trolig en feil i kilden."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-087', 'diydog', '087', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/087.json', 'Dog A', 'Cacao, Coffee, Chili Imperial Anniversary Stout.', 'stout', 15, 90, 1.12, 1.003, 100, 20, 'dog a cacao, coffee, chili imperial anniversary stout. stout og porter extra pale wheat flaked oats dark crystal carafa special malt type 1 carafa special malt type 3 honey chinook cascade fuggles coffee beans fuggles coffee beans wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Dog A","style":"Stout og porter","description":"Cacao, Coffee, Chili Imperial Anniversary Stout.\n\nOur anniversary stout was based on AB:04, one of our most sought after beers ever. This beer is slightly different each year, with subtle variations coming into play purely down to environmental and fermentation factors. What doesn''t change is the rich dark chocolate, bitter coffee and chili warmth of this monumental stout.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":63,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":8},{"id":"f2","name":"Wheat","type":"grain","amountKg":0.5},{"id":"f3","name":"Flaked Oats","type":"grain","amountKg":1.38},{"id":"f4","name":"Dark Crystal","type":"grain","amountKg":0.88},{"id":"f5","name":"Carafa Special Malt Type 1","type":"grain","amountKg":0.63},{"id":"f6","name":"Carafa Special Malt Type 3","type":"grain","amountKg":0.63},{"id":"f7","name":"Honey","type":"sugar","amountKg":0.7}],"hops":[{"id":"h1","name":"Chinook","amountG":50,"use":"boil","timeMin":60},{"id":"h2","name":"Cascade","amountG":25,"use":"boil","timeMin":60},{"id":"h3","name":"Fuggles","amountG":25,"use":"boil","timeMin":30},{"id":"h5","name":"Fuggles","amountG":25,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":98}],"miscs":[{"id":"x4","name":"Coffee beans","amount":12.5,"unit":"g","use":"boil","timeMin":30},{"id":"x6","name":"Coffee beans","amount":12.5,"unit":"g","use":"boil","timeMin":0}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":90}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.12,"fg":1.003,"ibu":90,"abvPct":15,"colorEbc":100},"notes":"Bryggetips: Be really careful when mashing, as this amount of malt can get tough to sparge! Add honey into the boil, and naga chili and vanilla in maturation (soak them in some neutral spirit to sanitise)\n\nTwist: Based on AB:04, but with added vanilla and 3.5 times the chili.\n\nFørst brygget: 05/2012"}', '{"id":87,"name":"Dog A","tagline":"Cacao, Coffee, Chili Imperial Anniversary Stout.","first_brewed":"05/2012","description":"Our anniversary stout was based on AB:04, one of our most sought after beers ever. This beer is slightly different each year, with subtle variations coming into play purely down to environmental and fermentation factors. What doesn''t change is the rich dark chocolate, bitter coffee and chili warmth of this monumental stout.","image":"087.png","abv":15,"ibu":90,"target_fg":1003,"target_og":1120,"ebc":100,"srm":50,"ph":4.4,"attenuation_level":98,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":90}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Based on AB:04, but with added vanilla and 3.5 times the chili."},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":8,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":1.38,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.88,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Honey","amount":{"value":0.7,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":50,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Cascade","amount":{"value":25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Fuggles","amount":{"value":25,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Coffee beans","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Fuggles","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Coffee beans","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"twist"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Blackened cajun beef","Cave-aged cheddar","Flourless chocolate chilli cake"],"brewers_tips":"Be really careful when mashing, as this amount of malt can get tough to sparge! Add honey into the boil, and naga chili and vanilla in maturation (soak them in some neutral spirit to sanitise)","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","12.7 kg malt til 20 L er urealistisk — trolig en feil i kilden."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-088', 'diydog', '088', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/088.json', 'Hunter Foundation Pale Ale', 'American Pale Ale.', 'pale', 5.4, 35, 1.05, 1.008, 11.5, 20, 'hunter foundation pale ale american pale ale. pale ale maris otter extra pale munich amarillo simcoe amarillo citra wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Hunter Foundation Pale Ale","style":"Pale ale","description":"American Pale Ale.\n\nThis straight-up US style pale ale uses some of our favourite hops against a toasty malt base. We brewed this with Sir Tom Hunter at our Fraserburgh brewery - to add a charitable element to your own version, feel free to share this citrusy pale ale with your friends. Or don''t, it''s your choice.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":68,"fermentables":[{"id":"f1","name":"Maris Otter Extra Pale","type":"grain","amountKg":4.3},{"id":"f2","name":"Munich","type":"grain","amountKg":0.8}],"hops":[{"id":"h1","name":"Amarillo","amountG":10,"use":"boil","timeMin":60},{"id":"h2","name":"Simcoe","amountG":15,"use":"boil","timeMin":60},{"id":"h3","name":"Amarillo","amountG":25,"use":"boil","timeMin":0},{"id":"h4","name":"Citra","amountG":20,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":84}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":63,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.05,"fg":1.008,"ibu":35,"abvPct":5.4,"colorEbc":11.5},"notes":"Bryggetips: To dry the beer out, mash at a slightly lower temp (62° - 63°C), this will increase the ratio of fermentable sugars in the beer.\n\nFørst brygget: 05/2012"}', '{"id":88,"name":"Hunter Foundation Pale Ale","tagline":"American Pale Ale.","first_brewed":"05/2012","description":"This straight-up US style pale ale uses some of our favourite hops against a toasty malt base. We brewed this with Sir Tom Hunter at our Fraserburgh brewery - to add a charitable element to your own version, feel free to share this citrusy pale ale with your friends. Or don''t, it''s your choice.","image":"088.png","abv":5.4,"ibu":35,"target_fg":1008,"target_og":1050,"ebc":11.5,"srm":5.75,"ph":4.4,"attenuation_level":84,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":63,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Maris Otter Extra Pale","amount":{"value":4.3,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.8,"unit":"kilograms"}}],"hops":[{"name":"Amarillo","amount":{"value":10,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Simcoe","amount":{"value":15,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Amarillo","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Citra","amount":{"value":20,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Monterey Jack stuffed grilled jalepenos","Barbecue corn and steak fajita seasoned wrap","Cinnamon & white chocolate churro"],"brewers_tips":"To dry the beer out, mash at a slightly lower temp (62° - 63°C), this will increase the ratio of fermentable sugars in the beer.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-089', 'diydog', '089', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/089.json', 'AB:19', 'A Blend of Two Barrel-aged Imperial Saisons.', 'belgian', 13.1, NULL, NULL, NULL, NULL, 20, 'ab:19 a blend of two barrel-aged imperial saisons. belgisk og saison', '{"schemaVersion":1,"name":"AB:19","style":"Belgisk og saison","description":"A Blend of Two Barrel-aged Imperial Saisons.\n\nOne of the most complex beers we’ve ever attempted. A blend of two barrel-aged Imperial Saisons – one black, one red – which has in turn then been aged in rum barrels, it is an enormous, intricate beer. A baseline of warm, smoky raisin and plum, followed by punchy flavour elements coming to the fore – coconut, mint and blackcurrant. There’s a long undercurrent of treacle toffee, before the finish darkens to liquorice, star anise amidst a touch of honey sweetness.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[],"hops":[],"cultures":[],"miscs":[],"mashSteps":[],"fermentationSteps":[],"targets":{"abvPct":13.1},"notes":"Bryggetips: It can be difficult to get the perfect balance between both beers. Set up several small blends of varying percentages to determine which you prefer.\n\nTwist: This beer is an odd one in our collection as it is a blend of two recipes that feature elsewhere. These recipes are #123 Everyday Anarchy and #124 Black Jacques. Both Imperial Saisons spent a little under a year in white and red wine barrels respectively. However, while the pair were being tasted to determine their readiness to be released, a fun game of blending turned into a light bulb moment. The beers were blended and laid down once more in our barrel cellar, this time being infused with the heady note of rum. We were so excited about this mystical blend that we ended up using up all the beer that had been lovingly aged. It would have been a travesty for these beers to go unrecognised as the unique individuals they were, so we brewed them again in 2013 to be released as had always been intended. Age the individual beers separately before blending and ageing further on oak chips soaked in rum.\n\nFørst brygget: 06/2012"}', '{"id":89,"name":"AB:19","tagline":"A Blend of Two Barrel-aged Imperial Saisons.","first_brewed":"06/2012","description":"One of the most complex beers we’ve ever attempted. A blend of two barrel-aged Imperial Saisons – one black, one red – which has in turn then been aged in rum barrels, it is an enormous, intricate beer. A baseline of warm, smoky raisin and plum, followed by punchy flavour elements coming to the fore – coconut, mint and blackcurrant. There’s a long undercurrent of treacle toffee, before the finish darkens to liquorice, star anise amidst a touch of honey sweetness.","image":"089.png","abv":13.1,"ibu":null,"target_fg":null,"target_og":null,"ebc":null,"srm":null,"ph":null,"attenuation_level":null,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":null,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":null,"unit":"celsius"}},"twist":"This beer is an odd one in our collection as it is a blend of two recipes that feature elsewhere. These recipes are #123 Everyday Anarchy and #124 Black Jacques. Both Imperial Saisons spent a little under a year in white and red wine barrels respectively. However, while the pair were being tasted to determine their readiness to be released, a fun game of blending turned into a light bulb moment. The beers were blended and laid down once more in our barrel cellar, this time being infused with the heady note of rum. We were so excited about this mystical blend that we ended up using up all the beer that had been lovingly aged. It would have been a travesty for these beers to go unrecognised as the unique individuals they were, so we brewed them again in 2013 to be released as had always been intended. Age the individual beers separately before blending and ageing further on oak chips soaked in rum."},"ingredients":{"malt":[],"hops":[],"yeast":null},"food_pairing":["Game terrine","Spiced fruit cake","Chocolate, cherry and hazelnut mousse"],"brewers_tips":"It can be difficult to get the perfect balance between both beers. Set up several small blends of varying percentages to determine which you prefer.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke gjær.","Meskesteg 1 har ingen gyldig temperatur i kilden; utelatt."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-090', 'diydog', '090', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/090.json', 'Jack Hammer', 'Ruthless India Pale Ale. Hoppy. Bitter. Hoppy.', 'ipa', 7.2, 250, 1.065, 1.01, 15, 20, 'jack hammer ruthless india pale ale. hoppy. bitter. hoppy. ipa extra pale centennial columbus extract centennial columbus centennial columbus amarillo citra simcoe wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Jack Hammer","style":"IPA","description":"Ruthless India Pale Ale. Hoppy. Bitter. Hoppy.\n\nHopped beyond the point at which IBUs are measurable, only the most hardened palate will get beyond Jack Hammer''s intensely resinous pithy bitterness and to the grapefruit, orange zest and dry biscuity malt beyond. You could brew this with less hops, but really, why would you bother?","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":77,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5.8}],"hops":[{"id":"h1","name":"Centennial","amountG":25,"use":"boil","timeMin":60},{"id":"h2","name":"Columbus Extract","amountG":30,"use":"boil","timeMin":60},{"id":"h3","name":"Centennial","amountG":18.8,"use":"boil","timeMin":30},{"id":"h4","name":"Columbus","amountG":18.8,"use":"boil","timeMin":30},{"id":"h5","name":"Centennial","amountG":50,"use":"boil","timeMin":0},{"id":"h6","name":"Columbus","amountG":25,"use":"boil","timeMin":0},{"id":"h7","name":"Amarillo","amountG":100,"use":"dry_hop"},{"id":"h8","name":"Citra","amountG":100,"use":"dry_hop"},{"id":"h9","name":"Simcoe","amountG":100,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":84.6}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.065,"fg":1.01,"ibu":250,"abvPct":7.2,"colorEbc":15},"notes":"Bryggetips: Be aware that this is probably the hoppiest beer you will ever make. Make sure you use fresh hops, for a massive fresh grapefruit hit. Have everything else in your store cupboard, and buy your hops last, as close to brew day as possible!\n\nFørst brygget: 06/2012"}', '{"id":90,"name":"Jack Hammer","tagline":"Ruthless India Pale Ale. Hoppy. Bitter. Hoppy.","first_brewed":"06/2012","description":"Hopped beyond the point at which IBUs are measurable, only the most hardened palate will get beyond Jack Hammer''s intensely resinous pithy bitterness and to the grapefruit, orange zest and dry biscuity malt beyond. You could brew this with less hops, but really, why would you bother?","image":"090.png","abv":7.2,"ibu":250,"target_fg":1010,"target_og":1065,"ebc":15,"srm":7.5,"ph":4.4,"attenuation_level":84.6,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5.8,"unit":"kilograms"}}],"hops":[{"name":"Centennial","amount":{"value":25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Columbus Extract","amount":{"value":30,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Centennial","amount":{"value":18.75,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Columbus","amount":{"value":18.75,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Centennial","amount":{"value":50,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Columbus","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Amarillo","amount":{"value":100,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Citra","amount":{"value":100,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Simcoe","amount":{"value":100,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Phall Curry","Pork burrito with a habanero and mango chilli salsa","Ginger and grapefruit poundcake"],"brewers_tips":"Be aware that this is probably the hoppiest beer you will ever make. Make sure you use fresh hops, for a massive fresh grapefruit hit. Have everything else in your store cupboard, and buy your hops last, as close to brew day as possible!","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-091', 'diydog', '091', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/091.json', 'Never Mind The Anabolics', 'Performance-Enhancing India Pale Ale.', 'ipa', 6.5, 35, 1.05, 1.012, 23, 20, 'never mind the anabolics performance-enhancing india pale ale. ipa extra pale - spring blend wheat caramalt motueka motueka wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Never Mind The Anabolics","style":"IPA","description":"Performance-Enhancing India Pale Ale.\n\nNever Mind the Anabolics, a 6.5% India Pale Ale brewed with copious amounts of performance-enhancing natural ingredients. Brewed to commemorate the 2012 Olympics and its merry marketing bandwagon.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":65,"fermentables":[{"id":"f1","name":"Extra Pale - Spring Blend","type":"grain","amountKg":4.38},{"id":"f2","name":"Wheat","type":"grain","amountKg":0.63},{"id":"f3","name":"Caramalt","type":"grain","amountKg":0.31}],"hops":[{"id":"h1","name":"Motueka","amountG":37.5,"use":"boil","timeMin":60},{"id":"h2","name":"Motueka","amountG":18.8,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":76}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":68,"durationMin":30}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":18}],"targets":{"og":1.05,"fg":1.012,"ibu":35,"abvPct":6.5,"colorEbc":23},"notes":"Bryggetips: Mix the powders into a paste before adding to the wort kettle. This will prevent the powders from balling up and not bringing the full flavour effect.\n\nTwist: Lycii Berries: 7.5g at end, Ginseng: 5.625g at end, Guarana: 25g at end, Kolabu: 25g at end, Gingko: 6.25g at end, Matcha Tea: 12.5g at end, Maca Powder: 16.25g at end\n\nFørst brygget: 06/2012"}', '{"id":91,"name":"Never Mind The Anabolics","tagline":"Performance-Enhancing India Pale Ale.","first_brewed":"06/2012","description":"Never Mind the Anabolics, a 6.5% India Pale Ale brewed with copious amounts of performance-enhancing natural ingredients. Brewed to commemorate the 2012 Olympics and its merry marketing bandwagon.","image":"091.png","abv":6.5,"ibu":35,"target_fg":1012,"target_og":1050,"ebc":23,"srm":11.5,"ph":4.4,"attenuation_level":76,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":68,"unit":"celsius"},"duration":30}],"fermentation":{"temp":{"value":18,"unit":"celsius"}},"twist":"Lycii Berries: 7.5g at end, Ginseng: 5.625g at end, Guarana: 25g at end, Kolabu: 25g at end, Gingko: 6.25g at end, Matcha Tea: 12.5g at end, Maca Powder: 16.25g at end"},"ingredients":{"malt":[{"name":"Extra Pale - Spring Blend","amount":{"value":4.38,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.31,"unit":"kilograms"}}],"hops":[{"name":"Motueka","amount":{"value":37.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Motueka","amount":{"value":18.75,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Grilled chicken salad with bacon and avocado","Red pepper houmous and flat bread","Matcha green tea cake"],"brewers_tips":"Mix the powders into a paste before adding to the wort kettle. This will prevent the powders from balling up and not bringing the full flavour effect.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","OG/FG i kilden gir 5.0 % ABV, men oppgitt ABV er 6.5 % — sjekk tallene."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-092', 'diydog', '092', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/092.json', 'San Diego Scotch Ale (w/ Ballast Point)', 'Imperial Scotch Ale With Rum & Raisin.', 'strong', 9, 70, 1.09, 1.018, 190, 20, 'san diego scotch ale (w/ ballast point) imperial scotch ale with rum & raisin. sterkt øl pale ale - tipple munich crystal dark crystal carafa special malt type 1 first gold challenger amarillo wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"San Diego Scotch Ale (w/ Ballast Point)","style":"Sterkt øl","description":"Imperial Scotch Ale With Rum & Raisin.\n\nWhisky cask aged with raisins soaked in rum. Warm, chocolatey and boozy with refreshing resinous bitterness and a lingering toasty biscuit background from the malt. Toasted oak comes courtesy of the barrels and spicy, sweet, dark fruit flavours from the rum soaked raisins.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":52,"fermentables":[{"id":"f1","name":"Pale Ale - Tipple","type":"grain","amountKg":8.32},{"id":"f2","name":"Munich","type":"grain","amountKg":1.79},{"id":"f3","name":"Crystal","type":"grain","amountKg":1.19},{"id":"f4","name":"Dark Crystal","type":"grain","amountKg":0.59},{"id":"f5","name":"Carafa Special Malt Type 1","type":"grain","amountKg":0.12}],"hops":[{"id":"h1","name":"First Gold","amountG":125,"use":"boil","timeMin":60},{"id":"h2","name":"Challenger","amountG":62.5,"use":"boil","timeMin":0},{"id":"h3","name":"Amarillo","amountG":125,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":80}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":50}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.09,"fg":1.018,"ibu":70,"abvPct":9,"colorEbc":190},"notes":"Bryggetips: Soak oak chips in rum, then steep in the beer for the rum cash finish.\n\nTwist: Age in whisky casks with rum soaked raisins\n\nFørst brygget: 07/2012"}', '{"id":92,"name":"San Diego Scotch Ale (w/ Ballast Point)","tagline":"Imperial Scotch Ale With Rum & Raisin.","first_brewed":"07/2012","description":"Whisky cask aged with raisins soaked in rum. Warm, chocolatey and boozy with refreshing resinous bitterness and a lingering toasty biscuit background from the malt. Toasted oak comes courtesy of the barrels and spicy, sweet, dark fruit flavours from the rum soaked raisins.","image":"092.png","abv":9,"ibu":70,"target_fg":1018,"target_og":1090,"ebc":190,"srm":95,"ph":4.4,"attenuation_level":80,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":50}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Age in whisky casks with rum soaked raisins"},"ingredients":{"malt":[{"name":"Pale Ale - Tipple","amount":{"value":8.32,"unit":"kilograms"}},{"name":"Munich","amount":{"value":1.79,"unit":"kilograms"}},{"name":"Crystal","amount":{"value":1.19,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.59,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":0.12,"unit":"kilograms"}}],"hops":[{"name":"First Gold","amount":{"value":125,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Challenger","amount":{"value":62.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Amarillo","amount":{"value":125,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Venison stroganoff","Chilli dog","Toffee chocolate cheesecake"],"brewers_tips":"Soak oak chips in rum, then steep in the beer for the rum cash finish.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","12.0 kg malt til 20 L er urealistisk — trolig en feil i kilden."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-093', 'diydog', '093', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/093.json', 'AB:12', 'Imperial Black Belgian Ale.', 'belgian', 11.2, 35, 1.108, 1.017, 80, 20, 'ab:12 imperial black belgian ale. belgisk og saison extra pale chocolate carafa special malt type 3 tomahawk magnum magnum tomahawk centennial amarillo centennial amarillo tomahawk wyeast 3522 - belgian ardennes™', '{"schemaVersion":1,"name":"AB:12","style":"Belgisk og saison","description":"Imperial Black Belgian Ale.\n\nAn Imperial Black Belgian Ale aged in old Invergordon Scotch whisky barrels with mountains of raspberries, tayberries and blackberries in each cask. Decadent but light and dry, this beer would make a fantastic base for ageing on pretty much any dark fruit - we used raspberries, tayberries and blackberries beause they were local.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":72,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":9.69},{"id":"f2","name":"Chocolate","type":"grain","amountKg":0.19},{"id":"f3","name":"Carafa Special Malt Type 3","type":"grain","amountKg":0.44}],"hops":[{"id":"h1","name":"Tomahawk","amountG":31.3,"use":"boil","timeMin":60},{"id":"h2","name":"Magnum","amountG":12.5,"use":"boil","timeMin":60},{"id":"h3","name":"Magnum","amountG":12.5,"use":"boil","timeMin":30},{"id":"h4","name":"Tomahawk","amountG":12.5,"use":"boil","timeMin":0},{"id":"h5","name":"Centennial","amountG":25,"use":"boil","timeMin":0},{"id":"h6","name":"Amarillo","amountG":25,"use":"boil","timeMin":0},{"id":"h7","name":"Centennial","amountG":25,"use":"dry_hop"},{"id":"h8","name":"Amarillo","amountG":25,"use":"dry_hop"},{"id":"h9","name":"Tomahawk","amountG":37.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 3522 - Belgian Ardennes™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":84}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":69,"durationMin":105}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.108,"fg":1.017,"ibu":35,"abvPct":11.2,"colorEbc":80},"notes":"Bryggetips: Don''t worry too much about controlling the temperature with the Belgian yeast strain - just make sure it doesn''t rise above 30°C!\n\nTwist: Aged in whisky barrels with raspberries, tayberries and blackberries\n\nFørst brygget: 07/2012"}', '{"id":93,"name":"AB:12","tagline":"Imperial Black Belgian Ale.","first_brewed":"07/2012","description":"An Imperial Black Belgian Ale aged in old Invergordon Scotch whisky barrels with mountains of raspberries, tayberries and blackberries in each cask. Decadent but light and dry, this beer would make a fantastic base for ageing on pretty much any dark fruit - we used raspberries, tayberries and blackberries beause they were local.","image":"093.png","abv":11.2,"ibu":35,"target_fg":1017,"target_og":1108,"ebc":80,"srm":40,"ph":5.3,"attenuation_level":84,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":69,"unit":"celsius"},"duration":105}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Aged in whisky barrels with raspberries, tayberries and blackberries"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":9.69,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.19,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":0.44,"unit":"kilograms"}}],"hops":[{"name":"Tomahawk","amount":{"value":31.25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Magnum","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Magnum","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Tomahawk","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Centennial","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Amarillo","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Centennial","amount":{"value":25,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Amarillo","amount":{"value":25,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Tomahawk","amount":{"value":37.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 3522 - Belgian Ardennes™"},"food_pairing":["Tandoori lamb with pomegranate","Beef Wellington with a red wine jus","Raspberry chocolate torte"],"brewers_tips":"Don''t worry too much about controlling the temperature with the Belgian yeast strain - just make sure it doesn''t rise above 30°C!","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-094', 'diydog', '094', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/094.json', 'White Noise', 'White IPA with Motueka.', 'ipa', 6.8, 50, 1.06, 1.012, 30, 20, 'white noise white ipa with motueka. ipa extra pale - spring blend wheat munich flaked oats motueka motueka motueka wyeast 3944 - belgian witbier™', '{"schemaVersion":1,"name":"White Noise","style":"IPA","description":"White IPA with Motueka.\n\nA White IPA; brewed with plenty of wheat, fermented with a Belgian yeast with some coriander thrown in for good measure. Oh and this one has mountains of Motueka hops. And then lots of dry hops too.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":60,"fermentables":[{"id":"f1","name":"Extra Pale - Spring Blend","type":"grain","amountKg":2.81},{"id":"f2","name":"Wheat","type":"grain","amountKg":2.81},{"id":"f3","name":"Munich","type":"grain","amountKg":0.94},{"id":"f4","name":"Flaked Oats","type":"grain","amountKg":0.31}],"hops":[{"id":"h1","name":"Motueka","amountG":50,"use":"boil","timeMin":60},{"id":"h2","name":"Motueka","amountG":31.3,"use":"boil","timeMin":0},{"id":"h3","name":"Motueka","amountG":250,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 3944 - Belgian Witbier™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":80}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":67,"durationMin":30}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":18}],"targets":{"og":1.06,"fg":1.012,"ibu":50,"abvPct":6.8,"colorEbc":30},"notes":"Bryggetips: Coriander seed or powder can be added to either the boil, or after the fermentation has finished. They will both impact different characteristics to the beer.\n\nTwist: Coriander powder: 37.5g at end\n\nFørst brygget: 07/2012"}', '{"id":94,"name":"White Noise","tagline":"White IPA with Motueka.","first_brewed":"07/2012","description":"A White IPA; brewed with plenty of wheat, fermented with a Belgian yeast with some coriander thrown in for good measure. Oh and this one has mountains of Motueka hops. And then lots of dry hops too.","image":"keg.png","abv":6.8,"ibu":50,"target_fg":1012,"target_og":1060,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":80,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":67,"unit":"celsius"},"duration":30}],"fermentation":{"temp":{"value":18,"unit":"celsius"}},"twist":"Coriander powder: 37.5g at end"},"ingredients":{"malt":[{"name":"Extra Pale - Spring Blend","amount":{"value":2.81,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":2.81,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.94,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.31,"unit":"kilograms"}}],"hops":[{"name":"Motueka","amount":{"value":50,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Motueka","amount":{"value":31.25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Motueka","amount":{"value":250,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 3944 - Belgian Witbier™"},"food_pairing":["Huevos rancheros","Mild coriander and chilli chicken curry","Panna cotta with an orange and raspberry sauce"],"brewers_tips":"Coriander seed or powder can be added to either the boil, or after the fermentation has finished. They will both impact different characteristics to the beer.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-095', 'diydog', '095', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/095.json', 'International Arms Race (w/ Flying Dog)', 'Zero IBU Herbal IPA.', 'ipa', 7.5, 0, 1.069, 1.013, 50, 20, 'international arms race (w/ flying dog) zero ibu herbal ipa. ipa maris otter extra pale caramalt crystal 150 bay leaves rosemary elderflower wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"International Arms Race (w/ Flying Dog)","style":"IPA","description":"Zero IBU Herbal IPA.\n\nThe International Arms Race was a new type of battle collaboration between hardcore American craft brewery Flying Dog and BrewDog. Both breweries attempted to brew an IPA with absolutely no hops.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":68,"fermentables":[{"id":"f1","name":"Maris Otter Extra Pale","type":"grain","amountKg":6},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.75},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.25}],"hops":[],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":81.1}],"miscs":[{"id":"x1","name":"Bay Leaves","amount":5,"unit":"g","use":"fermentation"},{"id":"x2","name":"Rosemary","amount":25,"unit":"g","use":"fermentation"},{"id":"x3","name":"Elderflower","amount":10,"unit":"g","use":"fermentation"}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":69,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.069,"fg":1.013,"ibu":0,"abvPct":7.5,"colorEbc":50},"notes":"Bryggetips: Allow the bay leaves to steep in the boil for extra time to extract some bitterness. The bitterness is really important to bring balance to an otherwise sweet beer.\n\nTwist: Juniper Berries: 25g at start, Bay Leaves: 2.75g at start, Rosemary: 7.5g at start, Rosemary: 5g at end, Elderflower: 15g at end, Juniper Berries: 25g at end\n\nFørst brygget: 08/2012"}', '{"id":95,"name":"International Arms Race (w/ Flying Dog)","tagline":"Zero IBU Herbal IPA.","first_brewed":"08/2012","description":"The International Arms Race was a new type of battle collaboration between hardcore American craft brewery Flying Dog and BrewDog. Both breweries attempted to brew an IPA with absolutely no hops.","image":"095.png","abv":7.5,"ibu":0,"target_fg":1013,"target_og":1069,"ebc":50,"srm":25,"ph":4.4,"attenuation_level":81.1,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":69,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Juniper Berries: 25g at start, Bay Leaves: 2.75g at start, Rosemary: 7.5g at start, Rosemary: 5g at end, Elderflower: 15g at end, Juniper Berries: 25g at end"},"ingredients":{"malt":[{"name":"Maris Otter Extra Pale","amount":{"value":6,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.75,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.25,"unit":"kilograms"}}],"hops":[{"name":"Bay Leaves","amount":{"value":5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Rosemary","amount":{"value":25,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Elderflower","amount":{"value":10,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Rosemary and thyme grilled chicken","Light vegetable and herb soup with toasted rye bread","Earl Grey ice cream with a lavender sauce"],"brewers_tips":"Allow the bay leaves to steep in the boil for extra time to extract some bitterness. The bitterness is really important to bring balance to an otherwise sweet beer.","contributed_by":"Sam Mason <samjbmason>"}', '["Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
