INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-098', 'diydog', '098', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/098.json', 'Dog Fight (w/ Flying Dog)', 'Rye IPA - Flying Dog Collab.', 'ipa', 8.5, 65, 1.078, 1.012, 31.2, 20, 'dog fight (w/ flying dog) rye ipa - flying dog collab. ipa extra pale - spring blend caramalt rye chinook amarillo chinook amarillo chinook wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Dog Fight (w/ Flying Dog)","style":"IPA","description":"Rye IPA - Flying Dog Collab.\n\nA clash of kings. A spiced toffee malt backbone arranged against a tidal wave of US hops. Citrus, nectarine and juicy tropical fruits are layered into this complex beer.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":65,"fermentables":[{"id":"f1","name":"Extra Pale - Spring Blend","type":"grain","amountKg":6.79},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.25},{"id":"f3","name":"Rye","type":"grain","amountKg":1.25}],"hops":[{"id":"h1","name":"Chinook","amountG":50,"use":"boil","timeMin":60},{"id":"h2","name":"Amarillo","amountG":62.5,"use":"boil","timeMin":30},{"id":"h3","name":"Chinook","amountG":62.5,"use":"boil","timeMin":0},{"id":"h4","name":"Amarillo","amountG":107.1,"use":"dry_hop"},{"id":"h5","name":"Chinook","amountG":142.9,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":84.6}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":50}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":18}],"targets":{"og":1.078,"fg":1.012,"ibu":65,"abvPct":8.5,"colorEbc":31.2},"notes":"Bryggetips: Space the rye and caramalt out evenly in the mash. If it is all collected in one section, it can contribute to a sticky run-off.\n\nFørst brygget: 10/2012"}', '{"id":98,"name":"Dog Fight (w/ Flying Dog)","tagline":"Rye IPA - Flying Dog Collab.","first_brewed":"10/2012","description":"A clash of kings. A spiced toffee malt backbone arranged against a tidal wave of US hops. Citrus, nectarine and juicy tropical fruits are layered into this complex beer.","image":"keg.png","abv":8.5,"ibu":65,"target_fg":1012,"target_og":1078,"ebc":31.2,"srm":15.6,"ph":4.4,"attenuation_level":84.6,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":50}],"fermentation":{"temp":{"value":18,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale - Spring Blend","amount":{"value":6.79,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Rye","amount":{"value":1.25,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":50,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Amarillo","amount":{"value":62.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Chinook","amount":{"value":62.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Amarillo","amount":{"value":107.14,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Chinook","amount":{"value":142.86,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Black bean and avocado enchiladas with mole sauce","Mexican spiced cheddar cheese","Pancakes with maple syrup"],"brewers_tips":"Space the rye and caramalt out evenly in the mash. If it is all collected in one section, it can contribute to a sticky run-off.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-099', 'diydog', '099', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/099.json', 'Hoppy Christmas', 'Simcoe Single-Hop India Pale Ale.', 'ipa', 7.2, 70, 1.067, 1.012, 30, 20, 'hoppy christmas simcoe single-hop india pale ale. ipa extra pale caramalt dark crystal simcoe simcoe simcoe simcoe wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Hoppy Christmas","style":"IPA","description":"Simcoe Single-Hop India Pale Ale.\n\nPineapple, citrus and papaya; single-hopped with Simcoe, Hoppy Christmas is an anti-festive IPA, redolent with summery flavours. Small caramel malt additions provide a touch of malt complexity. Simcoe, arguably our favourite hop, carries this beer - pine, tropical fruit and bitterness are its specialities.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":78,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5.65},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.25},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.06}],"hops":[{"id":"h1","name":"Simcoe","amountG":2.5,"use":"boil","timeMin":60},{"id":"h2","name":"Simcoe","amountG":25,"use":"boil","timeMin":30},{"id":"h3","name":"Simcoe","amountG":37.5,"use":"boil","timeMin":0},{"id":"h4","name":"Simcoe","amountG":187.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.1}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.067,"fg":1.012,"ibu":70,"abvPct":7.2,"colorEbc":30},"notes":"Bryggetips: Get the freshest Simcoe for the best profile.\n\nFørst brygget: 10/2012"}', '{"id":99,"name":"Hoppy Christmas","tagline":"Simcoe Single-Hop India Pale Ale.","first_brewed":"10/2012","description":"Pineapple, citrus and papaya; single-hopped with Simcoe, Hoppy Christmas is an anti-festive IPA, redolent with summery flavours. Small caramel malt additions provide a touch of malt complexity. Simcoe, arguably our favourite hop, carries this beer - pine, tropical fruit and bitterness are its specialities.","image":"099.png","abv":7.2,"ibu":70,"target_fg":1012,"target_og":1067,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":82.1,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5.65,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.06,"unit":"kilograms"}}],"hops":[{"name":"Simcoe","amount":{"value":2.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Simcoe","amount":{"value":25,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Simcoe","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Simcoe","amount":{"value":187.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Spiced cranberry turkey","Sriracha covered brussel sprouts","Ginger rice pudding"],"brewers_tips":"Get the freshest Simcoe for the best profile.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-100', 'diydog', '100', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/100.json', 'Black Eyed King Imp', 'Barrel-Aged Prototype Cocoa Psycho.', 'stout', 9.5, 85, 1.095, 1.022, 250, 20, 'black eyed king imp barrel-aged prototype cocoa psycho. stout og porter extra pale - spring blend wheat caramalt crystal dark crystal amber brown chocolate roasted barley magnum willamette first gold wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Black Eyed King Imp","style":"Stout og porter","description":"Barrel-Aged Prototype Cocoa Psycho.\n\nAn early Cocoa Psycho recipe that we loved, but didn''t fit what we were looking for. We locked this chocolate coffee stout away in barrels for two years, imparting toasted marshmallow, spicy vanilla, molasses and boozy warmth.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":50,"fermentables":[{"id":"f1","name":"Extra Pale - Spring Blend","type":"grain","amountKg":6.25},{"id":"f2","name":"Wheat","type":"grain","amountKg":1.25},{"id":"f3","name":"Caramalt","type":"grain","amountKg":1.25},{"id":"f4","name":"Crystal","type":"grain","amountKg":1.56},{"id":"f5","name":"Dark Crystal","type":"grain","amountKg":0.63},{"id":"f6","name":"Amber","type":"grain","amountKg":0.63},{"id":"f7","name":"Brown","type":"grain","amountKg":0.63},{"id":"f8","name":"Chocolate","type":"grain","amountKg":0.63},{"id":"f9","name":"Roasted Barley","type":"grain","amountKg":0.31}],"hops":[{"id":"h1","name":"Magnum","amountG":62.5,"use":"boil","timeMin":60},{"id":"h2","name":"Willamette","amountG":31.3,"use":"boil","timeMin":0},{"id":"h3","name":"First Gold","amountG":31.3,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":76.8}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":50}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":18}],"targets":{"og":1.095,"fg":1.022,"ibu":85,"abvPct":9.5,"colorEbc":250},"notes":"Bryggetips: There is a huge amount of roasted malts in this grist. Be careful not to pulverise the malt into powder during the milling process.\n\nTwist: Coffee Beans: 12.5g at end, Lactose: 125g\n\nFørst brygget: 11/2012"}', '{"id":100,"name":"Black Eyed King Imp","tagline":"Barrel-Aged Prototype Cocoa Psycho.","first_brewed":"11/2012","description":"An early Cocoa Psycho recipe that we loved, but didn''t fit what we were looking for. We locked this chocolate coffee stout away in barrels for two years, imparting toasted marshmallow, spicy vanilla, molasses and boozy warmth.","image":"100.png","abv":9.5,"ibu":85,"target_fg":1022,"target_og":1095,"ebc":250,"srm":125,"ph":4.4,"attenuation_level":76.8,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":50}],"fermentation":{"temp":{"value":18,"unit":"celsius"}},"twist":"Coffee Beans: 12.5g at end, Lactose: 125g"},"ingredients":{"malt":[{"name":"Extra Pale - Spring Blend","amount":{"value":6.25,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":1.25,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":1.25,"unit":"kilograms"}},{"name":"Crystal","amount":{"value":1.56,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Amber","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Brown","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Roasted Barley","amount":{"value":0.31,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":62.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Willamette","amount":{"value":31.25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"First Gold","amount":{"value":31.25,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Beef chilli made with cocoa powder","Dark chocolate covered bacon","Rich espresso tiramisu"],"brewers_tips":"There is a huge amount of roasted malts in this grist. Be careful not to pulverise the malt into powder during the milling process.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","13.1 kg malt til 20 L er urealistisk — trolig en feil i kilden."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-101', 'diydog', '101', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/101.json', 'Cocoa Psycho', 'Russian Imperial Stout. Rich. Decadent. Mocha.', 'stout', 10, 85, 1.098, 1.012, 30, 20, 'cocoa psycho russian imperial stout. rich. decadent. mocha. stout og porter extra pale wheat dark crystal black malt roasted barley weyermann smoked cascade cascade wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Cocoa Psycho","style":"Stout og porter","description":"Russian Imperial Stout. Rich. Decadent. Mocha.\n\nVanilla pods and toasted oak chips add a rounded character to this massive Russian Imperial Stout, brewed with a hefty malt bill, cacao nibs and coffee beans. Dark malts combine with Cascade to add a punchy bitterness, strong enough to offset the big chocolate sweetness.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":60,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":6.88},{"id":"f2","name":"Wheat","type":"grain","amountKg":1},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.13},{"id":"f4","name":"Black Malt","type":"grain","amountKg":1.25},{"id":"f5","name":"Roasted Barley","type":"grain","amountKg":1.5},{"id":"f6","name":"Weyermann Smoked","type":"grain","amountKg":0.5}],"hops":[{"id":"h1","name":"Cascade","amountG":75,"use":"boil","timeMin":60},{"id":"h2","name":"Cascade","amountG":25,"use":"boil","timeMin":30}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":70}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.098,"fg":1.012,"ibu":85,"abvPct":10,"colorEbc":30},"notes":"Bryggetips: Put coffee beans and cocoa nibs in a cheese cloth and dip in wort like a tea bag. Do multiple small additions for short lengths of time – the longer you leave them in the more heavy oils will be extracted.\n\nTwist: Coffee Beans: 25g at end, Cocoa Nibs: 25g at end, Cocoa Nibs: 25g at conditioning, Coffee Beans: 25g at conditioning, Oak Chips: 15g at conditioning\n\nFørst brygget: 11/2012"}', '{"id":101,"name":"Cocoa Psycho","tagline":"Russian Imperial Stout. Rich. Decadent. Mocha.","first_brewed":"11/2012","description":"Vanilla pods and toasted oak chips add a rounded character to this massive Russian Imperial Stout, brewed with a hefty malt bill, cacao nibs and coffee beans. Dark malts combine with Cascade to add a punchy bitterness, strong enough to offset the big chocolate sweetness.","image":"101.png","abv":10,"ibu":85,"target_fg":1012,"target_og":1098,"ebc":30,"srm":15.25,"ph":4.4,"attenuation_level":70,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Coffee Beans: 25g at end, Cocoa Nibs: 25g at end, Cocoa Nibs: 25g at conditioning, Coffee Beans: 25g at conditioning, Oak Chips: 15g at conditioning"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":6.88,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":1,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.13,"unit":"kilograms"}},{"name":"Black Malt","amount":{"value":1.25,"unit":"kilograms"}},{"name":"Roasted Barley","amount":{"value":1.5,"unit":"kilograms"}},{"name":"Weyermann Smoked","amount":{"value":0.5,"unit":"kilograms"}}],"hops":[{"name":"Cascade","amount":{"value":75,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Cascade","amount":{"value":25,"unit":"grams"},"add":"middle","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Smokey sweet pulled brisket","Espresso crusted venison with a dark cherry jus","Affogato with vanilla ice cream"],"brewers_tips":"Put coffee beans and cocoa nibs in a cheese cloth and dip in wort like a tea bag. Do multiple small additions for short lengths of time – the longer you leave them in the more heavy oils will be extracted.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-102', 'diydog', '102', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/102.json', 'Nuns With Guns', 'Dry-Hopped Lager.', 'lager', 4.2, 25, 1.044, 1.012, 19, 20, 'nuns with guns dry-hopped lager. lager og pils maris otter extra pale caramalt munich cascade cascade centennial chinook amarillo chinook amarillo cascade wyeast 2007 - pilsen lager™', '{"schemaVersion":1,"name":"Nuns With Guns","style":"Lager og pils","description":"Dry-Hopped Lager.\n\nA dry-hopped Session Pilsner. At 4.2% this amber-hued lager packs a malty punch with toasty Munich character and a light caramel sweetness. From here, things take a sharp turn towards the hoppy flavour, with some serious US citrus packed classic hops.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":71,"fermentables":[{"id":"f1","name":"Maris Otter Extra Pale","type":"grain","amountKg":3.38},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.25},{"id":"f3","name":"Munich","type":"grain","amountKg":0.63}],"hops":[{"id":"h1","name":"Cascade","amountG":1.3,"use":"boil","timeMin":60},{"id":"h2","name":"Cascade","amountG":10,"use":"boil","timeMin":0},{"id":"h3","name":"Centennial","amountG":10,"use":"boil","timeMin":0},{"id":"h4","name":"Chinook","amountG":10,"use":"boil","timeMin":0},{"id":"h5","name":"Amarillo","amountG":10,"use":"boil","timeMin":0},{"id":"h6","name":"Chinook","amountG":75,"use":"dry_hop"},{"id":"h7","name":"Amarillo","amountG":75,"use":"dry_hop"},{"id":"h8","name":"Cascade","amountG":100,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 2007 - Pilsen Lager™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":72.7}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":70,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":16}],"targets":{"og":1.044,"fg":1.012,"ibu":25,"abvPct":4.2,"colorEbc":19},"notes":"Bryggetips: Keep the temperature of the fermentation as close to 12C as possible (or below). This allows the yeast to create a crisper and cleaner beer.\n\nFørst brygget: 11/2012"}', '{"id":102,"name":"Nuns With Guns","tagline":"Dry-Hopped Lager.","first_brewed":"11/2012","description":"A dry-hopped Session Pilsner. At 4.2% this amber-hued lager packs a malty punch with toasty Munich character and a light caramel sweetness. From here, things take a sharp turn towards the hoppy flavour, with some serious US citrus packed classic hops.","image":"102.png","abv":4.2,"ibu":25,"target_fg":1012,"target_og":1044,"ebc":19,"srm":9.5,"ph":4.4,"attenuation_level":72.7,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":70,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":16,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Maris Otter Extra Pale","amount":{"value":3.38,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.63,"unit":"kilograms"}}],"hops":[{"name":"Cascade","amount":{"value":1.25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Cascade","amount":{"value":10,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Centennial","amount":{"value":10,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Chinook","amount":{"value":10,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Amarillo","amount":{"value":10,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Chinook","amount":{"value":75,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Amarillo","amount":{"value":75,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Cascade","amount":{"value":100,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 2007 - Pilsen Lager™"},"food_pairing":["Falafel and hummus pitta wrap","Bratwurst with spicy relish","Strawberry tart"],"brewers_tips":"Keep the temperature of the fermentation as close to 12C as possible (or below). This allows the yeast to create a crisper and cleaner beer.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-103', 'diydog', '103', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/103.json', 'Catherine''s Pony (w/ Beavertown)', 'Imperial Smoked Porter – Beavertown Collab.', 'stout', 8.8, 40, 1.084, 1.017, 190, 20, 'catherine''s pony (w/ beavertown) imperial smoked porter – beavertown collab. stout og porter extra pale caramalt carafa special malt type 2 crystal 150 smoked warminster magnum cascade fuggles first gold coffee wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Catherine''s Pony (w/ Beavertown)","style":"Stout og porter","description":"Imperial Smoked Porter – Beavertown Collab.\n\nAn Imperial Smoked Porter with a nose like gooseberries and blueberries, stuffed with coffee, covered in chocolate and toasted on a campfire by the beach, Catherine’s Pony is robust and imposing with a herculean mouthfeel. Rich and smooth with roasted smoky flavours battling for prominence over the assertive bitterness. A satisfying hoppiness rounds off the palate.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":56,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":7.5},{"id":"f2","name":"Caramalt","type":"grain","amountKg":1.15},{"id":"f3","name":"Carafa Special Malt Type 2","type":"grain","amountKg":0.48},{"id":"f4","name":"Crystal 150","type":"grain","amountKg":0.48},{"id":"f5","name":"Smoked Warminster","type":"grain","amountKg":0.77}],"hops":[{"id":"h1","name":"Magnum","amountG":11.5,"use":"boil","timeMin":60},{"id":"h2","name":"Cascade","amountG":11.5,"use":"boil","timeMin":30},{"id":"h3","name":"Fuggles","amountG":11.5,"use":"boil","timeMin":30},{"id":"h4","name":"First Gold","amountG":11.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79.8}],"miscs":[{"id":"x5","name":"Coffee","amount":19.3,"unit":"g","use":"boil","timeMin":0}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":67,"durationMin":90}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.084,"fg":1.017,"ibu":40,"abvPct":8.8,"colorEbc":190},"notes":"Bryggetips: The smoke aroma comes from a mix of the Carafa malt and smoked malt. If you can''t get hold of fresh smoked malt – make your own in a barbeque - carefully!\n\nTwist: Coffee at end for flavour\n\nFørst brygget: 12/2012"}', '{"id":103,"name":"Catherine''s Pony (w/ Beavertown)","tagline":"Imperial Smoked Porter – Beavertown Collab.","first_brewed":"12/2012","description":"An Imperial Smoked Porter with a nose like gooseberries and blueberries, stuffed with coffee, covered in chocolate and toasted on a campfire by the beach, Catherine’s Pony is robust and imposing with a herculean mouthfeel. Rich and smooth with roasted smoky flavours battling for prominence over the assertive bitterness. A satisfying hoppiness rounds off the palate.","image":"103.png","abv":8.8,"ibu":40,"target_fg":1017,"target_og":1084,"ebc":190,"srm":95,"ph":4.5,"attenuation_level":79.8,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":67,"unit":"celsius"},"duration":90}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Coffee at end for flavour"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":7.5,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":1.15,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 2","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Smoked Warminster","amount":{"value":0.77,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":11.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Cascade","amount":{"value":11.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Fuggles","amount":{"value":11.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"First Gold","amount":{"value":11.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Coffee","amount":{"value":19.25,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Flame grilled steak","Venison and Winter vegetable stew","Maple bacon chocolate cupcakes"],"brewers_tips":"The smoke aroma comes from a mix of the Carafa malt and smoked malt. If you can''t get hold of fresh smoked malt – make your own in a barbeque - carefully!","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-104', 'diydog', '104', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/104.json', 'Amarillo - IPA Is Dead', 'Single Hop India Pale Ale.', 'ipa', 7.2, 70, 1.067, 1.012, 30, 20, 'amarillo - ipa is dead single hop india pale ale. ipa extra pale caramalt dark crystal amarillo amarillo amarillo amarillo wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Amarillo - IPA Is Dead","style":"IPA","description":"Single Hop India Pale Ale.\n\nCitrus fruit. Lots of citrus fruit. Think blood orange, orange zest and grapefruit, tangerine and lemon; the fruit is balanced by floral notes in the most classic of new wave IPA hops. Amarillo adds a zesty, pithy character that sits beautifully alongside hints of toffee and honeycomb.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":88,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":4.88},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.31},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.06}],"hops":[{"id":"h1","name":"Amarillo","amountG":20,"use":"boil","timeMin":60},{"id":"h2","name":"Amarillo","amountG":25,"use":"boil","timeMin":30},{"id":"h3","name":"Amarillo","amountG":37.5,"use":"boil","timeMin":0},{"id":"h4","name":"Amarillo","amountG":250,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.1}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.067,"fg":1.012,"ibu":70,"abvPct":7.2,"colorEbc":30},"notes":"Bryggetips: Use the freshest hops for the most impact. It seems obvious but in a single hop beer, you want the hops to be at their best.\n\nFørst brygget: 01/2013"}', '{"id":104,"name":"Amarillo - IPA Is Dead","tagline":"Single Hop India Pale Ale.","first_brewed":"01/2013","description":"Citrus fruit. Lots of citrus fruit. Think blood orange, orange zest and grapefruit, tangerine and lemon; the fruit is balanced by floral notes in the most classic of new wave IPA hops. Amarillo adds a zesty, pithy character that sits beautifully alongside hints of toffee and honeycomb.","image":"104.png","abv":7.2,"ibu":70,"target_fg":1012,"target_og":1067,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":82.1,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":4.88,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.06,"unit":"kilograms"}}],"hops":[{"name":"Amarillo","amount":{"value":20,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Amarillo","amount":{"value":25,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Amarillo","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Amarillo","amount":{"value":250,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Bratwurst sausage with spicy mustard","Fried American bacon with chilli flakes added to the top","Dark chocolate chip cookies"],"brewers_tips":"Use the freshest hops for the most impact. It seems obvious but in a single hop beer, you want the hops to be at their best.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
