INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-106', 'diydog', '106', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/106.json', 'AB:14', 'Oak-Aged Imperial Weizenbock.', 'wheat', 10, 30, 1.094, 1.016, 20, 20, 'ab:14 oak-aged imperial weizenbock. hvete wheat extra pale munich caramalt bramling cross simcoe saaz simcoe saaz wyeast 3638 - bavarian wheat™', '{"schemaVersion":1,"name":"AB:14","style":"Hvete","description":"Oak-Aged Imperial Weizenbock.\n\nThink banoffee pie; loads of creamy sweet banana, and sticky warm toffee. This beer is super complex, and one for the sweet-toothed!","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":64,"fermentables":[{"id":"f1","name":"Wheat","type":"grain","amountKg":5},{"id":"f2","name":"Extra Pale","type":"grain","amountKg":2},{"id":"f3","name":"Munich","type":"grain","amountKg":2},{"id":"f4","name":"Caramalt","type":"grain","amountKg":1.13}],"hops":[{"id":"h1","name":"Bramling Cross","amountG":30,"use":"boil","timeMin":60},{"id":"h2","name":"Simcoe","amountG":12.5,"use":"boil","timeMin":30},{"id":"h3","name":"Saaz","amountG":15,"use":"boil","timeMin":30},{"id":"h4","name":"Simcoe","amountG":12.5,"use":"boil","timeMin":0},{"id":"h5","name":"Saaz","amountG":15,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 3638 - Bavarian Wheat™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":120}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":23}],"targets":{"og":1.094,"fg":1.016,"ibu":30,"abvPct":10,"colorEbc":20},"notes":"Bryggetips: Boil for even longer to get more caramelised flavours in the beer.\n\nTwist: Oak chips: 25g at end\n\nFørst brygget: 02/2013"}', '{"id":106,"name":"AB:14","tagline":"Oak-Aged Imperial Weizenbock.","first_brewed":"02/2013","description":"Think banoffee pie; loads of creamy sweet banana, and sticky warm toffee. This beer is super complex, and one for the sweet-toothed!","image":"106.png","abv":10,"ibu":30,"target_fg":1016,"target_og":1094,"ebc":20,"srm":10,"ph":4.4,"attenuation_level":83,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":120}],"fermentation":{"temp":{"value":23,"unit":"celsius"}},"twist":"Oak chips: 25g at end"},"ingredients":{"malt":[{"name":"Wheat","amount":{"value":5,"unit":"kilograms"}},{"name":"Extra Pale","amount":{"value":2,"unit":"kilograms"}},{"name":"Munich","amount":{"value":2,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":1.13,"unit":"kilograms"}}],"hops":[{"name":"Bramling Cross","amount":{"value":30,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Simcoe","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Saaz","amount":{"value":15,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Simcoe","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Saaz","amount":{"value":15,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 3638 - Bavarian Wheat™"},"food_pairing":["Sweet pork Chinese dumplings","Caramelised onion venison burger","Banoffee pie"],"brewers_tips":"Boil for even longer to get more caramelised flavours in the beer.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-107', 'diydog', '107', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/107.json', 'Dana - IPA Is Dead', 'Single Hop India Pale Ale.', 'ipa', 6.7, 70, 1.066, 1.015, 30, 20, 'dana - ipa is dead single hop india pale ale. ipa extra pale caramalt dark crystal munich dana dana dana dana wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Dana - IPA Is Dead","style":"IPA","description":"Single Hop India Pale Ale.\n\nHailing from Slovenia, Dana was originally cross bred from the German Hallertau Magnum and native Slovenian varieties. Like any good faux noble hop should, it infuses a rustic, musty spiciness into a toasty beast of a malt base.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":80,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.31},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.06},{"id":"f4","name":"Munich","type":"grain","amountKg":0.31}],"hops":[{"id":"h1","name":"Dana","amountG":2.5,"use":"boil","timeMin":60},{"id":"h2","name":"Dana","amountG":25,"use":"boil","timeMin":30},{"id":"h3","name":"Dana","amountG":37.5,"use":"boil","timeMin":0},{"id":"h4","name":"Dana","amountG":125,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":77.3}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.066,"fg":1.015,"ibu":70,"abvPct":6.7,"colorEbc":30},"notes":"Bryggetips: Noble hops (and their offspring) have a fundamentally different profile to many other hops, down to their different oil fractions. Chill your hops to retain all of the spicy, delicate volatile hop oils!\n\nFørst brygget: 02/2013"}', '{"id":107,"name":"Dana - IPA Is Dead","tagline":"Single Hop India Pale Ale.","first_brewed":"02/2013","description":"Hailing from Slovenia, Dana was originally cross bred from the German Hallertau Magnum and native Slovenian varieties. Like any good faux noble hop should, it infuses a rustic, musty spiciness into a toasty beast of a malt base.","image":"107.png","abv":6.7,"ibu":70,"target_fg":1015,"target_og":1066,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":77.3,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.06,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.31,"unit":"kilograms"}}],"hops":[{"name":"Dana","amount":{"value":2.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Dana","amount":{"value":25,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Dana","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Dana","amount":{"value":125,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Spicy Asian-style noodles","Smokey chipotle beef brisket tostada","Sweet potato pie"],"brewers_tips":"Noble hops (and their offspring) have a fundamentally different profile to many other hops, down to their different oil fractions. Chill your hops to retain all of the spicy, delicate volatile hop oils!","contributed_by":"Matt Ball <GeordieMatt>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-108', 'diydog', '108', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/108.json', 'El Dorado - IPA Is Dead', 'Single Hop India Pale Ale.', 'ipa', 6.7, 70, 1.066, 1.015, 30, 20, 'el dorado - ipa is dead single hop india pale ale. ipa extra pale caramalt dark crystal munich el dorado el dorado el dorado el dorado wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"El Dorado - IPA Is Dead","style":"IPA","description":"Single Hop India Pale Ale.\n\nThe Pacific North West of America grows remarkable hops and El Dorado is a killer example of this. A new hop on the block, loaded with tropical fruits, pear, watermelon, candy floss and stone fruit.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":80,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.31},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.06},{"id":"f4","name":"Munich","type":"grain","amountKg":0.31}],"hops":[{"id":"h1","name":"El Dorado","amountG":3.8,"use":"boil","timeMin":60},{"id":"h2","name":"El Dorado","amountG":12.5,"use":"boil","timeMin":30},{"id":"h3","name":"El Dorado","amountG":37.5,"use":"boil","timeMin":0},{"id":"h4","name":"El Dorado","amountG":125,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":77.3}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.066,"fg":1.015,"ibu":70,"abvPct":6.7,"colorEbc":30},"notes":"Bryggetips: El Dorado works well on its own but pairs up brilliantly with a higher alpha hop for bittering, saving your El Dorado for aroma and flavour.\n\nFørst brygget: 02/2013"}', '{"id":108,"name":"El Dorado - IPA Is Dead","tagline":"Single Hop India Pale Ale.","first_brewed":"02/2013","description":"The Pacific North West of America grows remarkable hops and El Dorado is a killer example of this. A new hop on the block, loaded with tropical fruits, pear, watermelon, candy floss and stone fruit.","image":"108.png","abv":6.7,"ibu":70,"target_fg":1015,"target_og":1066,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":77.3,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.06,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.31,"unit":"kilograms"}}],"hops":[{"name":"El Dorado","amount":{"value":3.75,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"El Dorado","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"El Dorado","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"El Dorado","amount":{"value":125,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Watermelon and feta salad with balsamic reduction","Grilled chicken with a chilli soy sauce marinade","Crème brûlée with apricot coulis"],"brewers_tips":"El Dorado works well on its own but pairs up brilliantly with a higher alpha hop for bittering, saving your El Dorado for aroma and flavour.","contributed_by":"Matt Ball <GeordieMatt>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-109', 'diydog', '109', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/109.json', 'Goldings - IPA Is Dead', 'Single Hop India Pale Ale.', 'ipa', 6.7, 70, 1.066, 1.015, 30, 20, 'goldings - ipa is dead single hop india pale ale. ipa extra pale caramalt dark crystal munich goldings goldings goldings goldings wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Goldings - IPA Is Dead","style":"IPA","description":"Single Hop India Pale Ale.\n\nThis is East Kent Goldings re- invented and re-imagined and shows just what can be done with English hops if you use enough of them. In this amped up Goldings reincarnation expect to be slammed with floral lavender, a fruity riot of blackberries and spiced pears, bubblegum, plums and the illusion of thyme.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":80,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.31},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.06},{"id":"f4","name":"Munich","type":"grain","amountKg":0.31}],"hops":[{"id":"h1","name":"Goldings","amountG":37.5,"use":"boil","timeMin":60},{"id":"h2","name":"Goldings","amountG":25,"use":"boil","timeMin":30},{"id":"h3","name":"Goldings","amountG":37.5,"use":"boil","timeMin":0},{"id":"h4","name":"Goldings","amountG":125,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":77.3}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.066,"fg":1.015,"ibu":70,"abvPct":6.7,"colorEbc":30},"notes":"Bryggetips: Take a read through each year’s hop harvest that is available. Some years are better than others.\n\nFørst brygget: 02/2013"}', '{"id":109,"name":"Goldings - IPA Is Dead","tagline":"Single Hop India Pale Ale.","first_brewed":"02/2013","description":"This is East Kent Goldings re- invented and re-imagined and shows just what can be done with English hops if you use enough of them. In this amped up Goldings reincarnation expect to be slammed with floral lavender, a fruity riot of blackberries and spiced pears, bubblegum, plums and the illusion of thyme.","image":"109.png","abv":6.7,"ibu":70,"target_fg":1015,"target_og":1066,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":77.3,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.06,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.31,"unit":"kilograms"}}],"hops":[{"name":"Goldings","amount":{"value":37.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Goldings","amount":{"value":25,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Goldings","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Goldings","amount":{"value":125,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Rosemary and thyme marinated venison","Fish and chips","Lavender chocolate chip cookies"],"brewers_tips":"Take a read through each year’s hop harvest that is available. Some years are better than others.","contributed_by":"Matt Ball <GeordieMatt>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-110', 'diydog', '110', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/110.json', 'Waimea - IPA Is Dead', 'Single Hop India Pale Ale.', 'ipa', 6.7, 70, 1.066, 1.015, 30, 20, 'waimea - ipa is dead single hop india pale ale. ipa extra pale caramalt dark crystal munich waimea waimea waimea waimea wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Waimea - IPA Is Dead","style":"IPA","description":"Single Hop India Pale Ale.\n\nWaimea has a new world flavour, infusing unique fresh crushed citrus aroma and flavour notes into this IPA - think intense fresh tangelo, citrus fruit and pine needle characteristics. There is a huge depth of flavour with astringent gooseberry balanced against the robust malt base.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":80,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.31},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.06},{"id":"f4","name":"Munich","type":"grain","amountKg":0.31}],"hops":[{"id":"h1","name":"Waimea","amountG":2.5,"use":"boil","timeMin":60},{"id":"h2","name":"Waimea","amountG":20,"use":"boil","timeMin":30},{"id":"h3","name":"Waimea","amountG":37.5,"use":"boil","timeMin":0},{"id":"h4","name":"Waimea","amountG":125,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":77.3}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.066,"fg":1.015,"ibu":70,"abvPct":6.7,"colorEbc":30},"notes":"Bryggetips: Use the freshest hops for the most impact.\n\nFørst brygget: 02/2013"}', '{"id":110,"name":"Waimea - IPA Is Dead","tagline":"Single Hop India Pale Ale.","first_brewed":"02/2013","description":"Waimea has a new world flavour, infusing unique fresh crushed citrus aroma and flavour notes into this IPA - think intense fresh tangelo, citrus fruit and pine needle characteristics. There is a huge depth of flavour with astringent gooseberry balanced against the robust malt base.","image":"110.png","abv":6.7,"ibu":70,"target_fg":1015,"target_og":1066,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":77.3,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.06,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.31,"unit":"kilograms"}}],"hops":[{"name":"Waimea","amount":{"value":2.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Waimea","amount":{"value":20,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Waimea","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Waimea","amount":{"value":125,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Hot spiced barbecue chicken wings","Orange sesame chicken","Chocolate fondue with fruit"],"brewers_tips":"Use the freshest hops for the most impact.","contributed_by":"Matt Ball <GeordieMatt>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-111', 'diydog', '111', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/111.json', 'Vagabond Pilsner', 'Hoppy Pilsner.', 'lager', 4.5, 55, 1.046, 1.012, 25, 20, 'vagabond pilsner hoppy pilsner. lager og pils extra pale munich crystal 150 acidulated malt cascade amarillo centennial chinook cascade centennial chinook amarillo wyeast 2007 - pilsen lager™', '{"schemaVersion":1,"name":"Vagabond Pilsner","style":"Lager og pils","description":"Hoppy Pilsner.\n\nTake the thirst-quenching crispness of a German Pilsner and combine it with lemon and honey to produce a rewarding modern twist on a beer classic.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":68,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":3.5},{"id":"f2","name":"Munich","type":"grain","amountKg":0.44},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.13},{"id":"f4","name":"Acidulated Malt","type":"grain","amountKg":0.63}],"hops":[{"id":"h1","name":"Cascade","amountG":6.3,"use":"boil","timeMin":60},{"id":"h2","name":"Amarillo","amountG":6.3,"use":"boil","timeMin":60},{"id":"h3","name":"Centennial","amountG":5,"use":"boil","timeMin":30},{"id":"h4","name":"Chinook","amountG":5,"use":"boil","timeMin":30},{"id":"h5","name":"Cascade","amountG":12.5,"use":"boil","timeMin":0},{"id":"h6","name":"Centennial","amountG":7.5,"use":"boil","timeMin":0},{"id":"h7","name":"Chinook","amountG":7.5,"use":"boil","timeMin":0},{"id":"h8","name":"Amarillo","amountG":12.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 2007 - Pilsen Lager™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":73.9}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":9}],"targets":{"og":1.046,"fg":1.012,"ibu":55,"abvPct":4.5,"colorEbc":25},"notes":"Bryggetips: The addition of the acidulated malt tweaks the pH down to aid the yeast fermentation, and helps to creates the crisp lager bite. Be careful not to use more than 10% in any grist, it will turn your mash into jelly!\n\nFørst brygget: 02/2013"}', '{"id":111,"name":"Vagabond Pilsner","tagline":"Hoppy Pilsner.","first_brewed":"02/2013","description":"Take the thirst-quenching crispness of a German Pilsner and combine it with lemon and honey to produce a rewarding modern twist on a beer classic.","image":"111.png","abv":4.5,"ibu":55,"target_fg":1012,"target_og":1046,"ebc":25,"srm":12.5,"ph":4.4,"attenuation_level":73.9,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":9,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":3.5,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.44,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.13,"unit":"kilograms"}},{"name":"Acidulated Malt","amount":{"value":0.63,"unit":"kilograms"}}],"hops":[{"name":"Cascade","amount":{"value":6.25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Amarillo","amount":{"value":6.25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Centennial","amount":{"value":5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Chinook","amount":{"value":5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Cascade","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Centennial","amount":{"value":7.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Chinook","amount":{"value":7.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Amarillo","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 2007 - Pilsen Lager™"},"food_pairing":["Jamaican jerk chicken","Hot dog with grilled onions and spicy ketchup","Shortbread and raspberry jam thumbprint cookie"],"brewers_tips":"The addition of the acidulated malt tweaks the pH down to aid the yeast fermentation, and helps to creates the crisp lager bite. Be careful not to use more than 10% in any grist, it will turn your mash into jelly!","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-112', 'diydog', '112', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/112.json', 'AB:15', 'Salted Caramel Popcorn Strong Ale.', 'strong', 12.8, 50, 1.096, 1.02, 111, 20, 'ab:15 salted caramel popcorn strong ale. sterkt øl maris otter extra pale caramalt munich crystal 150 popcorn sorachi ace willamette wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"AB:15","style":"Sterkt øl","description":"Salted Caramel Popcorn Strong Ale.\n\nA salted caramel popcorn Imperial Ale. Bourbon and Rum barrel aged, this 12.8% ale has complex and twisting flavours. Bitter caramel, wood, smoke, spice, treacle and vanilla are all present and intertwine against a smooth and lightly chewy mouthfeel. The salted caramel popcorn lends subtle hints of a smoky brininess.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":79,"fermentables":[{"id":"f1","name":"Maris Otter Extra Pale","type":"grain","amountKg":6.563},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.313},{"id":"f3","name":"Munich","type":"grain","amountKg":1.25},{"id":"f4","name":"Crystal 150","type":"grain","amountKg":0.313},{"id":"f5","name":"Popcorn","type":"grain","amountKg":0.006}],"hops":[{"id":"h1","name":"Sorachi Ace","amountG":62.5,"use":"boil","timeMin":60},{"id":"h2","name":"Willamette","amountG":25,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79.2}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":68,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.096,"fg":1.02,"ibu":50,"abvPct":12.8,"colorEbc":111},"notes":"Bryggetips: By soaking some oak chips in bourbon, then steeping in the beer you not only get an authentic Bourbon taste - the beer will also gain ABV! Add salt to taste, too much will totally ruin the balance of the beer.\n\nTwist: Adding popped popcorn into the mash, then barrel ageing in fresh bourbon barrels\n\nFørst brygget: 03/2013"}', '{"id":112,"name":"AB:15","tagline":"Salted Caramel Popcorn Strong Ale.","first_brewed":"03/2013","description":"A salted caramel popcorn Imperial Ale. Bourbon and Rum barrel aged, this 12.8% ale has complex and twisting flavours. Bitter caramel, wood, smoke, spice, treacle and vanilla are all present and intertwine against a smooth and lightly chewy mouthfeel. The salted caramel popcorn lends subtle hints of a smoky brininess.","image":"112.png","abv":12.8,"ibu":50,"target_fg":1020,"target_og":1096,"ebc":111,"srm":55.5,"ph":4.4,"attenuation_level":79.17,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":68,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Adding popped popcorn into the mash, then barrel ageing in fresh bourbon barrels"},"ingredients":{"malt":[{"name":"Maris Otter Extra Pale","amount":{"value":6.5625,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.3125,"unit":"kilograms"}},{"name":"Munich","amount":{"value":1.25,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.3125,"unit":"kilograms"}},{"name":"Popcorn","amount":{"value":0.00625,"unit":"kilograms"}}],"hops":[{"name":"Sorachi Ace","amount":{"value":62.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Willamette","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Crispy bacon on flat bread","Glazed ham with crackling coating","Popcorn caramel and chocolate cake"],"brewers_tips":"By soaking some oak chips in bourbon, then steeping in the beer you not only get an authentic Bourbon taste - the beer will also gain ABV! Add salt to taste, too much will totally ruin the balance of the beer.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","OG/FG i kilden gir 10.0 % ABV, men oppgitt ABV er 12.8 % — sjekk tallene."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-113', 'diydog', '113', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/113.json', 'Bracken''s Porter', 'A Tribute To Our Favourite 4 Pawed Friend.', 'stout', 5, 50, 1.049, 1.01, 110, 20, 'bracken''s porter a tribute to our favourite 4 pawed friend. stout og porter extra pale dark crystal roasted barley black malt vic secret bramling cross challenger wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Bracken''s Porter","style":"Stout og porter","description":"A Tribute To Our Favourite 4 Pawed Friend.\n\nThe beer was named Bracken’s Porter as a tribute to our favourite four pawed friend who sadly passed in 2013. Chocolately, robust, warming, laid back and lots of fun - there are plenty of similarities between the two. Bracken we miss you and we hope you like your beer. Long live the original BrewDog.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":80,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":3.63},{"id":"f2","name":"Dark Crystal","type":"grain","amountKg":0.19},{"id":"f3","name":"Roasted Barley","type":"grain","amountKg":0.31},{"id":"f4","name":"Black Malt","type":"grain","amountKg":0.13}],"hops":[{"id":"h1","name":"Vic Secret","amountG":12.5,"use":"boil","timeMin":60},{"id":"h2","name":"Bramling Cross","amountG":12.5,"use":"boil","timeMin":0},{"id":"h3","name":"Challenger","amountG":12.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.049,"fg":1.01,"ibu":50,"abvPct":5,"colorEbc":110},"notes":"Bryggetips: Try to replicate London’s highly carbonated water to really emphasise the dark malt profile.\n\nFørst brygget: 03/2013"}', '{"id":113,"name":"Bracken''s Porter","tagline":"A Tribute To Our Favourite 4 Pawed Friend.","first_brewed":"03/2013","description":"The beer was named Bracken’s Porter as a tribute to our favourite four pawed friend who sadly passed in 2013. Chocolately, robust, warming, laid back and lots of fun - there are plenty of similarities between the two. Bracken we miss you and we hope you like your beer. Long live the original BrewDog.","image":"keg.png","abv":5,"ibu":50,"target_fg":1010,"target_og":1049,"ebc":110,"srm":55,"ph":4.4,"attenuation_level":79,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":3.63,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.19,"unit":"kilograms"}},{"name":"Roasted Barley","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Black Malt","amount":{"value":0.13,"unit":"kilograms"}}],"hops":[{"name":"Vic Secret","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Bramling Cross","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"aroma"},{"name":"Challenger","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Grilled vegetable and chicken teriyaki skewers","Chilli covered burger (Sloppy Joe)","Candied bacon topped chocolate cheesecake"],"brewers_tips":"Try to replicate London’s highly carbonated water to really emphasise the dark malt profile.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-114', 'diydog', '114', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/114.json', 'Fake Lager', 'Bohemian Pilsner.', 'lager', 4.7, 40, 1.046, 1.01, 12, 20, 'fake lager bohemian pilsner. lager og pils extra pale munich caramalt acidulated malt magnum magnum hersbrucker saaz hersbrucker saaz wyeast 2007 - pilsen lager™', '{"schemaVersion":1,"name":"Fake Lager","style":"Lager og pils","description":"Bohemian Pilsner.\n\nFake is the new black. Fake is where it is at. Fake Art, fake brands, fake breasts, and fake lager. We want to play our part in the ugly fallout from the Lager Dream. Say hello to Fake Lager – a zesty, floral 21st century faux masterpiece with added BrewDog bitterness.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":78,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":3.33},{"id":"f2","name":"Munich","type":"grain","amountKg":0.42},{"id":"f3","name":"Caramalt","type":"grain","amountKg":0.28},{"id":"f4","name":"Acidulated Malt","type":"grain","amountKg":0.07}],"hops":[{"id":"h1","name":"Magnum","amountG":7.5,"use":"boil","timeMin":60},{"id":"h2","name":"Magnum","amountG":5,"use":"boil","timeMin":30},{"id":"h3","name":"Hersbrucker","amountG":6.3,"use":"boil","timeMin":30},{"id":"h4","name":"Saaz","amountG":6.3,"use":"boil","timeMin":30},{"id":"h5","name":"Hersbrucker","amountG":18.8,"use":"boil","timeMin":0},{"id":"h6","name":"Saaz","amountG":18.8,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 2007 - Pilsen Lager™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":78}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":10}],"targets":{"og":1.046,"fg":1.01,"ibu":40,"abvPct":4.7,"colorEbc":12},"notes":"Bryggetips: Once the primary fermentation is complete get this beer as cold as you can and let it mature for as long as you''ve got.\n\nFørst brygget: 03/2013"}', '{"id":114,"name":"Fake Lager","tagline":"Bohemian Pilsner.","first_brewed":"03/2013","description":"Fake is the new black. Fake is where it is at. Fake Art, fake brands, fake breasts, and fake lager. We want to play our part in the ugly fallout from the Lager Dream. Say hello to Fake Lager – a zesty, floral 21st century faux masterpiece with added BrewDog bitterness.","image":"114.png","abv":4.7,"ibu":40,"target_fg":1010,"target_og":1046,"ebc":12,"srm":6,"ph":4.4,"attenuation_level":78,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":10,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":3.33,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.42,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.28,"unit":"kilograms"}},{"name":"Acidulated Malt","amount":{"value":0.07,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":7.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Magnum","amount":{"value":5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Hersbrucker","amount":{"value":6.25,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Saaz","amount":{"value":6.25,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Hersbrucker","amount":{"value":18.75,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Saaz","amount":{"value":18.75,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 2007 - Pilsen Lager™"},"food_pairing":["Fried crab cakes with avocado salsa","Spicy shredded pork roll with hot dipping sauce","Key lime pie"],"brewers_tips":"Once the primary fermentation is complete get this beer as cold as you can and let it mature for as long as you''ve got.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-115', 'diydog', '115', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/115.json', '10 Heads High', 'Imperial Red Ale.', 'strong', 7.8, 70, 1.074, 1.015, 90, 20, '10 heads high imperial red ale. sterkt øl extra pale caramalt crystal 150 dark crystal chinook chinook centennial chinook centennial chinook wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"10 Heads High","style":"Sterkt øl","description":"Imperial Red Ale.\n\n10 Heads High is loosely based on our awesome 2011 Prototype beer Hops Kill Nazis. This is an uncompromising 7.8% Imperial Red Ale loaded high with American Hops. Think of this as an Imperial India Red Ale, or a super-charged version of 5am Saint. Either way this is a seriously good beer!","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":77,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":4.75},{"id":"f2","name":"Caramalt","type":"grain","amountKg":1.25},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.5},{"id":"f4","name":"Dark Crystal","type":"grain","amountKg":0.13}],"hops":[{"id":"h1","name":"Chinook","amountG":20,"use":"boil","timeMin":60},{"id":"h2","name":"Chinook","amountG":5,"use":"boil","timeMin":30},{"id":"h3","name":"Centennial","amountG":5,"use":"boil","timeMin":30},{"id":"h4","name":"Chinook","amountG":62.5,"use":"boil","timeMin":0},{"id":"h5","name":"Centennial","amountG":62.5,"use":"boil","timeMin":0},{"id":"h6","name":"Chinook","amountG":100,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79.7}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":18}],"targets":{"og":1.074,"fg":1.015,"ibu":70,"abvPct":7.8,"colorEbc":90},"notes":"Bryggetips: Achieve the red colour by using the ratio of Caramalt, Crystal and Dark Crystal malts. The trick is to get the colour, without too much dried fruit character.\n\nFørst brygget: 04/2013"}', '{"id":115,"name":"10 Heads High","tagline":"Imperial Red Ale.","first_brewed":"04/2013","description":"10 Heads High is loosely based on our awesome 2011 Prototype beer Hops Kill Nazis. This is an uncompromising 7.8% Imperial Red Ale loaded high with American Hops. Think of this as an Imperial India Red Ale, or a super-charged version of 5am Saint. Either way this is a seriously good beer!","image":"115.png","abv":7.8,"ibu":70,"target_fg":1015,"target_og":1074,"ebc":90,"srm":45,"ph":4.4,"attenuation_level":79.7,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":18,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":4.75,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":1.25,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.13,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":20,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Chinook","amount":{"value":5,"unit":"grams"},"add":"middle","attribute":"bitter"},{"name":"Centennial","amount":{"value":5,"unit":"grams"},"add":"middle","attribute":"bitter"},{"name":"Chinook","amount":{"value":62.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Centennial","amount":{"value":62.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Chinook","amount":{"value":100,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Arrabiata pasta","Mulled cheddar","Toasted almond cake"],"brewers_tips":"Achieve the red colour by using the ratio of Caramalt, Crystal and Dark Crystal malts. The trick is to get the colour, without too much dried fruit character.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-116', 'diydog', '116', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/116.json', 'Vice Bier', 'Hoppy Wheat Bier.', 'wheat', 4.3, 25, 1.043, 1.01, 30, 20, 'vice bier hoppy wheat bier. hvete extra pale wheat caramalt waimea amarillo nelson sauvin motueka simcoe citra waimea wyeast 3638 - bavarian wheat™', '{"schemaVersion":1,"name":"Vice Bier","style":"Hvete","description":"Hoppy Wheat Bier.\n\nOur take on the classic German Kristallweizen. A clear German wheat beer, layers of bubblegum and vanilla perfectly balanced with the American and New Zealand hops.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":69,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":2.69},{"id":"f2","name":"Wheat","type":"grain","amountKg":1.25},{"id":"f3","name":"Caramalt","type":"grain","amountKg":0.38}],"hops":[{"id":"h1","name":"Waimea","amountG":2.5,"use":"boil","timeMin":60},{"id":"h2","name":"Amarillo","amountG":2.5,"use":"boil","timeMin":30},{"id":"h3","name":"Nelson Sauvin","amountG":2.5,"use":"boil","timeMin":30},{"id":"h4","name":"Motueka","amountG":2.5,"use":"boil","timeMin":30},{"id":"h5","name":"Simcoe","amountG":6,"use":"boil","timeMin":0},{"id":"h6","name":"Citra","amountG":6,"use":"boil","timeMin":0},{"id":"h7","name":"Waimea","amountG":6,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 3638 - Bavarian Wheat™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":81.8}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":22}],"targets":{"og":1.043,"fg":1.01,"ibu":25,"abvPct":4.3,"colorEbc":30},"notes":"Bryggetips: Ferment at higher or lower temperatures to select the esters that will create clove- like or banana-like flavours.\n\nFørst brygget: 04/2013"}', '{"id":116,"name":"Vice Bier","tagline":"Hoppy Wheat Bier.","first_brewed":"04/2013","description":"Our take on the classic German Kristallweizen. A clear German wheat beer, layers of bubblegum and vanilla perfectly balanced with the American and New Zealand hops.","image":"keg.png","abv":4.3,"ibu":25,"target_fg":1010,"target_og":1043,"ebc":30,"srm":15,"ph":4,"attenuation_level":81.8,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":22,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":2.69,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":1.25,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.38,"unit":"kilograms"}}],"hops":[{"name":"Waimea","amount":{"value":2.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Amarillo","amount":{"value":2.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Nelson Sauvin","amount":{"value":2.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Motueka","amount":{"value":2.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Simcoe","amount":{"value":6,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Citra","amount":{"value":6,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Waimea","amount":{"value":6,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 3638 - Bavarian Wheat™"},"food_pairing":["Citrus salad with balsamic dressing","Lobster","Ginger and orange cookies"],"brewers_tips":"Ferment at higher or lower temperatures to select the esters that will create clove- like or banana-like flavours.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-117', 'diydog', '117', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/117.json', 'Misspent Youth', 'Milk & Honey Scotch Ale.', 'amber', 7.3, 30, 1.079, 1.02, 120, 20, 'misspent youth milk & honey scotch ale. amber, rød og brun pale ale caramalt dark crystal smoked weyermann flaked oats brown amber chocolate munich crystal 150 first gold fuggles honey lactose first gold fuggles wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Misspent Youth","style":"Amber, rød og brun","description":"Milk & Honey Scotch Ale.\n\nThe brainchild of our small batch brewer, George Woods. A dangerously drinkable milk sugar- infused Scotch Ale.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":81,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":2.18},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.3},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.3},{"id":"f4","name":"Smoked Weyermann","type":"grain","amountKg":1.8},{"id":"f5","name":"Flaked Oats","type":"grain","amountKg":0.6},{"id":"f6","name":"Brown","type":"grain","amountKg":0.6},{"id":"f7","name":"Amber","type":"grain","amountKg":0.1},{"id":"f8","name":"Chocolate","type":"grain","amountKg":0.05},{"id":"f9","name":"Munich","type":"grain","amountKg":0.6},{"id":"f10","name":"Crystal 150","type":"grain","amountKg":0.2}],"hops":[{"id":"h1","name":"First Gold","amountG":25,"use":"boil","timeMin":60},{"id":"h2","name":"Fuggles","amountG":25,"use":"boil","timeMin":60},{"id":"h5","name":"First Gold","amountG":10,"use":"boil","timeMin":0},{"id":"h6","name":"Fuggles","amountG":10,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":74.7}],"miscs":[{"id":"x3","name":"Honey","amount":250,"unit":"g","use":"boil","timeMin":30},{"id":"x4","name":"Lactose","amount":375,"unit":"g","use":"boil","timeMin":30}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":67,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.079,"fg":1.02,"ibu":30,"abvPct":7.3,"colorEbc":120},"notes":"Bryggetips: Lots of malt in this one. Mash-in in stages, and spread the pale ale malt throughout the mash to provide stability. If the mash starts to sink, stop, wait a few minutes while mixing, then start again.\n\nTwist: See honey and lactose additions\n\nFørst brygget: 04/2013"}', '{"id":117,"name":"Misspent Youth","tagline":"Milk & Honey Scotch Ale.","first_brewed":"04/2013","description":"The brainchild of our small batch brewer, George Woods. A dangerously drinkable milk sugar- infused Scotch Ale.","image":"keg.png","abv":7.3,"ibu":30,"target_fg":1020,"target_og":1079,"ebc":120,"srm":60,"ph":4.4,"attenuation_level":74.7,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":67,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"See honey and lactose additions"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":2.18,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.3,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.3,"unit":"kilograms"}},{"name":"Smoked Weyermann","amount":{"value":1.8,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Brown","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Amber","amount":{"value":0.1,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.05,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.2,"unit":"kilograms"}}],"hops":[{"name":"First Gold","amount":{"value":25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Fuggles","amount":{"value":25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Honey","amount":{"value":250,"unit":"grams"},"add":"middle","attribute":"Flavour"},{"name":"Lactose","amount":{"value":375,"unit":"grams"},"add":"middle","attribute":"Flavour"},{"name":"First Gold","amount":{"value":10,"unit":"grams"},"add":"end","attribute":"aroma"},{"name":"Fuggles","amount":{"value":10,"unit":"grams"},"add":"end","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Roasted garlic and chilli infused camembert cheese","Korean style chicken wings","Chocolate milk shake"],"brewers_tips":"Lots of malt in this one. Mash-in in stages, and spread the pale ale malt throughout the mash to provide stability. If the mash starts to sink, stop, wait a few minutes while mixing, then start again.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-118', 'diydog', '118', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/118.json', '#Mashtag 2013', 'Democratic American Brown Ale.', 'amber', 7.5, 50, 1.07, 1.013, 40, 20, '#mashtag 2013 democratic american brown ale. amber, rød og brun extra pale dark crystal caramalt amber chocolate motueka magnum cascade amarillo cascade amarillo willamette wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"#Mashtag 2013","style":"Amber, rød og brun","description":"Democratic American Brown Ale.\n\nA rich, nutty Brown Ale with a deep, rich malt profile, hopped with a range of citrusy and spicy US varieties. Mellow yet endlessly complex, with enough chocolate and fruit character to balance the bitterness, and a soft oaky roundness.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":76,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5},{"id":"f2","name":"Dark Crystal","type":"grain","amountKg":0.5},{"id":"f3","name":"Caramalt","type":"grain","amountKg":0.44},{"id":"f4","name":"Amber","type":"grain","amountKg":0.25},{"id":"f5","name":"Chocolate","type":"grain","amountKg":0.19}],"hops":[{"id":"h1","name":"Motueka","amountG":10,"use":"boil","timeMin":60},{"id":"h2","name":"Magnum","amountG":12.5,"use":"boil","timeMin":60},{"id":"h3","name":"Cascade","amountG":6,"use":"boil","timeMin":30},{"id":"h4","name":"Amarillo","amountG":6,"use":"boil","timeMin":30},{"id":"h5","name":"Cascade","amountG":5,"use":"boil","timeMin":0},{"id":"h6","name":"Amarillo","amountG":5,"use":"boil","timeMin":0},{"id":"h7","name":"Willamette","amountG":5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":81.4}],"mis