INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-129', 'diydog', '129', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/129.json', 'Dead Metaphor', 'Scottish Breakfast Stout.', 'stout', 6.8, 30, 1.068, 1.016, 86, 20, 'dead metaphor scottish breakfast stout. stout og porter extra pale wheat dark crystal brown black malt carafa special malt type 1 flaked oats crystal 150 magnum wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Dead Metaphor","style":"Stout og porter","description":"Scottish Breakfast Stout.\n\nScottish chocolate breakfast Stout - brewed with Brazilian Sertão coffee, Venezuelan cacao and (for the Scottish element) oatmeal. Smooth, chocolately and rich, with a honeycomb mouthfeel and a rich red berry coffee character. Brewed with our beer blogger friends from The Beer Cast and Hopzine.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":73,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":4.38},{"id":"f2","name":"Wheat","type":"grain","amountKg":0.31},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.19},{"id":"f4","name":"Brown","type":"grain","amountKg":0.31},{"id":"f5","name":"Black Malt","type":"grain","amountKg":0.31},{"id":"f6","name":"Carafa Special Malt Type 1","type":"grain","amountKg":0.19},{"id":"f7","name":"Flaked Oats","type":"grain","amountKg":0.44},{"id":"f8","name":"Crystal 150","type":"grain","amountKg":0.31}],"hops":[{"id":"h1","name":"Magnum","amountG":25,"use":"boil","timeMin":60}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":76.5}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets"