INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-131', 'diydog', '131', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/131.json', 'American Ale', 'Unleash the Yeast Series.', 'other', 6.3, 55, 1.06, 1.012, 30, 20, 'american ale unleash the yeast series. annet extra pale caramalt dark crystal munich centennial amarillo centennial amarillo centennial amarillo wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"American Ale","description":"Unleash the Yeast Series.\n\nOur Unleash the Yeast series was an epic experiment into the differences in aroma and flavour provided by switching up your yeast. We brewed up a wort with a light caramel note and some toasty biscuit flavour, and hopped it with Amarillo and Centennial for a citrusy bitterness. Everything else is down to the yeast. American Ale used a clean fermenting strain which provides some faint fruity notes.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":81,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":4.58},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.25},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.06},{"id":"f4","name":"Munich","type":"grain","amountKg":0.25}],"hops":[{"id":"h1","name":"Centennial","amountG":5,"use":"boil","timeMin":60},{"id":"h2","name":"Amarillo","amountG":5,"use":"boil","timeMin":60},{"id":"h3","name":"Centennial","amountG":10,"use":"boil","timeMin":30},{"id":"h4","name":"Amarillo","amountG":10,"use":"boil","timeMin":30},{"id":"h5","name":"Centennial","amountG":17.5,"use":"boil","timeMin":0},{"id":"h6","name":"Amarillo","amountG":17.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":80}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.06,"fg":1.012,"ibu":55,"abvPct":6.3,"colorEbc":30},"notes":"Bryggetips: Play around with the fermentation temperature to get the best flavour profile from the individual yeasts.\n\nFørst brygget: 09/2013"}', '{"id":131,"name":"American Ale","tagline":"Unleash the Yeast Series.","first_brewed":"09/2013","description":"Our Unleash the Yeast series was an epic experiment into the differences in aroma and flavour provided by switching up your yeast. We brewed up a wort with a light caramel note and some toasty biscuit flavour, and hopped it with Amarillo and Centennial for a citrusy bitterness. Everything else is down to the yeast. American Ale used a clean fermenting strain which provides some faint fruity notes.","image":"131.png","abv":6.3,"ibu":55,"target_fg":1012,"target_og":1060,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":80,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":4.58,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.06,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.25,"unit":"kilograms"}}],"hops":[{"name":"Centennial","amount":{"value":5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Amarillo","amount":{"value":5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Centennial","amount":{"value":10,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Amarillo","amount":{"value":10,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Centennial","amount":{"value":17.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Amarillo","amount":{"value":17.5,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Fried brie bites","American cheese burger","Poached apple tart"],"brewers_tips":"Play around with the fermentation temperature to get the best flavour profile from the individual yeasts.","contributed_by":"Ali Skinner <AliSkinner>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-132', 'diydog', '132', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/132.json', 'Bavarian Weizen', 'Unleash the Yeast Series.', 'wheat', 6.3, 55, 1.06, 1.012, 30, 20, 'bavarian weizen unleash the yeast series. hvete extra pale caramalt dark crystal munich centennial amarillo centennial amarillo centennial amarillo wlp351 - bavarian weizen', '{"schemaVersion":1,"name":"Bavarian Weizen","style":"Hvete","description":"Unleash the Yeast Series.\n\nOur Unleash the Yeast series was an epic experiment into the differences in aroma and flavour provided by switching up your yeast. We brewed up a wort with a light caramel note and some toasty biscuit flavour, and hopped it with Amarillo and Centennial for a citrusy bitterness. Everything else is down to the yeast. Bavarian Weizen yeast adds traditional weissbier notes of banana and clove.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":81,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":4.58},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.25},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.06},{"id":"f4","name":"Munich","type":"grain","amountKg":0.25}],"hops":[{"id":"h1","name":"Centennial","amountG":5,"use":"boil","timeMin":60},{"id":"h2","name":"Amarillo","amountG":5,"use":"boil","timeMin":60},{"id":"h3","name":"Centennial","amountG":10,"use":"boil","timeMin":30},{"id":"h4","name":"Amarillo","amountG":10,"use":"boil","timeMin":30},{"id":"h5","name":"Centennial","amountG":17.5,"use":"boil","timeMin":0},{"id":"h6","name":"Amarillo","amountG":17.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"WLP351 - Bavarian Weizen","form":"liquid","amount":1,"unit":"pkg","attenuationPct":80}],"miscs":[],"mashS