INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-141', 'diydog', '141', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/141.json', 'Lumberjack Stout', 'Blueberry Bacon Stout.', 'stout', 15.2, 20, 1.11, 1.02, 158, 20, 'lumberjack stout blueberry bacon stout. stout og porter extra pale carafa special malt type 3 flaked oats smoked malt crystal galena willamette wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Lumberjack Stout","style":"Stout og porter","description":"Blueberry Bacon Stout.\n\nLumberjack Stout is an intense beast that took its inspriation from what an actual bona-fide lumberjack might have for breakfast. Flavours of molasses, chocolate, smoke, berry, coffee and more, with a low bitterness, leaning this beer firmly towards the malty side.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":48,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":10.63},{"id":"f2","name":"Carafa Special Malt Type 3","type":"grain","amountKg":1.25},{"id":"f3","name":"Flaked Oats","type":"grain","amountKg":2.19},{"id":"f4","name":"Smoked Malt","type":"grain","amountKg":0.63},{"id":"f5","name":"Crystal","type":"grain","amountKg":1.25}],"hops":[{"id":"h1","name":"Galena","amountG":36,"use":"boil","timeMin":60},{"id":"h2","name":"Willamette","amountG":37.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":105}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.11,"fg":1.02,"ibu":20,"abvPct":15.2,"colorEbc":158},"notes":"Bryggetips: Adding extra smoked malt will amp up the bacon character.\n\nTwist: Blueberries, maple syrup and coffee, then aged in ex Grain whisky casks. Maple Syrup: 50g at end. Blueberries: 100g at middle.\n\nFørst brygget: 12/2013"}', '{"id":141,"name":"Lumberjack Stout","tagline":"Blueberry Bacon Stout.","first_brewed":"12/2013","description":"Lumberjack Stout is an intense beast that took its inspriation from what an actual bona-fide lumberjack might have for breakfast. Flavours of molasses, chocolate, smoke, berry, coffee and more, with a low bitterness, leaning this beer firmly towards the malty side.","image":"keg.png","abv":15.2,"ibu":20,"target_fg":1020,"target_og":1110,"ebc":158,"srm":79,"ph":4.4,"attenuation_level":82,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":105}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Blueberries, maple syrup and coffee, then aged in ex Grain whisky casks. Maple Syrup: 50g at end. Blueberries: 100g at middle."},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":10.63,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":1.25,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":2.19,"unit":"kilograms"}},{"name":"Smoked Malt","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Crystal","amount":{"value":1.25,"unit":"kilograms"}}],"hops":[{"name":"Galena","amount":{"value":36,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Willamette","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Maple syrup drizzled chocolate chip pancakes","Fried bacon with crispy honeycomb bits","Coffee cake"],"brewers_tips":"Adding extra smoked malt will amp up the bacon character.","contributed_by":"Ali Skinner <AliSkinner>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","OG/FG i kilden gir 11.8 % ABV, men oppgitt ABV er 15.2 % — sjekk tallene.","16.0 kg malt til 20 L er urealistisk — trolig en feil i kilden."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-142', 'diydog', '142', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/142.json', 'Clown King', 'US Style Barley Wine.', 'strong', 12, 85, 1.13, 1.02, 24, 20, 'clown king us style barley wine. sterkt øl extra pale caramalt crystal 150 brown munich magnum simcoe mosaic ahtanum ahtanum mosaic mosaic ahtanum simcoe wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Clown King","style":"Sterkt øl","description":"US Style Barley Wine.\n\nA heavy hitting combination of rich malt flavours and relentless, bitter hops. Aromas of caramel and toasted marshmallow, with raisin and dried fruit, alongside a spicy undercurrent of resin. With toasty malt and sweet dark fruit flavours, and a smooth, chewy mouthfeel, you’ll be lulled into a false sense of security, before the intense pine-sap resin draws out a huge bitter finish.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":80,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":9.5},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.5},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.13},{"id":"f4","name":"Brown","type":"grain","amountKg":0.25},{"id":"f5","name":"Munich","type":"grain","amountKg":0.88}],"hops":[{"id":"h1","name":"Magnum","amountG":25,"use":"boil","timeMin":60},{"id":"h2","name":"Simcoe","amountG":18.5,"use":"boil","timeMin":30},{"id":"h3","name":"Mosaic","amountG":12.5,"use":"boil","timeMin":30},{"id":"h4","name":"Ahtanum","amountG":18.5,"use":"boil","timeMin":30},{"id":"h5","name":"Ahtanum","amountG":18.5,"use":"boil","timeMin":0},{"id":"h6","name":"Mosaic","amountG":12.5,"use":"boil","timeMin":0},{"id":"h7","name":"Mosaic","amountG":62.5,"use":"dry_hop"},{"id":"h8","name":"Ahtanum","amountG":62.5,"use":"dry_hop"},{"id":"h9","name":"Simcoe","amountG":62.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg"}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":90}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.13,"fg":1.02,"ibu":85,"abvPct":12,"colorEbc":24},"notes":"Bryggetips: Leave this beer to chill in the cellar for a few months to round off the flavour profile.\n\nFørst brygget: 12/2013"}', '{"id":142,"name":"Clown King","tagline":"US Style Barley Wine.","first_brewed":"12/2013","description":"A heavy hitting combination of rich malt flavours and relentless, bitter hops. Aromas of caramel and toasted marshmallow, with raisin and dried fruit, alongside a spicy undercurrent of resin. With toasty malt and sweet dark fruit flavours, and a smooth, chewy mouthfeel, you’ll be lulled into a false sense of security, before the intense pine-sap resin draws out a huge bitter finish.","image":"142.png","abv":12,"ibu":85,"target_fg":1020,"target_og":1130,"ebc":24,"srm":12,"ph":4.4,"attenuation_level":102.3,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":90}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":9.5,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.13,"unit":"kilograms"}},{"name":"Brown","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.88,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Simcoe","amount":{"value":18.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Mosaic","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Ahtanum","amount":{"value":18.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Ahtanum","amount":{"value":18.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Mosaic","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Mosaic","amount":{"value":62.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Ahtanum","amount":{"value":62.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Simcoe","amount":{"value":62.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Aged Stilton","Flaky pastry beef pie and sweet potato mash","Chocolate pecan praline cake"],"brewers_tips":"Leave this beer to chill in the cellar for a few months to round off the flavour profile.","contributed_by":"Ali Skinner <AliSkinner>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","OG/FG i kilden gir 14.4 % ABV, men oppgitt ABV er 12 % — sjekk tallene."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-143', 'diydog', '143', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/143.json', 'Hello My Name is Vladimir', 'Limonnik Infused Imperial IPA (Not for Gays).', 'ipa', 8.2, 70, 1.076, 1.013, 16, 20, 'hello my name is vladimir limonnik infused imperial ipa (not for gays). ipa extra pale caramalt wheat citra citra citra blackberry concentrate sour cherry puree citra mosaic centennial wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Hello My Name is Vladimir","style":"IPA","description":"Limonnik Infused Imperial IPA (Not for Gays).\n\nA Limonnik-infused, triple dry- hopped double IPA. Dry berry tartness and intense citrus hop character meld with a dry bready malt base, boosted by a hint of alcohol warmth. This beer was brewed as a protest against the anti-LGBT legislation in Russia surrounding the Sochi Olympics.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5.77},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.63},{"id":"f3","name":"Wheat","type":"grain","amountKg":0.63}],"hops":[{"id":"h1","name":"Citra","amountG":4,"use":"boil","timeMin":60},{"id":"h2","name":"Citra","amountG":37.5,"use":"boil","timeMin":30},{"id":"h3","name":"Citra","amountG":37.5,"use":"boil","timeMin":0},{"id":"h6","name":"Citra","amountG":112.5,"use":"dry_hop"},{"id":"h7","name":"Mosaic","amountG":200,"use":"dry_hop"},{"id":"h8","name":"Centennial","amountG":187.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83}],"miscs":[{"id":"x4","name":"Blackberry Concentrate","amount":62.5,"unit":"g","use":"boil","timeMin":0},{"id":"x5","name":"Sour Cherry Puree","amount":250,"unit":"g","use":"boil","timeMin":0}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.076,"fg":1.013,"ibu":70,"abvPct":8.2,"colorEbc":16},"notes":"Bryggetips: If you can''t get hold of Limonnik berries, rose hips make an accessible alternative!\n\nTwist: Fruit in the boil, berries in the fermenter. Limonnik Berries: 2.5, Twist.\n\nFørst brygget: 01/2014"}', '{"id":143,"name":"Hello My Name is Vladimir","tagline":"Limonnik Infused Imperial IPA (Not for Gays).","first_brewed":"01/2014","description":"A Limonnik-infused, triple dry- hopped double IPA. Dry berry tartness and intense citrus hop character meld with a dry bready malt base, boosted by a hint of alcohol warmth. This beer was brewed as a protest against the anti-LGBT legislation in Russia surrounding the Sochi Olympics.","image":"143.png","abv":8.2,"ibu":70,"target_fg":1013,"target_og":1076,"ebc":16,"srm":8,"ph":4.4,"attenuation_level":83,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Fruit in the boil, berries in the fermenter. Limonnik Berries: 2.5, Twist."},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5.77,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.63,"unit":"kilograms"}}],"hops":[{"name":"Citra","amount":{"value":4,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Citra","amount":{"value":37.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Citra","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Blackberry Concentrate","amount":{"value":62.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Sour Cherry Puree","amount":{"value":250,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Citra","amount":{"value":112.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Mosaic","amount":{"value":200,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Centennial","amount":{"value":187.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Russian mini pork pies","Beef Stroganoff","Chocolate and fruit cake"],"brewers_tips":"If you can''t get hold of Limonnik berries, rose hips make an accessible alternative!","contributed_by":"Ali Skinner <AliSkinner>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-144', 'diydog', '144', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/144.json', 'Bourbon Baby', 'Barrel-Aged Scotch Ale.', 'amber', 5.8, 35, 1.049, 1.005, 44, 20, 'bourbon baby barrel-aged scotch ale. amber, rød og brun extra pale munich dark crystal wheat flaked oats carafa special malt type 3 amber weyermann beech smoked first gold willamette hallertauer mittelfrüh wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Bourbon Baby","style":"Amber, rød og brun","description":"Barrel-Aged Scotch Ale.\n\nSanta Paws Scotch ale aged in bourbon barrels - light, dry and toasty, with vanilla, hints of chocolate and ginger biscuit, and a faint spicy hoppiness.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":80,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":1.75},{"id":"f2","name":"Munich","type":"grain","amountKg":0.44},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.5},{"id":"f4","name":"Wheat","type":"grain","amountKg":0.56},{"id":"f5","name":"Flaked Oats","type":"grain","amountKg":0.56},{"id":"f6","name":"Carafa Special Malt Type 3","type":"grain","amountKg":0.13},{"id":"f7","name":"Amber","type":"grain","amountKg":0.25},{"id":"f8","name":"Weyermann Beech Smoked","type":"grain","amountKg":0.06}],"hops":[{"id":"h1","name":"First Gold","amountG":18.5,"use":"boil","timeMin":60},{"id":"h2","name":"Willamette","amountG":12.5,"use":"boil","timeMin":30},{"id":"h3","name":"Hallertauer Mittelfrüh","amountG":6,"use":"boil","timeMin":30}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":90}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":90}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.049,"fg":1.005,"ibu":35,"abvPct":5.8,"colorEbc":44},"notes":"Bryggetips: Use bourbon-soaked oak chips in secondary to achieve barrel character.\n\nFørst brygget: 01/2014"}', '{"id":144,"name":"Bourbon Baby","tagline":"Barrel-Aged Scotch Ale.","first_brewed":"01/2014","description":"Santa Paws Scotch ale aged in bourbon barrels - light, dry and toasty, with vanilla, hints of chocolate and ginger biscuit, and a faint spicy hoppiness.","image":"144.png","abv":5.8,"ibu":35,"target_fg":1005,"target_og":1049,"ebc":44,"srm":22,"ph":4.4,"attenuation_level":90,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":90}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":1.75,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.44,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.56,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.56,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":0.13,"unit":"kilograms"}},{"name":"Amber","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Weyermann Beech Smoked","amount":{"value":0.06,"unit":"kilograms"}}],"hops":[{"name":"First Gold","amount":{"value":18.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Willamette","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Hallertauer Mittelfrüh","amount":{"value":6,"unit":"grams"},"add":"middle","attribute":"flavour"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Blackened cajun beef","Pulled pork","Millionaire''s shortbread"],"brewers_tips":"Use bourbon-soaked oak chips in secondary to achieve barrel character.","contributed_by":"Ali Skinner <AliSkinner>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-145', 'diydog', '145', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/145.json', 'AB:16', 'Coffee-Infused Belgian Quad.', 'belgian', 10.6, 55, 1.09, 1.012, 30, 20, 'ab:16 coffee-infused belgian quad. belgisk og saison extra pale wheat munich crystal 150 chocolate waimea saaz fuggles wyeast 3787 - trappist high gravity™', '{"schemaVersion":1,"name":"AB:16","style":"Belgisk og saison","description":"Coffee-Infused Belgian Quad.\n\nOn the nose, clove and nutmeg, cafe au lait, subtle dark fruit notes, and hints of candied lemon peel. On the palate, smooth & fruity espresso, milk chocolate, and warm brandy-soaked currants are in the middle of a high-class dance-off against the spicy and peppery Belgian character. The overall impression evokes malt loaf or ginger cake.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":67,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":7.75},{"id":"f2","name":"Wheat","type":"grain","amountKg":0.5},{"id":"f3","name":"Munich","type":"grain","amountKg":0.5},{"id":"f4","name":"Crystal 150","type":"grain","amountKg":0.38},{"id":"f5","name":"Chocolate","type":"grain","amountKg":0.13}],"hops":[{"id":"h1","name":"Waimea","amountG":15,"use":"boil","timeMin":60},{"id":"h2","name":"Saaz","amountG":12.5,"use":"boil","timeMin":30},{"id":"h3","name":"Fuggles","amountG":12.5,"use":"boil","timeMin":30}],"cultures":[{"id":"y1","name":"Wyeast 3787 - Trappist High Gravity™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":86.7}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.09,"fg":1.012,"ibu":55,"abvPct":10.6,"colorEbc":30},"notes":"Bryggetips: For the traditional cellering, age this beer in vessel or bottle for 2 - 3 months at cellar temperature.\n\nTwist: Coffee Beans: 250g FV. Raisins: 90g at end. Dark Sugar:140g at end.\n\nFørst brygget: 02/2014"}', '{"id":145,"name":"AB:16","tagline":"Coffee-Infused Belgian Quad.","first_brewed":"02/2014","description":"On the nose, clove and nutmeg, cafe au lait, subtle dark fruit notes, and hints of candied lemon peel. On the palate, smooth & fruity espresso, milk chocolate, and warm brandy-soaked currants are in the middle of a high-class dance-off against the spicy and peppery Belgian character. The overall impression evokes malt loaf or ginger cake.","image":"145.png","abv":10.6,"ibu":55,"target_fg":1012,"target_og":1090,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":86.7,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Coffee Beans: 250g FV. Raisins: 90g at end. Dark Sugar:140g at end."},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":7.75,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.38,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.13,"unit":"kilograms"}}],"hops":[{"name":"Waimea","amount":{"value":15,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Saaz","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Fuggles","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"}],"yeast":"Wyeast 3787 - Trappist High Gravity™"},"food_pairing":["Roasted duck","Gorgonzola and rye nut bread with smoked honey ham","Raspberry coffee cheesecake"],"brewers_tips":"For the traditional cellering, age this beer in vessel or bottle for 2 - 3 months at cellar temperature.","contributed_by":"Ali Skinner <AliSkinner>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-146', 'diydog', '146', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/146.json', 'Comet', 'Single Hop India Pale Ale', 'ipa', 7.2, 70, 1.067, 1.012, 30, 20, 'comet single hop india pale ale ipa extra pale caramalt dark crystal comet comet comet comet wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Comet","style":"IPA","description":"Single Hop India Pale Ale\n\nA potently bitter hop variety originally grown in the US around 40 years ago, Comet has been newly resurrected - this German version has bold resinous grapefruit flavours, which add a huge fresh hop aroma to this IPA.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":77,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5.65},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.31},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.06}],"hops":[{"id":"h1","name":"Comet","amountG":15,"use":"boil","timeMin":60},{"id":"h2","name":"Comet","amountG":25,"use":"boil","timeMin":30},{"id":"h3","name":"Comet","amountG":37.5,"use":"boil","timeMin":0},{"id":"h4","name":"Comet","amountG":250,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.1}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.067,"fg":1.012,"ibu":70,"abvPct":7.2,"colorEbc":30},"notes":"Bryggetips: Experiment with other high alpha hops during dry-hop to discover their aroma and flavour characteristics.\n\nFørst brygget: 02/2014"}', '{"id":146,"name":"Comet","tagline":"Single Hop India Pale Ale","first_brewed":"02/2014","description":"A potently bitter hop variety originally grown in the US around 40 years ago, Comet has been newly resurrected - this German version has bold resinous grapefruit flavours, which add a huge fresh hop aroma to this IPA.","image":"146.png","abv":7.2,"ibu":70,"target_fg":1012,"target_og":1067,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":82.1,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5.65,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.06,"unit":"kilograms"}}],"hops":[{"name":"Comet","amount":{"value":15,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Comet","amount":{"value":25,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Comet","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Comet","amount":{"value":250,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Margherita pizza with chili flakes","Spicy Thai peanut satay","Panna cotta with a grapefruit tuile"],"brewers_tips":"Experiment with other high alpha hops during dry-hop to discover their aroma and flavour characteristics.","contributed_by":"Ali Skinner <AliSkinner>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-147', 'diydog', '147', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/147.json', 'HBC 366 - IPA Is Dead', 'Single Hop India Pale Ale.', 'ipa', 7.2, 70, 1.067, 1.012, 30, 20, 'hbc 366 - ipa is dead single hop india pale ale. ipa extra pale caramalt dark crystal hbc 366 hbc 366 hbc 366 hbc 366 wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"HBC 366 - IPA Is Dead","style":"IPA","description":"Single Hop India Pale Ale.\n\nA new, at-the-time un-named American hop now known as Equinox. Piney, resinous with spicy fruit notes and biting grapefruit. Stewed orange and pineapple with a resinous edge.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":77,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5.65},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.31},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.06}],"hops":[{"id":"h1","name":"HBC 366","amountG":2.5,"use":"boil","timeMin":60},{"id":"h2","name":"HBC 366","amountG":25,"use":"boil","timeMin":30},{"id":"h3","name":"HBC 366","amountG":37.5,"use":"boil","timeMin":0},{"id":"h4","name":"HBC 366","amountG":250,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.1}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.067,"fg":1.012,"ibu":70,"abvPct":7.2,"colorEbc":30},"notes":"Bryggetips: With new hop varieties, growers are discovering flavour attributes completely unexpected from hops, which can add unique character to your brews.\n\nFørst brygget: 02/2014"}', '{"id":147,"name":"HBC 366 - IPA Is Dead","tagline":"Single Hop India Pale Ale.","first_brewed":"02/2014","description":"A new, at-the-time un-named American hop now known as Equinox. Piney, resinous with spicy fruit notes and biting grapefruit. Stewed orange and pineapple with a resinous edge.","image":"147.png","abv":7.2,"ibu":70,"target_fg":1012,"target_og":1067,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":82.1,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5.65,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.06,"unit":"kilograms"}}],"hops":[{"name":"HBC 366","amount":{"value":2.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"HBC 366","amount":{"value":25,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"HBC 366","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"HBC 366","amount":{"value":250,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Spicy black bean and chicken tortilla soup","Spicy lamb tikka masala","Fruity bread pudding"],"brewers_tips":"With new hop varieties, growers are discovering flavour attributes completely unexpected from hops, which can add unique character to your brews.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-148', 'diydog', '148', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/148.json', 'Kohatu - IPA Is Dead', 'Single Hop India Pale Ale.', 'ipa', 7.2, 70, 1.067, 1.012, 30, 20, 'kohatu - ipa is dead single hop india pale ale. ipa extra pale caramalt dark crystal kohatu kohatu kohatu kohatu wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Kohatu - IPA Is Dead","style":"IPA","description":"Single Hop India Pale Ale.\n\nAs you’d expect from a New Zealand hop variety, Kohatu contributes bags of tropical fruit, but with loads of lime notes, & pineapple hits. Seriously fruity, with sweet, juicy melon and stonefruit notes.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":77,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5.65},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.31},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.06}],"hops":[{"id":"h1","name":"Kohatu","amountG":37.5,"use":"boil","timeMin":60},{"id":"h2","name":"Kohatu","amountG":25,"use":"boil","timeMin":30},{"id":"h3","name":"Kohatu","amountG":37.5,"use":"boil","timeMin":0},{"id":"h4","name":"Kohatu","amountG":250,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.1}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.067,"fg":1.012,"ibu":70,"abvPct":7.2,"colorEbc":30},"notes":"Bryggetips: New Zealand hops are in short supply - club together with other brewers to try and get hold of some, or ask your local brewery if you can buy small amounts from them.\n\nFørst brygget: 02/2014"}', '{"id":148,"name":"Kohatu - IPA Is Dead","tagline":"Single Hop India Pale Ale.","first_brewed":"02/2014","description":"As you’d expect from a New Zealand hop variety, Kohatu contributes bags of tropical fruit, but with loads of lime notes, & pineapple hits. Seriously fruity, with sweet, juicy melon and stonefruit notes.","image":"148.png","abv":7.2,"ibu":70,"target_fg":1012,"target_og":1067,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":82.1,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5.65,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.06,"unit":"kilograms"}}],"hops":[{"name":"Kohatu","amount":{"value":37.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Kohatu","amount":{"value":25,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Kohatu","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Kohatu","amount":{"value":250,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Tuna sushi roll with spicy mayonnaise sauce","Thai green curry","Pineapple upside down cake"],"brewers_tips":"New Zealand hops are in short supply - club together with other brewers to try and get hold of some, or ask your local brewery if you can buy small amounts from them.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-149', 'diydog', '149', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/149.json', 'Hello My Name Is Zé (w/ 2Cabeças)', 'Passionfruit IPA - 2Cabecas Collab.', 'ipa', 6.4, 50, 1.061, 1.012, 20, 20, 'hello my name is zé (w/ 2cabeças) passionfruit ipa - 2cabecas collab. ipa extra pale caramalt vic secret centennial centennial kohatu vic secret citra simcoe centennial amarillo wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Hello My Name Is Zé (w/ 2Cabeças)","style":"IPA","description":"Passionfruit IPA - 2Cabecas Collab.\n\nPunk multiplied by Jack Hammer, divided by passionfruit with some Brazilian spirit factored in too. A well-rounded IPA, with bags of tropical flavour boosted by the addition of passionfruit, which unsurprisingly dominates the aroma of this summery IPA.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":4.88},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.75}],"hops":[{"id":"h1","name":"Vic Secret","amountG":12.5,"use":"boil","timeMin":60},{"id":"h2","name":"Centennial","amountG":12.5,"use":"boil","timeMin":30},{"id":"h3","name":"Centennial","amountG":12.5,"use":"boil","timeMin":0},{"id":"h4","name":"Kohatu","amountG":16.5,"use":"boil","timeMin":0},{"id":"h5","name":"Vic Secret","amountG":12.5,"use":"dry_hop"},{"id":"h6","name":"Citra","amountG":62.5,"use":"dry_hop"},{"id":"h7","name":"Simcoe","amountG":87.5,"use":"dry_hop"},{"id":"h8","name":"Centennial","amountG":37.5,"use":"dry_hop"},{"id":"h9","name":"Amarillo","amountG":50,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":80.3}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.061,"fg":1.012,"ibu":50,"abvPct":6.4,"colorEbc":20},"notes":"Bryggetips: Try adding some of the passionfruit in the cold conditioning phase.\n\nTwist: Passionfruit: 438g at End\n\nFørst brygget: 03/2014"}', '{"id":149,"name":"Hello My Name Is Zé (w/ 2Cabeças)","tagline":"Passionfruit IPA - 2Cabecas Collab.","first_brewed":"03/2014","description":"Punk multiplied by Jack Hammer, divided by passionfruit with some Brazilian spirit factored in too. A well-rounded IPA, with bags of tropical flavour boosted by the addition of passionfruit, which unsurprisingly dominates the aroma of this summery IPA.","image":"149.png","abv":6.4,"ibu":50,"target_fg":1012,"target_og":1061,"ebc":20,"srm":10,"ph":4.4,"attenuation_level":80.3,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Passionfruit: 438g at End"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":4.88,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.75,"unit":"kilograms"}}],"hops":[{"name":"Vic Secret","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Centennial","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Centennial","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Kohatu","amount":{"value":16.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Vic Secret","amount":{"value":12.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Citra","amount":{"value":62.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Simcoe","amount":{"value":87.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Centennial","amount":{"value":37.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Amarillo","amount":{"value":50,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Grilled lamb chops with a fruit reduction","Ginger and chilli beef stir fry","Passionfruit soufflé"],"brewers_tips":"Try adding some of the passionfruit in the cold conditioning phase.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-150', 'diydog', '150', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/150.json', 'Alpha Pop', 'Hoppy Rye Pale Ale.', 'pale', 4.5, 30, 1.045, 1.011, 25, 20, 'alpha pop hoppy rye pale ale. pale ale extra pale caramalt dark crystal rye columbus columbus ahtanum ahtanum ahtanum columbus wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Alpha Pop","style":"Pale ale","description":"Hoppy Rye Pale Ale.\n\nA hoppy Rye Ale loaded with an avalanche of citrus and resinous flavours. Columbus, our high-alpha friend, lends a huge pithy citrus blast, with Ahtanum providing a punchy tropical fruit back-up. Brewing with rye adds a spiciness to the speciality malt caramel backbone, giving a warm ginger snap flavour, before slowly the hops, barley and rye combine and build to an orangey, biscuity, almost chocolatey crescendo.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":74,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":3.69},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.16},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.06},{"id":"f4","name":"Rye","type":"grain","amountKg":0.31}],"hops":[{"id":"h1","name":"Columbus","amountG":5,"use":"boil","timeMin":60},{"id":"h2","name":"Columbus","amountG":7.5,"use":"boil","timeMin":30},{"id":"h3","name":"Ahtanum","amountG":12.5,"use":"boil","timeMin":30},{"id":"h4","name":"Ahtanum","amountG":37.5,"use":"boil","timeMin":0},{"id":"h5","name":"Ahtanum","amountG":125,"use":"dry_hop"},{"id":"h6","name":"Columbus","amountG":125,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":75.6}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.045,"fg":1.011,"ibu":30,"abvPct":4.5,"colorEbc":25},"notes":"Bryggetips: Columbus and Ahtanum hop additions create a perfect blend of resin and lemon character.\n\nFørst brygget: 03/2014"}', '{"id":150,"name":"Alpha Pop","tagline":"Hoppy Rye Pale Ale.","first_brewed":"03/2014","description":"A hoppy Rye Ale loaded with an avalanche of citrus and resinous flavours. Columbus, our high-alpha friend, lends a huge pithy citrus blast, with Ahtanum providing a punchy tropical fruit back-up. Brewing with rye adds a spiciness to the speciality malt caramel backbone, giving a warm ginger snap flavour, before slowly the hops, barley and rye combine and build to an orangey, biscuity, almost chocolatey crescendo.","image":"150.png","abv":4.5,"ibu":30,"target_fg":1011,"target_og":1045,"ebc":25,"srm":12.5,"ph":4.4,"attenuation_level":75.6,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":3.69,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.16,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.06,"unit":"kilograms"}},{"name":"Rye","amount":{"value":0.31,"unit":"kilograms"}}],"hops":[{"name":"Columbus","amount":{"value":5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Columbus","amount":{"value":7.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Ahtanum","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Ahtanum","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Ahtanum","amount":{"value":125,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Columbus","amount":{"value":125,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Spicy lamb tikka masala","Spicy beef and Mexican black bean burger","Poached cinnamon apple muffins"],"brewers_tips":"Columbus and Ahtanum hop additions create a perfect blend of resin and lemon character.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-151', 'diydog', '151', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/151.json', 'Jasmine IPA', 'Floral & Fruity India Pale Ale.', 'ipa', 5.8, 40, 1.06, 1.014, 35, 20, 'jasmine ipa floral & fruity india pale ale. ipa pale ale munich rye wheat motueka amarillo motueka jasmine motueka jasmine amarillo wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Jasmine IPA","style":"IPA","description":"Floral & Fruity India Pale Ale.\n\nThis has big floral aromas backed up with some of our favourite fruity hop flavours. Bitter, bright and refreshing, our Jasmine IPA is a perfect spring beer for drinking outside (under a patio heater, with a pair of gloves on).","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":66,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.69},{"id":"f2","name":"Munich","type":"grain","amountKg":0.63},{"id":"f3","name":"Rye","type":"grain","amountKg":0.31},{"id":"f4","name":"Wheat","type":"grain","amountKg":0.63}],"hops":[{"id":"h1","name":"Motueka","amountG":50,"use":"boil","timeMin":60},{"id":"h2","name":"Amarillo","amountG":25,"use":"boil","timeMin":0},{"id":"h3","name":"Motueka","amountG":12.5,"use":"boil","timeMin":0},{"id":"h5","name":"Motueka","amountG":125,"use":"dry_hop"},{"id":"h7","name":"Amarillo","amountG":125,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":76.7}],"miscs":[{"id":"x4","name":"Jasmine","amount":31,"unit":"g","use":"boil","timeMin":0},{"id":"x6","name":"Jasmine","amount":37.5,"unit":"g","use":"fermentation"}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.06,"fg":1.014,"ibu":40,"abvPct":5.8,"colorEbc":35},"notes":"Bryggetips: When dry hopping with the jasmine, use a muslin or cloth like a tea bag, and make sure it has a heavy object in it (ensure its clean). This will help to keep the jasmine submerged in the beer for better flavour extraction.\n\nTwist: Jasmine addition in cold conditioning\n\nFørst brygget: 03/2014"}', '{"id":151,"name":"Jasmine IPA","tagline":"Floral & Fruity India Pale Ale.","first_brewed":"03/2014","description":"This has big floral aromas backed up with some of our favourite fruity hop flavours. Bitter, bright and refreshing, our Jasmine IPA is a perfect spring beer for drinking outside (under a patio heater, with a pair of gloves on).","image":"keg.png","abv":5.8,"ibu":40,"target_fg":1014,"target_og":1060,"ebc":35,"srm":17.5,"ph":4.4,"attenuation_level":76.7,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Jasmine addition in cold conditioning"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.69,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Rye","amount":{"value":0.31,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.63,"unit":"kilograms"}}],"hops":[{"name":"Motueka","amount":{"value":50,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Amarillo","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Motueka","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Jasmine","amount":{"value":31,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Motueka","amount":{"value":125,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Jasmine","amount":{"value":37.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Amarillo","amount":{"value":125,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Chicken satay","Thai fishcakes","Honey and almond sponge cake"],"brewers_tips":"When dry hopping with the jasmine, use a muslin or cloth like a tea bag, and make sure it has a heavy object in it (ensure its clean). This will help to keep the jasmine submerged in the beer for better flavour extraction.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-152', 'diydog', '152', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/152.json', '#Mashtag 2014', 'Democratic Imperial Red Ale.', 'strong', 9, 50, 1.084, 1.015, 20, 20, '#mashtag 2014 democratic imperial red ale. sterkt øl extra pale caramalt crystal 150 chocolate motueka hallertauer mittelfrüh amarillo motueka amarillo motueka amarillo centennial simcoe wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"#Mashtag 2014","style":"Sterkt øl","description":"Democratic Imperial Red Ale.\n\nA slightly psychotic, orange-that- thinks-it’s-a-grapefruit character builds upon and intensifies the hop bitterness, squaring up against the rich sweet malt base. The result is a huge Red Ale with a drinkable quality you’d expect in a beer half this strength.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":68,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":7.5},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.38},{"id":"f3","name":"Crystal 150","type":"grain","amountKg":0.58},{"id":"f4","name":"Chocolate","type":"grain","amountKg":0.1}],"hops":[{"id":"h1","name":"Motueka","amountG":9.5,"use":"boil","timeMin":60},{"id":"h2","name":"Hallertauer Mittelfrüh","amountG":19,"use":"boil","timeMin":60},{"id":"h3","name":"Amarillo","amountG":19,"use":"boil","timeMin":30},{"id":"h4","name":"Motueka","amountG":19,"use":"boil","timeMin":30},{"id":"h5","name":"Amarillo","amountG":19,"use":"boil","timeMin":0},{"id":"h6","name":"Motueka","amountG":28.5,"use":"boil","timeMin":0},{"id":"h7","name":"Amarillo","amountG":57.5,"use":"dry_hop"},{"id":"h8","name":"Centennial","amountG":57.5,"use":"dry_hop"},{"id":"h9","name":"Simcoe","amountG":57.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.1}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.084,"fg":1.015,"ibu":50,"abvPct":9,"colorEbc":20},"notes":"Bryggetips: Experiment with different citrus juices to get a wide array of flavours and aromas in the beer.\n\nTwist: Blood Orange: 250g at end, Lemon Peel: 3.9g at end, Orange Peel: 7.7g at end\n\nFørst brygget: 05/2014"}', '{"id":152,"name":"#Mashtag 2014","tagline":"Democratic Imperial Red Ale.","first_brewed":"05/2014","description":"A slightly psychotic, orange-that- thinks-it’s-a-grapefruit character builds upon and intensifies the hop bitterness, squaring up against the rich sweet malt base. The result is a huge Red Ale with a drinkable quality you’d expect in a beer half this strength.","image":"152.png","abv":9,"ibu":50,"target_fg":1015,"target_og":1084,"ebc":20,"srm":10,"ph":4.4,"attenuation_level":82.1,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Blood Orange: 250g at end, Lemon Peel: 3.9g at end, Orange Peel: 7.7g at end"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":7.5,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.38,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.58,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.1,"unit":"kilograms"}}],"hops":[{"name":"Motueka","amount":{"value":9.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Hallertauer Mittelfrüh","amount":{"value":19,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Amarillo","amount":{"value":19,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Motueka","amount":{"value":19,"unit":"grams"},"ad