INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-153', 'diydog', '153', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/153.json', 'Dog C', 'Cacao, Coffee Chili Anniversary Stout.', 'stout', 15, 90, 1.12, 1.003, 100, 20, 'dog c cacao, coffee chili anniversary stout. stout og porter extra pale wheat flaked oats dark crystal carafa special malt type 1 carafa special malt type 3 rye honey chinook cascade fuggles coffee fuggles coffee wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Dog C","style":"Stout og porter","description":"Cacao, Coffee Chili Anniversary Stout.\n\nOur anniversary stout was based on AB:04, one of our most sought after beers ever. This beer is slightly different each year, with subtle variations coming into play purely down to environmental and fermentation factors. What doesn''t change is the rich dark chocolate, bitter coffee and chilli warmth of this monumental stout.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":64,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":7.5},{"id":"f2","name":"Wheat","type":"grain","amountKg":0.5},{"id":"f3","name":"Flaked Oats","type":"grain","amountKg":1.38},{"id":"f4","name":"Dark Crystal","type":"grain","amountKg":0.88},{"id":"f5","name":"Carafa Special Malt Type 1","type":"grain","amountKg":0.63},{"id":"f6","name":"Carafa Special Malt Type 3","type":"grain","amountKg":0.63},{"id":"f7","name":"Rye","type":"grain","amountKg":0.75},{"id":"f8","name":"Honey","type":"sugar","amountKg":0.5}],"hops":[{"id":"h1","name":"Chinook","amountG":50,"use":"boil","timeMin":60},{"id":"h2","name":"Cascade","amountG":25,"use":"boil","timeMin":60},{"id":"h3","name":"Fuggles","amountG":25,"use":"boil","timeMin":30},{"id":"h5","name":"Fuggles","amountG":25,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":98}],"miscs":[{"id":"x4","name":"Coffee","amount":12.5,"unit":"g","use":"boil","timeMin":30},{"id":"x6","name":"Coffee","amount":12.5,"unit":"g","use":"boil","timeMin":0}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.12,"fg":1.003,"ibu":90,"abvPct":15,"colorEbc":100},"notes":"Bryggetips: Be really careful when mashing, as this amount of malts can get tough to sparge! Add honey into the boil, and naga chilli and vanilla in maturation (soak them in some neutral spirit to sanitise).\n\nTwist: Based on AB:04, but with added vanilla and 3.5 times the chilli.\n\nFørst brygget: 05/2014"}', '{"id":153,"name":"Dog C","tagline":"Cacao, Coffee Chili Anniversary Stout.","first_brewed":"05/2014","description":"Our anniversary stout was based on AB:04, one of our most sought after beers ever. This beer is slightly different each year, with subtle variations coming into play purely down to environmental and fermentation factors. What doesn''t change is the rich dark chocolate, bitter coffee and chilli warmth of this monumental stout.","image":"153.png","abv":15,"ibu":90,"target_fg":1003,"target_og":1120,"ebc":100,"srm":50,"ph":4.4,"attenuation_level":98,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Based on AB:04, but with added vanilla and 3.5 times the chilli."},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":7.5,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":1.38,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.88,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Rye","amount":{"value":0.75,"unit":"kilograms"}},{"name":"Honey","amount":{"value":0.5,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":50,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Cascade","amount":{"value":25,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Fuggles","amount":{"value":25,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Coffee","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Fuggles","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Coffee","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Blackened cajun beef","Blue cheese","Flourless chocolate cheesecake"],"brewers_tips":"Be really careful when mashing, as this amount of malts can get tough to sparge! Add honey into the boil, and naga chilli and vanilla in maturation (soak them in some neutral spirit to sanitise).","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min.","12.8 kg malt til 20 L er urealistisk — trolig en feil i kilden."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-154', 'diydog', '154', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/154.json', 'Hello My Name Is Päivi', 'Sea Buckthorn Double IPA.', 'ipa', 8.3, 70, 1.076, 1.013, 30, 20, 'hello my name is päivi sea buckthorn double ipa. ipa extra pale caramalt challenger bravo comet exp 366 centennial simcoe citra comet centennial simcoe citra wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Hello My Name Is Päivi","style":"IPA","description":"Sea Buckthorn Double IPA.\n\nBrewed with sea buckthorn, a tart and bitter berry found on the Finnish coastline. Bright, vibrant aromas of tangerine, mandarin and peach, with zesty hits of lime, envelop the nutty, caramel malt backbone. The intense fruitiness gives a jammy quality to the nose. On the palate is a warm biscuity sweetness, with tropical fruits in a supporting role to a huge grapefruit and orange bitterness.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":6.13},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.88}],"hops":[{"id":"h1","name":"Challenger","amountG":12.5,"use":"boil","timeMin":60},{"id":"h2","name":"Bravo","amountG":12.5,"use":"boil","timeMin":60},{"id":"h3","name":"Comet","amountG":12.5,"use":"boil","timeMin":30},{"id":"h4","name":"EXP 366","amountG":12.5,"use":"boil","timeMin":30},{"id":"h5","name":"Centennial","amountG":12.5,"use":"boil","timeMin":0},{"id":"h6","name":"Simcoe","amountG":12.5,"use":"boil","timeMin":0},{"id":"h7","name":"Citra","amountG":12.5,"use":"boil","timeMin":0},{"id":"h8","name":"Comet","amountG":25,"use":"dry_hop"},{"id":"h9","name":"Centennial","amountG":62.5,"use":"dry_hop"},{"id":"h10","name":"Simcoe","amountG":62.5,"use":"dry_hop"},{"id":"h11","name":"Citra","amountG":62.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.9}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.076,"fg":1.013,"ibu":70,"abvPct":8.3,"colorEbc":30},"notes":"Bryggetips: Sea buckthorn characteristics can vary from its country or origin. Taste the berries before addition to determine the best usage.\n\nTwist: Sea Buckthorn Puree: 375g at end, EXP 366: 37.5g at dry hop\n\nFørst brygget: 05/2014"}', '{"id":154,"name":"Hello My Name Is Päivi","tagline":"Sea Buckthorn Double IPA.","first_brewed":"05/2014","description":"Brewed with sea buckthorn, a tart and bitter berry found on the Finnish coastline. Bright, vibrant aromas of tangerine, mandarin and peach, with zesty hits of lime, envelop the nutty, caramel malt backbone. The intense fruitiness gives a jammy quality to the nose. On the palate is a warm biscuity sweetness, with tropical fruits in a supporting role to a huge grapefruit and orange bitterness.","image":"154.png","abv":8.3,"ibu":70,"target_fg":1013,"target_og":1076,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":82.9,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Sea Buckthorn Puree: 375g at end, EXP 366: 37.5g at dry hop"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":6.13,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.88,"unit":"kilograms"}}],"hops":[{"name":"Challenger","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Bravo","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Comet","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"EXP 366","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Centennial","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Simcoe","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Citra","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Comet","amount":{"value":25,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Centennial","amount":{"value":62.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Simcoe","amount":{"value":62.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Citra","amount":{"value":62.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Korvapuusti (cinnamon and cardamom buns)","Spicy orange chicken marmalade served with potato bread","Sea buckthorn cheesecake"],"brewers_tips":"Sea buckthorn characteristics can vary from its country or origin. Taste the berries before addition to determine the best usage.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-155', 'diydog', '155', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/155.json', 'Vote Sepp', 'Witbier With Hibiscus.', 'wheat', 3.6, 20, 1.036, 1.009, 8, 20, 'vote sepp witbier with hibiscus. hvete extra pale torrified wheat motueka motueka motueka wyeast 3944 - belgian witbier™', '{"schemaVersion":1,"name":"Vote Sepp","style":"Hvete","description":"Witbier With Hibiscus.\n\nVote Sepp is a single hop wheat beer brewed to a session strength, with hibiscus flower, which gives it an impressively vibrant shade of pink. What Vote Sepp lacks in complexity, it more than makes up for in a perfect balance of tartness, bitterness and body.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":78,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":2.5},{"id":"f2","name":"Torrified Wheat","type":"grain","amountKg":0.69}],"hops":[{"id":"h1","name":"Motueka","amountG":5,"use":"boil","timeMin":60},{"id":"h2","name":"Motueka","amountG":12.5,"use":"boil","timeMin":30},{"id":"h3","name":"Motueka","amountG":12.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 3944 - Belgian Witbier™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":75}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.036,"fg":1.009,"ibu":20,"abvPct":3.6,"colorEbc":8},"notes":"Bryggetips: Load hibiscus in the hot wort in a tea bag.\n\nTwist: Hibiscus: 37.5g Tank\n\nFørst brygget: 05/2014"}', '{"id":155,"name":"Vote Sepp","tagline":"Witbier With Hibiscus.","first_brewed":"05/2014","description":"Vote Sepp is a single hop wheat beer brewed to a session strength, with hibiscus flower, which gives it an impressively vibrant shade of pink. What Vote Sepp lacks in complexity, it more than makes up for in a perfect balance of tartness, bitterness and body.","image":"155.png","abv":3.6,"ibu":20,"target_fg":1009,"target_og":1036,"ebc":8,"srm":4,"ph":4.1,"attenuation_level":75,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Hibiscus: 37.5g Tank"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":2.5,"unit":"kilograms"}},{"name":"Torrified Wheat","amount":{"value":0.69,"unit":"kilograms"}}],"hops":[{"name":"Motueka","amount":{"value":5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Motueka","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Motueka","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 3944 - Belgian Witbier™"},"food_pairing":["Crab roll sushi with strawberries","Artichoke hearts and chicken melt","Caprese salad (mozzarella, tomato, basil, black pepper and sea salt)"],"brewers_tips":"Load hibiscus in the hot wort in a tea bag.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-156', 'diydog', '156', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/156.json', 'Magic Stone Dog (w/ Magic Rock & Stone Brewing Co.)', 'Session Farmhouse IPA - Stone / Magic Rock Collab.', 'ipa', 4.6, 30, 1.043, 1.008, 15, 20, 'magic stone dog (w/ magic rock & stone brewing co.) session farmhouse ipa - stone / magic rock collab. ipa extra pale wheat torrified wheat rye flaked oats amber simcoe amarillo wyeast 3711 - french saison™', '{"schemaVersion":1,"name":"Magic Stone Dog (w/ Magic Rock & Stone Brewing Co.)","style":"IPA","description":"Session Farmhouse IPA - Stone / Magic Rock Collab.\n\nA session IPA brewed with a diverse grain bill, hopped with Simcoe and Amarillo and fermented with saison yeast, for an incredible level of depth in a low ABV beer. Spicy, fruity, complex, refreshing and dry.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":73,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":2.38},{"id":"f2","name":"Wheat","type":"grain","amountKg":0.44},{"id":"f3","name":"Torrified Wheat","type":"grain","amountKg":0.44},{"id":"f4","name":"Rye","type":"grain","amountKg":0.19},{"id":"f5","name":"Flaked Oats","type":"grain","amountKg":0.44},{"id":"f6","name":"Amber","type":"grain","amountKg":0.19}],"hops":[{"id":"h1","name":"Simcoe","amountG":25,"use":"boil","timeMin":0},{"id":"h2","name":"Amarillo","amountG":25,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 3711 - French Saison™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":81.4}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":23}],"targets":{"og":1.043,"fg":1.008,"ibu":30,"abv