INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-158', 'diydog', '158', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/158.json', 'Sub Hop', 'Hopped-Up Imperial Pilsner.', 'lager', 8, 35, 1.077, 1.016, 15, 20, 'sub hop hopped-up imperial pilsner. lager og pils extra pale munich dextrose saaz hallertauer mittelfrüh pacifica pacific jade pacifica pacific jade pacifica wyeast 2007 - pilsen lager™', '{"schemaVersion":1,"name":"Sub Hop","style":"Lager og pils","description":"Hopped-Up Imperial Pilsner.\n\nBrewed for the opening of our first bar in Italy, BrewDog Firenze. A mega-hoppy Imperial Pilsner, with toasty malt complexity and tropical New World hops.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":76,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":6.25},{"id":"f2","name":"Munich","type":"grain","amountKg":0.25},{"id":"f3","name":"Dextrose","type":"sugar","amountKg":0.38}],"hops":[{"id":"h1","name":"Saaz","amountG":12.5,"use":"boil","timeMin":60},{"id":"h2","name":"Hallertauer Mittelfrüh","amountG":12.5,"use":"boil","timeMin":30},{"id":"h3","name":"Pacifica","amountG":12.5,"use":"boil","timeMin":0},{"id":"h4","name":"Pacific Jade","amountG":25,"use":"boil","timeMin":0},{"id":"h5","name":"Pacifica","amountG":25,"use":"boil","timeMin":0},{"id":"h6","name":"Pacific Jade","amountG":75,"use":"dry_hop"},{"id":"h7","name":"Pacifica","amountG":37.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 2007 - Pilsen Lager™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79.2}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":9}],"targets":{"og":1.077,"fg":1.016,"ibu":35,"abvPct":8,"colorEbc":15},"notes":"Bryggetips: Sit this beer aside for a month to allow it to mellow.\n\nFørst brygget: 06/2014"}', '{"id":158,"name":"Sub Hop","tagline":"Hopped-Up Imperial Pilsner.","first_brewed":"06/2014","description":"Brewed for the opening of our first bar in Italy, BrewDog Firenze. A mega-hoppy Imperial Pilsner, with toasty malt complexity and tropical New World hops.","image":"158.png","abv":8,"ibu":35,"target_fg":1016,"target_og":1077,"ebc":15,"srm":7.5,"ph":4.4,"attenuation_level":79.2,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":9,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":6.25,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Dextrose","amount":{"value":0.38,"unit":"kilograms"}}],"hops":[{"name":"Saaz","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Hallertauer Mittelfrüh","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Pacifica","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Pacific Jade","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Pacifica","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Pacific Jade","amount":{"value":75,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Pacifica","amount":{"value":37.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 2007 - Pilsen Lager™"},"food_pairing":["Seared lemon and herb salmon","Crab linguine","Almond biscotti"],"brewers_tips":"Sit this beer aside for a month to allow it to mellow.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790