INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-159', 'diydog', '159', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/159.json', 'U-Boat (w/ Victory Brewing)', 'Smoked Porter Collab With Victory Brewing.', 'stout', 8.4, 50, 1.08, 1.015, 200, 20, 'u-boat (w/ victory brewing) smoked porter collab with victory brewing. stout og porter extra pale crystal 150 carafa special malt type 1 chocolate munich smoked warminster hallertauer mittelfrüh hallertauer mittelfrüh galena wyeast 2007 - pilsen lager™', '{"schemaVersion":1,"name":"U-Boat (w/ Victory Brewing)","style":"Stout og porter","description":"Smoked Porter Collab With Victory Brewing.\n\nOn the palate is a big dark malt sweetness, balanced by the blend of spicy Mittelfruh and citrussy Galena. Cocoa powder, rich dark chocolate, and ripe berries interplay with a toasty burnt sugar bitterness. The mouthfeel is thick and chewy with a treacly quality that doesn’t cloy, as it plays off against the hops and roast malt bitterness.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":54,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":6.35},{"id":"f2","name":"Crystal 150","type":"grain","amountKg":0.48},{"id":"f3","name":"Carafa Special Malt Type 1","type":"grain","amountKg":0.48},{"id":"f4","name":"Chocolate","type":"grain","amountKg":0.48},{"id":"f5","name":"Munich","type":"grain","amountKg":1.92},{"id":"f6","name":"Smoked Warminster","type":"grain","amountKg":0.48}],"hops":[{"id":"h1","name":"Hallertauer Mittelfrüh","amountG":7.5,"use":"boil","timeMin":60},{"id":"h2","name":"Hallertauer Mittelfrüh","amountG":11.5,"use":"boil","timeMin":30},{"id":"h3","name":"Galena","amountG":19,"use":"boil","timeMin":30}],"cultures":[{"id":"y1","name":"Wyeast 2007 - Pilsen Lager™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":81.3}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":14}],"targets":{"og":1.08,"fg":1.015,"ibu":50,"abvPct":8.4,"colorEbc":200},"notes":"Bryggetips: A good Porter is dependant on a long fermentation and cellaring process. Keep the temperature controlled as much as possible.\n\nTwist: Try ageing on oak chips, infusing with rum raisins, or vanilla pods\n\nFørst brygget: 07/2014"}', '{"id":159,"name":"U-Boat (w/ Victory Brewing)","tagline":"Smoked Porter Collab With Victory Brewing.","first_brewed":"07/2014","description":"On the palate is a big dark malt sweetness, balanced by the blend of spicy Mittelfruh and citrussy Galena. Cocoa powder, rich dark chocolate, and ripe berries interplay with a toasty burnt sugar bitterness. The mouthfeel is thick and chewy with a treacly quality that doesn’t cloy, as it plays off against the hops and roast malt bitterness.","image":"159.png","abv":8.4,"ibu":50,"target_fg":1015,"target_og":1080,"ebc":200,"srm":100,"ph":4.4,"attenuation_level":81.3,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":14,"unit":"celsius"}},"twist":"Try ageing on oak chips, infusing with rum raisins, or vanilla pods"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":6.35,"unit":"kilograms"}},{"name":"Crystal 150","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Munich","amount":{"value":1.92,"unit":"kilograms"}},{"name":"Smoked Warminster","amount":{"value":0.48,"unit":"kilograms"}}],"hops":[{"name":"Hallertauer Mittelfrüh","amount":{"value":7.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Hallertauer Mittelfrüh","amount":{"value":11.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Galena","amount":{"value":19,"unit":"grams"},"add":"middle","attribute":"flavour"}],"yeast":"Wyeast 2007 - Pilsen Lager™"},"food_pairing":["Smoked bratwurst and mustard","Chargrilled steak","Grilled pineapple"],"brewers_tips":"A good Porter is dependant on a long fermentation and cellaring process. Keep the temperature controlled as much as possible.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-160', 'diydog', '160', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/160.json', 'American Wheat', 'Hoppy American Wheat.', 'wheat', 4.5, 17, 1.047, 1.013, 10, 20, 'american wheat hoppy american wheat. hvete extra pale wheat pale crystal ahtanum ahtanum wyeast 1010 - american wheat™', '{"schemaVersion":1,"name":"American Wheat","style":"Hvete","description":"Hoppy American Wheat.\n\nA luscious blend of peach, blood orange and banana to make a suitably refreshing beverage that happily straddles the Atlantic.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":68,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":2.13},{"id":"f2","name":"Wheat","type":"grain","amountKg":2.5},{"id":"f3","name":"Pale Crystal","type":"grain","amountKg":0.13}],"hops":[{"id":"h1","name":"Ahtanum","amountG":25,"use":"boil","timeMin":60},{"id":"h2","name":"Ahtanum","amountG":25,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1010 - American Wheat™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":72}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":90}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.047,"fg":1.013,"ibu":17,"abvPct":4.5,"colorEbc":10},"notes":"Bryggetips: Using a starter to get your yeast as vibrant and healthy as possible will make all the difference here.\n\nFørst brygget: 07/2014"}', '{"id":160,"name":"American Wheat","tagline":"Hoppy American Wheat.","first_brewed":"07/2014","description":"A luscious blend of peach, blood orange and banana to make a suitably refreshing beverage that happily straddles the Atlantic.","image":"keg.png","abv":4.5,"ibu":17,"target_fg":1013,"target_og