INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-164', 'diydog', '164', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/164.json', 'Russian Doll – Pale', 'Nesting Hop Bomb.', 'other', 4, 35, 1.041, 1.01, 45, 20, 'russian doll – pale nesting hop bomb. annet extra pale caramalt dark crystal cascade centennial citra simcoe simcoe cascade centennial citra wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Russian Doll – Pale","description":"Nesting Hop Bomb.\n\nThe levels of hops vary throughout the range. We love hops, so all four beers are big, bitter badasses, but by tweaking the amount of each hop used later in the boil and during dry- hopping, we can balance the malty backbone with some unexpected flavours. Simcoe is used in the whirlpool for all four beers, and yet still lends different characters to each.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":71,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":3.63},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.25},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.13}],"hops":[{"id":"h1","name":"Cascade","amountG":7.5,"use":"boil","timeMin":60},{"id":"h2","name":"Centennial","amountG":5,"use":"boil","timeMin":30},{"id":"h3","name":"Citra","amountG":5,"use":"boil","timeMin":30},{"id":"h4","name":"Simcoe","amountG":17.5,"use":"boil","timeMin":0},{"id":"h5","name":"Simcoe","amountG":62.5,"use":"dry_hop"},{"id":"h6","name":"Cascade","amountG":62.5,"use":"dry_hop"},{"id":"h7","name":"Centennial","amountG":62.5,"use":"dry_hop"},{"id":"h8","name":"Citra","amountG":12.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":75.6}],"miscs":[],"mashSteps":[{"id":"ms1","name":"