INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-165', 'diydog', '165', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/165.json', 'This. Is. Lager.', '21st Century Pilsner. Sharp. Robust. Honest.', 'lager', 4.7, 37, 1.043, 1.007, 10, 20, 'this. is. lager. 21st century pilsner. sharp. robust. honest. lager og pils pilsner columbus hersbrucker saaz wyeast 2007 - pilsen lager™', '{"schemaVersion":1,"name":"This. Is. Lager.","style":"Lager og pils","description":"21st Century Pilsner. Sharp. Robust. Honest.\n\nBrewed with 100% malt, ten times the hops of most industrial lagers and cold-conditioned for five weeks, this spicy, robust Pilsner is lager reborn. Expect a robust, full-bodied malt character on the front of the tongue, spicy citrus notes as it goes back through the palate and an assertive bitter finish with a lemon and pepper character to round things off.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":78,"fermentables":[{"id":"f1","name":"Pilsner","type":"grain","amountKg":3.81}],"hops":[{"id":"h1","name":"Columbus","amountG":5,"use":"boil","timeMin":60},{"id":"h2","name":"Hersbrucker","amountG":12.5,"use":"boil","timeMin":60},{"id":"h3","name":"Saaz","amountG":12.5,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 2007 - Pilsen Lager™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83.7}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":12}],"targets":{"og":1.043,"fg":1.007,"ibu":37,"abvPct":4.7,"colorEbc":10},"notes":"Bryggetips: The most important thing about making a lager? Fermentation temperature! Do everything you can to control the ambient temperature to 9 - 12°C. In the old days, they used to brew lager over winter, so the colder temperature gave a much preferable fermentation profile. Ferment too hot and you beer will taste like yeasty bread.\n\nFørst brygget: 08/2014"}', '{"id":165,"name":"This. Is. Lager.","tagline":"21st Century Pilsner. Sharp. Robust. Honest.","first_brewed":"08/2014","description":"Brewed with 100% malt, ten times the hops of most industrial lagers and cold-conditioned for five weeks, this spicy, robust Pilsner is lager reborn. Expect a robust, full-bodied malt character on the front of the tongue, spicy citrus notes as it goes back through the palate and an assertive bitter finish with a lemon and pepper character to round things off.","image":"165.png","abv":4.7,"ibu":37,"target_fg":1007,"target_og":1043,"ebc":10,"srm":6,"ph":4.2,"attenuation_level":83.7,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":12,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pilsner","amount":{"value":3.81,"unit":"kilograms"}}],"hops":[{"name":"Columbus","amount":{"value":5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Hersbrucker","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Saaz","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 2007 - Pilsen Lager™"},"food_pairing":["Mexican ceviche","Blue cheese crumbled over wedges","Gooey lemon bar"],"brewers_tips":"The most important thing about making a lager? Fermentation temperature! Do everything you can to control the ambient temperature to 9 - 12°C. In the old days, they used to brew lager over winter, so the colder temperature gave a much preferable fermentation profile. Ferment too hot and you beer will taste like yeasty bread.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-166', 'diydog', '166', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/166.json', 'India Pale Weizen (w/ Weihenstephan)', 'BrewDog Versus Weihenstephan.', 'ipa', 6.2, 50, 1.056, 1.01, 35, 20, 'india pale weizen (w/ weihenstephan) brewdog versus weihenstephan. ipa extra pale wheat dark crystal cascade cascade saaz hersbrucker wyeast 3638 - bavarian wheat™', '{"schemaVersion":1,"name":"India Pale Weizen (w/ Weihenstephan)","style":"IPA","description":"BrewDog Versus Weihenstephan.\n\n BrewDog vs. Weihenstephan India Pale Weizen kicked off a new direction for our collaborations. We took a simple concept (by our standards) and teamed up with the oldest brewery in the world to brew a mash-up beer using the signature styles of both breweries. India Pale Weizen has classic base hefeweizen aromas and flavours of banana, clove and bubblegum, with a distinctive haziness. Layered on top of this is a tapestry of US citrus hop character. India Pale Weizen is a perfect symbiosis of traditional and modern brewing.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":76,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":3},{"id":"f2","name":"Wheat","type":"grain","amountKg":2},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.08}],"hops":[{"id":"h1","name":"Cascade","amountG":6,"use":"boil","timeMin":60},{"id":"h2","name":"Cascade","amountG":6,"use":"boil","timeMin":30},{"id":"h3","name":"Saaz","amountG":12.5,"use":"boil","timeMin":30},{"id":"h4","name":"Hersbrucker","amountG":12.5,"use":"boil","timeMin":30}],"cultures":[{"id":"y1","name":"Wyeast 3638 - Bavarian Wheat™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":85}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.056,"fg":1.01,"ibu":50,"abvPct":6.2,"colorEbc":35},"notes":"Bryggetips: Let the fermentation temperature creep up a couple of degrees higher than normal to create the characteristic banana and bubblegum aromas.\n\nFørst brygget: 09/2014"}', '{"id":166,"name":"India Pale Weizen (w/ Weihenstephan)","tagline":"BrewDog Versus Weihenstephan.","first_brewed":"09/2014","description":" BrewDog vs. Weihenstephan India Pale Weizen kicked off a new direction for our collaborations. We took a simple concept (by our standards) and teamed up with the oldest brewery in the world to brew a mash-up beer using the signature styles of both breweries. India Pale Weizen has classic base hefeweizen aromas and flavours of banana, clove and bubblegum, with a distinctive haziness. Layered on top of this is a tapestry of US citrus hop character. India Pale Weizen is a perfect symbiosis of traditional and modern brewing.","image":"166.png","abv":6.2,"ibu":50,"target_fg":1010,"target_og":1056,"ebc":35,"srm":17.5,"ph":4,"attenuation_level":85,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":3,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":2,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.08,"unit":"kilograms"}}],"hops":[{"name":"Cascade","amount":{"value":6,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Cascade","amount":{"value":6,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Saaz","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Hersbrucker","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"}],"yeast":"Wyeast 3638 - Bavarian Wheat™"},"food_pairing":["Korean barbecue nachos","Beef pho soup","Waffles with caramelised apple and powdered sugar"],"brewers_tips":"Let the fermentation temperature creep up a couple of degrees higher than normal to create the characteristic banana and bubblegum aromas.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-167', 'diydog', '167', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/167.json', 'AB:17', 'Three Coffee Rye Imperial Porter.', 'stout', 10.7, 100, 1.105, 1.025, 300, 20, 'ab:17 three coffee rye imperial porter. stout og porter pale ale rye amber dark crystal roasted barley chocolate carafa special malt type 1 co2 extract willamette wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"AB:17","style":"Stout og porter","description":"Three Coffee Rye Imperial Porter.\n\nA triple whammy of coffee from HasBean gives our 17th Abstrakt concept beer an intense and roasty, dark mocha character. We brewed with espresso in the mash, cafetiere in the boil, and whole roast beans in the whirlpool and the fermenter.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":61,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":9},{"id":"f2","name":"Rye","type":"grain","amountKg":0.63},{"id":"f3","name":"Amber","type":"grain","amountKg":0.38},{"id":"f4","name":"Dark Crystal","type":"grain","amountKg":0.88},{"id":"f5","name":"Roasted Barley","type":"grain","amountKg":0.25},{"id":"f6","name":"Chocolate","type":"grain","amountKg":0.5},{"id":"f7","name":"Carafa Special Malt Type 1","type":"grain","amountKg":0.25}],"hops":[{"id":"h1","name":"CO2 Extract","amountG":20,"use":"boil","timeMin":60},{"id":"h2","name":"Willamette","amountG":50,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":76.2}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.105,"fg":1.025,"ibu":100,"abvPct":10.7,"colorEbc":300},"notes":"Bryggetips: Use freshly ground coffee for the best aromatic hit.\n\nTwist: Coffee: 25g at end, Coffee: 25g at end, Dark Muscavado Sugar: 250g at end\n\nFørst brygget: 10/2014"}', '{"id":167,"name":"AB:17","tagline":"Three Coffee Rye Imperial Porter.","first_brewed":"10/2014","description":"A triple whammy of coffee from HasBean gives our 17th Abstrakt concept beer an intense and roasty, dark mocha character. We brewed with espresso in the mash, cafetiere in the boil, and whole roast beans in the whirlpool and the fermenter.","image":"167.png","abv":10.7,"ibu":100,"target_fg":1025,"target_og":1105,"ebc":300,"srm":150,"ph":4.3,"attenuation_level":76.2,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Coffee: 25g at end, Coffee: 25g at end, Dark Muscavado Sugar: 250g at end"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":9,"unit":"kilograms"}},{"name":"Rye","amount":{"value":0.63,"unit":"kilograms"}},{"name":"Amber","amount":{"value":0.38,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.88,"unit":"kilograms"}},{"name":"Roasted Barley","amount":{"value":0.25,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":0.25,"unit":"kilograms"}}],"hops":[{"name":"CO2 Extract","amount":{"value":20,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Willamette","amount":{"value":50,"unit":"grams"},"add":"end","attribute":"flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["12hr smoked brisket","Chocolate pistachio cakes","Dulche de leche"],"brewers_tips":"Use freshly ground coffee for the best aromatic hit.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-168', 'diydog', '168', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/168.json', 'Konnichiwa Kitsune', 'Hello My Name Is Yuzu.', 'ipa', 4.4, 70, 1.045, 1.012, 30, 20, 'konnichiwa kitsune hello my name is yuzu. ipa extra pale caramalt amarillo citra cascade amarillo citra cascade amarillo citra cascade citra amarillo cascade wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Konnichiwa Kitsune","style":"IPA","description":"Hello My Name Is Yuzu.\n\nNamed in a slight deviation from our Hello My Name Is series, Konnichiwa Kitsune is a Japanese- inspired, yuzu-infused Imperial IPA, brewed with Amarillo, Cascade and Citra. These punchy new world hops bring orange, grapefruit and lime to back up the yuzu aroma and flavour. Big mandarin notes, balanced against a caramel malt biscuity base.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":6.13},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.86}],"hops":[{"id":"h1","name":"Amarillo","amountG":12.5,"use":"boil","timeMin":60},{"id":"h2","name":"Citra","amountG":6,"use":"boil","timeMin":60},{"id":"h3","name":"Cascade","amountG":12.5,"use":"boil","timeMin":60},{"id":"h4","name":"Amarillo","amountG":6,"use":"boil","timeMin":30},{"id":"h5","name":"Citra","amountG":6,"use":"boil","timeMin":30},{"id":"h6","name":"Cascade","amountG":12.5,"use":"boil","timeMin":30},{"id":"h7","name":"Amarillo","amountG":18.5,"use":"boil","timeMin":0},{"id":"h8","name":"Citra","amountG":12.5,"use":"boil","timeMin":0},{"id":"h9","name":"Cascade","amountG":12.5,"use":"boil","timeMin":0},{"id":"h10","name":"Citra","amountG":100,"use":"dry_hop"},{"id":"h11","name":"Amarillo","amountG":137.5,"use":"dry_hop"},{"id":"h12","name":"Cascade","amountG":87.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82.9}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":20}],"targets":{"og":1.045,"fg":1.012,"ibu":70,"abvPct":4.4,"colorEbc":30},"notes":"Bryggetips: Squeeze the fresh yuzu juice directly into the beer after primary fermentation is complete. Putting it in the hot wort may seem like better practice, but the juice will cook and some of the fresh citrus character will be lost.\n\nTwist: Yuzu juice: 250g at FV\n\nFørst brygget: 10/2014"}', '{"id":168,"name":"Konnichiwa Kitsune","tagline":"Hello My Name Is Yuzu.","first_brewed":"10/2014","description":"Named in a slight deviation from our Hello My Name Is series, Konnichiwa Kitsune is a Japanese- inspired, yuzu-infused Imperial IPA, brewed with Amarillo, Cascade and Citra. These punchy new world hops bring orange, grapefruit and lime to back up the yuzu aroma and flavour. Big mandarin notes, balanced against a caramel malt biscuity base.","image":"168.png","abv":4.4,"ibu":70,"target_fg":1012,"target_og":1045,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":82.9,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":20,"unit":"celsius"}},"twist":"Yuzu juice: 250g at FV"},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":6.13,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.86,"unit":"kilograms"}}],"hops":[{"name":"Amarillo","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Citra","amount":{"value":6,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Cascade","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Amarillo","amount":{"value":6,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Citra","amount":{"value":6,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Cascade","amount":{"value":12.5,"unit":"grams"},"add":"middle","attribute":"flavour"},{"name":"Amarillo","amount":{"value":18.5,"unit":"grams"},"add":"end","attribute":"flavoour"},{"name":"Citra","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavouor"},{"name":"Cascade","amount":{"value":12.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Citra","amount":{"value":100,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Amarillo","amount":{"value":137.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Cascade","amount":{"value":87.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Fresh seared tuna and rocket salad","Lemon meringue pie","Baked chicken with yuzu reduction"],"brewers_tips":"Squeeze the fresh yuzu juice directly into the beer after primary fermentation is complete. Putting it in the hot wort may seem like better practice, but the juice will cook and some of the fresh citrus character will be lost.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Malt og OG i kilden gir 45 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-169', 'diydog', '169', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/169.json', 'All Day Long - Prototype Challenge', 'Malty Low ABV Ale.', 'other', 2.8, 30, 1.0325, 1.012, 42, 20, 'all day long - prototype challenge malty low abv ale. annet caramalt columbus cascade centennial columbus ahtanum centennial cascade amarillo wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"All Day Long - Prototype Challenge","description":"Malty Low ABV Ale.\n\nPrototype Challenge 2014. All Day Long is a mild like no other. This complex, low-alcohol brew was the third of our 2014 Prototypes. Featuring a boatload of seven different speciality malts and some of our favourite hops, this beer is resinous at first, transitioning into something akin to bitter orange marmalade spread onto a thick bread crust. This is for everyone who said BrewDog would never brew a mild...","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":72,"fermentables":[{"id":"f1","name":"Caramalt","type":"grain","amountKg":3.13}],"hops":[{"id":"h1","name":"Columbus","amountG":8.5,"use":"boil","timeMin":60},{"id":"h2","name":"Cascade","amountG":20.5,"use":"boil","timeMin":0},{"id":"h3","name":"Centennial","amountG":20.5,"use":"boil","timeMin":0},{"id":"h4","name":"Columbus","amountG":20.5,"use":"boil","timeMin":0},{"id":"h5","name":"Ahtanum","amountG":20.5,"use":"boil","timeMin":0},{"id":"h6","name":"Centennial","amountG":75,"use":"dry_hop"},{"id":"h7","name":"Cascade","amountG":75,"use":"dry_hop"},{"id":"h8","name":"Amarillo","amountG":100,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":63.1}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":30}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":22}],"targets":{"og":1.0325,"fg":1.012,"ibu":30,"abvPct":2.8,"colorEbc":42},"notes":"Bryggetips: In any low ABV fermentation after primary fermentation has finished if the beer smells or tastes like wort, allow it to condition on the yeast for an extra 24 - 48 hours. This can round the profile off well.\n\nFørst brygget: 11/2014"}', '{"id":169,"name":"All Day Long - Prototype Challenge","tagline":"Malty Low ABV Ale.","first_brewed":"11/2014","description":"Prototype Challenge 2014. All Day Long is a mild like no other. This complex, low-alcohol brew was the third of our 2014 Prototypes. Featuring a boatload of seven different speciality malts and some of our favourite hops, this beer is resinous at first, transitioning into something akin to bitter orange marmalade spread onto a thick bread crust. This is for everyone who said BrewDog would never brew a mild...","image":"169.png","abv":2.8,"ibu":30,"target_fg":1012,"target_og":1032.5,"ebc":42,"srm":21,"ph":4.4,"attenuation_level":63.1,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":30}],"fermentation":{"temp":{"value":22,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Caramalt","amount":{"value":3.13,"unit":"kilograms"}}],"hops":[{"name":"Columbus","amount":{"value":8.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Cascade","amount":{"value":20.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Centennial","amount":{"value":20.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Columbus","amount":{"value":20.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Ahtanum","amount":{"value":20.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Centennial","amount":{"value":75,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Cascade","amount":{"value":75,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Amarillo","amount":{"value":100,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Chunky orange marmalade on toast","Prawn toast with sweet chilli sauce","Lemon tart"],"brewers_tips":"In any low ABV fermentation after primary fermentation has finished if the beer smells or tastes like wort, allow it to condition on the yeast for an extra 24 - 48 hours. This can round the profile off well.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-170', 'diydog', '170', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/170.json', 'Hop Fiction - Prototype Challenge', 'US-Style Pale Ale.', 'pale', 5.2, 40, 1.048, 1.01, 13, 20, 'hop fiction - prototype challenge us-style pale ale. pale ale pale ale chinook amarillo chinook mosaic amarillo chinook mosaic wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Hop Fiction - Prototype Challenge","style":"Pale ale","description":"US-Style Pale Ale.\n\nHop Fiction is an explosively tropical US-style Pale Ale. We rolled up our hop-dusted sleeves and put some advanced brewing techniques to work on this seasonal brew. Hop Fiction’s incredible aromas and flavours are down to a combination of early and late hops. Bags of soft, rounded citrus and stone fruit layer up on a dry light biscuit backbone. Hop Fiction, beer fact.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":76,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.38}],"hops":[{"id":"h1","name":"Chinook","amountG":12.5,"use":"boil","timeMin":60},{"id":"h2","name":"Amarillo","amountG":37.5,"use":"boil","timeMin":0},{"id":"h3","name":"Chinook","amountG":25,"use":"boil","timeMin":0},{"id":"h4","name":"Mosaic","amountG":37.5,"use":"dry_hop"},{"id":"h5","name":"Amarillo","amountG":62.5,"use":"dry_hop"},{"id":"h6","name":"Chinook","amountG":62.5,"use":"dry_hop"},{"id":"h7","name":"Mosaic","amountG":62.5,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79.2}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.048,"fg":1.01,"ibu":40,"abvPct":5.2,"colorEbc":13},"notes":"Bryggetips: Don''t be scared by the amount of hops. Seriously this beer can handle them.\n\nFørst brygget: 11/2014"}', '{"id":170,"name":"Hop Fiction - Prototype Challenge","tagline":"US-Style Pale Ale.","first_brewed":"11/2014","description":"Hop Fiction is an explosively tropical US-style Pale Ale. We rolled up our hop-dusted sleeves and put some advanced brewing techniques to work on this seasonal brew. Hop Fiction’s incredible aromas and flavours are down to a combination of early and late hops. Bags of soft, rounded citrus and stone fruit layer up on a dry light biscuit backbone. Hop Fiction, beer fact.","image":"170.png","abv":5.2,"ibu":40,"target_fg":1010,"target_og":1048,"ebc":13,"srm":6.5,"ph":4.4,"attenuation_level":79.2,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":null}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.38,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":12.5,"unit":"grams"},"add":"start","attribute":"bitter"},{"name":"Amarillo","amount":{"value":37.5,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Chinook","amount":{"value":25,"unit":"grams"},"add":"end","attribute":"flavour"},{"name":"Mosaic","amount":{"value":37.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Amarillo","amount":{"value":62.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Chinook","amount":{"value":62.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"},{"name":"Mosaic","amount":{"value":62.5,"unit":"grams"},"add":"dry hop","attribute":"aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Jalapeño and cream cheese poppers","Asparagus pesto pasta","Bacon and maple syrup cupcakes"],"brewers_tips":"Don''t be scared by the amount of hops. Seriously this beer can handle them.","contributed_by":"Sam Mason <samjbmason>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 mangler varighet; satt til 60 min."]', 1790238832282);
