INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-172', 'diydog', '172', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/172.json', 'Black Eyed King Imp', 'Vietnamese Coffee Edition.', 'other', 12.7, 85, 1.1135, 1.038, 250, 20, 'black eyed king imp vietnamese coffee edition. annet extra pale wheat caramalt crystal dark crystal amber brown chocolate roasted barley magnum willamette first gold wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Black Eyed King Imp","description":"Vietnamese Coffee Edition.\n\nThis is the Vietnamese Coffee Edition. At 12.7% ABV, Black Eyed King Imp is a super intense and twistedly complex brew, with intense notes of sweet vanilla, rich espresso, smooth molasses and bitter chocolate barely contained by the whatever container it''s in.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":60,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":6.25},{"id":"f2","name":"Wheat","type":"grain","amountKg":1.25},{"id":"f3","name":"Caramalt","type":"grain","amountKg":1.25},{"id":"f4","name":"Crystal","type":"grain","amountKg":1.563},{"id":"f5","name":"Dark Crystal","type":"grain","amountKg":0.625},{"id":"f6","name":"Amber","type":"grain","amountKg":0.625},{"id":"f7","name":"Brown","type":"grain","amountKg":0.625},{"id":"f8","name":"Chocolate","type":"grain","amountKg":0.625},{"id":"f9","name":"Roasted Barley","type":"grain","amountKg":0.313}],"hops":[{"id":"h1","name":"Magnum","amountG":62.5,"use":"boil","timeMin":60},{"id":"h2","name":"Willamette","amountG":31.3,"use":"boil","timeMin":0},{"id":"h3","name":"First Gold","amountG":31.3,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":76.8}],"miscs":[],"mas