INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-241', 'diydog', '241', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/241.json', 'Hello My Name Is Ingrid 2016', 'Cloudberry Double IPA', 'ipa', 8.2, 70, 1.076, 1.013, 30, 20, 'hello my name is ingrid 2016 cloudberry double ipa ipa extra pale caramalt columbus centennial columbus centennial enigma bramling cross columbus centennial enigma bramling cross citra enigma bramling cross wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Hello My Name Is Ingrid 2016","style":"IPA","description":"Cloudberry Double IPA\n\nWe asked the public to tell us the one beer we should brew again, from our entire back catalogue. They chose well. Cloudberries team up with pan-global hops for an all out fruit riot against a caramel malt base.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":94,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":4.9},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.7}],"hops":[{"id":"h1","name":"Columbus","amountG":8,"use":"boil","timeMin":60},{"id":"h2","name":"Centennial","amountG":8,"use":"boil","timeMin":60},{"id":"h3","name":"Columbus","amountG":5,"use":"boil","timeMin":30},{"id":"h4","name":"Centennial","amountG":5,"use":"boil","timeMin":30},{"id":"h5","name":"Enigma","amountG":5,"use":"boil","timeMin":30},{"id":"h6","name":"Bramling Cross","amountG":6,"use":"boil","timeMin":30},{"id":"h7","name":"Columbus","amountG":6,"use":"boil","timeMin":0},{"id":"h8","name":"Centennial","amountG":6,"use":"boil","timeMin":0},{"id":"h9","name":"Enigma","amountG":5,"use":"boil","timeMin":0},{"id":"h10","name":"Bramling Cross","amountG":6,"use":"boil","timeMin":0},{"id":"h11","name":"Citra","amountG":30,"use":"dry_hop"},{"id":"h12","name":"Enigma","amountG":60,"use":"dry_hop"},{"id":"h13","name":"Bramling Cross","amountG":30,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83.3}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.076,"fg":1.013,"ibu":70,"abvPct":8.2,"colorEbc":30},"notes":"Bryggetips: Add the cloudberries to your beer when racking the beer after primary fermentation. Grind them into a paste to allow maximum flavour extraction.\n\nFørst brygget: 2016"}', '{"id":241,"name":"Hello My Name Is Ingrid 2016","tagline":"Cloudberry Double IPA","first_brewed":"2016","description":"We asked the public to tell us the one beer we should brew again, from our entire back catalogue. They chose well. Cloudberries team up with pan-global hops for an all out fruit riot against a caramel malt base.","image":"241.png","abv":8.2,"ibu":70,"target_fg":1013,"target_og":1076,"ebc":30,"srm":15.2,"ph":5.2,"attenuation_level":83.3,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":4.9,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.7,"unit":"kilograms"}}],"hops":[{"name":"Columbus","amount":{"value":8,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"Centennial","amount":{"value":8,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"Columbus","amount":{"value":5,"unit":"grams"},"add":"Middle","attribute":"Flavour"},{"name":"Centennial","amount":{"value":5,"unit":"grams"},"add":"Middle","attribute":"Flavour"},{"name":"Enigma","amount":{"value":5,"unit":"grams"},"add":"Middle","attribute":"Flavour"},{"name":"Bramling Cross","amount":{"value":6,"unit":"grams"},"add":"Middle","attribute":"Flavour"},{"name":"Columbus","amount":{"value":6,"unit":"grams"},"add":"End","attribute":"Flavour"},{"name":"Centennial","amount":{"value":6,"unit":"grams"},"add":"End","attribute":"Flavour"},{"name":"Enigma","amount":{"value":5,"unit":"grams"},"add":"End","attribute":"Flavour"},{"name":"Bramling Cross","amount":{"value":6,"unit":"grams"},"add":"End","attribute":"Flavour"},{"name":"Citra","amount":{"value":30,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Enigma","amount":{"value":60,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Bramling Cross","amount":{"value":30,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Tempura Prawns","Soy-Glazed Chicken Thighs","Raspberry Soufflé"],"brewers_tips":"Add the cloudberries to your beer when racking the beer after primary fermentation. Grind them into a paste to allow maximum flavour extraction.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-242', 'diydog', '242', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/242.json', 'Crew Brew', 'Democratic Amber Ale', 'amber', 8, 100, 1.072, 1.011, 28, 20, 'crew brew democratic amber ale amber, rød og brun maris otter munich crystal carahell wheat cascade nelson sauvin cascade nelson sauvin cascade nelson sauvin cascade nelson sauvin wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Crew Brew","style":"Amber, rød og brun","description":"Democratic Amber Ale\n\nOur crew designed it, and we bottled it just for ourselves! We chose an 8% red ale, mash hopped and first wort hopped with New Zealand origin hops.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":83,"fermentables":[{"id":"f1","name":"Maris Otter","type":"grain","amountKg":4},{"id":"f2","name":"Munich","type":"grain","amountKg":0.5},{"id":"f3","name":"Crystal","type":"grain","amountKg":0.5},{"id":"f4","name":"Carahell","type":"grain","amountKg":0.5},{"id":"f5","name":"Wheat","type":"grain","amountKg":0.5}],"hops":[{"id":"h1","name":"Cascade","amountG":10,"use":"mash"},{"id":"h2","name":"Nelson Sauvin","amountG":10,"use":"mash"},{"id":"h3","name":"Cascade","amountG":30,"use":"boil","timeMin":60},{"id":"h4","name":"Nelson Sauvin","amountG":15,"use":"boil","timeMin":60},{"id":"h5","name":"Cascade","amountG":15,"use":"boil","timeMin":30},{"id":"h6","name":"Nelson Sauvin","amountG":15,"use":"boil","timeMin":30},{"id":"h7","name":"Cascade","amountG":100,"use":"boil","timeMin":0},{"id":"h8","name":"Nelson Sauvin","amountG":100,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":84.6}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.072,"fg":1.011,"ibu":100,"abvPct":8,"colorEbc":28},"notes":"Bryggetips: Bring a few bottles to your local BrewDog bar when it''s done and ask the staff if you got it right, they''re the only ones who can tell you for sure! They''ll also probably know of other homebrewers and beer enthusiasts nearby that you can link in with to share your experiences and get awesome first hand advice from.\n\nFørst brygget: 2016"}', '{"id":242,"name":"Crew Brew","tagline":"Democratic Amber Ale","first_brewed":"2016","description":"Our crew designed it, and we bottled it just for ourselves! We chose an 8% red ale, mash hopped and first wort hopped with New Zealand origin hops.","image":"242.png","abv":8,"ibu":100,"target_fg":1011,"target_og":1072,"ebc":28,"srm":14.2,"ph":5.2,"attenuation_level":84.62,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Maris Otter","amount":{"value":4,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Crystal","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Carahell","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.5,"unit":"kilograms"}}],"hops":[{"name":"Cascade","amount":{"value":10,"unit":"grams"},"add":"Mash","attribute":"Bitter"},{"name":"Nelson Sauvin","amount":{"value":10,"unit":"grams"},"add":"Mash","attribute":"Bitter"},{"name":"Cascade","amount":{"value":30,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"Nelson Sauvin","amount":{"value":15,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"Cascade","amount":{"value":15,"unit":"grams"},"add":"Middle","attribute":"Flavour"},{"name":"Nelson Sauvin","amount":{"value":15,"unit":"grams"},"add":"Middle","attribute":"Flavour"},{"name":"Cascade","amount":{"value":100,"unit":"grams"},"add":"End","attribute":"Aroma"},{"name":"Nelson Sauvin","amount":{"value":100,"unit":"grams"},"add":"End","attribute":"Aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Panko-coated Chicken Katsu","Classic Cheddar Ploughmans","Pecan Pie"],"brewers_tips":"Bring a few bottles to your local BrewDog bar when it''s done and ask the staff if you got it right, they''re the only ones who can tell you for sure! They''ll also probably know of other homebrewers and beer enthusiasts nearby that you can link in with to share your experiences and get awesome first hand advice from.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-243', 'diydog', '243', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/243.json', 'Gin Blitz', 'Botanical Berliner Weisse', 'sour', 3.2, 8, 1.038, 1.008, 8, 20, 'gin blitz botanical berliner weisse surøl maris otter wheat bramling cross juniper berry coriander orange peel wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Gin Blitz","style":"Surøl","description":"Botanical Berliner Weisse\n\nOur Blitz series sees us brew up low abv, super tart Berliner Weisse, and generally infuse them with bags of sour fruit flavour – but this batch uses gin botanicals instead.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":88,"fermentables":[{"id":"f1","name":"Maris Otter","type":"grain","amountKg":1.5},{"id":"f2","name":"Wheat","type":"grain","amountKg":1.5}],"hops":[{"id":"h1","name":"Bramling Cross","amountG":6,"use":"boil","timeMin":60}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":75}],"miscs":[{"id":"x2","name":"Juniper Berry","amount":400,"unit":"g","use":"boil","timeMin":60},{"id":"x3","name":"Coriander","amount":20,"unit":"g","use":"boil","timeMin":60},{"id":"x4","name":"Orange Peel","amount":155,"unit":"g","use":"boil","timeMin":60}],"mashSteps":[{"id":"ms1","name":"Steg 1","temperatureC":60,"durationMin":30},{"id":"ms2","name":"Steg 2","temperatureC":65,"durationMin":20},{"id":"ms3","name":"Steg 3","temperatureC":72,"durationMin":15},{"id":"ms4","name":"Steg 4","temperatureC":78,"durationMin":10}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.038,"fg":1.008,"ibu":8,"abvPct":3.2,"colorEbc":8},"notes":"Bryggetips: Crack open/mash up the Juniper berries to get the most flavour and aroma from them.\n\nTwist: Kettle Soured\n\nFørst brygget: 2016"}', '{"id":243,"name":"Gin Blitz","tagline":"Botanical Berliner Weisse","first_brewed":"2016","description":"Our Blitz series sees us brew up low abv, super tart Berliner Weisse, and generally infuse them with bags of sour fruit flavour – but this batch uses gin botanicals instead.","image":"keg.png","abv":3.2,"ibu":8,"target_fg":1008,"target_og":1038,"ebc":8,"srm":4,"ph":3.2,"attenuation_level":75,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":60,"unit":"celsius"},"duration":30},{"temp":{"value":65,"unit":"celsius"},"duration":20},{"temp":{"value":72,"unit":"celsius"},"duration":15},{"temp":{"value":78,"unit":"celsius"},"duration":10}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Kettle Soured"},"ingredients":{"malt":[{"name":"Maris Otter","amount":{"value":1.5,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":1.5,"unit":"kilograms"}}],"hops":[{"name":"Bramling Cross","amount":{"value":6,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"Juniper Berry","amount":{"value":400,"unit":"grams"},"add":"Start","attribute":"Aroma"},{"name":"Coriander","amount":{"value":20,"unit":"grams"},"add":"Start","attribute":"Aroma"},{"name":"Orange Peel","amount":{"value":155,"unit":"grams"},"add":"Start","attribute":"Aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Game Terrine with Pickles","Fish Tacos","Peach Melba"],"brewers_tips":"Crack open/mash up the Juniper berries to get the most flavour and aroma from them.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-244', 'diydog', '244', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/244.json', 'AB:21', 'Liquorice Blackcurrant Stout.', 'stout', 12, 100, 1.13, 1.015, 200, 20, 'ab:21 liquorice blackcurrant stout. stout og porter extra pale brown double roasted crystal flaked oats galena bramling cross wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"AB:21","style":"Stout og porter","description":"Liquorice Blackcurrant Stout.\n\nAB:21 is a liquorice and blackcurrant infused imperial stout. Rolling in at an imposing 12% abv, this huge and decadent dark beer dials down the charred roastiness and focuses instead on the rich, full-bodied chocolate and dark fruit character of the style.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":88,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":7.2},{"id":"f2","name":"Brown","type":"grain","amountKg":1},{"id":"f3","name":"Double Roasted Crystal","type":"grain","amountKg":1},{"id":"f4","name":"Flaked Oats","type":"grain","amountKg":1}],"hops":[{"id":"h1","name":"Galena","amountG":40,"use":"boil","timeMin":60},{"id":"h2","name":"Bramling Cross","amountG":40,"use":"boil","timeMin":30}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.13,"fg":1.015,"ibu":100,"abvPct":12,"colorEbc":200},"notes":"Bryggetips: As with all of our Abstrakts this one is great for ageing. Be extra vigilant at all times as a small fault now will lead to disaster a few years down the line.\n\nTwist: Liquorice and 200g Blackcurrant Concentrate FV.\n\nFørst brygget: 2016"}', '{"id":244,"name":"AB:21","tagline":"Liquorice Blackcurrant Stout.","first_brewed":"2016","description":"AB:21 is a liquorice and blackcurrant infused imperial stout. Rolling in at an imposing 12% abv, this huge and decadent dark beer dials down the charred roastiness and focuses instead on the rich, full-bodied chocolate and dark fruit character of the style.","image":"244.png","abv":12,"ibu":100,"target_fg":1015,"target_og":1130,"ebc":200,"srm":101.6,"ph":5.1,"attenuation_level":82,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Liquorice and 200g Blackcurrant Concentrate FV."},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":7.2,"unit":"kilograms"}},{"name":"Brown","amount":{"value":1,"unit":"kilograms"}},{"name":"Double Roasted Crystal","amount":{"value":1,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":1,"unit":"kilograms"}}],"hops":[{"name":"Galena","amount":{"value":40,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"Bramling Cross","amount":{"value":40,"unit":"grams"},"add":"Middle","attribute":"Flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Steak Pie and Winter Vegetables","Chocolate Torte","Blackcurrant Panna Cotta"],"brewers_tips":"As with all of our Abstrakts this one is great for ageing. Be extra vigilant at all times as a small fault now will lead to disaster a few years down the line.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","OG/FG i kilden gir 15.1 % ABV, men oppgitt ABV er 12 % — sjekk tallene."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-245', 'diydog', '245', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/245.json', 'Beatnik', 'Imperial Red Ale', 'strong', 8, 60, 1.075, 1.013, 60, 20, 'beatnik imperial red ale sterkt øl maris otter munich dark crystal apollo centennial centennial simcoe simcoe apollo wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Beatnik","style":"Sterkt øl","description":"Imperial Red Ale\n\nWe gave our Equity Punks the keys to the brewery and let them brew the beer, as well as join Q&As and tour our HQ. The beer was voted on exclusively by Equity Punks.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":89,"fermentables":[{"id":"f1","name":"Maris Otter","type":"grain","amountKg":5},{"id":"f2","name":"Munich","type":"grain","amountKg":0.53},{"id":"f3","name":"Dark Crystal","type":"grain","amountKg":0.27}],"hops":[{"id":"h1","name":"Apollo","amountG":26.7,"use":"boil","timeMin":60},{"id":"h2","name":"Centennial","amountG":13.3,"use":"boil","timeMin":30},{"id":"h3","name":"Centennial","amountG":13.3,"use":"boil","timeMin":0},{"id":"h4","name":"Simcoe","amountG":13.3,"use":"boil","timeMin":0},{"id":"h5","name":"Simcoe","amountG":1.3,"use":"dry_hop"},{"id":"h6","name":"Apollo","amountG":0.7,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83.8}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.075,"fg":1.013,"ibu":60,"abvPct":8,"colorEbc":60},"notes":"Bryggetips: Lightly toast the coconut chips to allow better interaction with the hot wort.\n\nFørst brygget: 2016"}', '{"id":245,"name":"Beatnik","tagline":"Imperial Red Ale","first_brewed":"2016","description":"We gave our Equity Punks the keys to the brewery and let them brew the beer, as well as join Q&As and tour our HQ. The beer was voted on exclusively by Equity Punks.","image":"245.png","abv":8,"ibu":60,"target_fg":1013,"target_og":1075,"ebc":60,"srm":30.5,"ph":5.2,"attenuation_level":83.78,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Maris Otter","amount":{"value":5,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.53,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.27,"unit":"kilograms"}}],"hops":[{"name":"Apollo","amount":{"value":26.67,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"Centennial","amount":{"value":13.33,"unit":"grams"},"add":"Middle","attribute":"Flavour"},{"name":"Centennial","amount":{"value":13.33,"unit":"grams"},"add":"End","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":13.33,"unit":"grams"},"add":"End","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":1.33,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Apollo","amount":{"value":0.67,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Loaded Hamburger and Spicy Fries","Warm Banana Bread","Pineapple Sponge Cake"],"brewers_tips":"Lightly toast the coconut chips to allow better interaction with the hot wort.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-246', 'diydog', '246', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/246.json', 'Casino Rye Ale', 'Life''s a Gamble', 'amber', 5.1, 40, 1.049, 1.009, 25, 20, 'casino rye ale life''s a gamble amber, rød og brun extra pale simpsons rye medium crystal equinox equinox equinox equinox wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Casino Rye Ale","style":"Amber, rød og brun","description":"Life''s a Gamble\n\nWe’ve split our bets with Casino Rye Ale and doubled up on the malt front, with barley and rye on the grain bill.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":2.6},{"id":"f2","name":"Simpsons Rye","type":"grain","amountKg":0.5},{"id":"f3","name":"Medium Crystal","type":"grain","amountKg":0.15}],"hops":[{"id":"h1","name":"Equinox","amountG":10,"use":"boil","timeMin":60},{"id":"h2","name":"Equinox","amountG":40,"use":"boil","timeMin":30},{"id":"h3","name":"Equinox","amountG":150,"use":"boil","timeMin":0},{"id":"h4","name":"Equinox","amountG":150,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":81.6}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.049,"fg":1.009,"ibu":40,"abvPct":5.1,"colorEbc":25},"notes":"Bryggetips: We don''t recommend roulette as a way to design beer. Spin the bottle is a much more sensible option. Make this beer with the freshest ingredients you can. Try to arrange brewday as close to delivery day as possible and throw 10 brewbucks on black 17 for us.\n\nFørst brygget: 2016"}', '{"id":246,"name":"Casino Rye Ale","tagline":"Life''s a Gamble","first_brewed":"2016","description":"We’ve split our bets with Casino Rye Ale and doubled up on the malt front, with barley and rye on the grain bill.","image":"246.png","abv":5.1,"ibu":40,"target_fg":1009,"target_og":1049,"ebc":25,"srm":12.7,"ph":5.2,"attenuation_level":81.6,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":2.6,"unit":"kilograms"}},{"name":"Simpsons Rye","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Medium Crystal","amount":{"value":0.15,"unit":"kilograms"}}],"hops":[{"name":"Equinox","amount":{"value":10,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"Equinox","amount":{"value":40,"unit":"grams"},"add":"Middle","attribute":"Flavour"},{"name":"Equinox","amount":{"value":150,"unit":"grams"},"add":"End","attribute":"Aroma"},{"name":"Equinox","amount":{"value":150,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Crab Cakes","Spicy Bean Burrito","Dundee Fruit Cake"],"brewers_tips":"We don''t recommend roulette as a way to design beer. Spin the bottle is a much more sensible option. Make this beer with the freshest ingredients you can. Try to arrange brewday as close to delivery day as possible and throw 10 brewbucks on black 17 for us.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Malt og OG i kilden gir 104 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-247', 'diydog', '247', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/247.json', 'Self Assembly Pope', 'Coconut Vanilla Porter', 'stout', 7.4, 75, 1.072, 1.016, 200, 20, 'self assembly pope coconut vanilla porter stout og porter pale ale wheat dextrin malt chocolate double roasted crystal galena dark muscavado wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Self Assembly Pope","style":"Stout og porter","description":"Coconut Vanilla Porter\n\nA dark and decadent beer brewed with coconut, vanilla, cacao.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3.6},{"id":"f2","name":"Wheat","type":"grain","amountKg":0.2},{"id":"f3","name":"Dextrin Malt","type":"grain","amountKg":0.2},{"id":"f4","name":"Chocolate","type":"grain","amountKg":0.35},{"id":"f5","name":"Double Roasted Crystal","type":"grain","amountKg":0.3}],"hops":[{"id":"h1","name":"Galena","amountG":30,"use":"boil","timeMin":60}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82}],"miscs":[{"id":"x2","name":"Dark Muscavado","amount":400,"unit":"g","use":"boil","timeMin":60}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.072,"fg":1.016,"ibu":75,"abvPct":7.4,"colorEbc":200},"notes":"Bryggetips: Don''t be shy with the roasted coconut, it''s a delicate flavour compared to the rest of the beer, so go nuts! If it grows wild near you, go grab some Gorse and chuck it in too for a local natural boost to the coconut flavours.\n\nTwist: Toasted Coconut Chips – 40g FV & Vanilla Extract – FV\n\nFørst brygget: 2016"}', '{"id":247,"name":"Self Assembly Pope","tagline":"Coconut Vanilla Porter","first_brewed":"2016","description":"A dark and decadent beer brewed with coconut, vanilla, cacao.","image":"247.png","abv":7.4,"ibu":75,"target_fg":1016,"target_og":1072,"ebc":200,"srm":101.6,"ph":5.1,"attenuation_level":82,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Toasted Coconut Chips – 40g FV & Vanilla Extract – FV"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3.6,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.2,"unit":"kilograms"}},{"name":"Dextrin Malt","amount":{"value":0.2,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.35,"unit":"kilograms"}},{"name":"Double Roasted Crystal","amount":{"value":0.3,"unit":"kilograms"}}],"hops":[{"name":"Galena","amount":{"value":30,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"Dark Muscavado","amount":{"value":400,"unit":"grams"},"add":"Additions","attribute":"Flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Beef Rendang","Coconut Macaroons","Profiteroles with Chantilly Cream"],"brewers_tips":"Don''t be shy with the roasted coconut, it''s a delicate flavour compared to the rest of the beer, so go nuts! If it grows wild near you, go grab some Gorse and chuck it in too for a local natural boost to the coconut flavours.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Malt og OG i kilden gir 107 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-248', 'diydog', '248', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/248.json', 'Twin Atlantic', 'Mango & Pineapple Pale', 'other', 5, 80, 1.048, 1.011, 19, 20, 'twin atlantic mango & pineapple pale annet pale ale caramalt cascade equinox wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Twin Atlantic","description":"Mango & Pineapple Pale\n\nBrewed in collaboration with our AGM-headlining band, Twin Atlantic, this US style pale features some of our favourite hops and is loaded with tropical fruit.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.2}],"hops":[{"id":"h1","name":"Cascade","amountG":40,"use":"boil","timeMin":0},{"id":"h2","name":"Equinox","amountG":40,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":77}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.048,"fg":1.011,"ibu":80,"abvPct":5,"colorEbc":19},"notes":"Bryggetips: If you can''t find an awesome Scottish band to collaborate with just pump up the volume on your stereo and have fun moshing whilst you''re mashing in. Use ripe but fresh fruit and be prepared to lose extra volume to it. It''ll be worth it.\n\nTwist: Mango and Pineapple added to FV after Primary fermentation\n\nFørst brygget: 2016"}', '{"id":248,"name":"Twin Atlantic","tagline":"Mango & Pineapple Pale","first_brewed":"2016","description":"Brewed in collaboration with our AGM-headlining band, Twin Atlantic, this US style pale features some of our favourite hops and is loaded with tropical fruit.","image":"keg.png","abv":5,"ibu":80,"target_fg":1011,"target_og":1048,"ebc":19,"srm":9.7,"ph":5.2,"attenuation_level":77,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Mango and Pineapple added to FV after Primary fermentation"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.2,"unit":"kilograms"}}],"hops":[{"name":"Cascade","amount":{"value":40,"unit":"grams"},"add":"End","attribute":"Aroma"},{"name":"Equinox","amount":{"value":40,"unit":"grams"},"add":"End","attribute":"Aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Jerk Chicken Kebabs with Mango Salsa","Avocado and Citrus Salad","Pineapple Upside Down Cake"],"brewers_tips":"If you can''t find an awesome Scottish band to collaborate with just pump up the volume on your stereo and have fun moshing whilst you''re mashing in. Use ripe but fresh fruit and be prepared to lose extra volume to it. It''ll be worth it.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Malt og OG i kilden gir 104 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-249', 'diydog', '249', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/249.json', 'Hop Shot', 'Quadruple India Pale Ale', 'ipa', 7, 250, 1.065, 1.01, 15, 20, 'hop shot quadruple india pale ale ipa extra pale centennial columbus extract centennial columbus centennial columbus amarillo citra simcoe wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Hop Shot","style":"IPA","description":"Quadruple India Pale Ale\n\nHop Shot is a high-velocity hop hit. Our latest experiment in ice-distillation is a west coast IPA, subjected to Antarctic temperatures and concentrated by removing the ice that forms. The result is a 22% ABV hop grenade in a 110ml bottle.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":77,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5.8}],"hops":[{"id":"h1","name":"Centennial","amountG":25,"use":"boil","timeMin":60},{"id":"h2","name":"Columbus Extract","amountG":30,"use":"boil","timeMin":60},{"id":"h3","name":"Centennial","amountG":18.8,"use":"boil","timeMin":30},{"id":"h4","name":"Columbus","amountG":18.8,"use":"boil","timeMin":30},{"id":"h5","name":"Centennial","amountG":50,"use":"boil","timeMin":0},{"id":"h6","name":"Columbus","amountG":25,"use":"boil","timeMin":0},{"id":"h7","name":"Amarillo","amountG":100,"use":"dry_hop"},{"id":"h8","name":"Citra","amountG":100,"use":"dry_hop"},{"id":"h9","name":"Simcoe","amountG":100,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":85}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.065,"fg":1.01,"ibu":250,"abvPct":7,"colorEbc":15},"notes":"Bryggetips: This level of alcohol can be achieved using a domestic freezer. Use a container with a tap close to the bottom so you can run the un-frozen, concentrated beer from under the ice on top. You may have to do this three or four times. The colder you freeze it the boozier it gets. Be careful to not dilute it too much when draining off the concentrated liquid after freezing so you don’t dilute it too much.\n\nFørst brygget: 2016"}', '{"id":249,"name":"Hop Shot","tagline":"Quadruple India Pale Ale","first_brewed":"2016","description":"Hop Shot is a high-velocity hop hit. Our latest experiment in ice-distillation is a west coast IPA, subjected to Antarctic temperatures and concentrated by removing the ice that forms. The result is a 22% ABV hop grenade in a 110ml bottle.","image":"249.png","abv":7,"ibu":250,"target_fg":1010,"target_og":1065,"ebc":15,"srm":7.5,"ph":4.4,"attenuation_level":85,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5.8,"unit":"kilograms"}}],"hops":[{"name":"Centennial","amount":{"value":25,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"Columbus Extract","amount":{"value":30,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"Centennial","amount":{"value":18.75,"unit":"grams"},"add":"Middle","attribute":"Flavour"},{"name":"Columbus","amount":{"value":18.75,"unit":"grams"},"add":"Middle","attribute":"Flavour"},{"name":"Centennial","amount":{"value":50,"unit":"grams"},"add":"End","attribute":"Flavour"},{"name":"Columbus","amount":{"value":25,"unit":"grams"},"add":"End","attribute":"Flavour"},{"name":"Amarillo","amount":{"value":100,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Citra","amount":{"value":100,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":100,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Phall Curry","Pork Burrito with a Habanero and Mango Chili Salsa","Ginger and Grapefruit Poundcake"],"brewers_tips":"This level of alcohol can be achieved using a domestic freezer. Use a container with a tap close to the bottom so you can run the un-frozen, concentrated beer from under the ice on top. You may have to do this three or four times. The colder you freeze it the boozier it gets. Be careful to not dilute it too much when draining off the concentrated liquid after freezing so you don’t dilute it too much.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-250', 'diydog', '250', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/250.json', 'Small Batch: Rye IPA', 'Rye India Pale Ale.', 'ipa', 7.2, 100, 1.065, 1.01, 8, 20, 'small batch: rye ipa rye india pale ale. ipa maris otter rye centennial centennial columbus centennial columbus columbus citra wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Small Batch: Rye IPA","style":"IPA","description":"Rye India Pale Ale.\n\nA 7.2% rye IPA loaded with grapefruit notes, pithy citrus, and huge resinous bitterness, with rye character. The Centennial and Columbus flavours are amplified by the spicy, dry rye.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":94,"fermentables":[{"id":"f1","name":"Maris Otter","type":"grain","amountKg":4},{"id":"f2","name":"Rye","type":"grain","amountKg":0.8}],"hops":[{"id":"h1","name":"Centennial","amountG":40,"use":"boil","timeMin":60},{"id":"h2","name":"Centennial","amountG":15,"use":"boil","timeMin":15},{"id":"h3","name":"Columbus","amountG":15,"use":"boil","timeMin":15},{"id":"h4","name":"Centennial","amountG":50,"use":"whirlpool"},{"id":"h5","name":"Columbus","amountG":25,"use":"whirlpool"},{"id":"h6","name":"Columbus","amountG":10,"use":"dry_hop"},{"id":"h7","name":"Citra","amountG":10,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":84}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Steg 1","temperatureC":60,"durationMin":30},{"id":"ms2","name":"Steg 2","temperatureC":65,"durationMin":20},{"id":"ms3","name":"Steg 3","temperatureC":72,"durationMin":15},{"id":"ms4","name":"Steg 4","temperatureC":78,"durationMin":10}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.065,"fg":1.01,"ibu":100,"abvPct":7.2,"colorEbc":8},"notes":"Bryggetips: Be prepared for a long sparge as the rye content is really high.\n\nFørst brygget: 2016"}', '{"id":250,"name":"Small Batch: Rye IPA","tagline":"Rye India Pale Ale.","first_brewed":"2016","description":"A 7.2% rye IPA loaded with grapefruit notes, pithy citrus, and huge resinous bitterness, with rye character. The Centennial and Columbus flavours are amplified by the spicy, dry rye.","image":"keg.png","abv":7.2,"ibu":100,"target_fg":1010,"target_og":1065,"ebc":8,"srm":16,"ph":4.4,"attenuation_level":84,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":60,"unit":"celsius"},"duration":30},{"temp":{"value":65,"unit":"celsius"},"duration":20},{"temp":{"value":72,"unit":"celsius"},"duration":15},{"temp":{"value":78,"unit":"celsius"},"duration":10}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Maris Otter","amount":{"value":4,"unit":"kilograms"}},{"name":"Rye","amount":{"value":0.8,"unit":"kilograms"}}],"hops":[{"name":"Centennial","amount":{"value":40,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Centennial","amount":{"value":15,"unit":"grams"},"add":"15","attribute":"Bitter"},{"name":"Columbus","amount":{"value":15,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"Centennial","amount":{"value":50,"unit":"grams"},"add":"Whirlpool","attribute":"Aroma"},{"name":"Columbus","amount":{"value":25,"unit":"grams"},"add":"Whirlpool","attribute":"Aroma"},{"name":"Columbus","amount":{"value":10,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Citra","amount":{"value":10,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Salmon Fishcakes with Rocket Salad","Baked Goat''s Cheese","Classic Victoria Sponge"],"brewers_tips":"Be prepared for a long sparge as the rye content is really high.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-251', 'diydog', '251', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/251.json', 'Small Batch: Sorachi Ace Session', 'Sorachi Ace Belgian Pale.', 'pale', 4, 25, 1.035, 1.005, 15, 20, 'small batch: sorachi ace session sorachi ace belgian pale. pale ale pale ale crisp rye munich wheat acidulated malt sorachi ace sorachi ace wyeast 1388 - belgian strong ale™', '{"schemaVersion":1,"name":"Small Batch: Sorachi Ace Session","style":"Pale ale","description":"Sorachi Ace Belgian Pale.\n\nThis brew is a pale ale fermented with Belgian yeast and spiced with coriander seed.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":95,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":2},{"id":"f2","name":"Crisp Rye","type":"grain","amountKg":0.22},{"id":"f3","name":"Munich","type":"grain","amountKg":0.11},{"id":"f4","name":"Wheat","type":"grain","amountKg":0.17},{"id":"f5","name":"Acidulated Malt","type":"grain","amountKg":0.06}],"hops":[{"id":"h1","name":"Sorachi Ace","amountG":22,"use":"boil","timeMin":60},{"id":"h2","name":"Sorachi Ace","amountG":22,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1388 - Belgian Strong Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.035,"fg":1.005,"ibu":25,"abvPct":4,"colorEbc":15},"notes":"Bryggetips: If you dry hop with extra Sorachi Ace you''ll end up with an awesome extra hit of lemony zing but be warned, it''ll go through a lot of interesting variations on the way, including coconut and even bubblegum! Give it time though and it''ll land back at that lovely lemon zest that will compliment the coriander seeds perfectly.\n\nTwist: Crushed Coridaner Seeds – FV\n\nFørst brygget: 2016"}', '{"id":251,"name":"Small Batch: Sorachi Ace Session","tagline":"Sorachi Ace Belgian Pale.","first_brewed":"2016","description":"This brew is a pale ale fermented with Belgian yeast and spiced with coriander seed.","image":"keg.png","abv":4,"ibu":25,"target_fg":1005,"target_og":1035,"ebc":15,"srm":7.62,"ph":5.1,"attenuation_level":79,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Crushed Coridaner Seeds – FV"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":2,"unit":"kilograms"}},{"name":"Crisp Rye","amount":{"value":0.22,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.11,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.17,"unit":"kilograms"}},{"name":"Acidulated Malt","amount":{"value":0.06,"unit":"kilograms"}}],"hops":[{"name":"Sorachi Ace","amount":{"value":22,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"Sorachi Ace","amount":{"value":22,"unit":"grams"},"add":"End","attribute":"Flavour"}],"yeast":"Wyeast 1388 - Belgian Strong Ale™"},"food_pairing":["Californian Sushi Roll","Parmesan and Rocket Pizza","Coconut Cake"],"brewers_tips":"If you dry hop with extra Sorachi Ace you''ll end up with an awesome extra hit of lemony zing but be warned, it''ll go through a lot of interesting variations on the way, including coconut and even bubblegum! Give it time though and it''ll land back at that lovely lemon zest that will compliment the coriander seeds perfectly.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
