bc":15,"srm":7.62,"ph":5.2,"attenuation_level":81.5,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":14,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pilsner","amount":{"value":5.16,"unit":"kilograms"}},{"name":"Pale Ale","amount":{"value":1.72,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":5,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"Sterling","amount":{"value":10,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"Sterling","amount":{"value":10,"unit":"grams"},"add":"End","attribute":"Flavour"}],"yeast":"Wyeast 2124 - Bohemian Lager™"},"food_pairing":["Cajun Chicken Burger","Baked Brie","Tomato and Herb Bruschetta"],"brewers_tips":"To really nail this style you need to get the water right. Do a bit of research on water profiles and ask a local brewery if they can help you out with some water treatments.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-253', 'diydog', '253', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/253.json', 'Small Batch: 90 Shilling', 'Honeyed Spicy Malt.', 'amber', 5.3, 25, 1.056, 1.01, 40, 20, 'small batch: 90 shilling honeyed spicy malt. amber, rød og brun propino pale malt premium english caramalt munich amber dark crystal brown bramling cross first gold first gold wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Small Batch: 90 Shilling","style":"Amber, rød og brun","description":"Honeyed Spicy Malt.\n\nA malt-forward Scotch ale with a complex but mellow mix of toast crust, caramel, hints of cocoa, and a light hop spiciness.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":52,"fermentables":[{"id":"f1","name":"Propino Pale Malt","type":"grain","amountKg":5.6},{"id":"f2","name":"Premium English Caramalt","type":"grain","amountKg":0.6},{"id":"f3","name":"Munich","type":"grain","amountKg":0.6},{"id":"f4","name":"Amber","type":"grain","amountKg":0.2},{"id":"f5","name":"Dark Crystal","type":"grain","amountKg":0.2},{"id":"f6","name":"Brown","type":"grain","amountKg":0.2}],"hops":[{"id":"h1","name":"Bramling Cross","amountG":10,"use":"boil","timeMin":60},{"id":"h2","name":"First Gold","amountG":10,"use":"boil","timeMin":60},{"id":"h3","name":"First Gold","amountG":5,"use":"boil","timeMin":30}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":73}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":54,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.056,"fg":1.01,"ibu":25,"abvPct":5.3,"colorEbc":40},"notes":"Bryggetips: Pre-mix your malts to keep the conversion of starches to sugars even across the mash and give you a more uniform grain bed for lautering and sparging. This is a lot less labour intensive than manually stirring your speciality malts into your mash tun.\n\nFørst brygget: 2017"}', '{"id":253,"name":"Small Batch: 90 Shilling","tagline":"Honeyed Spicy Malt.","first_brewed":"2017","description":"A malt-forward Scotch ale with a complex but mellow mix of toast crust, caramel, hints of cocoa, and a light hop spiciness.","image":"keg.png","abv":5.3,"ibu":25,"target_fg":1010,"target_og":1056,"ebc":40,"srm":20.32,"ph":4.2,"attenuation_level":73,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":54,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Propino Pale Malt","amount":{"value":5.6,"unit":"kilograms"}},{"name":"Premium English Caramalt","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Amber","amount":{"value":0.2,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.2,"unit":"kilograms"}},{"name":"Brown","amount":{"value":0.2,"unit":"kilograms"}}],"hops":[{"name":"Bramling Cross","amount":{"value":10,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"First Gold","amount":{"value":10,"unit":"grams"},"add":"Start","attribute":"Bitter"},{"name":"First Gold","amount":{"value":5,"unit":"grams"},"add":"Middle","attribute":"Flavour"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Game Terrine","Barbecue-griddled Poussin","Clootie Dumpling"],"brewers_tips":"Pre-mix your malts to keep the conversion of starches to sugars even across the mash and give you a more uniform grain bed for lautering and sparging. This is a lot less labour intensive than manually stirring your speciality malts into your mash tun.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
