INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-277', 'diydog', '277', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/277.json', 'Prototype Blonde Ale', 'Mellow Golden Ale.', 'other', 4.5, 15, 1.044, 1.009, 12, 20, 'prototype blonde ale mellow golden ale. annet pale ale wheat carapils perle hallertauer mittelfrüh wlp013 - london ale', '{"schemaVersion":1,"name":"Prototype Blonde Ale","description":"Mellow Golden Ale.\n\nThis Blonde Ale is a new recipe and uses a new yeast - so it is a true Prototype. Originally lined up as part of the 2017 Prototype Challenge it was released shortly afterwards. but hey, these things happen.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":79,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3.3},{"id":"f2","name":"Wheat","type":"grain","amountKg":0.3},{"id":"f3","name":"Carapils","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Perle","amountG":70,"use":"boil","timeMin":70},{"id":"h2","name":"Hallertauer Mittelfrüh","amountG":20,"use":"boil","timeMin":15}],"cultures":[{"id":"y1","name":"WLP013 - London Ale","form":"liquid","amount":1,"unit":"pkg","attenuationPct":80}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":67,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.044,"fg":1.009,"ibu":15,"abvPct":4.5,"colorEbc":12},"notes":"Bryggetips: This yeast strain produces a marked sulphurous note in the beer. If that’s not your thing, don’t Burtonise your mash and see the difference!\n\nFørst brygget: 2017"}', '{"id":277,"name":"Prototype Blonde Ale","tagline":"Mellow Golden Ale.","first_brewed":"2017","description":"This Blonde Ale is a new recipe and uses a new yeast - so it is a true Prototype. Originally lined up as part of the 2017 Prototype Challenge it was released shortly afterwards. but hey, these things happen.","image":"277.png","abv":4.5,"ibu":15,"target_fg":1009,"target_og":1044,"ebc":12,"srm":6,"ph":4.6,"attenuation_level":80,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":67,"unit":"celsius"},"duration":60}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3.3,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.3,"unit":"kilograms"}},{"name":"Carapils","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Perle","amount":{"value":70,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"Hallertauer Mittelfrüh","amount":{"value":20,"unit":"grams"},"add":"15","attribute":"Flavour"}],"yeast":"WLP013 - London Ale"},"food_pairing":["Salmon Salad","Montery Jack Cheese","Mandarin Cake"],"brewers_tips":"This yeast strain produces a marked sulphurous note in the beer. If that’s not your thing, don’t Burtonise your mash and see the difference!","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-278', 'diydog', '278', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/278.json', 'AB:23', 'Bourbon Barrel-Aged Barley Wine.', 'strong', 11.5, 80, 1.11, 1.02, 80, 20, 'ab:23 bourbon barrel-aged barley wine. sterkt øl extra pale munich flaked oats amber brown double roasted crystal bramling cross bramling cross honey american oak chips medium toast soaked in bourbon wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"AB:23","style":"Sterkt øl","description":"Bourbon Barrel-Aged Barley Wine.\n\nOur Abstrakt series showcases one-off beers, brewed or blended to the peak of our abilities. Each release is unique and never to be repeated.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":67,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":9.6},{"id":"f2","name":"Munich","type":"grain","amountKg":0.48},{"id":"f3","name":"Flaked Oats","type":"grain","amountKg":0.48},{"id":"f4","name":"Amber","type":"grain","amountKg":0.24},{"id":"f5","name":"Brown","type":"grain","amountKg":0.24},{"id":"f6","name":"Double Roasted Crystal","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Bramling Cross","amountG":60,"use":"boil","timeMin":70},{"id":"h2","name":"Bramling Cross","amountG":20,"use":"boil","timeMin":15}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82}],"miscs":[{"id":"x3","name":"Honey","amount":400,"unit":"g","use":"boil","timeMin":0},{"id":"x4","name":"American Oak Chips Medium Toast Soaked in Bourbon","amount":50,"unit":"g","use":"fermentation","notes":"Fatlagring / treflis"}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.11,"fg":1.02,"ibu":80,"abvPct":11.5,"colorEbc":80},"notes":"Bryggetips: Never put honey into your beer without pasteurising it. It is full of wild yeasts that are waiting to spoil your hard work.\n\nFørst brygget: 2017"}', '{"id":278,"name":"AB:23","tagline":"Bourbon Barrel-Aged Barley Wine.","first_brewed":"2017","description":"Our Abstrakt series showcases one-off beers, brewed or blended to the peak of our abilities. Each release is unique and never to be repeated.","image":"278.png","abv":11.5,"ibu":80,"target_fg":1020,"target_og":1110,"ebc":80,"srm":41,"ph":4.1,"attenuation_level":82,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":9.6,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Amber","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Brown","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Double Roasted Crystal","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Bramling Cross","amount":{"value":60,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"Bramling Cross","amount":{"value":20,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"Honey","amount":{"value":400,"unit":"grams"},"add":"Flame Out","attribute":"Flavour"},{"name":"American Oak Chips Medium Toast Soaked in Bourbon","amount":{"value":50,"unit":"grams"},"add":"Wood Ageing","attribute":"Flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Stilton and Walnut Welsh Rarebit.","Cherry Chocolate Cake With Chocolate Whipped Mousse","Simnel Cake"],"brewers_tips":"Never put honey into your beer without pasteurising it. It is full of wild yeasts that are waiting to spoil your hard work.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-279', 'diydog', '279', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/279.json', 'Slot Machine', 'Red Rye IPA.', 'ipa', 5.2, 50, 1.051, 1.011, 50, 20, 'slot machine red rye ipa. ipa pale ale rye medium crystal carafa special malt type 3 magnum amarillo mandarina bavaria amarillo hallertauer blanc mandarina bavaria amarillo hallertauer blanc wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Slot Machine","style":"IPA","description":"Red Rye IPA.\n\nOur Q4 Seasonal is a red rye IPA. This twist on an American IPA involves a more complex malt base, with the careful addition of rye - a grain known for its trickiness when brewing with anything above a tiny percentage.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":84,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3.42},{"id":"f2","name":"Rye","type":"grain","amountKg":0.48},{"id":"f3","name":"Medium Crystal","type":"grain","amountKg":0.18},{"id":"f4","name":"Carafa Special Malt Type 3","type":"grain","amountKg":0.12}],"hops":[{"id":"h1","name":"Magnum","amountG":10,"use":"boil","timeMin":70},{"id":"h2","name":"Amarillo","amountG":10,"use":"boil","timeMin":10},{"id":"h3","name":"Mandarina Bavaria","amountG":10,"use":"boil","timeMin":0},{"id":"h4","name":"Amarillo","amountG":20,"use":"boil","timeMin":0},{"id":"h5","name":"Hallertauer Blanc","amountG":10,"use":"boil","timeMin":0},{"id":"h6","name":"Mandarina Bavaria","amountG":50,"use":"dry_hop"},{"id":"h7","name":"Amarillo","amountG":100,"use":"dry_hop"},{"id":"h8","name":"Hallertauer Blanc","amountG":50,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":78}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":30}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.051,"fg":1.011,"ibu":50,"abvPct":5.2,"colorEbc":50},"notes":"Bryggetips: Rye can cause run off problems. Try to reach a temperature of 78 degrees Celsius if possible, and sparge at the same temperature.\n\nFørst brygget: 2017"}', '{"id":279,"name":"Slot Machine","tagline":"Red Rye IPA.","first_brewed":"2017","description":"Our Q4 Seasonal is a red rye IPA. This twist on an American IPA involves a more complex malt base, with the careful addition of rye - a grain known for its trickiness when brewing with anything above a tiny percentage.","image":"279.png","abv":5.2,"ibu":50,"target_fg":1011,"target_og":1051,"ebc":50,"srm":25,"ph":4.3,"attenuation_level":78,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":30}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3.42,"unit":"kilograms"}},{"name":"Rye","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Medium Crystal","amount":{"value":0.18,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":0.12,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":10,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"Amarillo","amount":{"value":10,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Mandarina Bavaria","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Hallertauer Blanc","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Mandarina Bavaria","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":100,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Hallertauer Blanc","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Barbeque and Mustard Beef on Rye Bread","Gooseberry and Plum Compote","Mature Wensleydale"],"brewers_tips":"Rye can cause run off problems. Try to reach a temperature of 78 degrees Celsius if possible, and sparge at the same temperature.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-280', 'diydog', '280', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/280.json', 'Make Earth Great Again', 'Cloudberry Saison.', 'belgian', 7.5, 35, 1.065, 1.004, 9, 20, 'make earth great again cloudberry saison. belgisk og saison pilsner dextrose white wheat torrified wheat amarillo amarillo mandarina bavaria amarillo mandarina bavaria cloudberries wyeast 3711 - french saison™', '{"schemaVersion":1,"name":"Make Earth Great Again","style":"Belgisk og saison","description":"Cloudberry Saison.\n\nIn protest against the potential withdrawal of the USA from the Paris agreement, we brewed a saison (which ferments at high temperatures) with melted ice caps (glacier water) and cloudberries (an Arctic berry).","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":82,"fermentables":[{"id":"f1","name":"Pilsner","type":"grain","amountKg":3.72},{"id":"f2","name":"Dextrose","type":"sugar","amountKg":0.84},{"id":"f3","name":"White Wheat","type":"grain","amountKg":0.48},{"id":"f4","name":"Torrified Wheat","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Amarillo","amountG":6,"use":"boil","timeMin":70},{"id":"h2","name":"Amarillo","amountG":4,"use":"boil","timeMin":15},{"id":"h3","name":"Mandarina Bavaria","amountG":6,"use":"boil","timeMin":15},{"id":"h4","name":"Amarillo","amountG":10,"use":"boil","timeMin":0},{"id":"h5","name":"Mandarina Bavaria","amountG":10,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 3711 - French Saison™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":94}],"miscs":[{"id":"x6","name":"Cloudberries","amount":100,"unit":"g","use":"boil","timeMin":0}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":23}],"targets":{"og":1.065,"fg":1.004,"ibu":35,"abvPct":7.5,"colorEbc":9},"notes":"Bryggetips: So your homebrew shop of choice may not stock all the ingredients here! You can buy cloudberry jam and add that instead. The pectin in the jam is not ideal and will form a haze but that can be forgiven in a saison.\n\nTwist: 10kg of glacier water added to the mash.\n\nFørst brygget: 2017"}', '{"id":280,"name":"Make Earth Great Again","tagline":"Cloudberry Saison.","first_brewed":"2017","description":"In protest against the potential withdrawal of the USA from the Paris agreement, we brewed a saison (which ferments at high temperatures) with melted ice caps (glacier water) and cloudberries (an Arctic berry).","image":"280.png","abv":7.5,"ibu":35,"target_fg":1004,"target_og":1065,"ebc":9,"srm":5,"ph":4.6,"attenuation_level":94,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":60}],"fermentation":{"temp":{"value":23,"unit":"celsius"}},"twist":"10kg of glacier water added to the mash."},"ingredients":{"malt":[{"name":"Pilsner","amount":{"value":3.72,"unit":"kilograms"}},{"name":"Dextrose","amount":{"value":0.84,"unit":"kilograms"}},{"name":"White Wheat","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Torrified Wheat","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Amarillo","amount":{"value":6,"unit":"grams"},"add":"70","attribute":"Bitter"},{"name":"Amarillo","amount":{"value":4,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"Mandarina Bavaria","amount":{"value":6,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"Amarillo","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Mandarina Bavaria","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Cloudberries","amount":{"value":100,"unit":"grams"},"add":"Flame Out","attribute":"Flavour"}],"yeast":"Wyea