INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-281', 'diydog', '281', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/281.json', 'Homicidal Puppet Help Desk', 'Barrel-Aged Rye Barley Wine.', 'strong', 11.5, 132, 1.105, 1.02, 45, 20, 'homicidal puppet help desk barrel-aged rye barley wine. sterkt øl pale ale rye brown magnum galena american oak chips heavy toast soaked in bourbon wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Homicidal Puppet Help Desk","style":"Sterkt øl","description":"Barrel-Aged Rye Barley Wine.\n\nIndulgent, complex, and endlessly rewarding; packed with flavours of toffee, coconut, red berry, burnt sugar, marzipan, orange, cherry - American oak adds structure and depth to this chewy and warming barley wine brewed with rye and aged in rye whiskey cask.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":8.16},{"id":"f2","name":"Rye","type":"grain","amountKg":1.44},{"id":"f3","name":"Brown","type":"grain","amountKg":0.12}],"hops":[{"id":"h1","name":"Magnum","amountG":40,"use":"boil","timeMin":70},{"id":"h2","name":"Galena","amountG":20,"use":"boil","timeMin":15}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":81}],"miscs":[{"id":"x3","name":"American Oak Chips Heavy Toast Soaked in Bourbon","amount":100,"unit":"g","use":"fermentation","notes":"Fatlagring / treflis"}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.105,"fg":1.02,"ibu":132,"abvPct":11.5,"colorEbc":45},"notes":"Bryggetips: Be careful with brown malt. If you put too much in, it can very easily turn a fantastic tasting beer into a beer that tastes like someone has poured a pint into an ash tray, swirled it around and put it back into your pint.\n\nFørst brygget: 2017"}', '{"id":281,"name":"Homicidal Puppet Help Desk","tagline":"Barrel-Aged Rye Barley Wine.","first_brewed":"2017","description":"Indulgent, complex, and endlessly rewarding; packed with flavours of toffee, coconut, red berry, burnt sugar, marzipan, orange, cherry - American oak adds structure and depth to this chewy and warming barley wine brewed with rye and aged in rye whiskey cask.","image":"281.png","abv":11.5,"ibu":132,"target_fg":1020,"target_og":1105,"ebc":45,"srm":23,"ph":4.1,"attenuation_level":81,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":60}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":8.16,"unit":"kilograms"}},{"name":"Rye","amount":{"value":1.44,"unit":"kilograms"}},{"name":"Brown","amount":{"value":0.12,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":40,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"Galena","amount":{"value":20,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"American Oak Chips Heavy Toast Soaked in Bourbon","amount":{"value":100,"unit":"grams"},"add":"Wood Ageing","attribute":"Flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Stilton and Walnut Welsh Rarebit.","Cherry Chocolate Cake With Chocolate Whipped Mousse","Simnel Cake"],"brewers_tips":"Be careful with brown malt. If you put too much in, it can very easily turn a fantastic tasting beer into a beer that tastes like someone has poured a pint into an ash tray, swirled it around and put it back into your pint.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne be