INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-284', 'diydog', '284', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/284.json', 'Hello My Name Is Helga', 'Cherry Double IPA.', 'ipa', 8.2, 70, 1.07, 1.009, 15, 20, 'hello my name is helga cherry double ipa. ipa pale ale caramalt simcoe chinook simcoe citra chinook centennial simcoe wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Hello My Name Is Helga","style":"IPA","description":"Cherry Double IPA.\n\nBrewed exclusively for the German market, this Hello My Name brew features a twist of flavour inspired by Germany.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":90,"efficiencyPct":86,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.52},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.12}],"hops":[{"id":"h1","name":"Simcoe","amountG":24,"use":"boil","timeMin":90},{"id":"h2","name":"Chinook","amountG":20,"use":"boil","timeMin":30},{"id":"h3","name":"Simcoe","amountG":30,"use":"boil","timeMin":0},{"id":"h4","name":"Citra","amountG":40,"use":"dry_hop"},{"id":"h5","name":"Chinook","amountG":40,"use":"dry_hop"},{"id":"h6","name":"Centennial","amountG":20,"use":"dry_hop"},{"id":"h7","name":"Simcoe","amountG":40,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":87}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":66,"durationMin":65}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.07,"fg":1.009,"ibu":70,"abvPct":8.2,"colorEbc":15},"notes":"Bryggetips: Morello Cherries are the go to cherry variety for this beer (and Krieks), the sour compliments the residual sweetness of the malt. Works well if you reduce your IBU to the 20 to 30 range too.\n\nFørst brygget: 2017"}', '{"id":284,"name":"Hello My Name Is Helga","tagline":"Cherry Double IPA.","first_brewed":"2017","description":"Brewed exclusively for the German market, this Hello My Name brew features a twist of flavour inspired by Germany.","image":"284.png","abv":8.2,"ibu":70,"target_fg":1009,"target_og":1070,"ebc":15,"srm":8,"ph":4.4,"attenuation_level":87,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":66,"unit":"celsius"},"duration":65}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.52,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.12,"unit":"kilograms"}}],"hops":[{"name":"Simcoe","amount":{"value":24,"unit":"grams"},"add":"90","attribute":"Bittering"},{"name":"Chinook","amount":{"value":20,"unit":"grams"},"add":"30","attribute":"Flavour"},{"name":"Simcoe","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Chinook","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Centennial","amount":{"value":20,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Roast pork chops","Beef in port stew","Cherry frangipane tart"],"brewers_tips":"Morello Cherries are the go to cherry variety for this beer (and Krieks), the sour compliments the residual sweetness of the malt. Works well if you reduce your IBU to the 20 to 30 range too.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
