INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-292', 'diydog', '292', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/292.json', 'Hello My Name Is Maria', 'Mandarin Infused Double IPA.', 'ipa', 8.2, 70, 1.07, 1.009, 15, 20, 'hello my name is maria mandarin infused double ipa. ipa pale ale caramalt simcoe chinook simcoe citra chinook simcoe centennial mandarin segements wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Hello My Name Is Maria","style":"IPA","description":"Mandarin Infused Double IPA.\n\nBrewed exclusively for the Spanish market, this Hello My Name brew features a twist of flavour inspired by Spain.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":90,"efficiencyPct":86,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.52},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.12}],"hops":[{"id":"h1","name":"Simcoe","amountG":24,"use":"boil","timeMin":90},{"id":"h2","name":"Chinook","amountG":20,"use":"boil","timeMin":30},{"id":"h3","name":"Simcoe","amountG":30,"use":"boil","timeMin":0},{"id":"h4","name":"Citra","amountG":40,"use":"dry_hop"},{"id":"h5","name":"Chinook","amountG":40,"use":"dry_hop"},{"id":"h6","name":"Simcoe","amountG":40,"use":"dry_hop"},{"id":"h7","name":"Centennial","amountG":20,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":87}],"miscs":[{"id":"x8","name":"Mandarin Segements","amount":1000,"unit":"g","use":"mash"}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":66,"durationMin":65}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.07,"fg":1.009,"ibu":70,"abvPct":8.2,"colorEbc":15},"notes":"Bryggetips: Using the mandarin in the mash means you can also throw in the peel to extract the essential oils from it. The pith can be quite bitter if it makes it into the boil.\n\nFørst brygget: 2017"}', '{"id":292,"name":"Hello My Name Is Maria","tagline":"Mandarin Infused Double IPA.","first_brewed":"2017","description":"Brewed exclusively for the Spanish market, this Hello My Name brew features a twist of flavour inspired by Spain.","image":"292.png","abv":8.2,"ibu":70,"target_fg":1009,"target_og":1070,"ebc":15,"srm":8,"ph":4.4,"attenuation_level":87,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":66,"unit":"celsius"},"duration":65}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.52,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.12,"unit":"kilograms"}}],"hops":[{"name":"Simcoe","amount":{"value":24,"unit":"grams"},"add":"90","attribute":"Bittering"},{"name":"Chinook","amount":{"value":20,"unit":"grams"},"add":"30","attribute":"Flavour"},{"name":"Simcoe","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Chinook","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Centennial","amount":{"value":20,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mandarin Segements","amount":{"value":1000,"unit":"grams"},"add":"Mash","attribute":"Flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Stir-fried chicken","Chocolate mousse","Orange polenta cake"],"brewers_tips":"Using the mandarin in the mash means you can also throw in the peel to extract the essential oils from it. The pith can be quite bitter if it makes it into the boil.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-293', 'diydog', '293', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/293.json', 'I Wanna Be Your Dog', 'Omnipollo X BrewDog - Barrel Aged Imperial Stout.', 'stout', 12, 55, 1.125, 1.035, 600, 20, 'i wanna be your dog omnipollo x brewdog - barrel aged imperial stout. stout og porter extra pale caramalt chocolate flaked oats extra dark crystal brown dextrin malt double roasted crystal amber magnum american oak chips medium toast soaked in speyside whisky american oak chips heavy toast soaked in speyside whisky wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"I Wanna Be Your Dog","style":"Stout og porter","description":"Omnipollo X BrewDog - Barrel Aged Imperial Stout.\n\nA collaboration with Omnipollo, known for their uncanny ability to repilcate dessert flavours in indulgent beers. This caramel and pecan flavoured imperial stout has been barrel aged for almost a year in whisky casks, to add an extra level of depth to the pecan mud pie concept.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":81,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":5.76},{"id":"f2","name":"Caramalt","type":"grain","amountKg":1.2},{"id":"f3","name":"Chocolate","type":"grain","amountKg":1.08},{"id":"f4","name":"Flaked Oats","type":"grain","amountKg":0.72},{"id":"f5","name":"Extra Dark Crystal","type":"grain","amountKg":0.48},{"id":"f6","name":"Brown","type":"grain","amountKg":0.48},{"id":"f7","name":"Dextrin Malt","type":"grain","amountKg":0.48},{"id":"f8","name":"Double Roasted Crystal","type":"grain","amountKg":0.24},{"id":"f9","name":"Amber","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Magnum","amountG":40,"use":"boil","timeMin":70}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":72}],"miscs":[{"id":"x2","name":"American Oak Chips Medium Toast soaked in Speyside Whisky","amount":50,"unit":"g","use":"fermentation","notes":"Fatlagring / treflis"},{"id":"x3","name":"American Oak Chips Heavy Toast soaked in Speyside Whisky","amount":50,"unit":"g","use":"fermentation","notes":"Fatlagring / treflis"}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.125,"fg":1.035,"ibu":55,"abvPct":12,"colorEbc":600},"notes":"Bryggetips: Don’t be too quick to rack the beer off the yeast once your final gravity is reached. The stressed yeast will be absorbing a number of undesirable fermentation by-products such as acetaldehyde and diacetyl. Give them a minimum of 10 days at fermentation temperature to do this before cooling it down.\n\nFørst brygget: 2017"}', '{"id":293,"name":"I Wanna Be Your Dog","tagline":"Omnipollo X BrewDog - Barrel Aged Imperial Stout.","first_brewed":"2017","description":"A collaboration with Omnipollo, known for their uncanny ability to repilcate dessert flavours in indulgent beers. This caramel and pecan flavoured imperial stout has been barrel aged for almost a year in whisky casks, to add an extra level of depth to the pecan mud pie concept.","image":"293.png","abv":12,"ibu":55,"target_fg":1035,"target_og":1125,"ebc":600,"srm":305,"ph":4.1,"attenuation_level":72,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":5.76,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":1.2,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":1.08,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.72,"unit":"kilograms"}},{"name":"Extra Dark Crystal","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Brown","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Dextrin Malt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Double Roasted Crystal","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Amber","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":40,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"American Oak Chips Medium Toast soaked in Speyside Whisky","amount":{"value":50,"unit":"grams"},"add":"Wood Ageing","attribute":"Flavour"},{"name":"American Oak Chips Heavy Toast soaked in Speyside Whisky","amount":{"value":50,"unit":"grams"},"add":"Wood Ageing","attribute":"Flavour"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Pecan muffins with chocolate ganache","Salted caramels","Hazelnut truffles"],"brewers_tips":"Don’t be too quick to rack the beer off the yeast once your final gravity is reached. The stressed yeast will be absorbing a number of undesirable fermentation by-products such as acetaldehyde and diacetyl. Give them a minimum of 10 days at fermentation temperature to do this before cooling it down.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-294', 'diydog', '294', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/294.json', 'Opaque Jake', 'Vermont IPA.', 'ipa', 7.2, 20, 1.065, 1.009, 20, 20, 'opaque jake vermont ipa. ipa pale ale flaked oats wheat citra citra citra wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Opaque Jake","style":"IPA","description":"Vermont IPA.\n\nOur first single-hop Vermont IPA; all the flavour in this beer comes from a combination of Citra''s naturally complex flavour profile, the yeast-produced esters, and the biotransformation of the hop oils by its contact with the yeast.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":76,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.92},{"id":"f2","name":"Flaked Oats","type":"grain","amountKg":0.6},{"id":"f3","name":"Wheat","type":"grain","amountKg":0.36}],"hops":[{"id":"h1","name":"Citra","amountG":2,"use":"boil","timeMin":70},{"id":"h2","name":"Citra","amountG":30,"use":"boil","timeMin":0},{"id":"h3","name":"Citra","amountG":200,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":86}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":66,"durationMin":20}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.065,"fg":1.009,"ibu":20,"abvPct":7.2,"colorEbc":20},"notes":"Bryggetips: Pectin powder can easily be sourced and is an easy alternative for a homebrewer to produce murky beer if you don’t have access to a low flocculating yeast.\n\nFørst brygget: 2017"}', '{"id":294,"name":"Opaque Jake","tagline":"Vermont IPA.","first_brewed":"2017","description":"Our first single-hop Vermont IPA; all the flavour in this beer comes from a combination of Citra''s naturally complex flavour profile, the yeast-produced esters, and the biotransformation of the hop oils by its contact with the yeast.","image":"keg.png","abv":7.2,"ibu":20,"target_fg":1009,"target_og":1065,"ebc":20,"srm":10,"ph":4.4,"attenuation_level":86,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":66,"unit":"celsius"},"duration":20}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.92,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.36,"unit":"kilograms"}}],"hops":[{"name":"Citra","amount":{"value":2,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"Citra","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":200,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Steak","Chicken korma","Lobster salad"],"brewers_tips":"Pectin powder can easily be sourced and is an easy alternative for a homebrewer to produce murky beer if you don’t have access to a low flocculating yeast.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
