INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-296', 'diydog', '296', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/296.json', 'Off-Duty Alien', 'Citrus IPA', 'ipa', 6.5, 50, 1.06, 1.01, 20, 20, 'off-duty alien citrus ipa ipa pale ale caramalt bitter orange sweet orange peel grapefruit peel magnum simcoe amarillo simcoe amarillo citra mosaic simcoe amarillo citra wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Off-Duty Alien","style":"IPA","description":"Citrus IPA\n\nOff-Duty Alien is a citrus IPA, brewed with blood orange and grapefruit to enhance the citurs characteristics of the hops.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":80,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.32},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.84}],"hops":[{"id":"h1","name":"Magnum","amountG":2,"use":"boil","timeMin":70},{"id":"h2","name":"Simcoe","amountG":10,"use":"boil","timeMin":10},{"id":"h3","name":"Amarillo","amountG":10,"use":"boil","timeMin":10},{"id":"h4","name":"Simcoe","amountG":10,"use":"boil","timeMin":0},{"id":"h5","name":"Amarillo","amountG":10,"use":"boil","timeMin":0},{"id":"h6","name":"Citra","amountG":20,"use":"boil","timeMin":0},{"id":"h7","name":"Mosaic","amountG":20,"use":"boil","timeMin":10},{"id":"h8","name":"Simcoe","amountG":40,"use":"dry_hop"},{"id":"h9","name":"Amarillo","amountG":40,"use":"dry_hop"},{"id":"h10","name":"Citra","amountG":40,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83}],"miscs":[{"id":"m3","name":"Bitter Orange","amount":10,"unit":"g","use":"boil","timeMin":10},{"id":"m4","name":"Sweet Orange Peel","amount":10,"unit":"g","use":"boil","timeMin":10},{"id":"m5","name":"Grapefruit Peel","amount":10,"unit":"g","use":"boil","timeMin":10}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":20}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.06,"fg":1.01,"ibu":50,"abvPct":6.5,"colorEbc":20},"notes":"Bryggetips: Adding the orange and grapefruit peels to the mash gently extracts the essential oils from the peel but leaves the bitter pith behind in the spent grain.\n\nFørst brygget: 2018"}', '{"id":296,"name":"Off-Duty Alien","tagline":"Citrus IPA","first_brewed":"2018","description":"Off-Duty Alien is a citrus IPA, brewed with blood orange and grapefruit to enhance the citurs characteristics of the hops.","image":"keg.png","abv":6.5,"ibu":50,"target_fg":1010,"target_og":1060,"ebc":20,"srm":10,"ph":4.4,"attenuation_level":83,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":20}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.32,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.84,"unit":"kilograms"}},{"name":"Bitter Orange","amount":{"value":10,"unit":"grams"}},{"name":"Sweet Orange Peel","amount":{"value":10,"unit":"grams"}},{"name":"Grapefruit Peel","amount":{"value":10,"unit":"grams"}}],"hops":[{"name":"Magnum","amount":{"value":2,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"Simcoe","amount":{"value":10,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Amarillo","amount":{"value":10,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Simcoe","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Citra","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Roasted halibut with grapefruit salsa","Butternut squash bisque","+80% Dark chocolate"],"brewers_tips":"Adding the orange and grapefruit peels to the mash gently extracts the essential oils from the peel but leaves the bitter pith behind in the spent grain.","contributed_by":"John Jenkman <johnjenkman>"}', '["«Bitter Orange» sto under malt; lagt inn som tilsetning i kok (10 min) — tidspunkt er antatt.","«Sweet Orange Peel» sto under malt; lagt inn som tilsetning i kok (10 min) — tidspunkt er antatt.","«Grapefruit Peel» sto under malt; lagt inn som tilsetning i kok (10 min) — tidspunkt er antatt.","Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-297', 'diydog', '297', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/297.json', 'East Of Vermont', 'Mango & Peach Milkshake Vermont IPA.', 'ipa', 7.8, 15, 1.077, 1.018, 20, 20, 'east of vermont mango & peach milkshake vermont ipa. ipa pale ale wheat flaked oats mosaic citra peach concentrate mango concentrate milk sugars wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"East Of Vermont","style":"IPA","description":"Mango & Peach Milkshake Vermont IPA.\n\nA Vermont IPA with fruit and milk sugars added - recreating fruity milkshake character in an IPA.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":89,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.8},{"id":"f2","name":"Wheat","type":"grain","amountKg":0.6},{"id":"f3","name":"Flaked Oats","type":"grain","amountKg":0.6}],"hops":[{"id":"h1","name":"Mosaic","amountG":10,"use":"boil","timeMin":0},{"id":"h2","name":"Citra","amountG":10,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":77}],"miscs":[{"id":"x3","name":"Peach Concentrate","amount":150,"unit":"g","use":"boil","timeMin":0},{"id":"x4","name":"Mango Concentrate","amount":150,"unit":"g","use":"boil","timeMin":0},{"id":"x5","name":"Milk Sugars","amount":400,"unit":"g","use":"boil","timeMin":60}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":36}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.077,"fg":1.018,"ibu":15,"abvPct":7.8,"colorEbc":20},"notes":"Bryggetips: If you use mango pulp, extend the time that you whirlpool to let it settle out. Trying to clean mango pulp out of your heat exchanger or cooling coil is not a fun ending to a brewday.\n\nFørst brygget: 2018"}', '{"id":297,"name":"East Of Vermont","tagline":"Mango & Peach Milkshake Vermont IPA.","first_brewed":"2018","description":"A Vermont IPA with fruit and milk sugars added - recreating fruity milkshake character in an IPA.","image":"keg.png","abv":7.8,"ibu":15,"target_fg":1018,"target_og":1077,"ebc":20,"srm":10,"ph":4.4,"attenuation_level":77,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":36}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.8,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.6,"unit":"kilograms"}}],"hops":[{"name":"Mosaic","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Peach Concentrate","amount":{"value":150,"unit":"grams"},"add":"Flame Out","attribute":"Aroma"},{"name":"Mango Concentrate","amount":{"value":150,"unit":"grams"},"add":"Flame Out","attribute":"Aroma"},{"name":"Milk Sugars","amount":{"value":400,"unit":"grams"},"add":"Kettle","attribute":"Flavour"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Thai sweet potato and carrot soup","Carrot cake","Peaches and cream"],"brewers_tips":"If you use mango pulp, extend the time that you whirlpool to let it settle out. Trying to clean mango pulp out of your heat exchanger or cooling coil is not a fun ending to a brewday.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-298', 'diydog', '298', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/298.json', 'Declassified Demi-God', 'Barrel-Aged Imperial Milk Stout.', 'stout', 14.1, 70, 1.127, 1.02, 90, 20, 'declassified demi-god barrel-aged imperial milk stout. stout og porter extra pale flaked oats chocolate roasted barley caramalt smoked malt dark crystal nelson sauvin columbus sorachi ace centennial nelson sauvin sorachi ace centennial nelson sauvin wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Declassified Demi-God","style":"Stout og porter","description":"Barrel-Aged Imperial Milk Stout.\n\nAn exclusive barrel-aged blend, brought together to reward investors on Equity for Punks USA; two imperial stouts aged in grain whisky barrels for over a year.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Extra Pale","type":"grain","amountKg":7.44},{"id":"f2","name":"Flaked Oats","type":"grain","amountKg":1.44},{"id":"f3","name":"Chocolate","type":"grain","amountKg":0.72},{"id":"f4","name":"Roasted Barley","type":"grain","amountKg":0.72},{"id":"f5","name":"Caramalt","type":"grain","amountKg":0.48},{"id":"f6","name":"Smoked Malt","type":"grain","amountKg":0.48},{"id":"f7","name":"Dark Crystal","type":"grain","amountKg":0.48}],"hops":[{"id":"h1","name":"Nelson Sauvin","amountG":40,"use":"boil","timeMin":60},{"id":"h2","name":"Columbus","amountG":40,"use":"boil","timeMin":60},{"id":"h3","name":"Sorachi Ace","amountG":20,"use":"boil","timeMin":10},{"id":"h4","name":"Centennial","amountG":20,"use":"boil","timeMin":10},{"id":"h5","name":"Nelson Sauvin","amountG":20,"use":"boil","timeMin":10},{"id":"h6","name":"Sorachi Ace","amountG":20,"use":"boil","timeMin":0},{"id":"h7","name":"Centennial","amountG":20,"use":"boil","timeMin":0},{"id":"h8","name":"Nelson Sauvin","amountG":20,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":84}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":90}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.127,"fg":1.02,"ibu":70,"abvPct":14.1,"colorEbc":90},"notes":"Bryggetips: The lactose kettle addition is unfermentable by yeast. Target a pre-boil OG of between 90 and 100, then use the lactose to increase it to the target OG.\n\nFørst brygget: 2018"}', '{"id":298,"name":"Declassified Demi-God","tagline":"Barrel-Aged Imperial Milk Stout.","first_brewed":"2018","description":"An exclusive barrel-aged blend, brought together to reward investors on Equity for Punks USA; two imperial stouts aged in grain whisky barrels for over a year.","image":"298.png","abv":14.1,"ibu":70,"target_fg":1020,"target_og":1127,"ebc":90,"srm":46,"ph":4.1,"attenuation_level":84,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":90}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Extra Pale","amount":{"value":7.44,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":1.44,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":0.72,"unit":"kilograms"}},{"name":"Roasted Barley","amount":{"value":0.72,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Smoked Malt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.48,"unit":"kilograms"}}],"hops":[{"name":"Nelson Sauvin","amount":{"value":40,"unit":"grams"},"add":"60","attribute":"Bittering"},{"name":"Columbus","amount":{"value":40,"unit":"grams"},"add":"60","attribute":"Bittering"},{"name":"Sorachi Ace","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Centennial","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Nelson Sauvin","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Sorachi Ace","amount":{"value":20,"unit":"grams"},"add":"Flame Out","attribute":"Aroma"},{"name":"Centennial","amount":{"value":20,"unit":"grams"},"add":"Flame Out","attribute":"Aroma"},{"name":"Nelson Sauvin","amount":{"value":20,"unit":"grams"},"add":"Flame Out","attribute":"Aroma"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Mole Mexican chilli beef","BBQ pit beans","Chocolate ganache"],"brewers_tips":"The lactose kettle addition is unfermentable by yeast. Target a pre-boil OG of between 90 and 100, then use the lactose to increase it to the target OG.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-299', 'diydog', '299', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/299.json', 'Raspberry Popsicle Parade', 'Raspberry Berliner Weisse.', 'sour', 0.5, 8, 1.009, 1.005, 8, 20, 'raspberry popsicle parade raspberry berliner weisse. surøl maris otter torrified wheat carapils flaked oats magnum raspberry juice wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Raspberry Popsicle Parade","style":"Surøl","description":"Raspberry Berliner Weisse.\n\nA draft-only kettle-soured raspberry ale, brewed to just 0.5% ABV, using our knowledge from brewing both Blitz and Nanny State. Aromas of fresh raspberry juice, soft red berries, and a blast of lemon zest, with a juicy palate encompassing zingy acidity and the smooth velvety note of oats, rounding out this low-ABV juicebox.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":92,"fermentables":[{"id":"f1","name":"Maris Otter","type":"grain","amountKg":0.227},{"id":"f2","name":"Torrified Wheat","type":"grain","amountKg":0.227},{"id":"f3","name":"Carapils","type":"grain","amountKg":0.113},{"id":"f4","name":"Flaked Oats","type":"grain","amountKg":0.113}],"hops":[{"id":"h1","name":"Magnum","amountG":2,"use":"boil","timeMin":45}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":44}],"miscs":[{"id":"x2","name":"Raspberry Juice","amount":800,"unit":"g","use":"boil","timeMin":60}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":60,"durationMin":80}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.009,"fg":1.005,"ibu":8,"abvPct":0.5,"colorEbc":8},"notes":"Bryggetips: If you don’t need it to be low ABV, try tripling the amount of malt to get more body. Experiment with different sources for lactic acid bacteria, like unpasteurised yogurt or sour dough.\n\nFørst brygget: 2018"}', '{"id":299,"name":"Raspberry Popsicle Parade","tagline":"Raspberry Berliner Weisse.","first_brewed":"2018","description":"A draft-only kettle-soured raspberry ale, brewed to just 0.5% ABV, using our knowledge from brewing both Blitz and Nanny State. Aromas of fresh raspberry juice, soft red berries, and a blast of lemon zest, with a juicy palate encompassing zingy acidity and the smooth velvety note of oats, rounding out this low-ABV juicebox.","image":"keg.png","abv":0.5,"ibu":8,"target_fg":1005,"target_og":1009,"ebc":8,"srm":4,"ph":3.5,"attenuation_level":44,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":60,"unit":"celsius"},"duration":80}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Maris Otter","amount":{"value":0.227,"unit":"kilograms"}},{"name":"Torrified Wheat","amount":{"value":0.227,"unit":"kilograms"}},{"name":"Carapils","amount":{"value":0.113,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.113,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":2,"unit":"grams"},"add":"45","attribute":"Bittering"},{"name":"Raspberry Juice","amount":{"value":800,"unit":"grams"},"add":"Kettle","attribute":"Flavour"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Walnut and goat''s cheese salad with pomegranate dressing","Cranachan pudding","Panna cotta"],"brewers_tips":"If you don’t need it to be low ABV, try tripling the amount of malt to get more body. Experiment with different sources for lactic acid bacteria, like unpasteurised yogurt or sour dough.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-300', 'diydog', '300', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/300.json', 'Indie Pale Ale', 'True Independent Craft.', 'pale', 4.2, 30, 1.044, 1.008, 16.6, 20, 'indie pale ale true independent craft. pale ale pale ale wheat caramalt munich simcoe cascade simcoe mosaic wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Indie Pale Ale","style":"Pale ale","description":"True Independent Craft.\n\nA non-dry-hopped pale ale, using new hopping technqiues and in- depth fermentation know-how.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":65,"efficiencyPct":76,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3.12},{"id":"f2","name":"Wheat","type":"grain","amountKg":0.3},{"id":"f3","name":"Caramalt","type":"grain","amountKg":0.3},{"id":"f4","name":"Munich","type":"grain","amountKg":0.3}],"hops":[{"id":"h1","name":"Simcoe","amountG":11,"use":"boil","timeMin":65},{"id":"h2","name":"Cascade","amountG":3,"use":"boil","timeMin":10},{"id":"h3","name":"Simcoe","amountG":5,"use":"boil","timeMin":0},{"id":"h4","name":"Mosaic","amountG":28,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.044,"fg":1.008,"ibu":30,"abvPct":4.2,"colorEbc":16.6},"notes":"Bryggetips: This beer is charactised by the subtle aromas derived from yeast. Ensure you have fresh healthy yeast and good temperature control to replicate these flavours.\n\nFørst brygget: 2018"}', '{"id":300,"name":"Indie Pale Ale","tagline":"True Independent Craft.","first_brewed":"2018","description":"A non-dry-hopped pale ale, using new hopping technqiues and in- depth fermentation know-how.","image":"300.png","abv":4.2,"ibu":30,"target_fg":1008,"target_og":1044,"ebc":16.6,"srm":8,"ph":4.6,"attenuation_level":82,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3.12,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.3,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.3,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.3,"unit":"kilograms"}}],"hops":[{"name":"Simcoe","amount":{"value":11,"unit":"grams"},"add":"65","attribute":"Bittering"},{"name":"Cascade","amount":{"value":3,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Simcoe","amount":{"value":5,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":28,"unit":"grams"},"add":"0","attribute":"Aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Tempura seafood","Ham and cheese toastie","Lemon custard tart"],"brewers_tips":"This beer is charactised by the subtle aromas derived from yeast. Ensure you have fresh healthy yeast and good temperature control to replicate these flavours.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-301', 'diydog', '301', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/301.json', 'Small Batch: Dry-hopped Pilsner', 'Dry-hopped lager.', 'lager', 4.7, 37, 1.042, 1.006, 5, 20, 'small batch: dry-hopped pilsner dry-hopped lager. lager og pils pilsner carapils magnum spalter spalter saphire saphire saflager w-34/70', '{"schemaVersion":1,"name":"Small Batch: Dry-hopped Pilsner","style":"Lager og pils","description":"Dry-hopped lager.\n\nA BrewDog bar exclusive draft lager, brewed with Weihenstephan''s lager yeast, and dry-hopped with the contemporary German variety Saphir; this lager has been lightly centrifuged and packaged at just under 28 days in tank.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":81,"fermentables":[{"id":"f1","name":"Pilsner","type":"grain","amountKg":3.36},{"id":"f2","name":"Carapils","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Magnum","amountG":12,"use":"boil","timeMin":70},{"id":"h2","name":"Spalter","amountG":15,"use":"boil","timeMin":30},{"id":"h3","name":"Spalter","amountG":15,"use":"boil","timeMin":10},{"id":"h4","name":"Saphire","amountG":30,"use":"boil","timeMin":0},{"id":"h5","name":"Saphire","amountG":30,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Saflager W-34/70","form":"dry","amount":1,"unit":"pkg","attenuationPct":86}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":50}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":11}],"targets":{"og":1.042,"fg":1.006,"ibu":37,"abvPct":4.7,"colorEbc":5},"notes":"Bryggetips: Before dry hopping, if you aren''t happy with the \"green\" beer, drink it (or dump it) and make a new one to avoid wasting your premium hops on something flawed.\n\nFørst brygget: 2018"}', '{"id":301,"name":"Small Batch: Dry-hopped Pilsner","tagline":"Dry-hopped lager.","first_brewed":"2018","description":"A BrewDog bar exclusive draft lager, brewed with Weihenstephan''s lager yeast, and dry-hopped with the contemporary German variety Saphir; this lager has been lightly centrifuged and packaged at just under 28 days in tank.","image":"keg.png","abv":4.7,"ibu":37,"target_fg":1006,"target_og":1042,"ebc":5,"srm":3,"ph":4.4,"attenuation_level":86,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":50}],"fermentation":{"temp":{"value":11,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pilsner","amount":{"value":3.36,"unit":"kilograms"}},{"name":"Carapils","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":12,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"Spalter","amount":{"value":15,"unit":"grams"},"add":"30","attribute":"Flavour"},{"name":"Spalter","amount":{"value":15,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Saphire","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Saphire","amount":{"value":30,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Saflager W-34/70"},"food_pairing":["Grilled salmon tacos","Chicken and pesto pasta","Ham and mustard crisps"],"brewers_tips":"Before dry hopping, if you aren''t happy with the \"green\" beer, drink it (or dump it) and make a new one to avoid wasting your premium hops on something flawed.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-302', 'diydog', '302', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/302.json', 'Hazy Jane (Bourbon Barrel-Aged)', 'Bourbon Barrel Vermont IPA.', 'ipa', 7.2, 30, 1.065, 1.009, 15, 20, 'hazy jane (bourbon barrel-aged) bourbon barrel vermont ipa. ipa pale ale maris otter wheat flaked oats chinook chinook amarillo simcoe citra simcoe amarillo mosaic american oak wood- chip medium toast, ageing soaked in bourbon wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Hazy Jane (Bourbon Barrel-Aged)","style":"IPA","description":"Bourbon Barrel Vermont IPA.\n\nA draft-only BrewDog bar exclusive; we have experimented with ageing our Vermount IPA for a short time in bourbon and rye barrels, both known for imparting flavour quickly compared to other types of barrel.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":78,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3.96},{"id":"f2","name":"Maris Otter","type":"grain","amountKg":0.96},{"id":"f3","name":"Wheat","type":"grain","amountKg":0.6},{"id":"f4","name":"Flaked Oats","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Chinook","amountG":1,"use":"boil","timeMin":10},{"id":"h2","name":"Chinook","amountG":20,"use":"boil","timeMin":0},{"id":"h3","name":"Amarillo","amountG":20,"use":"boil","timeMin":0},{"id":"h4","name":"Simcoe","amountG":20,"use":"boil","timeMin":0},{"id":"h5","name":"Citra","amountG":50,"use":"dry_hop"},{"id":"h6","name":"Simcoe","amountG":50,"use":"dry_hop"},{"id":"h7","name":"Amarillo","amountG":50,"use":"dry_hop"},{"id":"h8","name":"Mosaic","amountG":50,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":86}],"miscs":[{"id":"x9","name":"American Oak Wood- chip medium toast, Ageing soaked in Bourbon","amount":50,"unit":"g","use":"fermentation"}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":66,"durationMin":25}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.065,"fg":1.009,"ibu":30,"abvPct":7.2,"colorEbc":15},"notes":"Bryggetips: Avoid any oxygen uptake! It will oxidise the delicate hop flavours during the ageing period. Purge your barrel/ageing vessel with CO2 and seal it airtight.\n\nFørst brygget: 2018"}', '{"id":302,"name":"Hazy Jane (Bourbon Barrel-Aged)","tagline":"Bourbon Barrel Vermont IPA.","first_brewed":"2018","description":"A draft-only BrewDog bar exclusive; we have experimented with ageing our Vermount IPA for a short time in bourbon and rye barrels, both known for imparting flavour quickly compared to other types of barrel.","image":"keg.png","abv":7.2,"ibu":30,"target_fg":1009,"target_og":1065,"ebc":15,"srm":8,"ph":4.2,"attenuation_level":86,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":66,"unit":"celsius"},"duration":25}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3.96,"unit":"kilograms"}},{"name":"Maris Otter","amount":{"value":0.96,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":1,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Chinook","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"American Oak Wood- chip medium toast, Ageing soaked in Bourbon","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Wood Ageing"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Coconut vanilla prawns","Italian style goat''s cheese pizza","Vanilla panna cotta with pomegranate"],"brewers_tips":"Avoid any oxygen uptake! It will oxidise the delicate hop flavours during the ageing period. Purge your barrel/ageing vessel with CO2 and seal it airtight.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
