INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-305', 'diydog', '305', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/305.json', 'Native Son', 'West Coast IPA.', 'ipa', 8.5, 70, 1.073, 1.01, 18, 20, 'native son west coast ipa. ipa pale ale dextrose medium crystal simcoe columbus chinook centennial simcoe citra mosaic centennial simcoe wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Native Son","style":"IPA","description":"West Coast IPA.\n\nA big, dank, double IPA, sitting in the 8-9% ABV bracket, in our Amplified range - filling a gap that has been sitting empty since Hardcore IPA departed. A new beer developed by our Head of Production Jason Pond; the first brew he came up with since joining became an instant hit.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":90,"efficiencyPct":85,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.28},{"id":"f2","name":"Dextrose","type":"sugar","amountKg":0.48},{"id":"f3","name":"Medium Crystal","type":"grain","amountKg":0.12}],"hops":[{"id":"h1","name":"Simcoe","amountG":16,"use":"boil","timeMin":90},{"id":"h2","name":"Columbus","amountG":12,"use":"boil","timeMin":90},{"id":"h3","name":"Chinook","amountG":20,"use":"boil","timeMin":30},{"id":"h4","name":"Centennial","amountG":20,"use":"boil","timeMin":0},{"id":"h5","name":"Simcoe","amountG":20,"use":"boil","timeMin":0},{"id":"h6","name":"Citra","amountG":60,"use":"dry_hop"},{"id":"h7","name":"Mosaic","amountG":60,"use":"dry_hop"},{"id":"h8","name":"Centennial","amountG":40,"use":"dry_hop"},{"id":"h9","name":"Simcoe","amountG":40,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":86}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":66,"d