INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-311', 'diydog', '311', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/311.json', 'Sonic Boom', 'New German Hop IPA.', 'ipa', 6.5, 60, 1.058, 1.008, 11, 20, 'sonic boom new german hop ipa. ipa pale ale wheat carapils columbus cascade centennial german cascade ariana huell melon german comet wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Sonic Boom","style":"IPA","description":"New German Hop IPA.\n\nWelcome aboard our experimental range of tuned IPAs. Buckle up for an explosive sensory bombardment. Tropical fruit and resinous pine are primed. The first wave of pineapple, melon and mango quickly accelerate into a afterburner of candied citrus fruit and sweet caramel. Sonic Boom - IPA turning at the speed of sound.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":90,"efficiencyPct":81,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.38},{"id":"f2","name":"Wheat","type":"grain","amountKg":0.36},{"id":"f3","name":"Carapils","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Columbus","amountG":40,"use":"boil","timeMin":90},{"id":"h2","name":"Cascade","amountG":20,"use":"boil","timeMin":30},{"id":"h3","name":"Centennial","amountG":30,"use":"boil","timeMin":0},{"id":"h4","name":"German Cascade","amountG":40,"use":"dry_hop"},{"id":"h5","name":"Ariana","amountG":40,"use":"dry_hop"},{"id":"h6","name":"Huell Melon","amountG":40,"use":"dry_hop"},{"id":"h7","name":"German Comet","amountG":60,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":86}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":55}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.058,"fg":1.008,"ibu":60,"abvPct":6.5,"colorEbc":11},"notes":"Bryggetips: This IPA features German hops in the dry hop. Why not try a Slovenian only version using: Dana, Bobek, Aurora & Cascade.\n\nFørst brygget: 2018"}', '{"id":311,"name":"Sonic Boom","tagline":"New German Hop IPA.","first_brewed":"2018","description":"Welcome aboard our experimental range of tuned IPAs. Buckle up for an explosive sensory bombardment. Tropical fruit and resinous pine are primed. The first wave of pineapple, melon and mango quickly accelerate into a afterburner of candied citrus fruit and sweet caramel. Sonic Boom - IPA turning at the speed of sound.","image":"311.png","abv":6.5,"ibu":60,"target_fg":1008,"target_og":1058,"ebc":11,"srm":6,"ph":4.6,"attenuation_level":86,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":55}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.38,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Carapils","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Columbus","amount":{"value":40,"unit":"grams"},"add":"90","attribute":"Bittering"},{"name":"Cascade","amount":{"value":20,"unit":"grams"},"add":"30","attribute":"Flavour"},{"name":"Centennial","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"German Cascade","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Ariana","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Huell Melon","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"German Comet","amount":{"value":60,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Spicy Thai peanut satay","Pizza with chili flakes","Lemon tart"],"brewers_tips":"This IPA features German hops in the dry hop. Why not try a Slovenian only version using: Dana, Bobek, Aurora & Cascade.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-312', 'diydog', '312', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/312.json', 'Dog G', '11th Anniversary Imperial Stout.', 'stout', 17, 100, 1.125, 1.015, 500, 20, 'dog g 11th anniversary imperial stout. stout og porter pale ale brown rye dark crystal flaked oats wheat carafa special malt type 1 carafa special malt type 3 chinook sorachi ace ginger powder cold infused coffee honey habanero lemon drop chili wyeast 1272 - american ale ii™', '{"schemaVersion":1,"name":"Dog G","style":"Stout og porter","description":"11th Anniversary Imperial Stout.\n\nDog G is a benchmark in liquid form; our 11th anniversary beer. A 17% imperial stout brewed with a compelling mix of dark malts, chillies, cacao and coffee - to make it a true milestone we then decided to age Dog G in rye whiskey barrels.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":72,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":7.5},{"id":"f2","name":"Brown","type":"grain","amountKg":0.75},{"id":"f3","name":"Rye","type":"grain","amountKg":0.75},{"id":"f4","name":"Dark Crystal","type":"grain","amountKg":0.75},{"id":"f5","name":"Flaked Oats","type":"grain","amountKg":0.75},{"id":"f6","name":"Wheat","type":"grain","amountKg":0.5},{"id":"f7","name":"Carafa Special Malt Type 1","type":"grain","amountKg":0.5},{"id":"f8","name":"Carafa Special Malt Type 3","type":"grain","amountKg":0.5}],"hops":[{"id":"h1","name":"Chinook","amountG":25,"use":"boil","timeMin":60},{"id":"h2","name":"Sorachi Ace","amountG":50,"use":"boil","timeMin":60}],"cultures":[{"id":"y1","name":"Wyeast 1272 - American Ale II™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":84}],"miscs":[{"id":"x3","name":"Ginger Powder","amount":1.3,"unit":"g","use":"boil","timeMin":0},{"id":"x4","name":"Cold infused coffee","amount":25,"unit":"g","use":"boil","timeMin":0},{"id":"x5","name":"Honey","amount":1250,"unit":"g","use":"boil","timeMin":0},{"id":"x6","name":"Habanero","amount":5,"unit":"g","use":"fermentation"},{"id":"x7","name":"Lemon drop chili","amount":3,"unit":"g","use":"fermentation"}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":63,"durationMin":90}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.125,"fg":1.015,"ibu":100,"abvPct":17,"colorEbc":500},"notes":"Bryggetips: Age this beer!!! Often it will pick up new incredible flavours after an extended cellaring. Think 2 years plus.\n\nFørst brygget: 2018"}', '{"id":312,"name":"Dog G","tagline":"11th Anniversary Imperial Stout.","first_brewed":"2018","description":"Dog G is a benchmark in liquid form; our 11th anniversary beer. A 17% imperial stout brewed with a compelling mix of dark malts, chillies, cacao and coffee - to make it a true milestone we then decided to age Dog G in rye whiskey barrels.","image":"312.png","abv":17,"ibu":100,"target_fg":1015,"target_og":1125,"ebc":500,"srm":254,"ph":4.4,"attenuation_level":84,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":63,"unit":"celsius"},"duration":90}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":7.5,"unit":"kilograms"}},{"name":"Brown","amount":{"value":0.75,"unit":"kilograms"}},{"name":"Rye","amount":{"value":0.75,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.75,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.75,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 1","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":0.5,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":25,"unit":"grams"},"add":"Start","attribute":"Bittering"},{"name":"Sorachi Ace","amount":{"value":50,"unit":"grams"},"add":"Start","attribute":"Bittering"},{"name":"Ginger Powder","amount":{"value":1.25,"unit":"grams"},"add":"End","attribute":"Flavour"},{"name":"Cold infused coffee","amount":{"value":25,"unit":"grams"},"add":"End","attribute":"Flavour"},{"name":"Honey","amount":{"value":1250,"unit":"grams"},"add":"End","attribute":"Flavour"},{"name":"Habanero","amount":{"value":5,"unit":"grams"},"add":"Dry Hop","attribute":"Flavour"},{"name":"Lemon drop chili","amount":{"value":3,"unit":"grams"},"add":"Dry Hop","attribute":"Flavour"}],"yeast":"Wyeast 1272 - American Ale II™"},"food_pairing":["Ginger and chocolate biscuits","Spicy chorizo and prawn Jambalaya","Jamaican Curry Goat"],"brewers_tips":"Age this beer!!! Often it will pick up new incredible flavours after an extended cellaring. Think 2 years plus.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","OG/FG i kilden gir 14.4 % ABV, men oppgitt ABV er 17 % — sjekk tallene."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-313', 'diydog', '313', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/313.json', 'Mallow Mafia', 'Russian Imperial Stout.', 'stout', 12, 75, 1.116, 1.025, 390, 20, 'mallow mafia russian imperial stout. stout og porter pilsner chocolate munich wheat brown black malt extra dark crystal flaked oats oat husks cascade cascade demerara sugar marshmallows ground coffee cocoa nibs wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Mallow Mafia","style":"Stout og porter","description":"Russian Imperial Stout.\n\nBrewDog vs Amundsen. One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. With Norwegian craft brewers Amundsen, we are creating a mash-up of two existing beers, resulting in a coffee, chocolate and marshmallow Russian Imperial Stout.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":72,"fermentables":[{"id":"f1","name":"Pilsner","type":"grain","amountKg":5.88},{"id":"f2","name":"Chocolate","type":"grain","amountKg":1.68},{"id":"f3","name":"Munich","type":"grain","amountKg":0.96},{"id":"f4","name":"Wheat","type":"grain","amountKg":0.96},{"id":"f5","name":"Brown","type":"grain","amountKg":0.6},{"id":"f6","name":"Black Malt","type":"grain","amountKg":0.48},{"id":"f7","name":"Extra Dark Crystal","type":"grain","amountKg":0.24},{"id":"f8","name":"Flaked Oats","type":"grain","amountKg":0.24},{"id":"f9","name":"Oat Husks","type":"grain","amountKg":0.048}],"hops":[{"id":"h1","name":"Cascade","amountG":30,"use":"boil","timeMin":70},{"id":"h2","name":"Cascade","amountG":30,"use":"boil","timeMin":10}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":78}],"miscs":[{"id":"x3","name":"Demerara Sugar","amount":750,"unit":"g","use":"boil","timeMin":70},{"id":"x4","name":"Marshmallows","amount":40,"unit":"g","use":"boil","timeMin":70},{"id":"x5","name":"Ground Coffee","amount":10,"unit":"g","use":"fermentation"},{"id":"x6","name":"Cocoa Nibs","amount":10,"unit":"g","use":"fermentation"}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":135}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.116,"fg":1.025,"ibu":75,"abvPct":12,"colorEbc":390},"notes":"Bryggetips: If your mash run off takes a long time, increase the temperature of your sparge water to keep the mash bed warm and permeable.\n\nFørst brygget: 2018"}', '{"id":313,"name":"Mallow Mafia","tagline":"Russian Imperial Stout.","first_brewed":"2018","description":"BrewDog vs Amundsen. One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. With Norwegian craft brewers Amundsen, we are creating a mash-up of two existing beers, resulting in a coffee, chocolate and marshmallow Russian Imperial Stout.","image":"313.png","abv":12,"ibu":75,"target_fg":1025,"target_og":1116,"ebc":390,"srm":198,"ph":4.4,"attenuation_level":78,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":135}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pilsner","amount":{"value":5.88,"unit":"kilograms"}},{"name":"Chocolate","amount":{"value":1.68,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.96,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":0.96,"unit":"kilograms"}},{"name":"Brown","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Black Malt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Extra Dark Crystal","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Oat Husks","amount":{"value":0.048,"unit":"kilograms"}}],"hops":[{"name":"Cascade","amount":{"value":30,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"Cascade","amount":{"value":30,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Demerara Sugar","amount":{"value":750,"unit":"grams"},"add":"Kettle","attribute":"Flavour"},{"name":"Marshmallows","amount":{"value":40,"unit":"grams"},"add":"Kettle","attribute":"Flavour"},{"name":"Ground Coffee","amount":{"value":10,"unit":"grams"},"add":"Dry Hop","attribute":"Flavour"},{"name":"Cocoa Nibs","amount":{"value":10,"unit":"grams"},"add":"Dry Hop","attribute":"Flavour"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Affogato with ice cream","Chocolate cake"],"brewers_tips":"If your mash run off takes a long time, increase the temperature of your sparge water to keep the mash bed warm and permeable.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-314', 'diydog', '314', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/314.json', 'Manic Mango', 'Mango IPA.', 'ipa', 6, 20, 1.057, 1.01, 12, 20, 'manic mango mango ipa. ipa pale ale uncrushed wheat flaked oats magnum citra amarillo nelson sauvin citra idaho 7 nelson sauvin citra mango puree wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Manic Mango","style":"IPA","description":"Mango IPA.\n\nBrewDog v Brewski. One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. Our Swedish collaboration with Brewski is a mango IPA.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":65,"efficiencyPct":76,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3.96},{"id":"f2","name":"Uncrushed Wheat","type":"grain","amountKg":0.6},{"id":"f3","name":"Flaked Oats","type":"grain","amountKg":0.6}],"hops":[{"id":"h1","name":"Magnum","amountG":2,"use":"boil","timeMin":65},{"id":"h2","name":"Citra","amountG":20,"use":"boil","timeMin":10},{"id":"h3","name":"Amarillo","amountG":40,"use":"boil","timeMin":0},{"id":"h4","name":"Nelson Sauvin","amountG":40,"use":"boil","timeMin":0},{"id":"h5","name":"Citra","amountG":40,"use":"boil","timeMin":0},{"id":"h6","name":"Idaho 7","amountG":60,"use":"dry_hop"},{"id":"h7","name":"Nelson Sauvin","amountG":80,"use":"dry_hop"},{"id":"h8","name":"Citra","amountG":60,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82}],"miscs":[{"id":"x9","name":"Mango Puree","amount":1000,"unit":"g","use":"fermentation"}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":63,"durationMin":35}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.057,"fg":1.01,"ibu":20,"abvPct":6,"colorEbc":12},"notes":"Bryggetips: Add the mango puree towards the end of primary fermentation, about 10 SG points above your FG. Allow it to reach FG and have a diacetyl rest before dry hopping it.\n\nFørst brygget: 2018"}', '{"id":314,"name":"Manic Mango","tagline":"Mango IPA.","first_brewed":"2018","description":"BrewDog v Brewski. One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. Our Swedish collaboration with Brewski is a mango IPA.","image":"314.png","abv":6,"ibu":20,"target_fg":1010,"target_og":1057,"ebc":12,"srm":6,"ph":4.4,"attenuation_level":82,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":63,"unit":"celsius"},"duration":35}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3.96,"unit":"kilograms"}},{"name":"Uncrushed Wheat","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.6,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":2,"unit":"grams"},"add":"65","attribute":"Bittering"},{"name":"Citra","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Amarillo","amount":{"value":40,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Nelson Sauvin","amount":{"value":40,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":40,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Idaho 7","amount":{"value":60,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Nelson Sauvin","amount":{"value":80,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Citra","amount":{"value":60,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mango Puree","amount":{"value":1000,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Green Thai curry","Salmon with mango salsa","Pho soup with light rice noodles"],"brewers_tips":"Add the mango puree towards the end of primary fermentation, about 10 SG points above your FG. Allow it to reach FG and have a diacetyl rest before dry hopping it.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-315', 'diydog', '315', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/315.json', 'Baltic Fleet', 'Baltic Porter.', 'stout', 7.2, 45, 1.071, 1.016, 120, 20, 'baltic fleet baltic porter. stout og porter pale ale munich type 1 light double roasted crystal chocolate wheat medium crystal carafa special malt type 3 magnum amarillo saphire plum concentrate wyeast 2126 - bohemian lager™', '{"schemaVersion":1,"name":"Baltic Fleet","style":"Stout og porter","description":"Baltic Porter.\n\nBrewDog vs Bevog. One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. Our Austrian collaboration is with Bevog, and incorporates plum into a Baltic porter.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":81,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.32},{"id":"f2","name":"Munich Type 1 Light","type":"grain","amountKg":0.6},{"id":"f3","name":"Double Roasted Crystal","type":"grain","amountKg":0.42},{"id":"f4","name":"Chocolate Wheat","type":"grain","amountKg":0.3},{"id":"f5","name":"Medium Crystal","type":"grain","amountKg":0.24},{"id":"f6","name":"Carafa Special Malt Type 3","type":"grain","amountKg":0.18}],"hops":[{"id":"h1","name":"Magnum","amountG":12,"use":"boil","timeMin":70},{"id":"h2","name":"Amarillo","amountG":8,"use":"boil","timeMin":15},{"id":"h3","name":"Saphire","amountG":6,"use":"boil","timeMin":15}],"cultures":[{"id":"y1","name":"Wyeast 2126 - Bohemian Lager™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":77}],"miscs":[{"id":"x4","name":"Plum Concentrate","amount":400,"unit":"g","use":"boil","timeMin":0}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":66,"durationMin":45}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":12}],"targets":{"og":1.071,"fg":1.016,"ibu":45,"abvPct":7.2,"colorEbc":120},"notes":"Bryggetips: Double Roasted Crystal is used when the astringency and bitterness inherent to roast malts is not desired. This means that it can be used at a higher rate in the grist to add complex caramel and dried fruit notes with a beautiful red-brown hue.\n\nFørst brygget: 2018"}', '{"id":315,"name":"Baltic Fleet","tagline":"Baltic Porter.","first_brewed":"2018","description":"BrewDog vs Bevog. One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. Our Austrian collaboration is with Bevog, and incorporates plum into a Baltic porter.","image":"315.png","abv":7.2,"ibu":45,"target_fg":1016,"target_og":1071,"ebc":120,"srm":61,"ph":4.2,"attenuation_level":77,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":66,"unit":"celsius"},"duration":45}],"fermentation":{"temp":{"value":12,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.32,"unit":"kilograms"}},{"name":"Munich Type 1 Light","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Double Roasted Crystal","amount":{"value":0.42,"unit":"kilograms"}},{"name":"Chocolate Wheat","amount":{"value":0.3,"unit":"kilograms"}},{"name":"Medium Crystal","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Carafa Special Malt Type 3","amount":{"value":0.18,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":12,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"Amarillo","amount":{"value":8,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"Saphire","amount":{"value":6,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"Plum Concentrate","amount":{"value":400,"unit":"grams"},"add":"Flame Out","attribute":"Flavour"}],"yeast":"Wyeast 2126 - Bohemian Lager™"},"food_pairing":["Chilli covered burgers","Roasted garlic Camembert","Chocolate and walnut brownies"],"brewers_tips":"Double Roasted Crystal is used when the astringency and bitterness inherent to roast malts is not desired. This means that it can be used at a higher rate in the grist to add complex caramel and dried fruit notes with a beautiful red-brown hue.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-316', 'diydog', '316', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/316.json', 'SOS! (May Day!)', 'Dry-Hopped Maibock.', 'lager', 6.4, 34, 1.06, 1.014, 21, 20, 'sos! (may day!) dry-hopped maibock. lager og pils pilsner munich type 1 light carapils acidulated malt magnum hallertauer mittelfrüh hallertauer mittelfrüh hallertauer mittelfrüh mandarina bavaria motueka hallertauer mittelfrüh mandarina bavaria motueka wyeast 2126 - bohemian lager™', '{"schemaVersion":1,"name":"SOS! (May Day!)","style":"Lager og pils","description":"Dry-Hopped Maibock.\n\nBrewDog vs Brlo. One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. Our German collaboration is with BRLO, and the beer is a dry- hopped Maibock; a new world take on a strong pale lager.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":79,"fermentables":[{"id":"f1","name":"Pilsner","type":"grain","amountKg":4.2},{"id":"f2","name":"Munich Type 1 Light","type":"grain","amountKg":0.96},{"id":"f3","name":"Carapils","type":"grain","amountKg":0.06},{"id":"f4","name":"Acidulated Malt","type":"grain","amountKg":0.06}],"hops":[{"id":"h1","name":"Magnum","amountG":4,"use":"boil","timeMin":70},{"id":"h2","name":"Hallertauer Mittelfrüh","amountG":10,"use":"boil","timeMin":10},{"id":"h3","name":"Hallertauer Mittelfrüh","amountG":20,"use":"boil","timeMin":0},{"id":"h4","name":"Hallertauer Mittelfrüh","amountG":20,"use":"boil","timeMin":0},{"id":"h5","name":"Mandarina Bavaria","amountG":40,"use":"boil","timeMin":0},{"id":"h6","name":"Motueka","amountG":20,"use":"boil","timeMin":0},{"id":"h7","name":"Hallertauer Mittelfrüh","amountG":20,"use":"dry_hop"},{"id":"h8","name":"Mandarina Bavaria","amountG":30,"use":"dry_hop"},{"id":"h9","name":"Motueka","amountG":20,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 2126 - Bohemian Lager™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":77}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":10}],"targets":{"og":1.06,"fg":1.014,"ibu":34,"abvPct":6.4,"colorEbc":21},"notes":"Bryggetips: Traditional German brewing is awesome and deserving of respect. If you brew this during spring time, call it a Maibock, any other time of the year and it should be called an Helles Bock.\n\nFørst brygget: 2018"}', '{"id":316,"name":"SOS! (May Day!)","tagline":"Dry-Hopped Maibock.","first_brewed":"2018","description":"BrewDog vs Brlo. One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. Our German collaboration is with BRLO, and the beer is a dry- hopped Maibock; a new world take on a strong pale lager.","image":"316.png","abv":6.4,"ibu":34,"target_fg":1014,"target_og":1060,"ebc":21,"srm":11,"ph":4.2,"attenuation_level":77,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":60}],"fermentation":{"temp":{"value":10,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pilsner","amount":{"value":4.2,"unit":"kilograms"}},{"name":"Munich Type 1 Light","amount":{"value":0.96,"unit":"kilograms"}},{"name":"Carapils","amount":{"value":0.06,"unit":"kilograms"}},{"name":"Acidulated Malt","amount":{"value":0.06,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":4,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"Hallertauer Mittelfrüh","amount":{"value":10,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Hallertauer Mittelfrüh","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Hallertauer Mittelfrüh","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Mandarina Bavaria","amount":{"value":40,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Motueka","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Hallertauer Mittelfrüh","amount":{"value":20,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mandarina Bavaria","amount":{"value":30,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Motueka","amount":{"value":20,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 2126 - Bohemian Lager™"},"food_pairing":["Honey ham sandwich Gruyère cheese","Steamed mussels","Carrot cake"],"brewers_tips":"Traditional German brewing is awesome and deserving of respect. If you brew this during spring time, call it a Maibock, any other time of the year and it should be called an Helles Bock.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-317', 'diydog', '317', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/317.json', 'Al Adjore!', 'Barley Wine', 'strong', 9, 65, 1.085, 1.018, 35, 20, 'al adjore! barley wine sterkt øl pale ale caramalt light crystal medium crystal sweet orange peel magnum mandarina bavaria hallertauer blanc french oak chips medium toast wyeast 1056 - american ale™', '{"schemaVersion":1,"name":"Al Adjore!","style":"Sterkt øl","description":"Barley Wine\n\nBrewDog vs La Pirata. One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. Our collab with Spanish brewes La Pirata features a barley wine, inspired by Muscatel.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":74,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":7.08},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.48},{"id":"f3","name":"Light Crystal","type":"grain","amountKg":0.24},{"id":"f4","name":"Medium Crystal","type":"grain","amountKg":0.12}],"hops":[{"id":"h1","name":"Magnum","amountG":6,"use":"boil","timeMin":70},{"id":"h2","name":"Mandarina Bavaria","amountG":20,"use":"boil","timeMin":10},{"id":"h3","name":"Hallertauer Blanc","amountG":20,"use":"boil","timeMin":10}],"cultures":[{"id":"y1","name":"Wyeast 1056 - American Ale™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79}],"miscs":[{"id":"m5","name":"Sweet Orange Peel","amount":20,"unit":"g","use":"boil","timeMin":10},{"id":"x4","name":"French Oak Chips Medium Toast","amount":40,"unit":"g","use":"fermentation","notes":"Fatlagring / treflis"}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":35}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.085,"fg":1.018,"ibu":65,"abvPct":9,"colorEbc":35},"notes":"Bryggetips: Sanitise the oak chips before adding them to the fermenter. Vodka is ideal as it’s a neutral spirit and can be drained off. If you don’t want to affect the ABV, try steaming them.\n\nFørst brygget: 2018"}', '{"id":317,"name":"Al Adjore!","tagline":"Barley Wine","first_brewed":"2018","description":"BrewDog vs La Pirata. One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. Our collab with Spanish brewes La Pirata features a barley wine, inspired by Muscatel.","image":"317.png","abv":9,"ibu":65,"target_fg":1018,"target_og":1085,"ebc":35,"srm":18,"ph":79,"attenuation_level":79,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":35}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":7.08,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Light Crystal","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Medium Crystal","amount":{"value":0.12,"unit":"kilograms"}},{"name":"Sweet Orange Peel","amount":{"value":20,"unit":"grams"}}],"hops":[{"name":"Magnum","amount":{"value":6,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"Mandarina Bavaria","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Hallertauer Blanc","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"French Oak Chips Medium Toast","amount":{"value":40,"unit":"grams"},"add":"Wood Ageing","attribute":"Flavour"}],"yeast":"Wyeast 1056 - American Ale™"},"food_pairing":["Stilton and walnut salad","Toffee caramel cheesecake"],"brewers_tips":"Sanitise the oak chips before adding them to the fermenter. Vodka is ideal as it’s a neutral spirit and can be drained off. If you don’t want to affect the ABV, try steaming them.","contributed_by":"John Jenkman <johnjenkman>"}', '["«Sweet Orange Peel» sto under malt; lagt inn som tilsetning i kok (10 min) — tidspunkt er antatt.","Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-318', 'diydog', '318', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/318.json', 'Neverland', 'India Pale Lager.', 'ipa', 5, 40, 1.048, 1.007, 12, 20, 'neverland india pale lager. ipa pilsner carapils vienna acidulated malt magnum citra centennial citra centennial citra centennial nelson sauvin wyeast 2126 - bohemian lager™', '{"schemaVersion":1,"name":"Neverland","style":"IPA","description":"India Pale Lager.\n\nBrewDog vs Oedipus. One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. This India pale lager has been brewed with Dutch brewers Oedipus.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":78,"fermentables":[{"id":"f1","name":"Pilsner","type":"grain","amountKg":3.6},{"id":"f2","name":"Carapils","type":"grain","amountKg":0.36},{"id":"f3","name":"Vienna","type":"grain","amountKg":0.24},{"id":"f4","name":"Acidulated Malt","type":"grain","amountKg":0.06}],"hops":[{"id":"h1","name":"Magnum","amountG":2,"use":"boil","timeMin":70},{"id":"h2","name":"Citra","amountG":10,"use":"boil","timeMin":10},{"id":"h3","name":"Centennial","amountG":10,"use":"boil","timeMin":10},{"id":"h4","name":"Citra","amountG":15,"use":"boil","timeMin":0},{"id":"h5","name":"Centennial","amountG":15,"use":"boil","timeMin":0},{"id":"h6","name":"Citra","amountG":10,"use":"dry_hop"},{"id":"h7","name":"Centennial","amountG":10,"use":"dry_hop"},{"id":"h8","name":"Nelson Sauvin","amountG":10,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 2126 - Bohemian Lager™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":85}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":35}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":11}],"targets":{"og":1.048,"fg":1.007,"ibu":40,"abvPct":5,"colorEbc":12},"notes":"Bryggetips: Acidulated malt was first produced to circumvent the Reinheitsgebot in Germany where they could not acidify their brewing water. A weak organic acid such as lactic acid can be used in its place.\n\nFørst brygget: 2018"}', '{"id":318,"name":"Neverland","tagline":"India Pale Lager.","first_brewed":"2018","description":"BrewDog vs Oedipus. One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. This India pale lager has been brewed with Dutch brewers Oedipus.","image":"318.png","abv":5,"ibu":40,"target_fg":1007,"target_og":1048,"ebc":12,"srm":6,"ph":4.2,"attenuation_level":85,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":35}],"fermentation":{"temp":{"value":11,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pilsner","amount":{"value":3.6,"unit":"kilograms"}},{"name":"Carapils","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Vienna","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Acidulated Malt","amount":{"value":0.06,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":2,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"Citra","amount":{"value":10,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Centennial","amount":{"value":10,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Citra","amount":{"value":15,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Centennial","amount":{"value":15,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":10,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Centennial","amount":{"value":10,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Nelson Sauvin","amount":{"value":10,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 2126 - Bohemian Lager™"},"food_pairing":["Roast Chicken","Spicy jalapeño and seared steak fajitas","Peach cobbler"],"brewers_tips":"Acidulated malt was first produced to circumvent the Reinheitsgebot in Germany where they could not acidify their brewing water. A weak organic acid such as lactic acid can be used in its place.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-319', 'diydog', '319', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/319.json', 'Grano Giusto', 'Dark Lager.', 'lager', 5.5, 28, 1.052, 1.009, 55, 20, 'grano giusto dark lager. lager og pils pilsner munich type 1 light grano dei miracoli brown chocolate wheat magnum east kent golding fuggles east kent golding fuggles wyeast 2126 - bohemian lager™', '{"schemaVersion":1,"name":"Grano Giusto","style":"Lager og pils","description":"Dark Lager.\n\nBrewDog vs Birrificiano Italiano. One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. Our Italian collaboration is with Birrificiano Italiano, and the beer is a dark lager brewed with a unique dark malt from an Italian micro-maltster.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":72,"fermentables":[{"id":"f1","name":"Pilsner","type":"grain","amountKg":3.48},{"id":"f2","name":"Munich Type 1 Light","type":"grain","amountKg":0.96},{"id":"f3","name":"Grano Dei Miracoli","type":"grain","amountKg":0.24},{"id":"f4","name":"Brown","type":"grain","amountKg":0.18},{"id":"f5","name":"Chocolate Wheat","type":"grain","amountKg":0.12}],"hops":[{"id":"h1","name":"Magnum","amountG":6,"use":"boil","timeMin":70},{"id":"h2","name":"East Kent Golding","amountG":10,"use":"boil","timeMin":15},{"id":"h3","name":"Fuggles","amountG":10,"use":"boil","timeMin":15},{"id":"h4","name":"East Kent Golding","amountG":24,"use":"boil","timeMin":0},{"id":"h5","name":"Fuggles","amountG":24,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 2126 - Bohemian Lager™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":63,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":12}],"targets":{"og":1.052,"fg":1.009,"ibu":28,"abvPct":5.5,"colorEbc":55},"notes":"Bryggetips: Grano dei Miracoli is a unique ancient grain and shouldn''t be substituted, this beer is focused on what this ingredient offers when paired with modern malts.\n\nFørst brygget: 2018"}', '{"id":319,"name":"Grano Giusto","tagline":"Dark Lager.","first_brewed":"2018","description":"BrewDog vs Birrificiano Italiano. One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. Our Italian collaboration is with Birrificiano Italiano, and the beer is a dark lager brewed with a unique dark malt from an Italian micro-maltster.","image":"319.png","abv":5.5,"ibu":28,"target_fg":1009,"target_og":1052,"ebc":55,"srm":28,"ph":4.3,"attenuation_level":83,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":63,"unit":"celsius"},"duration":60}],"fermentation":{"temp":{"value":12,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pilsner","amount":{"value":3.48,"unit":"kilograms"}},{"name":"Munich Type 1 Light","amount":{"value":0.96,"unit":"kilograms"}},{"name":"Grano Dei Miracoli","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Brown","amount":{"value":0.18,"unit":"kilograms"}},{"name":"Chocolate Wheat","amount":{"value":0.12,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":6,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"East Kent Golding","amount":{"value":10,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"Fuggles","amount":{"value":10,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"East Kent Golding","amount":{"value":24,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Fuggles","amount":{"value":24,"unit":"grams"},"add":"0","attribute":"Aroma"}],"yeast":"Wyeast 2126 - Bohemian Lager™"},"food_pairing":["BBQ hot wings","Pomegran