INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-323', 'diydog', '323', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/323.json', 'Interstate Vienna Lager.', 'Vienna Lager.', 'lager', 5, 25, 1.045, 1.007, 14, 20, 'interstate vienna lager. vienna lager. lager og pils pilsner vienna munich carahell carared perle hallertauer mittelfrüh mandarina bavaria wyeast 2126 - bohemian lager™', '{"schemaVersion":1,"name":"Interstate Vienna Lager.","style":"Lager og pils","description":"Vienna Lager.\n\nA new 5% ABV Vienna Lager, that features in Fanzine, our new subscription model.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":65,"efficiencyPct":76,"fermentables":[{"id":"f1","name":"Pilsner","type":"grain","amountKg":1.56},{"id":"f2","name":"Vienna","type":"grain","amountKg":1.56},{"id":"f3","name":"Munich","type":"grain","amountKg":0.6},{"id":"f4","name":"Carahell","type":"grain","amountKg":0.18},{"id":"f5","name":"Carared","type":"grain","amountKg":0.18}],"hops":[{"id":"h1","name":"Perle","amountG":5,"use":"boil","timeMin":65},{"id":"h2","name":"Hallertauer Mittelfrüh","amountG":20,"use":"boil","timeMin":10},{"id":"h3","name":"Mandarina Bavaria","amountG":20,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 2126 - Bohemian Lager™","form":"liquid","amount":1,"unit":"pkg","attenuationPct":84}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":67,"durationMin":70}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":10}],"targets":{"og":1.045,"fg":1.007,"ibu":25,"abvPct":5,"colorEbc":14},"notes":"Bryggetips: Instead of using Pilsner, try to substitute this out for more Vienna malt. This is more traditional but you should calculate your diastatic power for your new mash. Ideally it should be a minimum of 30 to 50 Lintner.\n\nFørst brygget: 2018"}', '{"id":323,"name":"Interstate Vienna Lager.","tagline":"Vienna Lager.","first_brewed":"2018","description":"A new 5% ABV Vienna Lager, that features in Fanzine, our new subscription model.","image":"323.png","abv":5,"ibu":25,"target_fg":1007,"target_og":1045,"ebc":14,"srm":7,"ph":4.2,"attenuation_level":84,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":67,"unit":"celsius"},"duration":70}],"fermentation":{"temp":{"value":10,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pilsner","amount":{"value":1.56,"unit":"kilograms"}},{"name":"Vienna","amount":{"value":1.56,"unit":"kilograms"}},{"name":"Munich","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Carahell","amount":{"value":0.18,"unit":"kilograms"}},{"name":"Carared","amount":{"value":0.18,"unit":"kilograms"}}],"hops":[{"name":"Perle","amount":{"value":5,"unit":"grams"},"add":"65","attribute":"Bittering"},{"name":"Hallertauer Mittelfrüh","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Aroma"},{"name":"Mandarina Bavaria","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"}],"yeast":"Wyeast 2126 - Bohemian Lager™"},"food_pairing":["Grilled chicken and steamed vegetables","Pork sausages","Almond biscotti"],"brewers_tips":"Instead of using Pilsner, try to substitute this out for more Vienna malt. This is more traditional but you should calculate your diastatic power for your new mash. Ideally it should be a minimum of 30 to 50 Lintner.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
