ume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":50,"unit":"celsius"},"duration":50}],"fermentation":{"temp":{"value":11,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pilsner","amount":{"value":3.54,"unit":"kilograms"}},{"name":"Carapils","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":12,"unit":"grams"},"add":"70","attribute":"Bittering"},{"name":"Spalter","amount":{"value":15,"unit":"grams"},"add":"30","attribute":"Flavour"},{"name":"Spalter","amount":{"value":15,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Saphire","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Saphire","amount":{"value":30,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Saflager W-34/70"},"food_pairing":["Goat''s cheese salad","Pesto pasta","Lemon cookies"],"brewers_tips":"Saphir hops are not widespread at the moment if you cannot get hold of any, a good batch of Mittlefruh is a fair substitute.","contributed_by":"John Jenkman <johnjenkman>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-326', 'diydog', '326', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/326.json', 'The Emperors Blue Clothes (BD vs People Like Us)', 'Unfiltered Blueberry Hefeweizen.', 'wheat', 5, 16, 1.05, 1.01, 35, 20, 'the emperors blue clothes (bd vs people like us) unfiltered blueberry hefeweizen. hvete pilsner malt wheat malt extra dark crystal malt weyermann carapils weyermann carafa special type 1 mandarina bavaria mandarina bavaria wb-06', '{"schemaVersion":1,"name":"The Emperors Blue Clothes (BD vs People Like Us)","style":"Hvete","description":"Unfiltered Blueberry Hefeweizen.\n\nBrewed in collaboration with People Like Us, this wheat beer sits just between a weissbier and a dunkelweisse, and is loaded with blueberry juice.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":77,"fermentables":[{"id":"f1","name":"Pilsner Malt","type":"grain","amountKg":1.8},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":2.4},{"id":"f3","name":"Extra Dark Crystal Malt","type":"grain","amountKg":0.12},{"id":"f4","name":"Weyermann Carapils","type":"grain","amountKg":0.12},{"id":"f5","name":"Weyermann Carafa Special Type 1","type":"grain","amountKg":0.036}],"hops":[{"id":"h1","name":"Mandarina Bavaria","amountG":6,"use":"boil","timeMin":60},{"id":"h2","name":"Mandarina Bavaria","amountG":8,"use":"whirlpool"}],"cultures":[{"id":"y1","name":"WB-06","form":"other","amount":1,"unit":"pkg","attenuationPct":79}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":30}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.05,"fg":1.01,"ibu":16,"abvPct":5,"colorEbc":35},"notes":"Bryggetips: Adding juices adds both sweetness and acidity to your beer - although these beers have been designed to have the right balance, play around with the quantity of the juice to add different levels of acidity and flavour of your beer.\n\nTwist: Blueberry Juice: 3.6kg\n\nFørst brygget: 2018"}', '{"id":326,"name":"The Emperors Blue Clothes (BD vs People Like Us)","tagline":"Unfiltered Blueberry Hefeweizen.","first_brewed":"2018","description":"Brewed in collaboration with People Like Us, this wheat beer sits just between a weissbier and a dunkelweisse, and is loaded with blueberry juice.","image":"keg.png","abv":5,"ibu":16,"target_fg":1010,"target_og":1050,"ebc":35,"srm":18,"ph":4.4,"attenuation_level":79,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":30}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Blueberry Juice: 3.6kg"},"ingredients":{"malt":[{"name":"Pilsner Malt","amount":{"value":1.8,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":2.4,"unit":"kilograms"}},{"name":"Extra Dark Crystal Malt","amount":{"value":0.12,"unit":"kilograms"}},{"name":"Weyermann Carapils","amount":{"value":0.12,"unit":"kilograms"}},{"name":"Weyermann Carafa Special Type 1","amount":{"value":0.036,"unit":"kilograms"}}],"hops":[{"name":"Mandarina Bavaria","amount":{"value":6,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Mandarina Bavaria","amount":{"value":8,"unit":"grams"},"add":"Whirlpool","attribute":"Aroma"}],"yeast":"WB-06"},"food_pairing":["German Pretzels","French Toast with Mixed Berries","Blueberry Muffins"],"brewers_tips":"Adding juices adds both sweetness and acidity to your beer - although these beers have been designed to have the right balance, play around with the quantity of the juice to add different levels of acidity and flavour of your beer.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-327', 'diydog', '327', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/327.json', 'Zephyr Citrus Tart (Fanzine)', 'Zephyr Sour Ale.', 'sour', 4.6, 10, 1.044, 1.008, 10, 20, 'zephyr citrus tart (fanzine) zephyr sour ale. surøl pale ale wheat malt perle wyeast 1272', '{"schemaVersion":1,"name":"Zephyr Citrus Tart (Fanzine)","style":"Surøl","description":"Zephyr Sour Ale.\n\nA new 4.6% ABV tart pale ale. Zephyr is one of the core Fanzine beers, and will feature evolving editions as part of our new subscription model.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":82,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":2.52},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":1.2}],"hops":[{"id":"h1","name":"Perle","amountG":8,"use":"boil","timeMin":60}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":53,"durationMin":50}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.044,"fg":1.008,"ibu":10,"abvPct":4.6,"colorEbc":10},"notes":"Bryggetips: Lactic acid, malic acid and citric acid all give different perception of acidity and flavour at the same concentration. Play around with them in water to understand their interaction and optimise your own recipe.\n\nTwist: Lactic Acid: 48g, Malic Acid: 5g, Citric Acid Powder: 44g\n\nFørst brygget: 2018"}', '{"id":327,"name":"Zephyr Citrus Tart (Fanzine)","tagline":"Zephyr Sour Ale.","first_brewed":"2018","description":"A new 4.6% ABV tart pale ale. Zephyr is one of the core Fanzine beers, and will feature evolving editions as part of our new subscription model.","image":"327.png","abv":4.6,"ibu":10,"target_fg":1008,"target_og":1044,"ebc":10,"srm":5,"ph":3.3,"attenuation_level":82,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":53,"unit":"celsius"},"duration":50}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Lactic Acid: 48g, Malic Acid: 5g, Citric Acid Powder: 44g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":2.52,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":1.2,"unit":"kilograms"}}],"hops":[{"name":"Perle","amount":{"value":8,"unit":"grams"},"add":"60","attribute":"Bitter"}],"yeast":"Wyeast 1272"},"food_pairing":["Green Papaya Salad","Seared Monkfish","Cured Ham Ciabatta"],"brewers_tips":"Lactic acid, malic acid and citric acid all give different perception of acidity and flavour at the same concentration. Play around with them in water to understand their interaction and optimise your own recipe.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-328', 'diydog', '328', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/328.json', 'Tangerine Zephyr (Small Batch)', 'Zephyr Sour Ale.', 'sour', 4.6, 10, 1.044, 1.008, 10, 20, 'tangerine zephyr (small batch) zephyr sour ale. surøl pale ale wheat malt perle wyeast 1272', '{"schemaVersion":1,"name":"Tangerine Zephyr (Small Batch)","style":"Surøl","description":"Zephyr Sour Ale.\n\nA trial brew, testing our new Zephyr concept - a Berliner-style pale, infused with tangerine.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":82,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":2.52},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":1.2}],"hops":[{"id":"h1","name":"Perle","amountG":8,"use":"boil","timeMin":60}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":53,"durationMin":25}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.044,"fg":1.008,"ibu":10,"abvPct":4.6,"colorEbc":10},"notes":"Bryggetips: Adding juices adds both sweetness and acidity to your beer - although these beers have been designed to have the right balance, play around with the quantity of the juice to add different levels of acidity and flavour of your beer.\n\nTwist: Tangerine Juice: 200g, Lactic Acid: 48g, Malic Acid: 5g, Citric Acid Powder: 44g\n\nFørst brygget: 2018"}', '{"id":328,"name":"Tangerine Zephyr (Small Batch)","tagline":"Zephyr Sour Ale.","first_brewed":"2018","description":"A trial brew, testing our new Zephyr concept - a Berliner-style pale, infused with tangerine.","image":"keg.png","abv":4.6,"ibu":10,"target_fg":1008,"target_og":1044,"ebc":10,"srm":5,"ph":3.3,"attenuation_level":82,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":53,"unit":"celsius"},"duration":25}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Tangerine Juice: 200g, Lactic Acid: 48g, Malic Acid: 5g, Citric Acid Powder: 44g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":2.52,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":1.2,"unit":"kilograms"}}],"hops":[{"name":"Perle","amount":{"value":8,"unit":"grams"},"add":"60","attribute":"Bitter"}],"yeast":"Wyeast 1272"},"food_pairing":["Eggs Benedict","Chicken Liver Pâté","Chocolate Mousse"],"brewers_tips":"Adding juices adds both sweetness and acidity to your beer - although these beers have been designed to have the right balance, play around with the quantity of the juice to add different levels of acidity and flavour of your beer.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-329', 'diydog', '329', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/329.json', 'Cybernaut', 'New Wave Session IPA.', 'ipa', 4.5, 20, 1.044, 1.01, 15, 20, 'cybernaut new wave session ipa. ipa pale ale wheat malt flaked oat malt chinook chinook amarillo simcoe citra simcoe amarillo amarillo mosaic wyeast 1272', '{"schemaVersion":1,"name":"Cybernaut","style":"IPA","description":"New Wave Session IPA.\n\nA new wave session IPA. We''ve cranked up the wheat and oats and turned down the ABV, creating a juicy equilibrium. This is a beer that has all of the taste of a New England IPA, but allows a more sessionable delivery.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":78,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3.12},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.54},{"id":"f3","name":"Flaked Oat Malt","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Chinook","amountG":1,"use":"boil","timeMin":10},{"id":"h2","name":"Chinook","amountG":11,"use":"boil","timeMin":0},{"id":"h3","name":"Amarillo","amountG":11,"use":"boil","timeMin":0},{"id":"h4","name":"Simcoe","amountG":11,"use":"boil","timeMin":0},{"id":"h5","name":"Citra","amountG":46,"use":"dry_hop"},{"id":"h6","name":"Simcoe","amountG":46,"use":"dry_hop"},{"id":"h7","name":"Amarillo","amountG":46,"use":"dry_hop"},{"id":"h8","name":"Amarillo","amountG":46,"use":"dry_hop"},{"id":"h9","name":"Mosaic","amountG":46,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":77}],"miscs":[],"mashSteps":[],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.044,"fg":1.01,"ibu":20,"abvPct":4.5,"colorEbc":15},"notes":"Bryggetips: Don''t cool the beer too cold after fermentation or you will loose the haze, 3°C should do.\n\nTwist: Pectin Powder: 2g\n\nFørst brygget: 2018"}', '{"id":329,"name":"Cybernaut","tagline":"New Wave Session IPA.","first_brewed":"2018","description":"A new wave session IPA. We''ve cranked up the wheat and oats and turned down the ABV, creating a juicy equilibrium. This is a beer that has all of the taste of a New England IPA, but allows a more sessionable delivery.","image":"329.png","abv":4.5,"ibu":20,"target_fg":1010,"target_og":1044,"ebc":15,"srm":8,"ph":4.2,"attenuation_level":77,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":0,"unit":"celsius"},"duration":15}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Pectin Powder: 2g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3.12,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.54,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":1,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Chinook","amount":{"value":11,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":11,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":11,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":46,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":46,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":46,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":46,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":46,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Scallops with Apricot Salsa","Lemon and Thyme Roasted Chicken","Raspberry Cheesecake with Mango Sorbet"],"brewers_tips":"Don''t cool the beer too cold after fermentation or you will loose the haze, 3°C should do.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 har ingen gyldig temperatur i kilden; utelatt."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-330', 'diydog', '330', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/330.json', 'BA ASA Barrel #132', 'Rye Aged IPA.', 'ipa', 7.4, 65, 1.069, 1.012, 60, 20, 'ba asa barrel #132 rye aged ipa. ipa pale ale medium crystal extra dark crystal malt carafa special type 1 rye malt hallertauer taurus chinook citra chinook citra chinook citra wyeast 1272', '{"schemaVersion":1,"name":"BA ASA Barrel #132","style":"IPA","description":"Rye Aged IPA.\n\nOur Red Rye IPA, Albino Squid Assassin, barrel aged in rye – a rebrew of one of our most requested barrel-aged beers.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":82,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.8},{"id":"f2","name":"Medium Crystal","type":"grain","amountKg":0.36},{"id":"f3","name":"Extra Dark Crystal Malt","type":"grain","amountKg":0.12},{"id":"f4","name":"Carafa Special Type 1","type":"grain","amountKg":0.06},{"id":"f5","name":"Rye Malt","type":"grain","amountKg":0.48}],"hops":[{"id":"h1","name":"Hallertauer Taurus","amountG":10,"use":"boil","timeMin":70},{"id":"h2","name":"Chinook","amountG":20,"use":"boil","timeMin":10},{"id":"h3","name":"Citra","amountG":5,"use":"boil","timeMin":10},{"id":"h4","name":"Chinook","amountG":30,"use":"boil","timeMin":0},{"id":"h5","name":"Citra","amountG":15,"use":"boil","timeMin":0},{"id":"h6","name":"Chinook","amountG":80,"use":"dry_hop"},{"id":"h7","name":"Citra","amountG":60,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":50}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.069,"fg":1.012,"ibu":65,"abvPct":7.4,"colorEbc":60},"notes":"Bryggetips: Allow the fermentation to go as far as possible. Soak oak chips in whisky to get the barrel aged characteristic.\n\nTwist: Oak Chips in Whiskey: 50g\n\nFørst brygget: 2018"}', '{"id":330,"name":"BA ASA Barrel #132","tagline":"Rye Aged IPA.","first_brewed":"2018","description":"Our Red Rye IPA, Albino Squid Assassin, barrel aged in rye – a rebrew of one of our most requested barrel-aged beers.","image":"cask.png","abv":7.4,"ibu":65,"target_fg":1012,"target_og":1069,"ebc":60,"srm":30,"ph":4.2,"attenuation_level":83,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":50}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Oak Chips in Whiskey: 50g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.8,"unit":"kilograms"}},{"name":"Medium Crystal","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Extra Dark Crystal Malt","amount":{"value":0.12,"unit":"kilograms"}},{"name":"Carafa Special Type 1","amount":{"value":0.06,"unit":"kilograms"}},{"name":"Rye Malt","amount":{"value":0.48,"unit":"kilograms"}}],"hops":[{"name":"Hallertauer Taurus","amount":{"value":10,"unit":"grams"},"add":"70","attribute":"Bitter"},{"name":"Chinook","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Citra","amount":{"value":5,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Chinook","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":15,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Chinook","amount":{"value":80,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Citra","amount":{"value":60,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Chickpea Curry","Orange Roast Chicken","Turkish Delight"],"brewers_tips":"Allow the fermentation to go as far as possible. Soak oak chips in whisky to get the barrel aged characteristic.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
