INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-333', 'diydog', '333', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/333.json', 'Nebula (Fanzine)', 'Russian Imperial Stout.', 'stout', 10, 70, 1.104, 1.025, 360, 20, 'nebula (fanzine) russian imperial stout. stout og porter pale ale caramalt brown malt chocolate malt chocolate wheat simpsons t50 flaked oat malt cascade cascade wyeast 1272', '{"schemaVersion":1,"name":"Nebula (Fanzine)","style":"Stout og porter","description":"Russian Imperial Stout.\n\nA new 10% ABV Imperial Stout. It is one of the core Fanzine beers, and will feature evolving editions as part of our subscription model.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":74,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.76},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.48},{"id":"f3","name":"Brown Malt","type":"grain","amountKg":1.44},{"id":"f4","name":"Chocolate Malt","type":"grain","amountKg":0.6},{"id":"f5","name":"Chocolate Wheat","type":"grain","amountKg":0.48},{"id":"f6","name":"Simpsons T50","type":"grain","amountKg":0.72},{"id":"f7","name":"Flaked Oat Malt","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Cascade","amountG":30,"use":"boil","timeMin":70},{"id":"h2","name":"Cascade","amountG":30,"use":"boil","timeMin":10}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":76}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":63,"durationMin":85}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.104,"fg":1.025,"ibu":70,"abvPct":10,"colorEbc":360},"notes":"Bryggetips: Condition for up to a month at 1°C for best results.\n\nTwist: Mexican Honey: 30g, Brown Sugar: 30g\n\nFørst brygget: 2018"}', '{"id":333,"name":"Nebula (Fanzine)","tagline":"Russian Imperial Stout.","first_brewed":"2018","description":"A new 10% ABV Imperial Stout. It is one of the core Fanzine beers, and will feature evolving editions as part of our subscription model.","image":"333.png","abv":10,"ibu":70,"target_fg":1025,"target_og":1104,"ebc":360,"srm":183,"ph":4.5,"attenuation_level":76,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":63,"unit":"celsius"},"duration":85}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Mexican Honey: 30g, Brown Sugar: 30g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.76,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Brown Malt","amount":{"value":1.44,"unit":"kilograms"}},{"name":"Chocolate Malt","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Chocolate Wheat","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Simpsons T50","amount":{"value":0.72,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Cascade","amount":{"value":30,"unit":"grams"},"add":"70","attribute":"Bitter"},{"name":"Cascade","amount":{"value":30,"unit":"grams"},"add":"10","attribute":"Flavour"}],"yeast":"Wyeast 1272"},"food_pairing":["Beef Jerky","Steak with Blue Cheese Sauce","Chocolate Lava Cake"],"brewers_tips":"Condition for up to a month at 1°C for best results.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-334', 'diydog', '334', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/334.json', 'Lemon Zephyr (Small Batch)', 'Zephyr Sour Ale.', 'sour', 4.6, 10, 1.044, 1.008, 10, 20, 'lemon zephyr (small batch) zephyr sour ale. surøl pale ale wheat malt perle wyeast 1272', '{"schemaVersion":1,"name":"Lemon Zephyr (Small Batch)","style":"Surøl","description":"Zephyr Sour Ale.\n\nA trial brew, testing our new Zephyr concept - a Berliner-style pale, infused with lemon.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":82,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":2.5},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":1.2}],"hops":[{"id":"h1","name":"Perle","amountG":8,"use":"boil","timeMin":60}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":53,"durationMin":25}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.044,"fg":1.008,"ibu":10,"abvPct":4.6,"colorEbc":10},"notes":"Bryggetips: Adding juices adds both sweetness and acidity to your beer - although these beers have been designed to have the right balance, play around with the quantity of the juice to add different levels of acidity and flavour of your beer.\n\nTwist: Lemon Juice: 60g, Lactic Acid: 48g, Malic Acid: 5g, Citric Acid Powder: 44g\n\nFørst brygget: 2018"}', '{"id":334,"name":"Lemon Zephyr (Small Batch)","tagline":"Zephyr Sour Ale.","first_brewed":"2018","description":"A trial brew, testing our new Zephyr concept - a Berliner-style pale, infused with lemon.","image":"keg.png","abv":4.6,"ibu":10,"target_fg":1008,"target_og":1044,"ebc":10,"srm":5,"ph":3.3,"attenuation_level":82,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":53,"unit":"celsius"},"duration":25}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Lemon Juice: 60g, Lactic Acid: 48g, Malic Acid: 5g, Citric Acid Powder: 44g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":2.5,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":1.2,"unit":"kilograms"}}],"hops":[{"name":"Perle","amount":{"value":8,"unit":"grams"},"add":"60","attribute":"Bitter"}],"yeast":"Wyeast 1272"},"food_pairing":["Prawn Pad Thai","Turkish Delight","Lemon Tart"],"brewers_tips":"Adding juices adds both sweetness and acidity to your beer - although these beers have been designed to have the right balance, play around with the quantity of the juice to add different levels of acidity and flavour of your beer.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-335', 'diydog', '335', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/335.json', 'Pulp Patriot (Fanzine)', 'Milkshake NEIPA', 'ipa', 9.5, 10, 1.092, 1.018, 15, 20, 'pulp patriot (fanzine) milkshake neipa ipa pale ale wheat malt flaked oat malt dry malt extract citra mosaic citra mosaic wyeast 1272', '{"schemaVersion":1,"name":"Pulp Patriot (Fanzine)","style":"IPA","description":"Milkshake NEIPA\n\nA scaled up rebrew of our recent milkshake IPA. A hazy New England DIPA, loaded with mango and peach resulting in an explosive aroma and a sweet full-bodied fruit shake flavour.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":93,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.04},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.6},{"id":"f3","name":"Flaked Oat Malt","type":"grain","amountKg":0.6},{"id":"f4","name":"Dry Malt Extract","type":"grain","amountKg":0.6}],"hops":[{"id":"h1","name":"Citra","amountG":11,"use":"boil","timeMin":0},{"id":"h2","name":"Mosaic","amountG":11,"use":"boil","timeMin":0},{"id":"h3","name":"Citra","amountG":149,"use":"dry_hop"},{"id":"h4","name":"Mosaic","amountG":149,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":80}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":46}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.092,"fg":1.018,"ibu":10,"abvPct":9.5,"colorEbc":15},"notes":"Bryggetips: Don''t cool the beer too cold after fermentation or you will loose the haze, 3°C should do.\n\nTwist: Peach Juice Concentrate: 250g, Mango Concentrate: 250g, Milk Sugars (Lactose): 400g\n\nFørst brygget: 2018"}', '{"id":335,"name":"Pulp Patriot (Fanzine)","tagline":"Milkshake NEIPA","first_brewed":"2018","description":"A scaled up rebrew of our recent milkshake IPA. A hazy New England DIPA, loaded with mango and peach resulting in an explosive aroma and a sweet full-bodied fruit shake flavour.","image":"335.png","abv":9.5,"ibu":10,"target_fg":1018,"target_og":1092,"ebc":15,"srm":8,"ph":4.4,"attenuation_level":80,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":46}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Peach Juice Concentrate: 250g, Mango Concentrate: 250g, Milk Sugars (Lactose): 400g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.04,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Dry Malt Extract","amount":{"value":0.6,"unit":"kilograms"}}],"hops":[{"name":"Citra","amount":{"value":11,"unit":"grams"},"add":"0","attribute":"Flavour"},{"name":"Mosaic","amount":{"value":11,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":149,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":149,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Pad Thai","Solero","Peach Cobbler"],"brewers_tips":"Don''t cool the beer too cold after fermentation or you will loose the haze, 3°C should do.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-336', 'diydog', '336', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/336.json', 'Ten Ton Truck Espresso (Fanzine)', 'Imperial Espresso Stout.', 'stout', 10, 70, 1.104, 1.025, 360, 20, 'ten ton truck espresso (fanzine) imperial espresso stout. stout og porter pale ale caramalt brown malt chocolate malt chocolate wheat simpsons t50 flaked oat malt cascade cascade wyeast 1272', '{"schemaVersion":1,"name":"Ten Ton Truck Espresso (Fanzine)","style":"Stout og porter","description":"Imperial Espresso Stout.\n\nA Fanzine release, evolving from Nebula and featuring espresso coffee.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":74,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.76},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.48},{"id":"f3","name":"Brown Malt","type":"grain","amountKg":1.44},{"id":"f4","name":"Chocolate Malt","type":"grain","amountKg":0.6},{"id":"f5","name":"Chocolate Wheat","type":"grain","amountKg":0.48},{"id":"f6","name":"Simpsons T50","type":"grain","amountKg":0.72},{"id":"f7","name":"Flaked Oat Malt","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Cascade","amountG":30,"use":"boil","timeMin":70},{"id":"h2","name":"Cascade","amountG":30,"use":"boil","timeMin":10}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":76}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":63,"durationMin":85}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.104,"fg":1.025,"ibu":70,"abvPct":10,"colorEbc":360},"notes":"Bryggetips: Add ground coffee in muslin bags directly at conditioning.\n\nTwist: Mexican Honey: 360g, Brown Sugar: 360g, Caber Coffee: 130g\n\nFørst brygget: 2018"}', '{"id":336,"name":"Ten Ton Truck Espresso (Fanzine)","tagline":"Imperial Espresso Stout.","first_brewed":"2018","description":"A Fanzine release, evolving from Nebula and featuring espresso coffee.","image":"336.png","abv":10,"ibu":70,"target_fg":1025,"target_og":1104,"ebc":360,"srm":183,"ph":4.5,"attenuation_level":76,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":63,"unit":"celsius"},"duration":85}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Mexican Honey: 360g, Brown Sugar: 360g, Caber Coffee: 130g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.76,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Brown Malt","amount":{"value":1.44,"unit":"kilograms"}},{"name":"Chocolate Malt","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Chocolate Wheat","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Simpsons T50","amount":{"value":0.72,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Cascade","amount":{"value":30,"unit":"grams"},"add":"70","attribute":"Bitter"},{"name":"Cascade","amount":{"value":30,"unit":"grams"},"add":"10","attribute":"Flavour"}],"yeast":"Wyeast 1272"},"food_pairing":["Italian Espresso","Smoky Chilli","Biscotti"],"brewers_tips":"Add ground coffee in muslin bags directly at conditioning.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
