INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-338', 'diydog', '338', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/338.json', 'Hopshop (Fanzine)', 'Double IPA.', 'ipa', 9, 70, 1.077, 1.008, 18, 20, 'hopshop (fanzine) double ipa. ipa pale ale munich malt carared malt simcoe co2 extract chinook centennial citra chinook centennial comet cascade wyeast 1272', '{"schemaVersion":1,"name":"Hopshop (Fanzine)","style":"IPA","description":"Double IPA.\n\nA Fanzine released American Double IPA, created as a one-off for our subscription club.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":89,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.6},{"id":"f2","name":"Munich Malt","type":"grain","amountKg":0.3},{"id":"f3","name":"CaraRed Malt","type":"grain","amountKg":0.1}],"hops":[{"id":"h1","name":"Simcoe CO2 Extract","amountG":4,"use":"boil","timeMin":60},{"id":"h2","name":"Chinook","amountG":20,"use":"boil","timeMin":15},{"id":"h3","name":"Centennial","amountG":40,"use":"boil","timeMin":0},{"id":"h4","name":"Citra","amountG":40,"use":"dry_hop"},{"id":"h5","name":"Chinook","amountG":40,"use":"dry_hop"},{"id":"h6","name":"Centennial","amountG":40,"use":"dry_hop"},{"id":"h7","name":"Comet","amountG":40,"use":"dry_hop"},{"id":"h8","name":"Cascade","amountG":40,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":88}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":70}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.077,"fg":1.008,"ibu":70,"abvPct":9,"colorEbc":18},"notes":"Bryggetips: Allow for 36 to 48 hours for the initial dry hop before adding the second dry hop addition.\n\nTwist: Amyloglucosidase: 1g, Dextrose: 300g\n\nFørst brygget: 2018"}', '{"id":338,"name":"Hopshop (Fanzine)","tagline":"Double IPA.","first_brewed":"2018","description":"A Fanzine released American Double IPA, created as a one-off for our subscription club.","image":"338.png","abv":9,"ibu":70,"target_fg":1008,"target_og":1077,"ebc":18,"srm":9,"ph":3.3,"attenuation_level":88,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":70}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Amyloglucosidase: 1g, Dextrose: 300g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.6,"unit":"kilograms"}},{"name":"Munich Malt","amount":{"value":0.3,"unit":"kilograms"}},{"name":"CaraRed Malt","amount":{"value":0.1,"unit":"kilograms"}}],"hops":[{"name":"Simcoe CO2 Extract","amount":{"value":4,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Chinook","amount":{"value":20,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"Centennial","amount":{"value":40,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Chinook","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Centennial","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Comet","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Cascade","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Burnt Ends","Jalapeño Poppers","Blue Cheese"],"brewers_tips":"Allow for 36 to 48 hours for the initial dry hop before adding the second dry hop addition.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-339', 'diydog', '339', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/339.json', 'Zulu Time (BD vs La Goutte d''Or)', 'South African Stout.', 'stout', 6.9, 40, 1.02, NULL, 130, 20, 'zulu time (bd vs la goutte d''or) south african stout. stout og porter pale ale propino flaked barley brown malt crystal medium dark crystal carafa special type 1 goldings goldings wyeast 1272', '{"schemaVersion":1,"name":"Zulu Time (BD vs La Goutte d''Or)","style":"Stout og porter","description":"South African Stout.\n\nOne of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. With French craft brewers Brasserie La Goutte D''or, we are brewing a stout with South African influences.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Pale Ale propino","type":"grain","amountKg":4.5},{"id":"f2","name":"Flaked Barley","type":"grain","amountKg":0.8},{"id":"f3","name":"Brown Malt","type":"grain","amountKg":0.5},{"id":"f4","name":"Crystal medium","type":"grain","amountKg":0.3},{"id":"f5","name":"Dark Crystal","type":"grain","amountKg":0.2},{"id":"f6","name":"Carafa Special Type 1","type":"grain","amountKg":0.1}],"hops":[{"id":"h1","name":"Goldings","amountG":32,"use":"boil","timeMin":70},{"id":"h2","name":"Goldings","amountG":20,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":80}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":63,"durationMin":95}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.02,"ibu":40,"abvPct":6.9,"colorEbc":130},"notes":"Bryggetips: Load rooibos tea into the hot wort in a using a tea bag or muslin cloth at flame out.\n\nTwist: Rooibos Tea: 60g\n\nFørst brygget: 2018"}', '{"id":339,"name":"Zulu Time (BD vs La Goutte d''Or)","tagline":"South African Stout.","first_brewed":"2018","description":"One of a series of collaborations with European craft breweries, aimed at promoting engagement and market growth. With French craft brewers Brasserie La Goutte D''or, we are brewing a stout with South African influences.","image":"339.png","abv":6.9,"ibu":40,"target_fg":1072,"target_og":1020,"ebc":130,"srm":66,"ph":4.4,"attenuation_level":80,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":63,"unit":"celsius"},"duration":95}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Rooibos Tea: 60g"},"ingredients":{"malt":[{"name":"Pale Ale propino","amount":{"value":4.5,"unit":"kilograms"}},{"name":"Flaked Barley","amount":{"value":0.8,"unit":"kilograms"}},{"name":"Brown Malt","amount":{"value":0.5,"unit":"kilograms"}},{"name":"Crystal medium","amount":{"value":0.3,"unit":"kilograms"}},{"name":"Dark Crystal","amount":{"value":0.2,"unit":"kilograms"}},{"name":"Carafa Special Type 1","amount":{"value":0.1,"unit":"kilograms"}}],"hops":[{"name":"Goldings","amount":{"value":32,"unit":"grams"},"add":"70","attribute":"Bitter"},{"name":"Goldings","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Flavour"}],"yeast":"Wyeast 1272"},"food_pairing":["Bunny Chow","Lamb Potjiekos","Cape Malay Koesisters"],"brewers_tips":"Load rooibos tea into the hot wort in a using a tea bag or muslin cloth at flame out.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Malt og OG i kilden gir 22 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %."]', 1790238832282);
