INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-341', 'diydog', '341', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/341.json', 'King of Eights V2 (Fanzine)', 'Double Dry-Hopped IPA.', 'ipa', 7.4, 20, 1.069, 1.012, 20, 20, 'king of eights v2 (fanzine) double dry-hopped ipa. ipa pale ale wheat malt flaked oat malt simcoe simcoe citra comet wyeast 1272', '{"schemaVersion":1,"name":"King of Eights V2 (Fanzine)","style":"IPA","description":"Double Dry-Hopped IPA.\n\nA 4.6% tart pale ale. It has a twist of tartness up-front, with juicy sour fruit notes dominating the palate.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":78,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.16},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.36},{"id":"f3","name":"Flaked Oat Malt","type":"grain","amountKg":0.6}],"hops":[{"id":"h1","name":"Simcoe","amountG":2,"use":"boil","timeMin":60},{"id":"h2","name":"Simcoe","amountG":30,"use":"boil","timeMin":0},{"id":"h3","name":"Citra","amountG":100,"use":"dry_hop","dayOfFermentation":6},{"id":"h4","name":"Comet","amountG":100,"use":"dry_hop","dayOfFermentation":8}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":66,"durationMin":21}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.069,"fg":1.012,"ibu":20,"abvPct":7.4,"colorEbc":20},"notes":"Bryggetips: The experimental hop HBC 438 used for this brew is now named Sabro. This will bring a huge pineapple aroma to the finished beer.\n\nFørst brygget: 2018"}', '{"id":341,"name":"King of Eights V2 (Fanzine)","tagline":"Double Dry-Hopped IPA.","first_brewed":"2018","description":"A 4.6% tart pale ale. It has a twist of tartness up-front, with juicy sour fruit notes dominating the palate.","image":"341.png","abv":7.4,"ibu":20,"target_fg":1012,"target_og":1069,"ebc":20,"srm":10,"ph":4.4,"attenuation_level":83,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":66,"unit":"celsius"},"duration":21}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.16,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.6,"unit":"kilograms"}}],"hops":[{"name":"Simcoe","amount":{"value":2,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Simcoe","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":100,"unit":"grams"},"add":"Dry Hop, at Day 6","attribute":"Aroma"},{"name":"Comet","amount":{"value":100,"unit":"grams"},"add":"Dry Hop, at Day 8","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Chorizo","Mexican Cheese Burgers","Three Bean Salad"],"brewers_tips":"The experimental hop HBC 438 used for this brew is now named Sabro. This will bring a huge pineapple aroma to the finished beer.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-342', 'diydog', '342', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/342.json', 'Sonic Boom V2', 'Experimental Hop IPA.', 'ipa', 6.5, 60, 1.058, 1.008, 11, 20, 'sonic boom v2 experimental hop ipa. ipa pale ale wheat malt carapils malt simcoe co2 extract cascade centennial simcoe chinook centennial hbc 438 wyeast 1272', '{"schemaVersion":1,"name":"Sonic Boom V2","style":"IPA","description":"Experimental Hop IPA.\n\nAn experimental IPA. Replacing our single hop series, this series of IPAs will allow our brew team to experiment with hops, with the base beer unchanging from release to release. New and experimental varieties, new hopping techniques, or whatever they want to do to evolve the beer each time round.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":81,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.38},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.36},{"id":"f3","name":"Carapils Malt","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Simcoe CO2 Extract","amountG":4,"use":"boil","timeMin":60},{"id":"h2","name":"Cascade","amountG":20,"use":"boil","timeMin":10},{"id":"h3","name":"Centennial","amountG":30,"use":"boil","timeMin":0},{"id":"h4","name":"Simcoe","amountG":40,"use":"dry_hop"},{"id":"h5","name":"Chinook","amountG":40,"use":"dry_hop"},{"id":"h6","name":"Centennial","amountG":40,"use":"dry_hop"},{"id":"h7","name":"HBC 438","amountG":60,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":86}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.058,"fg":1.008,"ibu":60,"abvPct":6.5,"colorEbc":11},"notes":"Bryggetips: We''ve experimented with this beer so you should too! Try swapping some hops out for others, have fun with it.\n\nFørst brygget: 2018"}', '{"id":342,"name":"Sonic Boom V2","tagline":"Experimental Hop IPA.","first_brewed":"2018","description":"An experimental IPA. Replacing our single hop series, this series of IPAs will allow our brew team to experiment with hops, with the base beer unchanging from release to release. New and experimental varieties, new hopping techniques, or whatever they want to do to evolve the beer each time round.","image":"342.png","abv":6.5,"ibu":60,"target_fg":1008,"target_og":1058,"ebc":11,"srm":6,"ph":4.6,"attenuation_level":86,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.38,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Carapils Malt","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Simcoe CO2 Extract","amount":{"value":4,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Cascade","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Centennial","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Chinook","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Centennial","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"HBC 438","amount":{"value":60,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Paneer Korma","Potato and Cumin Salad","Snickerdoodle"],"brewers_tips":"We''ve experimented with this beer so you should too! Try swapping some hops out for others, have fun with it.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-343', 'diydog', '343', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/343.json', 'Raspberry Rivet (Fanzine)', 'Raspberry Oatmeal Cream Ale.', 'ipa', 6.5, 15, 1.069, 1.019, 30, 20, 'raspberry rivet (fanzine) raspberry oatmeal cream ale. ipa pale ale wheat malt flaked oat malt amarillo mosaic citra amarillo mosaic citra wyeast 1272', '{"schemaVersion":1,"name":"Raspberry Rivet (Fanzine)","style":"IPA","description":"Raspberry Oatmeal Cream Ale.\n\nA New England IPA brewed with raspberry, oats and milk sugar.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":95,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.08},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.48},{"id":"f3","name":"Flaked Oat Malt","type":"grain","amountKg":0.48}],"hops":[{"id":"h1","name":"Amarillo","amountG":20,"use":"boil","timeMin":0},{"id":"h2","name":"Mosaic","amountG":20,"use":"boil","timeMin":0},{"id":"h3","name":"Citra","amountG":20,"use":"boil","timeMin":0},{"id":"h4","name":"Amarillo","amountG":30,"use":"dry_hop"},{"id":"h5","name":"Mosaic","amountG":30,"use":"dry_hop"},{"id":"h6","name":"Citra","amountG":30,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":72}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":30}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.069,"fg":1.019,"ibu":15,"abvPct":6.5,"colorEbc":30},"notes":"Bryggetips: Add the raspberry puree at flame out, the sugars will ferment out and this is fine. The residual sweetness comes from the milk sugars (lactose).\n\nTwist: Raspberry Juice: 550g, Milk Sugars (Lactose): 550g\n\nFørst brygget: 2018"}', '{"id":343,"name":"Raspberry Rivet (Fanzine)","tagline":"Raspberry Oatmeal Cream Ale.","first_brewed":"2018","description":"A New England IPA brewed with raspberry, oats and milk sugar.","image":"343.png","abv":6.5,"ibu":15,"target_fg":1019,"target_og":1069,"ebc":30,"srm":15,"ph":4.4,"attenuation_level":72,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":30}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Raspberry Juice: 550g, Milk Sugars (Lactose): 550g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.08,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.48,"unit":"kilograms"}}],"hops":[{"name":"Amarillo","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":30,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":30,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Citra","amount":{"value":30,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Cream Cheese Crackers","White Chocolate and Raspberry Cookies","Birthday Cake"],"brewers_tips":"Add the raspberry puree at flame out, the sugars will ferment out and this is fine. The residual sweetness comes from the milk sugars (lactose).","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-344', 'diydog', '344', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/344.json', 'Zephyr Piña Colada (Fanzine)', 'Zephyr Sour Ale.', 'sour', 4.6, 10, 1.044, 1.008, 10, 20, 'zephyr piña colada (fanzine) zephyr sour ale. surøl pale ale wheat malt perle wyeast 1272', '{"schemaVersion":1,"name":"Zephyr Piña Colada (Fanzine)","style":"Surøl","description":"Zephyr Sour Ale.\n\nOur latest session sour, this time based on Piña Colada.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":82,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":2.5},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":1.2}],"hops":[{"id":"h1","name":"Perle","amountG":8,"use":"boil","timeMin":60}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":53,"durationMin":25}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.044,"fg":1.008,"ibu":10,"abvPct":4.6,"colorEbc":10},"notes":"Bryggetips: Used toasted coconut in the mash and steep in the cold conditioning phase to emphasis the Piña Colada smoothness.\n\nTwist: Pineapple Juice: 500g, Coconut Extract: 2g, Lactic Acid: 48g, Malic Acid: 5g, Citric Acid Powder: 44g\n\nFørst brygget: 2018"}', '{"id":344,"name":"Zephyr Piña Colada (Fanzine)","tagline":"Zephyr Sour Ale.","first_brewed":"2018","description":"Our latest session sour, this time based on Piña Colada.","image":"344.png","abv":4.6,"ibu":10,"target_fg":1008,"target_og":1044,"ebc":10,"srm":5,"ph":3.3,"attenuation_level":82,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":53,"unit":"celsius"},"duration":25}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Pineapple Juice: 500g, Coconut Extract: 2g, Lactic Acid: 48g, Malic Acid: 5g, Citric Acid Powder: 44g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":2.5,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":1.2,"unit":"kilograms"}}],"hops":[{"name":"Perle","amount":{"value":8,"unit":"grams"},"add":"60","attribute":"Bitter"}],"yeast":"Wyeast 1272"},"food_pairing":["Prawn Korma","Coconut Ice","Keylime Pie"],"brewers_tips":"Used toasted coconut in the mash and steep in the cold conditioning phase to emphasis the Piña Colada smoothness.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-345', 'diydog', '345', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/345.json', 'Vinyl Vigilante (Fanzine)', 'Coffee Milk Stout.', 'stout', 7, 10, 1.071, 1.019, 150, 20, 'vinyl vigilante (fanzine) coffee milk stout. stout og porter pilsner brown malt chocolate wheat simpsons drc flaked oat malt magnum wyeast 1272', '{"schemaVersion":1,"name":"Vinyl Vigilante (Fanzine)","style":"Stout og porter","description":"Coffee Milk Stout.\n\nA Fanzine release, alongside the international draft exclusive. Vinyl Vigilante is a Coffee Milk Stout, taking the coffee flavours already present in dark ales and enhancing them.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":82,"fermentables":[{"id":"f1","name":"Pilsner","type":"grain","amountKg":4.2},{"id":"f2","name":"Brown Malt","type":"grain","amountKg":0.48},{"id":"f3","name":"Chocolate Wheat","type":"grain","amountKg":0.48},{"id":"f4","name":"Simpsons DRC","type":"grain","amountKg":0.48},{"id":"f5","name":"Flaked Oat Malt","type":"grain","amountKg":0.36}],"hops":[{"id":"h1","name":"Magnum","amountG":10,"use":"boil","timeMin":60}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":73}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":70}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.071,"fg":1.019,"ibu":10,"abvPct":7,"colorEbc":150},"notes":"Bryggetips: Use freshly ground coffee for the best aromatic hit. Consider the addition of cold brew coffee into the secondary. This will give a big coffee flavour but not impart any of the astringent bitterness of over extracted coffee, just be careful not to add too much and dilute the beer.\n\nTwist: Cold Brew Coffee: 100g Dry Hop, Milk Sugars (Lactose): 480g\n\nFørst brygget: 2018"}', '{"id":345,"name":"Vinyl Vigilante (Fanzine)","tagline":"Coffee Milk Stout.","first_brewed":"2018","description":"A Fanzine release, alongside the international draft exclusive. Vinyl Vigilante is a Coffee Milk Stout, taking the coffee flavours already present in dark ales and enhancing them.","image":"345.png","abv":7,"ibu":10,"target_fg":1019,"target_og":1071,"ebc":150,"srm":76,"ph":4.4,"attenuation_level":73,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":70}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Cold Brew Coffee: 100g Dry Hop, Milk Sugars (Lactose): 480g"},"ingredients":{"malt":[{"name":"Pilsner","amount":{"value":4.2,"unit":"kilograms"}},{"name":"Brown Malt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Chocolate Wheat","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Simpsons DRC","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.36,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":10,"unit":"grams"},"add":"60","attribute":"Bitter"}],"yeast":"Wyeast 1272"},"food_pairing":["Beef Rendang","Profiteroles","Shortbread"],"brewers_tips":"Use freshly ground coffee for the best aromatic hit. Consider the addition of cold brew coffee into the secondary. This will give a big coffee flavour but not impart any of the astringent bitterness of over extracted coffee, just be careful not to add too much and dilute the beer.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-346', 'diydog', '346', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/346.json', 'Jet Trash V2 (Fanzine)', 'West Coast IPA.', 'ipa', 6.9, 65, 1.061, 1.006, 18, 20, 'jet trash v2 (fanzine) west coast ipa. ipa pale ale munich malt dextrin malt carared malt simcoe co2 extract cascade cascade centennial citra centennial simcoe citra centennial mosaic wyeast 1272', '{"schemaVersion":1,"name":"Jet Trash V2 (Fanzine)","style":"IPA","description":"West Coast IPA.\n\nA double dry hopped edition of our 6.9% ABV west coast IPA, Jet Trash. It’s the second version of one of our core Fanzine beers, and will continue to feature evolving editions.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":80,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.44},{"id":"f2","name":"Munich Malt","type":"grain","amountKg":0.36},{"id":"f3","name":"Dextrin Malt","type":"grain","amountKg":0.24},{"id":"f4","name":"CaraRed Malt","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Simcoe CO2 Extract","amountG":4,"use":"boil","timeMin":60},{"id":"h2","name":"Cascade","amountG":20,"use":"boil","timeMin":10},{"id":"h3","name":"Cascade","amountG":30,"use":"boil","timeMin":0},{"id":"h4","name":"Centennial","amountG":30,"use":"boil","timeMin":0},{"id":"h5","name":"Citra","amountG":40,"use":"dry_hop","dayOfFermentation":6},{"id":"h6","name":"Centennial","amountG":20,"use":"dry_hop","dayOfFermentation":6},{"id":"h7","name":"Simcoe","amountG":40,"use":"dry_hop","dayOfFermentation":8},{"id":"h8","name":"Citra","amountG":40,"use":"dry_hop","dayOfFermentation":8},{"id":"h9","name":"Centennial","amountG":30,"use":"dry_hop","dayOfFermentation":8},{"id":"h10","name":"Mosaic","amountG":30,"use":"dry_hop","dayOfFermentation":8}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":90}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.061,"fg":1.006,"ibu":65,"abvPct":6.9,"colorEbc":18},"notes":"Bryggetips: Allow for 36 to 48 hours for the initial dry hop before adding the second dry hop addition.\n\nTwist: Dextrose: 120g\n\nFørst brygget: 2018"}', '{"id":346,"name":"Jet Trash V2 (Fanzine)","tagline":"West Coast IPA.","first_brewed":"2018","description":"A double dry hopped edition of our 6.9% ABV west coast IPA, Jet Trash. It’s the second version of one of our core Fanzine beers, and will continue to feature evolving editions.","image":"346.png","abv":6.9,"ibu":65,"target_fg":1006,"target_og":1061,"ebc":18,"srm":9,"ph":4.6,"attenuation_level":90,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Dextrose: 120g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.44,"unit":"kilograms"}},{"name":"Munich Malt","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Dextrin Malt","amount":{"value":0.24,"unit":"kilograms"}},{"name":"CaraRed Malt","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Simcoe CO2 Extract","amount":{"value":4,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Cascade","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Cascade","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Centennial","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":40,"unit":"grams"},"add":"Dry Hop, at Day 6","attribute":"Aroma"},{"name":"Centennial","amount":{"value":20,"unit":"grams"},"add":"Dry Hop, at Day 6","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":40,"unit":"grams"},"add":"Dry Hop, at Day 8","attribute":"Aroma"},{"name":"Citra","amount":{"value":40,"unit":"grams"},"add":"Dry Hop, at Day 8","attribute":"Aroma"},{"name":"Centennial","amount":{"value":30,"unit":"grams"},"add":"Dry Hop, at Day 8","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":30,"unit":"grams"},"add":"Dry Hop, at Day 8","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Salmon and Avocado Tostadas","Carrot Cake with Orange, Pistachio and Pomegranate","Blueberry and Lemon Trifle"],"brewers_tips":"Allow for 36 to 48 hours for the initial dry hop before adding the second dry hop addition.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-347', 'diydog', '347', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/347.json', 'Technicolour Black (Fanzine)', 'Black Rye IPA.', 'ipa', 6.5, 70, 1.057, 1.0055, 135, 20, 'technicolour black (fanzine) black rye ipa. ipa pale ale rye malt premium english cara malt chocolate wheat carafa type 3 simcoe co2 extract chinook centennial simcoe citra chinook wyeast 1272', '{"schemaVersion":1,"name":"Technicolour Black (Fanzine)","style":"IPA","description":"Black Rye IPA.\n\nAn aggressive black IPA with a spicy hint of rye. Intense flavours for the lovers of bitterness, balanced beautifully between malt and hops.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":82,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.08},{"id":"f2","name":"Rye Malt","type":"grain","amountKg":0.36},{"id":"f3","name":"Premium English Cara Malt","type":"grain","amountKg":0.12},{"id":"f4","name":"Chocolate Wheat","type":"grain","amountKg":0.12},{"id":"f5","name":"Carafa type 3","type":"grain","amountKg":0.12}],"hops":[{"id":"h1","name":"Simcoe CO2 Extract","amountG":6,"use":"boil","timeMin":60},{"id":"h2","name":"Chinook","amountG":20,"use":"boil","timeMin":10},{"id":"h3","name":"Centennial","amountG":20,"use":"boil","timeMin":0},{"id":"h4","name":"Simcoe","amountG":20,"use":"boil","timeMin":0},{"id":"h5","name":"Citra","amountG":150,"use":"dry_hop"},{"id":"h6","name":"Chinook","amountG":50,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":90}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":70}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.057,"fg":1.0055,"ibu":70,"abvPct":6.5,"colorEbc":135},"notes":"Bryggetips: To boost the colour but less of the roasted flavour of the dark malts, try substituting the Carafa® special III for a dehusked version of Carafa® that delivers a smoother flavour.\n\nTwist: Dextrose: 300g, Weyermann Organic Sinamar: 30g\n\nFørst brygget: 2018"}', '{"id":347,"name":"Technicolour Black (Fanzine)","tagline":"Black Rye IPA.","first_brewed":"2018","description":"An aggressive black IPA with a spicy hint of rye. Intense flavours for the lovers of bitterness, balanced beautifully between malt and hops.","image":"347.png","abv":6.5,"ibu":70,"target_fg":1005.5,"target_og":1057,"ebc":135,"srm":69,"ph":4.5,"attenuation_level":90,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":70}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Dextrose: 300g, Weyermann Organic Sinamar: 30g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.08,"unit":"kilograms"}},{"name":"Rye Malt","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Premium English Cara Malt","amount":{"value":0.12,"unit":"kilograms"}},{"name":"Chocolate Wheat","amount":{"value":0.12,"unit":"kilograms"}},{"name":"Carafa type 3","amount":{"value":0.12,"unit":"kilograms"}}],"hops":[{"name":"Simcoe CO2 Extract","amount":{"value":6,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Chinook","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Centennial","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":150,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Chinook","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Westcombe Dairy Cheddar","Memphis-Style Beef Ribs","Carrot Cake"],"brewers_tips":"To boost the colour but less of the roasted flavour of the dark malts, try substituting the Carafa® special III for a dehusked version of Carafa® that delivers a smoother flavour.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-348', 'diydog', '348', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/348.json', 'King of Eights V3 (Fanzine)', 'Triple Dry-Hopped NEIPA.', 'strong', 7.4, 20, 1.069, 1.012, 20, 20, 'king of eights v3 (fanzine) triple dry-hopped neipa. sterkt øl pale ale wheat malt flaked oat malt citra citra citra comet mosaic wyeast 1272', '{"schemaVersion":1,"name":"King of Eights V3 (Fanzine)","style":"Sterkt øl","description":"Triple Dry-Hopped NEIPA.\n\nA Fanzine release which has been dry hopped three consecutive times with three different hops. It''s crammed with fresh tropical vibes from Citra, Comet and Mosaic.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":78,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.16},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.36},{"id":"f3","name":"Flaked Oat Malt","type":"grain","amountKg":0.6}],"hops":[{"id":"h1","name":"Citra","amountG":2,"use":"boil","timeMin":60},{"id":"h2","name":"Citra","amountG":30,"use":"boil","timeMin":0},{"id":"h3","name":"Citra","amountG":80,"use":"dry_hop","dayOfFermentation":6},{"id":"h4","name":"Comet","amountG":80,"use":"dry_hop","dayOfFermentation":7},{"id":"h5","name":"Mosaic","amountG":80,"use":"dry_hop","dayOfFermentation":8}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":66,"durationMin":21}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.069,"fg":1.012,"ibu":20,"abvPct":7.4,"colorEbc":20},"notes":"Bryggetips: Depending on the yeast strain and hops you’re using, you can benefit from the effect of “biotransformation” by dry hopping before the primary fermentation is finished. Some yeasts are capable of extracting extra flavours from the hops. The earlier you dry hop in the fermentation process, the more flavour is extracted from the hops through the process of biotransformation, however at the same time more flavour also disappears again through the stripping effect of the generated CO2. A good balance is to add the hops just before primary fermentation is finished.\n\nFørst brygget: 2018"}', '{"id":348,"name":"King of Eights V3 (Fanzine)","tagline":"Triple Dry-Hopped NEIPA.","first_brewed":"2018","description":"A Fanzine release which has been dry hopped three consecutive times with three different hops. It''s crammed with fresh tropical vibes from Citra, Comet and Mosaic.","image":"348.png","abv":7.4,"ibu":20,"target_fg":1012,"target_og":1069,"ebc":20,"srm":10,"ph":4.4,"attenuation_level":83,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":66,"unit":"celsius"},"duration":21}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.16,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.6,"unit":"kilograms"}}],"hops":[{"name":"Citra","amount":{"value":2,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Citra","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":80,"unit":"grams"},"add":"Dry Hop, at Day 6","attribute":"Aroma"},{"name":"Comet","amount":{"value":80,"unit":"grams"},"add":"Dry Hop, at Day 7","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":80,"unit":"grams"},"add":"Dry Hop, at Day 8","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Étouffée","Chilli-Shrimp Quesadilla","Bakewell Tart"],"brewers_tips":"Depending on the yeast strain and hops you’re using, you can benefit from the effect of “biotransformation” by dry hopping before the primary fermentation is finished. Some yeasts are capable of extracting extra flavours from the hops. The earlier you dry hop in the fermentation process, the more flavour is extracted from the hops through the process of biotransformation, however at the same time more flavour also disappears again through the stripping effect of the generated CO2. A good balance is to add the hops just before primary fermentation is finished.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-349', 'diydog', '349', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/349.json', 'Pulp Patriot V2 Double Dry-Hop (Fanzine)', 'Double Dry-Hopped Milkshake IPA.', 'ipa', 9.5, 10, 1.095, 1.018, 15, 20, 'pulp patriot v2 double dry-hop (fanzine) double dry-hopped milkshake ipa. ipa pale ale wheat malt flaked oat malt dry malt extract citra mosaic chinook citra mosaic chinook wyeast 1272', '{"schemaVersion":1,"name":"Pulp Patriot V2 Double Dry-Hop (Fanzine)","style":"IPA","description":"Double Dry-Hopped Milkshake IPA.\n\nA double dry hopped edition of our recent milkshake IPAs, this fruited NEIPA combines peach, mango and milk sugar with low bitterness and extreme dry hopping rates.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":93,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.28},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.6},{"id":"f3","name":"Flaked Oat Malt","type":"grain","amountKg":0.6},{"id":"f4","name":"Dry Malt Extract","type":"grain","amountKg":0.6}],"hops":[{"id":"h1","name":"Citra","amountG":10,"use":"whirlpool"},{"id":"h2","name":"Mosaic","amountG":10,"use":"whirlpool"},{"id":"h3","name":"Chinook","amountG":10,"use":"whirlpool"},{"id":"h4","name":"Citra","amountG":100,"use":"dry_hop","dayOfFermentation":8},{"id":"h5","name":"Mosaic","amountG":100,"use":"dry_hop","dayOfFermentation":8},{"id":"h6","name":"Chinook","amountG":100,"use":"dry_hop","dayOfFermentation":6}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":81}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":46}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.095,"fg":1.018,"ibu":10,"abvPct":9.5,"colorEbc":15},"notes":"Bryggetips: Depending on the yeast strain and hops you’re using, you can benefit from the effect of “biotransformation” by dry hopping before the primary fermentation is finished. Some yeasts are capable of extracting extra flavours from the hops. The earlier you dry hop in the fermentation process, the more flavour is extracted from the hops through the process of biotransformation, however at the same time more flavour also disappears again through the stripping effect of the generated CO2. A good balance is to add the hops just before primary fermentation is finished.\n\nTwist: Peach Juice Concentrate: 250g, Mango Concentrate: 250g, Milk Sugars (Lactose): 400g\n\nFørst brygget: 2018"}', '{"id":349,"name":"Pulp Patriot V2 Double Dry-Hop (Fanzine)","tagline":"Double Dry-Hopped Milkshake IPA.","first_brewed":"2018","description":"A double dry hopped edition of our recent milkshake IPAs, this fruited NEIPA combines peach, mango and milk sugar with low bitterness and extreme dry hopping rates.","image":"349.png","abv":9.5,"ibu":10,"target_fg":1018,"target_og":1095,"ebc":15,"srm":8,"ph":4.4,"attenuation_level":81,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":46}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Peach Juice Concentrate: 250g, Mango Concentrate: 250g, Milk Sugars (Lactose): 400g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.28,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Dry Malt Extract","amount":{"value":0.6,"unit":"kilograms"}}],"hops":[{"name":"Citra","amount":{"value":10,"unit":"grams"},"add":"WHP","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":10,"unit":"grams"},"add":"WHP","attribute":"Aroma"},{"name":"Chinook","amount":{"value":10,"unit":"grams"},"add":"WHP","attribute":"Aroma"},{"name":"Citra","amount":{"value":100,"unit":"grams"},"add":"Dry Hop, at Day 8","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":100,"unit":"grams"},"add":"Dry Hop, at Day 8","attribute":"Aroma"},{"name":"Chinook","amount":{"value":100,"unit":"grams"},"add":"Dry Hop, at Day 6","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Keen''s Cheddar","Green Mango Chutney","Orange Pound Cake"],"brewers_tips":"Depending on the yeast strain and hops you’re using, you can benefit from the effect of “biotransformation” by dry hopping before the primary fermentation is finished. Some yeasts are capable of extracting extra flavours from the hops. The earlier you dry hop in the fermentation process, the more flavour is extracted from the hops through the process of biotransformation, however at the same time more flavour also disappears again through the stripping effect of the generated CO2. A good balance is to add the hops just before primary fermentation is finished.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-350', 'diydog', '350', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/350.json', 'Radio Zombie Phone In', 'Russian Imperial Stout.', 'stout', 14, 80, 1.131, 1.024, 800, 20, 'radio zombie phone in russian imperial stout. stout og porter pale ale extra dark crystal malt wheat malt black malt roasted barley carafa special type 1 oat husks trienzyme dextrose hallertauer taurus hallertauer taurus wyeast 1272', '{"schemaVersion":1,"name":"Radio Zombie Phone In","style":"Stout og porter","description":"Russian Imperial Stout.\n\nA 14% ABV Russian Imperial Stout brewed as an EFP V referral reward. Aggressive and imposing, this massive stout is black as pitch and delivers huge and complex flavours.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":71,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":8.88},{"id":"f2","name":"Extra Dark Crystal Malt","type":"grain","amountKg":0.36},{"id":"f3","name":"Wheat Malt","type":"grain","amountKg":0.36},{"id":"f4","name":"Black Malt","type":"grain","amountKg":0.36},{"id":"f5","name":"Roasted Barley","type":"grain","amountKg":0.24},{"id":"f6","name":"Carafa Special Type 1","type":"grain","amountKg":0.6},{"id":"f7","name":"Oat Husks","type":"grain","amountKg":0.24},{"id":"f8","name":"Trienzyme","type":"grain","amountKg":0.01},{"id":"f9","name":"Dextrose","type":"sugar","amountKg":1.2}],"hops":[{"id":"h1","name":"Hallertauer Taurus","amountG":29,"use":"boil","timeMin":70},{"id":"h2","name":"Hallertauer Taurus","amountG":17,"use":"boil","timeMin":10}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":115}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.131,"fg":1.024,"ibu":80,"abvPct":14,"colorEbc":800},"notes":"Bryggetips: A long mash rest is essential for complete attenuation.\n\nFørst brygget: 2018"}', '{"id":350,"name":"Radio Zombie Phone In","tagline":"Russian Imperial Stout.","first_brewed":"2018","description":"A 14% ABV Russian Imperial Stout brewed as an EFP V referral reward. Aggressive and imposing, this massive stout is black as pitch and delivers huge and complex flavours.","image":"350.png","abv":14,"ibu":80,"target_fg":1024,"target_og":1131,"ebc":800,"srm":406,"ph":4.4,"attenuation_level":82,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":115}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":8.88,"unit":"kilograms"}},{"name":"Extra Dark Crystal Malt","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Black Malt","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Roasted Barley","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Carafa Special Type 1","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Oat Husks","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Trienzyme","amount":{"value":0.01,"unit":"kilograms"}},{"name":"Dextrose","amount":{"value":1.2,"unit":"kilograms"}}],"hops":[{"name":"Hallertauer Taurus","amount":{"value":29,"unit":"grams"},"add":"70","attribute":"Bitter"},{"name":"Hallertauer Taurus","amount":{"value":17,"unit":"grams"},"add":"10","attribute":"Flavour"}],"yeast":"Wyeast 1272"},"food_pairing":["Kingstone Farm Rollright","Porterhouse Steak","Black Forest Gateau"],"brewers_tips":"A long mash rest is essential for complete attenuation.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskri