INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-351', 'diydog', '351', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/351.json', 'Mashtag 2018', 'Hibiscus and Yuzu Pale Ale.', 'pale', 5, 10, 1.048, 1.01, 10, 20, 'mashtag 2018 hibiscus and yuzu pale ale. pale ale pale ale wheat malt chinook chinook mosaic citra chinook mosaic citra wyeast 1272', '{"schemaVersion":1,"name":"Mashtag 2018","style":"Pale ale","description":"Hibiscus and Yuzu Pale Ale.\n\nThe triumphant return of our democratic brewing concept; Mashtag sees us run a series of votes to determine each element of the beer. This year, at the public’s request, we have brewed an American pale ale with hibiscus flower and yuzu.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":77,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3.84},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.48}],"hops":[{"id":"h1","name":"Chinook","amountG":10,"use":"dry_hop","notes":"Tørrhumling 1"},{"id":"h2","name":"Chinook","amountG":20,"use":"whirlpool"},{"id":"h3","name":"Mosaic","amountG":20,"use":"whirlpool"},{"id":"h4","name":"Citra","amountG":20,"use":"whirlpool"},{"id":"h5","name":"Chinook","amountG":50,"use":"dry_hop"},{"id":"h6","name":"Mosaic","amountG":50,"use":"dry_hop"},{"id":"h7","name":"Citra","amountG":50,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":25}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.048,"fg":1.01,"ibu":10,"abvPct":5,"colorEbc":10},"notes":"Bryggetips: Adding hibiscus at fermentation temp will allow for maximum flavour and colour extraction.\n\nTwist: Yuzu Extract: 1g Dry Hop, Hibiscus Flowers: 40g Dry Hop\n\nFørst brygget: 2018"}', '{"id":351,"name":"Mashtag 2018","tagline":"Hibiscus and Yuzu Pale Ale.","first_brewed":"2018","description":"The triumphant return of our democratic brewing concept; Mashtag sees us run a series of votes to determine each element of the beer. This year, at the public’s request, we have brewed an American pale ale with hibiscus flower and yuzu.","image":"351.png","abv":5,"ibu":10,"target_fg":1010,"target_og":1048,"ebc":10,"srm":5,"ph":4.4,"attenuation_level":79,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":25}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Yuzu Extract: 1g Dry Hop, Hibiscus Flowers: 40g Dry Hop"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3.84,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.48,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":10,"unit":"grams"},"add":"HD1","attribute":"Bitter"},{"name":"Chinook","amount":{"value":20,"unit":"grams"},"add":"WHP","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":20,"unit":"grams"},"add":"WHP","attribute":"Aroma"},{"name":"Citra","amount":{"value":20,"unit":"grams"},"add":"WHP","attribute":"Aroma"},{"name":"Chinook","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Citra","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Tonkotsu Ramen","Marmalade Baked Camembert","Blueberry and Yuzu Cheesecake"],"brewers_tips":"Adding hibiscus at fermentation temp will allow for maximum flavour and colour extraction.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-352', 'diydog', '352', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/352.json', 'Beatnik', 'Raspberry Cheesecake Imperial Stout.', 'stout', 10.2, 70, 1.104, 1.025, 360, 20, 'beatnik raspberry cheesecake imperial stout. stout og porter pale ale brown malt chocolate malt chocolate wheat simpsons t50 wheat malt oat husks dry malt extract cascade cascade wyeast 1272', '{"schemaVersion":1,"name":"Beatnik","style":"Stout og porter","description":"Raspberry Cheesecake Imperial Stout.\n\nOur annual EFP-designed beatnik brew. The winning concept is a raspberry cheesecake inspired imperial stout.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":87,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.48},{"id":"f2","name":"Brown Malt","type":"grain","amountKg":0.4},{"id":"f3","name":"Chocolate Malt","type":"grain","amountKg":0.72},{"id":"f4","name":"Chocolate Wheat","type":"grain","amountKg":0.4},{"id":"f5","name":"Simpsons T50","type":"grain","amountKg":0.72},{"id":"f6","name":"Wheat Malt","type":"grain","amountKg":0.8},{"id":"f7","name":"Oat Husks","type":"grain","amountKg":0.32},{"id":"f8","name":"Dry Malt Extract","type":"grain","amountKg":0.45}],"hops":[{"id":"h1","name":"Cascade","amountG":27,"use":"dry_hop","notes":"Tørrhumling 1"},{"id":"h2","name":"Cascade","amountG":27,"use":"dry_hop","notes":"Tørrhumling 2"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":76}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":63,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.104,"fg":1.025,"ibu":70,"abvPct":10.2,"colorEbc":360},"notes":"Bryggetips: When using fresh fruit, it is best to freeze it to both sanitise without chemicals or alcohol and to cause the cells within the fruit to burst allowing for maximum flavour extraction.\n\nTwist: Raspberry Puree: 200g, Milk Sugars (Lactose): 500g, Amyloglucosidase: 2g\n\nFørst brygget: 2018"}', '{"id":352,"name":"Beatnik","tagline":"Raspberry Cheesecake Imperial Stout.","first_brewed":"2018","description":"Our annual EFP-designed beatnik brew. The winning concept is a raspberry cheesecake inspired imperial stout.","image":"352.png","abv":10.2,"ibu":70,"target_fg":1025,"target_og":1104,"ebc":360,"srm":183,"ph":4.5,"attenuation_level":76,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":63,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Raspberry Puree: 200g, Milk Sugars (Lactose): 500g, Amyloglucosidase: 2g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.48,"unit":"kilograms"}},{"name":"Brown Malt","amount":{"value":0.4,"unit":"kilograms"}},{"name":"Chocolate Malt","amount":{"value":0.72,"unit":"kilograms"}},{"name":"Chocolate Wheat","amount":{"value":0.4,"unit":"kilograms"}},{"name":"Simpsons T50","amount":{"value":0.72,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.8,"unit":"kilograms"}},{"name":"Oat Husks","amount":{"value":0.32,"unit":"kilograms"}},{"name":"Dry Malt Extract","amount":{"value":0.45,"unit":"kilograms"}}],"hops":[{"name":"Cascade","amount":{"value":27,"unit":"grams"},"add":"HD1","attribute":"Bitter"},{"name":"Cascade","amount":{"value":27,"unit":"grams"},"add":"HD2","attribute":"Bitter"}],"yeast":"Wyeast 1272"},"food_pairing":["Brie","Chai Doughnuts","Chocolate Ice Cream"],"brewers_tips":"When using fresh fruit, it is best to freeze it to both sanitise without chemicals or alcohol and to cause the cells within the fruit to burst allowing for maximum flavour extraction.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-353', 'diydog', '353', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/353.json', 'Cloud Cartel (Fanzine)', 'New England Session IPA.', 'ipa', 5, 20, 1.048, 1.01, 15, 20, 'cloud cartel (fanzine) new england session ipa. ipa pale ale wheat malt flaked oat milk chinook chinook amarillo simcoe ariana huell melon german cascade wyeast 1272', '{"schemaVersion":1,"name":"Cloud Cartel (Fanzine)","style":"IPA","description":"New England Session IPA.\n\nA 5% take on a New England IPA, for our Fanzine subscription club.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":78,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3.48},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.54},{"id":"f3","name":"Flaked Oat Milk","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Chinook","amountG":1,"use":"boil","timeMin":15},{"id":"h2","name":"Chinook","amountG":10,"use":"boil","timeMin":0},{"id":"h3","name":"Amarillo","amountG":10,"use":"boil","timeMin":0},{"id":"h4","name":"Simcoe","amountG":10,"use":"boil","timeMin":0},{"id":"h5","name":"Ariana","amountG":60,"use":"dry_hop"},{"id":"h6","name":"Huell Melon","amountG":60,"use":"dry_hop"},{"id":"h7","name":"German Cascade","amountG":40,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79}],"miscs":[],"mashSteps":[],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.048,"fg":1.01,"ibu":20,"abvPct":5,"colorEbc":15},"notes":"Bryggetips: The key to NEIPA is a lot of hops at flame out for no longer than 15 minutes to extract flavour and aroma without adding any additional bitterness.\n\nFørst brygget: 2018"}', '{"id":353,"name":"Cloud Cartel (Fanzine)","tagline":"New England Session IPA.","first_brewed":"2018","description":"A 5% take on a New England IPA, for our Fanzine subscription club.","image":"353.png","abv":5,"ibu":20,"target_fg":1010,"target_og":1048,"ebc":15,"srm":8,"ph":4.2,"attenuation_level":79,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":0,"unit":"celsius"},"duration":15}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3.48,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.54,"unit":"kilograms"}},{"name":"Flaked Oat Milk","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":1,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"Chinook","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Ariana","amount":{"value":60,"unit":"grams"},"add":"Dry Hop","attribute":null},{"name":"Huell Melon","amount":{"value":60,"unit":"grams"},"add":"Dry Hop","attribute":null},{"name":"German Cascade","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":null}],"yeast":"Wyeast 1272"},"food_pairing":["Cornish Yarg","Chicken Choila","Banana Fritter"],"brewers_tips":"The key to NEIPA is a lot of hops at flame out for no longer than 15 minutes to extract flavour and aroma without adding any additional bitterness.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 har ingen gyldig temperatur i kilden; utelatt."]', 1790238832282);
