INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-357', 'diydog', '357', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/357.json', 'Quench Quake', 'Grapefruit and Tangerine Sour.', 'sour', 4.6, 10, 1.044, 1.008, 10, 20, 'quench quake grapefruit and tangerine sour. surøl pale ale wheat malt perle wyeast 1272', '{"schemaVersion":1,"name":"Quench Quake","style":"Surøl","description":"Grapefruit and Tangerine Sour.\n\nA session strength sour ale infused with grapefruit and tangerine. A straightforward, easy-going introduction to sour beer.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":82,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":2.52},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":1.2}],"hops":[{"id":"h1","name":"Perle","amountG":8,"use":"boil","timeMin":60}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":53,"durationMin":25}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.044,"fg":1.008,"ibu":10,"abvPct":4.6,"colorEbc":10},"notes":"Bryggetips: A low pH at fermentation is normal, usually under 4 pH.\n\nTwist: Grapefruit Juice: 100g FV Addition, White Grapefruit Juice: 100g FV Addition, Tangerine Juice: 150g FV Addition, Lactic Acid: 50g, Malic Acid: 10g, Citric Acid Powder: 40g\n\nFørst brygget: 2018"}', '{"id":357,"name":"Quench Quake","tagline":"Grapefruit and Tangerine Sour.","first_brewed":"2018","description":"A session strength sour ale infused with grapefruit and tangerine. A straightforward, easy-going introduction to sour beer.","image":"357.png","abv":4.6,"ibu":10,"target_fg":1008,"target_og":1044,"ebc":10,"srm":5,"ph":3.3,"atten