INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-359', 'diydog', '359', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/359.json', 'Coin-Op Kaiser (Fanzine)', 'Dry Hopped Imperial Pilsner.', 'lager', 6, 40, 1.054, 1.006, 4, 20, 'coin-op kaiser (fanzine) dry hopped imperial pilsner. lager og pils pilsner malt hallertauer taurus select spalter select spalter triskel triskel w34/70', '{"schemaVersion":1,"name":"Coin-Op Kaiser (Fanzine)","style":"Lager og pils","description":"Dry Hopped Imperial Pilsner.\n\nA dry hopped imperial lager, brewed for Dog Dealers and Fanzine. It''s a big, toasty lager, packed with pilsner malt character, layered with a soft and yielding Sauvignon-like dry hop flavour.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":82,"fermentables":[{"id":"f1","name":"Pilsner Malt","type":"grain","amountKg":4.56}],"hops":[{"id":"h1","name":"Hallertauer Taurus","amountG":10,"use":"boil","timeMin":60},{"id":"h2","name":"Select Spalter","amountG":10,"use":"boil","timeMin":30},{"id":"h3","name":"Select Spalter","amountG":10,"use":"boil","timeMin":10},{"id":"h4","name":"Triskel","amountG":30,"use":"boil","timeMin":0},{"id":"h5","name":"Triskel","amountG":30,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"W34/70","form":"dry","amount":1,"unit":"pkg","attenuationPct":89}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":65}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":11}],"targets":{"og":1.054,"fg":1.006,"ibu":40,"abvPct":6,"colorEbc":4},"notes":"Bryggetips: Condition the beer for at least 15 days at 1°C.\n\nFørst brygget: 2018"}', '{"id":359,"name":"Coin-Op Kaiser (Fanzine)","tagline":"Dry Hopped Imperial Pilsner.","first_brewed":"2018","description":"A dry hopped imperial lager, brewed for Dog Dealers and Fanzine. It''s a big, toasty lager, packed with pilsner malt character, layered with a soft and yielding Sauvignon-like dry hop flavour.","image":"359.png","abv":6,"ibu":40,"target_fg":1006,"target_og":1054,"ebc":4,"srm":2,"ph":4.4,"attenuation_level":89,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":65}],"fermentation":{"temp":{"value":11,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pilsner Malt","amount":{"value":4.56,"unit":"kilograms"}}],"hops":[{"name":"Hallertauer Taurus","amount":{"value":10,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Select Spalter","amount":{"value":10,"unit":"grams"},"add":"30","attribute":"Flavour"},{"name":"Select Spalter","amount":{"value":10,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Triskel","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Triskel","amount":{"value":30,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"W34/70"},"food_pairing":["Chilean ChorIPAn","Black Bean Tostadas with Avocado Salsa","Sushi"],"brewers_tips":"Condition the beer for at least 15 days at 1°C.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-360', 'diydog', '360', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/360.json', 'Heist Monkey (Fanzine)', 'American Pale Ale.', 'pale', 5.4, 45, 1.048, 1.01, 10, 20, 'heist monkey (fanzine) american pale ale. pale ale pale ale caramalt hallertauer taurus hallertauer blanc mosaic simcoe columbus hallertauer blanc mosaic simcoe columbus centennial citra mandarina bavaria wyeast 1272', '{"schemaVersion":1,"name":"Heist Monkey (Fanzine)","style":"Pale ale","description":"American Pale Ale.\n\nA Fanzine exclusive American pale ale, aggressively dry hopped with a range of new world varieties.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":53,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.76},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.48}],"hops":[{"id":"h1","name":"Hallertauer Taurus","amountG":1,"use":"boil","timeMin":60},{"id":"h2","name":"Hallertauer Blanc","amountG":4,"use":"boil","timeMin":15},{"id":"h3","name":"Mosaic","amountG":4,"use":"boil","timeMin":15},{"id":"h4","name":"Simcoe","amountG":4,"use":"boil","timeMin":15},{"id":"h5","name":"Columbus","amountG":4,"use":"boil","timeMin":15},{"id":"h6","name":"Hallertauer Blanc","amountG":16,"use":"boil","timeMin":0},{"id":"h7","name":"Mosaic","amountG":16,"use":"boil","timeMin":0},{"id":"h8","name":"Simcoe","amountG":16,"use":"boil","timeMin":0},{"id":"h9","name":"Columbus","amountG":16,"use":"boil","timeMin":0},{"id":"h10","name":"Centennial","amountG":80,"use":"dry_hop"},{"id":"h11","name":"Citra","amountG":80,"use":"dry_hop"},{"id":"h12","name":"Mandarina Bavaria","amountG":80,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":79}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":25}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.048,"fg":1.01,"ibu":45,"abvPct":5.4,"colorEbc":10},"notes":"Bryggetips: Depending on the yeast strain and hops you’re using, you can benefit from the effect of “biotransformation” by dry hopping before the primary fermentation is finished. Some yeasts are capable of extracting extra flavours from the hops. The earlier you dry hop in the fermentation process, the more flavour is extracted from the hops through the process of biotransformation, however at the same time more flavour also disappears again through the stripping effect of the generated CO2. A good balance is to add the hops just before primary fermentation is finished.\n\nFørst brygget: 2018"}', '{"id":360,"name":"Heist Monkey (Fanzine)","tagline":"American Pale Ale.","first_brewed":"2018","description":"A Fanzine exclusive American pale ale, aggressively dry hopped with a range of new world varieties.","image":"360.png","abv":5.4,"ibu":45,"target_fg":1010,"target_og":1048,"ebc":10,"srm":5,"ph":4.4,"attenuation_level":79,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":25}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.76,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.48,"unit":"kilograms"}}],"hops":[{"name":"Hallertauer Taurus","amount":{"value":1,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Hallertauer Blanc","amount":{"value":4,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"Mosaic","amount":{"value":4,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"Simcoe","amount":{"value":4,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"Columbus","amount":{"value":4,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"Hallertauer Blanc","amount":{"value":16,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":16,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":16,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Columbus","amount":{"value":16,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Centennial","amount":{"value":80,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Citra","amount":{"value":80,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mandarina Bavaria","amount":{"value":80,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Sparkenhoe Red Leicester","Huevos Rancheros","Margherita Pizza"],"brewers_tips":"Depending on the yeast strain and hops you’re using, you can benefit from the effect of “biotransformation” by dry hopping before the primary fermentation is finished. Some yeasts are capable of extracting extra flavours from the hops. The earlier you dry hop in the fermentation process, the more flavour is extracted from the hops through the process of biotransformation, however at the same time more flavour also disappears again through the stripping effect of the generated CO2. A good balance is to add the hops just before primary fermentation is finished.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-361', 'diydog', '361', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/361.json', 'King Of Eights V4 (German Hop Edition)', 'German-Hopped New England IPA.', 'ipa', 7.4, 20, 1.069, 1.012, 20, 20, 'king of eights v4 (german hop edition) german-hopped new england ipa. ipa pale ale wheat malt flaked oat malt citra citra ariana huell melon wyeast 1272', '{"schemaVersion":1,"name":"King Of Eights V4 (German Hop Edition)","style":"IPA","description":"German-Hopped New England IPA.\n\nThe last planned twist on King of Eights for the foreseeable future, this version showcases the flavours of new German hops in a lightly hazy New England IPA.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":78,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.16},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.36},{"id":"f3","name":"Flaked Oat Malt","type":"grain","amountKg":0.6}],"hops":[{"id":"h1","name":"Citra","amountG":2,"use":"boil","timeMin":70},{"id":"h2","name":"Citra","amountG":30,"use":"boil","timeMin":10},{"id":"h3","name":"Ariana","amountG":80,"use":"dry_hop"},{"id":"h4","name":"Huell Melon","amountG":80,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":66,"durationMin":21}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.069,"fg":1.012,"ibu":20,"abvPct":7.4,"colorEbc":20},"notes":"Bryggetips: Don''t cool the beer too cold after fermentation or you will loose the haze, 3°C should do.\n\nFørst brygget: 2018"}', '{"id":361,"name":"King Of Eights V4 (German Hop Edition)","tagline":"German-Hopped New England IPA.","first_brewed":"2018","description":"The last planned twist on King of Eights for the foreseeable future, this version showcases the flavours of new German hops in a lightly hazy New England IPA.","image":"361.png","abv":7.4,"ibu":20,"target_fg":1012,"target_og":1069,"ebc":20,"srm":10,"ph":4.4,"attenuation_level":83,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":66,"unit":"celsius"},"duration":21}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.16,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.6,"unit":"kilograms"}}],"hops":[{"name":"Citra","amount":{"value":2,"unit":"grams"},"add":"70","attribute":"Bitter"},{"name":"Citra","amount":{"value":30,"unit":"grams"},"add":"10","attribute":"Aroma"},{"name":"Ariana","amount":{"value":80,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Huell Melon","amount":{"value":80,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Allondigas Meatballs","Quadruple-Cheese Spätzle","Bienenstich"],"brewers_tips":"Don''t cool the beer too cold after fermentation or you will loose the haze, 3°C should do.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-362', 'diydog', '362', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/362.json', 'Alter Ego', 'West Coast IPA.', 'ipa', 8.5, 70, 1.071, 1.005, 18, 20, 'alter ego west coast ipa. ipa pale ale simpsons t50 simcoe co2 extract columbus chinook centennial simcoe chinook ahtanum simcoe amarillo cascade wyeast 1272', '{"schemaVersion":1,"name":"Alter Ego","style":"IPA","description":"West Coast IPA.\n\nA punchy IPA with a hefty hop bill. A deft touch of caramel and toast runs alongside massive hoppy aromas of pine, mango, grapefruit and lychee. Finishing with just a hint of sweetness, this classically West Coast IPA is dry, aggressive, and puts big hop flavours front and centre.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":82,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.86},{"id":"f2","name":"Simpsons T50","type":"grain","amountKg":0.12}],"hops":[{"id":"h1","name":"Simcoe CO2 Extract","amountG":2,"use":"boil","timeMin":60},{"id":"h2","name":"Columbus","amountG":12,"use":"boil","timeMin":60},{"id":"h3","name":"Chinook","amountG":20,"use":"boil","timeMin":10},{"id":"h4","name":"Centennial","amountG":20,"use":"boil","timeMin":0},{"id":"h5","name":"Simcoe","amountG":20,"use":"boil","timeMin":0},{"id":"h6","name":"Chinook","amountG":26,"use":"dry_hop"},{"id":"h7","name":"Ahtanum","amountG":20,"use":"dry_hop"},{"id":"h8","name":"Simcoe","amountG":20,"use":"dry_hop"},{"id":"h9","name":"Amarillo","amountG":4,"use":"dry_hop"},{"id":"h10","name":"Cascade","amountG":20,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":93}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.071,"fg":1.005,"ibu":70,"abvPct":8.5,"colorEbc":18},"notes":"Bryggetips: Be careful to use fresh hops for dry hopping.\n\nTwist: Dextrose: 120g\n\nFørst brygget: 2018"}', '{"id":362,"name":"Alter Ego","tagline":"West Coast IPA.","first_brewed":"2018","description":"A punchy IPA with a hefty hop bill. A deft touch of caramel and toast runs alongside massive hoppy aromas of pine, mango, grapefruit and lychee. Finishing with just a hint of sweetness, this classically West Coast IPA is dry, aggressive, and puts big hop flavours front and centre.","image":"362.png","abv":8.5,"ibu":70,"target_fg":1005,"target_og":1071,"ebc":18,"srm":9,"ph":4.6,"attenuation_level":93,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Dextrose: 120g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.86,"unit":"kilograms"}},{"name":"Simpsons T50","amount":{"value":0.12,"unit":"kilograms"}}],"hops":[{"name":"Simcoe CO2 Extract","amount":{"value":2,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Columbus","amount":{"value":12,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Chinook","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Centennial","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Chinook","amount":{"value":26,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Ahtanum","amount":{"value":20,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":20,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":4,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Cascade","amount":{"value":20,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Spicy Honey-Roasted Cashew Nuts","Dhaba-Style Punjabi Lamb Curry","Pumpkin Roulade with Ginger Buttercream"],"brewers_tips":"Be careful to use fresh hops for dry hopping.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-363', 'diydog', '363', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/363.json', 'Ten Ton Truck Black Forest (Fanzine)', 'Black Forest Imperial Stout.', 'stout', 10, 70, 1.1, 1.022, 360, 20, 'ten ton truck black forest (fanzine) black forest imperial stout. stout og porter pale ale caramalt brown malt chocolate malt chocolate wheat simpsons t50 cascade cascade wyeast 1272', '{"schemaVersion":1,"name":"Ten Ton Truck Black Forest (Fanzine)","style":"Stout og porter","description":"Black Forest Imperial Stout.\n\nA Fanzine imperial stout with additions of cherry and vanilla.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":73,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.76},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.48},{"id":"f3","name":"Brown Malt","type":"grain","amountKg":1.44},{"id":"f4","name":"Chocolate Malt","type":"grain","amountKg":0.6},{"id":"f5","name":"Chocolate Wheat","type":"grain","amountKg":0.48},{"id":"f6","name":"Simpsons T50","type":"grain","amountKg":0.72}],"hops":[{"id":"h1","name":"Cascade","amountG":30,"use":"boil","timeMin":60},{"id":"h2","name":"Cascade","amountG":30,"use":"boil","timeMin":20}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":78}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":63,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.1,"fg":1.022,"ibu":70,"abvPct":10,"colorEbc":360},"notes":"Bryggetips: When using berries, it is best to freeze them first to sanitise the fruit and to burst the cells within the fruit for maximum flavour extraction. They should also be added after primary fermentation, this will keep a lot more flavour and aroma in the beer as the secondary fermentation won''t be as mettlesome as the primary fermentation.\n\nTwist: Sour Cherry Juice: 250g FV Addition, Vanilla Extract: 140g FV Addition, English Heather Honey: 120g, Dextrose: 600g\n\nFørst brygget: 2018"}', '{"id":363,"name":"Ten Ton Truck Black Forest (Fanzine)","tagline":"Black Forest Imperial Stout.","first_brewed":"2018","description":"A Fanzine imperial stout with additions of cherry and vanilla.","image":"keg.png","abv":10,"ibu":70,"target_fg":1022,"target_og":1100,"ebc":360,"srm":183,"ph":4.5,"attenuation_level":78,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":63,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Sour Cherry Juice: 250g FV Addition, Vanilla Extract: 140g FV Addition, English Heather Honey: 120g, Dextrose: 600g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.76,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Brown Malt","amount":{"value":1.44,"unit":"kilograms"}},{"name":"Chocolate Malt","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Chocolate Wheat","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Simpsons T50","amount":{"value":0.72,"unit":"kilograms"}}],"hops":[{"name":"Cascade","amount":{"value":30,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Cascade","amount":{"value":30,"unit":"grams"},"add":"20","attribute":"Flavour"}],"yeast":"Wyeast 1272"},"food_pairing":["Godminster Vintage with Caramelised Cranberry Relish","A Massive Ribeye Steak","Mississippi Mud Pie"],"brewers_tips":"When using berries, it is best to freeze them first to sanitise the fruit and to burst the cells within the fruit for maximum flavour extraction. They should also be added after primary fermentation, this will keep a lot more flavour and aroma in the beer as the secondary fermentation won''t be as mettlesome as the primary fermentation.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-364', 'diydog', '364', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/364.json', 'Raspberry Blitz', 'Alcohol Free Sour.', 'sour', 0.5, 10, 1.0115, 1.008, 3, 20, 'raspberry blitz alcohol free sour. surøl pale ale wheat malt carapils malt flaked oat malt hallertauer taurus wyeast 1272', '{"schemaVersion":1,"name":"Raspberry Blitz","style":"Surøl","description":"Alcohol Free Sour.\n\nOne of our longest running brews returned as a brand new take on a fruity kettle sour. Inspired by our old favourite Berliner Weisse Raspberry Blitz, and using our recent Raspberry Popsicle Parade as a testing ground, this is an alcohol free Berliner Weisse, jam-packed with fruit flavour.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":0.1},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.1},{"id":"f3","name":"Carapils Malt","type":"grain","amountKg":0.13},{"id":"f4","name":"Flaked Oat Malt","type":"grain","amountKg":0.15}],"hops":[{"id":"h1","name":"Hallertauer Taurus","amountG":4,"use":"dry_hop","notes":"Tørrhumling 1"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":30}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":62,"durationMin":20}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.0115,"fg":1.008,"ibu":10,"abvPct":0.5,"colorEbc":3},"notes":"Bryggetips: For extra body, add a little milk sugars (lactose) to the brew.\n\nTwist: Raspberry Juice: 4kg FV Addition, Lactic Acid: 25g FV Addition, Malic Acid: 4g FV Addition\n\nFørst brygget: 2018"}', '{"id":364,"name":"Raspberry Blitz","tagline":"Alcohol Free Sour.","first_brewed":"2018","description":"One of our longest running brews returned as a brand new take on a fruity kettle sour. Inspired by our old favourite Berliner Weisse Raspberry Blitz, and using our recent Raspberry Popsicle Parade as a testing ground, this is an alcohol free Berliner Weisse, jam-packed with fruit flavour.","image":"364.png","abv":0.5,"ibu":10,"target_fg":1008,"target_og":1011.5,"ebc":3,"srm":2,"ph":3.8,"attenuation_level":30,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":62,"unit":"celsius"},"duration":20}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Raspberry Juice: 4kg FV Addition, Lactic Acid: 25g FV Addition, Malic Acid: 4g FV Addition"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":0.1,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.1,"unit":"kilograms"}},{"name":"Carapils Malt","amount":{"value":0.13,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.15,"unit":"kilograms"}}],"hops":[{"name":"Hallertauer Taurus","amount":{"value":4,"unit":"grams"},"add":"HD1","attribute":"Bitter"}],"yeast":"Wyeast 1272"},"food_pairing":["Balsamic Glazed Chicken","Brie and Goats Cheese Topped Pizza","White Chocolate Cookies"],"brewers_tips":"For extra body, add a little milk sugars (lactose) to the brew.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Malt og OG i kilden gir 166 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-365', 'diydog', '365', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/365.json', 'Sonic Boom V3', 'Euro-Hopped IPA.', 'ipa', 6.5, 60, 1.057, 1.006, 11, 20, 'sonic boom v3 euro-hopped ipa. ipa pale ale wheat malt carapils malt simcoe co2 extract cascade centennial german cascade centennial ariana aurora wyeast 1272', '{"schemaVersion":1,"name":"Sonic Boom V3","style":"IPA","description":"Euro-Hopped IPA.\n\nExperimental IPA Series. Replacing our single hop series, this series of IPAs will allow our brew team to experiment with hops, with the base beer unchanging from release to release. New and experimental varieties, new hopping techniques, or whatever they want to do to evolve the beer each time round.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":79,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.38},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.36},{"id":"f3","name":"Carapils Malt","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Simcoe CO2 Extract","amountG":4,"use":"boil","timeMin":60},{"id":"h2","name":"Cascade","amountG":20,"use":"boil","timeMin":10},{"id":"h3","name":"Centennial","amountG":30,"use":"boil","timeMin":0},{"id":"h4","name":"German Cascade","amountG":40,"use":"dry_hop"},{"id":"h5","name":"Centennial","amountG":40,"use":"dry_hop"},{"id":"h6","name":"Ariana","amountG":40,"use":"dry_hop"},{"id":"h7","name":"Aurora","amountG":60,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":89}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.057,"fg":1.006,"ibu":60,"abvPct":6.5,"colorEbc":11},"notes":"Bryggetips: Make sure your hops have been stored in an oxygen free environment, especially for the dry hops.\n\nFørst brygget: 2018"}', '{"id":365,"name":"Sonic Boom V3","tagline":"Euro-Hopped IPA.","first_brewed":"2018","description":"Experimental IPA Series. Replacing our single hop series, this series of IPAs will allow our brew team to experiment with hops, with the base beer unchanging from release to release. New and experimental varieties, new hopping techniques, or whatever they want to do to evolve the beer each time round.","image":"365.png","abv":6.5,"ibu":60,"target_fg":1006,"target_og":1057,"ebc":11,"srm":6,"ph":4.6,"attenuation_level":89,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.38,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Carapils Malt","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Simcoe CO2 Extract","amount":{"value":4,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Cascade","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Centennial","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"German Cascade","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Centennial","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Ariana","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Aurora","amount":{"value":60,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Moroccan Chicken Tagine","Orange Blossom Madeleines","Razor Clams with Sauce Verge"],"brewers_tips":"Make sure your hops have been stored in an oxygen free environment, especially for the dry hops.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-366', 'diydog', '366', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/366.json', 'Lost Lager', 'Dry-Hopped Pilsner.', 'lager', 4.7, 37, 1.042, 1.006, 5, 20, 'lost lager dry-hopped pilsner. lager og pils pilsner malt carapils malt hallertauer taurus select spalter select spalter saphir saphir w34/70', '{"schemaVersion":1,"name":"Lost Lager","style":"Lager og pils","description":"Dry-Hopped Pilsner.\n\nA pilsner that combines the light, crisp and clean lager profile provided by Weihenstephan''s house yeast, with the vibrant citrus and stonefruit aromas associated with new German hop Saphir. This lager is easy-going but has subtle depths; toast, hints of spice and a zesty lime marmalade character.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":81,"fermentables":[{"id":"f1","name":"Pilsner Malt","type":"grain","amountKg":3.36},{"id":"f2","name":"Carapils Malt","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Hallertauer Taurus","amountG":8,"use":"boil","timeMin":60},{"id":"h2","name":"Select Spalter","amountG":15,"use":"boil","timeMin":20},{"id":"h3","name":"Select Spalter","amountG":15,"use":"boil","timeMin":10},{"id":"h4","name":"Saphir","amountG":30,"use":"boil","timeMin":0},{"id":"h5","name":"Saphir","amountG":30,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"W34/70","form":"dry","amount":1,"unit":"pkg","attenuationPct":86}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":65}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":11}],"targets":{"og":1.042,"fg":1.006,"ibu":37,"abvPct":4.7,"colorEbc":5},"notes":"Bryggetips: Temperature control is extremely important for Lager, fermentation temperature around 10-12°C and a maturation period of 3-4 weeks at 1.5-2°C is ideal.\n\nTwist: Amyloglucosidase: 1g\n\nFørst brygget: 2018"}', '{"id":366,"name":"Lost Lager","tagline":"Dry-Hopped Pilsner.","first_brewed":"2018","description":"A pilsner that combines the light, crisp and clean lager profile provided by Weihenstephan''s house yeast, with the vibrant citrus and stonefruit aromas associated with new German hop Saphir. This lager is easy-going but has subtle depths; toast, hints of spice and a zesty lime marmalade character.","image":"366.png","abv":4.7,"ibu":37,"target_fg":1006,"target_og":1042,"ebc":5,"srm":3,"ph":4.4,"attenuation_level":86,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":65}],"fermentation":{"temp":{"value":11,"unit":"celsius"}},"twist":"Amyloglucosidase: 1g"},"ingredients":{"malt":[{"name":"Pilsner Malt","amount":{"value":3.36,"unit":"kilograms"}},{"name":"Carapils Malt","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Hallertauer Taurus","amount":{"value":8,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Select Spalter","amount":{"value":15,"unit":"grams"},"add":"20","attribute":"Flavour"},{"name":"Select Spalter","amount":{"value":15,"unit":"grams"},"add":"10","attribute":"Aroma"},{"name":"Saphir","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Saphir","amount":{"value":30,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"W34/70"},"food_pairing":["Vietnamese Pho","Buffalo Chicken Wings","Sashimi"],"brewers_tips":"Temperature control is extremely important for Lager, fermentation temperature around 10-12°C and a maturation period of 3-4 weeks at 1.5-2°C is ideal.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-367', 'diydog', '367', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/367.json', 'Opaque Jake V2 (Fanzine)', 'New England IPA.', 'ipa', 7.2, 20, 1.068, 1.013, 40, 20, 'opaque jake v2 (fanzine) new england ipa. ipa pale ale wheat malt flaked oat milk citra citra citra mosaic wyeast 1272', '{"schemaVersion":1,"name":"Opaque Jake V2 (Fanzine)","style":"IPA","description":"New England IPA.\n\nA full scale, tweaked version of a tiny batch tested out early in 2018.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":78,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.04},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.36},{"id":"f3","name":"Flaked Oat Milk","type":"grain","amountKg":0.6}],"hops":[{"id":"h1","name":"Citra","amountG":2,"use":"boil","timeMin":70},{"id":"h2","name":"Citra","amountG":30,"use":"boil","timeMin":0},{"id":"h3","name":"Citra","amountG":100,"use":"dry_hop"},{"id":"h4","name":"Mosaic","amountG":100,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":81}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":66,"durationMin":21}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.068,"fg":1.013,"ibu":20,"abvPct":7.2,"colorEbc":40},"notes":"Bryggetips: Pectin is added to give some stable haziness in the beer.\n\nTwist: Pectin Powder: 2g\n\nFørst brygget: 2018"}', '{"id":367,"name":"Opaque Jake V2 (Fanzine)","tagline":"New England IPA.","first_brewed":"2018","description":"A full scale, tweaked version of a tiny batch tested out early in 2018.","image":"367.png","abv":7.2,"ibu":20,"target_fg":1013,"target_og":1068,"ebc":40,"srm":20,"ph":4.4,"attenuation_level":81,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":66,"unit":"celsius"},"duration":21}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Pectin Powder: 2g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.04,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Flaked Oat Milk","amount":{"value":0.6,"unit":"kilograms"}}],"hops":[{"name":"Citra","amount":{"value":2,"unit":"grams"},"add":"70","attribute":"Bitter"},{"name":"Citra","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":100,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":100,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Manchego","Vietnamese Tuna Burger","Mango and Cardamom Syllabub"],"brewers_tips":"Pectin is added to give some stable haziness in the beer.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-368', 'diydog', '368', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/368.json', 'Scarlet Fever (Fanzine)', 'Red Rye Saison.', 'belgian', 5.4, 10, 1.054, 1.005, 30, 20, 'scarlet fever (fanzine) red rye saison. belgisk og saison pilsner malt vienna malt munich malt rye malt extra dark crystal malt torrified barley sterling fuggles saaz east kent goldings be-134', '{"schemaVersion":1,"name":"Scarlet Fever (Fanzine)","style":"Belgisk og saison","description":"Red Rye Saison.\n\nA more traditional style of saison, with additions of rye, citrus peel and peppercorns.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":82,"fermentables":[{"id":"f1","name":"Pilsner Malt","type":"grain","amountKg":2.88},{"id":"f2","name":"Vienna Malt","type":"grain","amountKg":0.6},{"id":"f3","name":"Munich Malt","type":"grain","amountKg":0.24},{"id":"f4","name":"Rye Malt","type":"grain","amountKg":0.36},{"id":"f5","name":"Extra Dark Crystal Malt","type":"grain","amountKg":0.12},{"id":"f6","name":"Torrified Barley","type":"grain","amountKg":0.36}],"hops":[{"id":"h1","name":"Sterling","amountG":18,"use":"first_wort","timeMin":60},{"id":"h2","name":"Fuggles","amountG":20,"use":"boil","timeMin":0},{"id":"h3","name":"Saaz","amountG":10,"use":"boil","timeMin":0},{"id":"h4","name":"East Kent Goldings","amountG":20,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Be-134","form":"other","amount":1,"unit":"pkg","attenuationPct":91}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":63,"durationMin":80}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.054,"fg":1.005,"ibu":10,"abvPct":5.4,"colorEbc":30},"notes":"Bryggetips: When using spices it is best to add them at flame out for no more than 15 minutes, too long or at too high a heat can result in unwanted bitterness.\n\nTwist: Amyloglucosidase: 10g, Bitter Orange Peel: 10g, Sweet Orange Peel: 10g, Pink Peppercorns: 2g, Grains of Paradise: 2g\n\nFørst brygget: 2018"}', '{"id":368,"name":"Scarlet Fever (Fanzine)","tagline":"Red Rye Saison.","first_brewed":"2018","description":"A more traditional style of saison, with additions of rye, citrus peel and peppercorns.","image":"368.png","abv":5.4,"ibu":10,"target_fg":1005,"target_og":1054,"ebc":30,"srm":15,"ph":4.2,"attenuation_level":91,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":63,"unit":"celsius"},"duration":80}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Amyloglucosidase: 10g, Bitter Orange Peel: 10g, Sweet Orange Peel: 10g, Pink Peppercorns: 2g, Grains of Paradise: 2g"},"ingredients":{"malt":[{"name":"Pilsner Malt","amount":{"value":2.88,"unit":"kilograms"}},{"name":"Vienna Malt","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Munich Malt","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Rye Malt","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Extra Dark Crystal Malt","amount":{"value":0.12,"unit":"kilograms"}},{"name":"Torrified Barley","amount":{"value":0.36,"unit":"kilograms"}}],"hops":[{"name":"Sterling","amount":{"value":18,"unit":"grams"},"add":"FWH","attribute":"Bitter"},{"name":"Fuggles","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Saaz","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"East Kent Goldings","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"}],"yeast":"Be-134"},"food_pairing":["Stoemp","Bouillabaisse","Oliebol"],"brewers_tips":"When using spices it is best to add them at flame out for no more than 15 minutes, too long or at too high a heat can result in unwanted bitterness.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
