INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-370', 'diydog', '370', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/370.json', 'Brutalist (Fanzine)', 'Brut India Pale Ale.', 'ipa', 6, 20, 1.048, 1, 9, 20, 'brutalist (fanzine) brut india pale ale. ipa pilsner malt hallertauer taurus hallertauer blanc hallertauer blanc ariana mosaic wyeast 1272', '{"schemaVersion":1,"name":"Brutalist (Fanzine)","style":"IPA","description":"Brut India Pale Ale.\n\nOur first Brut IPA brewed in Ellon, for Fanzine. A bone dry, tropical, Sauvignon-like IPA, with a champagne-like body, exceptionally dry and effervescent.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":84,"fermentables":[{"id":"f1","name":"Pilsner Malt","type":"grain","amountKg":3.96}],"hops":[{"id":"h1","name":"Hallertauer Taurus","amountG":5,"use":"boil","timeMin":70},{"id":"h2","name":"Hallertauer Blanc","amountG":30,"use":"boil","timeMin":0},{"id":"h3","name":"Hallertauer Blanc","amountG":80,"use":"dry_hop"},{"id":"h4","name":"Ariana","amountG":40,"use":"dry_hop"},{"id":"h5","name":"Mosaic","amountG":40,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":100}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":75}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.048,"fg":1,"ibu":20,"abvPct":6,"colorEbc":9},"notes":"Bryggetips: Pay special attention to that initial low mash temperature in order to get the body right on the final beer.\n\nTwist: Amyloglucosidase: 10g, Dextrose: 240g\n\nFørst brygget: 2018"}', '{"id":370,"name":"Brutalist (Fanzine)","tagline":"Brut India Pale Ale.","first_brewed":"2018","description":"Our first Brut IPA brewed in Ellon, for Fanzine. A bone dry, tropical, Sauvignon-like IPA, with a champagne-like body, exceptionally dry and effervescent.","image":"370.png","abv":6,"ibu":20,"target_fg":1000,"target_og":1048,"ebc":9,"srm":5,"ph":4.4,"attenuation_level":100,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":75}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Amyloglucosidase: 10g, Dextrose: 240g"},"ingredients":{"malt":[{"name":"Pilsner Malt","amount":{"value":3.96,"unit":"kilograms"}}],"hops":[{"name":"Hallertauer Taurus","amount":{"value":5,"unit":"grams"},"add":"70","attribute":"Bitter"},{"name":"Hallertauer Blanc","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Hallertauer Blanc","amount":{"value":80,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Ariana","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Salt + Pepper Tofu","Melon Fruit Salad","Oysters"],"brewers_tips":"Pay special attention to that initial low mash temperature in order to get the body right on the final beer.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-371', 'diydog', '371', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/371.json', 'Flux Factory (Fanzine)', 'West Coast IPA.', 'ipa', 6.1, 60, 1.055, 1.008, 18, 20, 'flux factory (fanzine) west coast ipa. ipa pale ale wheat malt munich malt simcoe co2 extract cascade centennial simcoe cascade centennial chinook simcoe mosaic wyeast 1272', '{"schemaVersion":1,"name":"Flux Factory (Fanzine)","style":"IPA","description":"West Coast IPA.\n\nA Fanzine West Coast IPA, heavily whirlpool and dry hopped, and with lower than normal kettle hopping.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":80,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.14},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.36},{"id":"f3","name":"Munich Malt","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Simcoe CO2 Extract","amountG":7,"use":"boil","timeMin":70},{"id":"h2","name":"Cascade","amountG":20,"use":"boil","timeMin":30},{"id":"h3","name":"Centennial","amountG":20,"use":"boil","timeMin":0},{"id":"h4","name":"Simcoe","amountG":20,"use":"boil","timeMin":0},{"id":"h5","name":"Cascade","amountG":10,"use":"dry_hop"},{"id":"h6","name":"Centennial","amountG":20,"use":"dry_hop"},{"id":"h7","name":"Chinook","amountG":20,"use":"dry_hop"},{"id":"h8","name":"Simcoe","amountG":30,"use":"dry_hop"},{"id":"h9","name":"Mosaic","amountG":20,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":85}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":50}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.055,"fg":1.008,"ibu":60,"abvPct":6.1,"colorEbc":18},"notes":"Bryggetips: Depending on the yeast strain and hops you’re using, you can benefit from the effect of “biotransformation” by dry hopping before the primary fermentation is finished. Some yeasts are capable of extracting extra flavours from the hops. The earlier you dry hop in the fermentation process, the more flavour is extracted from the hops through the process of biotransformation, however at the same time more flavour also disappears again through the stripping effect of the generated CO2. A good balance is to add the hops just before primary fermentation is finished.\n\nFørst brygget: 2018"}', '{"id":371,"name":"Flux Factory (Fanzine)","tagline":"West Coast IPA.","first_brewed":"2018","description":"A Fanzine West Coast IPA, heavily whirlpool and dry hopped, and with lower than normal kettle hopping.","image":"371.png","abv":6.1,"ibu":60,"target_fg":1008,"target_og":1055,"ebc":18,"srm":9,"ph":4.6,"attenuation_level":85,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":50}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.14,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Munich Malt","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Simcoe CO2 Extract","amount":{"value":7,"unit":"grams"},"add":"70","attribute":"Bitter"},{"name":"Cascade","amount":{"value":20,"unit":"grams"},"add":"30","attribute":"Flavour"},{"name":"Centennial","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Cascade","amount":{"value":10,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Centennial","amount":{"value":20,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Chinook","amount":{"value":20,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":30,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":20,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Lasagne","Fried Chicken Sandwich","Boston Cream Pie"],"brewers_tips":"Depending on the yeast strain and hops you’re using, you can benefit from the effect of “biotransformation” by dry hopping before the primary fermentation is finished. Some yeasts are capable of extracting extra flavours from the hops. The earlier you dry hop in the fermentation process, the more flavour is extracted from the hops through the process of biotransformation, however at the same time more flavour also disappears again through the stripping effect of the generated CO2. A good balance is to add the hops just before primary fermentation is finished.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
