"image":"373.png","abv":5.4,"ibu":25,"target_fg":1010,"target_og":1050,"ebc":25,"srm":13,"ph":4.2,"attenuation_level":80,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":60}],"fermentation":{"temp":{"value":11,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pilsner Malt","amount":{"value":0.9,"unit":"kilograms"}},{"name":"Vienna Malt","amount":{"value":0.9,"unit":"kilograms"}},{"name":"Munich Malt Type 1","amount":{"value":1.8,"unit":"kilograms"}},{"name":"Munich Malt Type 2","amount":{"value":0.72,"unit":"kilograms"}},{"name":"English Cara Malt","amount":{"value":0.18,"unit":"kilograms"}}],"hops":[{"name":"Tettnang","amount":{"value":10,"unit":"grams"},"add":"FWH","attribute":"Bitter"},{"name":"Tettnang","amount":{"value":20,"unit":"grams"},"add":"30","attribute":"Flavour"},{"name":"Tettnang","amount":{"value":20,"unit":"grams"},"add":"15","attribute":"Flavour"}],"yeast":"W34/70"},"food_pairing":["Weisswurst with Mustard and Pretzels","Smoky Lamb Rendang","Lemon Cheesecake"],"brewers_tips":"Condition the beer for at least 15 days at 1°C.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-374', 'diydog', '374', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/374.json', 'Straight Up', 'Single Hop IPA.', 'ipa', 6.5, 65, 1.058, 1.008, 25, 20, 'straight up single hop ipa. ipa pale ale medium crystal malt ahtanum ahtanum ahtanum ahtanum ahtanum wyeast 1272', '{"schemaVersion":1,"name":"Straight Up","style":"IPA","description":"Single Hop IPA.\n\nA single hop IPA showcasing ahtanum, a hop that we use more than anyone else in the world. This single hop IPA is a USA style IPA.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":81,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.8},{"id":"f2","name":"Medium Crystal Malt","type":"grain","amountKg":0.18}],"hops":[{"id":"h1","name":"Ahtanum","amountG":20,"use":"first_wort","timeMin":60},{"id":"h2","name":"Ahtanum","amountG":20,"use":"boil","timeMin":30},{"id":"h3","name":"Ahtanum","amountG":20,"use":"boil","timeMin":10},{"id":"h4","name":"Ahtanum","amountG":60,"use":"boil","timeMin":0},{"id":"h5","name":"Ahtanum","amountG":150,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":86}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":45}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.058,"fg":1.008,"ibu":65,"abvPct":6.5,"colorEbc":25},"notes":"Bryggetips: Make sure and follow the WK dosing schedule, these single hop beers get their complexity by adding hops at different times.\n\nFørst brygget: 2018"}', '{"id":374,"name":"Straight Up","tagline":"Single Hop IPA.","first_brewed":"2018","description":"A single hop IPA showcasing ahtanum, a hop that we use more than anyone else in the world. This single hop IPA is a USA style IPA.","image":"374.png","abv":6.5,"ibu":65,"target_fg":1008,"target_og":1058,"ebc":25,"srm":13,"ph":4.2,"attenuation_level":86,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":45}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.8,"unit":"kilograms"}},{"name":"Medium Crystal Malt","amount":{"value":0.18,"unit":"kilograms"}}],"hops":[{"name":"Ahtanum","amount":{"value":20,"unit":"grams"},"add":"FWH","attribute":"Bitter"},{"name":"Ahtanum","amount":{"value":20,"unit":"grams"},"add":"30","attribute":"Flavour"},{"name":"Ahtanum","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Ahtanum","amount":{"value":60,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Ahtanum","amount":{"value":150,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Goats Cheese and Caramelised Onion Tart","Moroccan Chicken Tagine","Mild Blue Cheese"],"brewers_tips":"Make sure and follow the WK dosing schedule, these single hop beers get their complexity by adding hops at different times.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-375', 'diydog', '375', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/375.json', 'Paradox Uncle Duke''s (Barrel Aged)', 'Whisky Cask Aged Imperial Stout.', 'stout', 13, 40, 1.112, 1.015, 250, 20, 'paradox uncle duke''s (barrel aged) whisky cask aged imperial stout. stout og porter pale ale caramalt munich malt extra dark crystal malt carafa special type 1 carafa special type 3 flaked oat malt columbus columbus saaz hallertauer mittelfruh wyeast 1272', '{"schemaVersion":1,"name":"Paradox Uncle Duke''s (Barrel Aged)","style":"Stout og porter","description":"Whisky Cask Aged Imperial Stout.\n\nAn imperial stout that has been aged in oak barrels that contained Uncle Duke''s, our category defying Bourbon/Scotch whisky.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":75,"efficiencyPct":70,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":6.24},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.84},{"id":"f3","name":"Munich Malt","type":"grain","amountKg":0.48},{"id":"f4","name":"Extra Dark Crystal Malt","type":"grain","amountKg":0.84},{"id":"f5","name":"Carafa Special Type 1","type":"grain","amountKg":0.24},{"id":"f6","name":"Carafa Special Type 3","type":"grain","amountKg":0.48},{"id":"f7","name":"Flaked Oat Malt","type":"grain","amountKg":1.92}],"hops":[{"id":"h1","name":"Columbus","amountG":60,"use":"boil","timeMin":75},{"id":"h2","name":"Columbus","amountG":20,"use":"boil","timeMin":30},{"id":"h3","name":"Saaz","amountG":20,"use":"boil","timeMin":0},{"id":"h4","name":"Hallertauer Mittelfruh","amountG":20,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":87}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":60}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":18}],"targets":{"og":1.112,"fg":1.015,"ibu":40,"abvPct":13,"colorEbc":250},"notes":"Bryggetips: If you’re are lucky enough to own a barrel to age your beers in, be sure to take good care of it. Especially when barrels are empty, they need some TLC. When you don’t have beer in the barrel always keep it full of water to prevent it drying out. Getting a dry barrel to stop leaking is very hard to impossible. Should you encounter microbiological problems, burning sulphur wicks in the barrel or keeping it filled up with a sulphite/citric acid solution can help.\n\nTwist: Uncle Duke''s Soaked Oak Chips: 10g FV\n\nFørst brygget: 2018"}', '{"id":375,"name":"Paradox Uncle Duke''s (Barrel Aged)","tagline":"Whisky Cask Aged Imperial Stout.","first_brewed":"2018","description":"An imperial stout that has been aged in oak barrels that contained Uncle Duke''s, our category defying Bourbon/Scotch whisky.","image":"375.png","abv":13,"ibu":40,"target_fg":1015,"target_og":1112,"ebc":250,"srm":127,"ph":4.4,"attenuation_level":87,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":60}],"fermentation":{"temp":{"value":18,"unit":"celsius"}},"twist":"Uncle Duke''s Soaked Oak Chips: 10g FV"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":6.24,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.84,"unit":"kilograms"}},{"name":"Munich Malt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Extra Dark Crystal Malt","amount":{"value":0.84,"unit":"kilograms"}},{"name":"Carafa Special Type 1","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Carafa Special Type 3","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":1.92,"unit":"kilograms"}}],"hops":[{"name":"Columbus","amount":{"value":60,"unit":"grams"},"add":"75","attribute":"Bitter"},{"name":"Columbus","amount":{"value":20,"unit":"grams"},"add":"30","attribute":"Flavour"},{"name":"Saaz","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Hallertauer Mittelfruh","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Pork Ribs","Game Pie","Honey and Garlic Roasted Vegetables"],"brewers_tips":"If you’re are lucky enough to own a barrel to age your beers in, be sure to take good care of it. Especially when barrels are empty, they need some TLC. When you don’t have beer in the barrel always keep it full of water to prevent it drying out. Getting a dry barrel to stop leaking is very hard to impossible. Should you encounter microbiological problems, burning sulphur wicks in the barrel or keeping it filled up with a sulphite/citric acid solution can help.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-376', 'diydog', '376', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/376.json', 'Red & Dead (Fanzine)', 'Imperial Red IPA.', 'ipa', 8, 65, 1.076, 1.015, 75, 20, 'red & dead (fanzine) imperial red ipa. ipa pale ale carared malt munich malt extra dark crystal malt medium crystal malt hallertauer taurus citra simcoe citra simcoe huell melon simcoe citra cascade amarillo huell melon wyeast 1272', '{"schemaVersion":1,"name":"Red & Dead (Fanzine)","style":"IPA","description":"Imperial Red IPA.\n\nA Fanzine release, this imperial red IPA is part of a Halloween inspired issue. Big rounded sweet character drawn from a range of malt varieties, while an apple-like character is hinted at through the fermentation profile.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":90,"efficiencyPct":84,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3.55},{"id":"f2","name":"CaraRed Malt","type":"grain","amountKg":1.2},{"id":"f3","name":"Munich Malt","type":"grain","amountKg":0.83},{"id":"f4","name":"Extra Dark Crystal Malt","type":"grain","amountKg":0.09},{"id":"f5","name":"Medium Crystal Malt","type":"grain","amountKg":0.55}],"hops":[{"id":"h1","name":"Hallertauer Taurus","amountG":12,"use":"boil","timeMin":90},{"id":"h2","name":"Citra","amountG":6,"use":"boil","timeMin":10},{"id":"h3","name":"Simcoe","amountG":6,"use":"boil","timeMin":10},{"id":"h4","name":"Citra","amountG":9,"use":"boil","timeMin":0},{"id":"h5","name":"Simcoe","amountG":9,"use":"boil","timeMin":0},{"id":"h6","name":"Huell Melon","amountG":15,"use":"boil","timeMin":0},{"id":"h7","name":"Simcoe","amountG":71,"use":"dry_hop"},{"id":"h8","name":"Citra","amountG":71,"use":"dry_hop"},{"id":"h9","name":"Cascade","amountG":71,"use":"dry_hop"},{"id":"h10","name":"Amarillo","amountG":47,"use":"dry_hop"},{"id":"h11","name":"Huell Melon","amountG":47,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":80}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":35}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.076,"fg":1.015,"ibu":65,"abvPct":8,"colorEbc":75},"notes":"Bryggetips: The malt backbone of this brew would easily allow for creating a dank red ale by changing the hops for West Coast hops, columbus, chinook, cascade and centennial.\n\nFørst brygget: 2018"}', '{"id":376,"name":"Red & Dead (Fanzine)","tagline":"Imperial Red IPA.","first_brewed":"2018","description":"A Fanzine release, this imperial red IPA is part of a Halloween inspired issue. Big rounded sweet character drawn from a range of malt varieties, while an apple-like character is hinted at through the fermentation profile.","image":"376.png","abv":8,"ibu":65,"target_fg":1015,"target_og":1076,"ebc":75,"srm":38,"ph":4.2,"attenuation_level":80,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":35}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3.55,"unit":"kilograms"}},{"name":"CaraRed Malt","amount":{"value":1.2,"unit":"kilograms"}},{"name":"Munich Malt","amount":{"value":0.83,"unit":"kilograms"}},{"name":"Extra Dark Crystal Malt","amount":{"value":0.09,"unit":"kilograms"}},{"name":"Medium Crystal Malt","amount":{"value":0.55,"unit":"kilograms"}}],"hops":[{"name":"Hallertauer Taurus","amount":{"value":12,"unit":"grams"},"add":"90","attribute":"Bitter"},{"name":"Citra","amount":{"value":6,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Simcoe","amount":{"value":6,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Citra","amount":{"value":9,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":9,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Huell Melon","amount":{"value":15,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":71,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Citra","amount":{"value":71,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Cascade","amount":{"value":71,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":47,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Huell Melon","amount":{"value":47,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Toffee Apples","Pumpkin Pie","Sugared Doughnuts"],"brewers_tips":"The malt backbone of this brew would easily allow for creating a dank red ale by changing the hops for West Coast hops, columbus, chinook, cascade and centennial.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
