INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-382', 'diydog', '382', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/382.json', 'Mistletoe Mafia', 'Toasty Amber Lager.', 'lager', 4.5, 25, 1.044, 1.009, 15, 20, 'mistletoe mafia toasty amber lager. lager og pils pilsner vienna munich malt type 2 carahell malt carared malt mandarina bavaria saphir tettnang w34/70', '{"schemaVersion":1,"name":"Mistletoe Mafia","style":"Lager og pils","description":"Toasty Amber Lager.\n\nAn easy-going Vienna style lager, packed with complex yet subtle malt flavours, at sessionable strength. Available for the Festive period only.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":65,"efficiencyPct":82,"fermentables":[{"id":"f1","name":"Pilsner","type":"grain","amountKg":1.44},{"id":"f2","name":"Vienna","type":"grain","amountKg":1.44},{"id":"f3","name":"Munich Malt Type 2","type":"grain","amountKg":0.48},{"id":"f4","name":"Carahell Malt","type":"grain","amountKg":0.18},{"id":"f5","name":"CaraRed Malt","type":"grain","amountKg":0.18}],"hops":[{"id":"h1","name":"Mandarina Bavaria","amountG":5,"use":"boil","timeMin":65},{"id":"h2","name":"Saphir","amountG":20,"use":"boil","timeMin":10},{"id":"h3","name":"Tettnang","amountG":20,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"W34/70","form":"dry","amount":1,"unit":"pkg","attenuationPct":80}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":67,"durationMin":85}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":10}],"targets":{"og":1.044,"fg":1.009,"ibu":25,"abvPct":4.5,"colorEbc":15},"notes":"Bryggetips: Condition for up to a month at 1°C for best results.\n\nFørst brygget: 2018"}', '{"id":382,"name":"Mistletoe Mafia","tagline":"Toasty Amber Lager.","first_brewed":"2018","description":"An easy-going Vienna style lager, packed with complex yet subtle malt flavours, at sessionable strength. Available for the Festive period only.","image":"382.png","abv":4.5,"ibu":25,"target_fg":1009,"target_og":1044,"ebc":15,"srm":8,"ph":4.2,"attenuation_level":80,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":67,"unit":"celsius"},"duration":85}],"fermentation":{"temp":{"value":10,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pilsner","amount":{"value":1.44,"unit":"kilograms"}},{"name":"Vienna","amount":{"value":1.44,"unit":"kilograms"}},{"name":"Munich Malt Type 2","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Carahell Malt","amount":{"value":0.18,"unit":"kilograms"}},{"name":"CaraRed Malt","amount":{"value":0.18,"unit":"kilograms"}}],"hops":[{"name":"Mandarina Bavaria","amount":{"value":5,"unit":"grams"},"add":"65","attribute":"Bitter"},{"name":"Saphir","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Tettnang","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"}],"yeast":"W34/70"},"food_pairing":["Sausages with Marmalade","Roast Chicken","Mac ''n'' Cheese with Crispy Pancetta"],"brewers_tips":"Condition for up to a month at 1°C for best results.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-383', 'diydog', '383', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/383.json', 'Caramel Carousel (Fanzine)', 'Caramel Scotch Ale.', 'amber', 8, 30, 1.085, 1.023, 45, 20, 'caramel carousel (fanzine) caramel scotch ale. amber, rød og brun pale ale munich malt caramalt medium crystal malt extra dark crystal malt wheat malt chocolate wheat beech smoked barley malt brown malt flaked oat malt hallertauer taurus wyeast 1272', '{"schemaVersion":1,"name":"Caramel Carousel (Fanzine)","style":"Amber, rød og brun","description":"Caramel Scotch Ale.\n\nA Scotch ale with flavours reminiscent of both Dogma and 5AM Saint. This caramelly, rounded wee heavy brewed for Fanzine, is infused with salt, bringing out the toffee notes and adding a softly savoury counterpoint to a huge, decadent beer.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":70,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":2.4},{"id":"f2","name":"Munich Malt","type":"grain","amountKg":1.92},{"id":"f3","name":"Caramalt","type":"grain","amountKg":0.48},{"id":"f4","name":"Medium Crystal Malt","type":"grain","amountKg":0.36},{"id":"f5","name":"Extra Dark Crystal Malt","type":"grain","amountKg":0.48},{"id":"f6","name":"Wheat Malt","type":"grain","amountKg":0.96},{"id":"f7","name":"Chocolate Wheat","type":"grain","amountKg":0.24},{"id":"f8","name":"Beech Smoked Barley Malt","type":"grain","amountKg":0.06},{"id":"f9","name":"Brown Malt","type":"grain","amountKg":0.48},{"id":"f10","name":"Flaked Oat Malt","type":"grain","amountKg":0.96}],"hops":[{"id":"h1","name":"Hallertauer Taurus","amountG":16,"use":"boil","timeMin":70}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":73}]