INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-393', 'diydog', '393', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/393.json', 'Pulp Patriot V3', 'Raspberry Dry Hop Edition.', 'other', 9.5, 10, 1.092, 1.018, 15, 20, 'pulp patriot v3 raspberry dry hop edition. annet pale ale wheat malt flaked oat malt dry malt extract citra simcoe ahtanum citra simcoe ahtanum wyeast 1272', '{"schemaVersion":1,"name":"Pulp Patriot V3","description":"Raspberry Dry Hop Edition.\n\nA 9.5% Raspberry dry hopped NEDIPA, brewed for Fanzine January issue.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":94,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.04},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.6},{"id":"f3","name":"Flaked Oat Malt","type":"grain","amountKg":0.6},{"id":"f4","name":"Dry Malt Extract","type":"grain","amountKg":0.5}],"hops":[{"id":"h1","name":"Citra","amountG":10,"use":"boil","timeMin":0},{"id":"h2","name":"Simcoe","amountG":10,"use":"boil","timeMin":0},{"id":"h3","name":"Ahtanum","amountG":10,"use":"boil","timeMin":0},{"id":"h4","name":"Citra","amountG":120,"use":"dry_hop"},{"id":"h5","name":"Simcoe","amountG":80,"use":"dry_hop"},{"id":"h6","name":"Ahtanum","amountG":80,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":80}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":46}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.092,"fg":1.018,"ibu":10,"abvPct":9.5,"colorEbc":15},"notes":"Bryggetips: The best fruit juice to use will have the pectin removed.\n\nTwist: Raspberry Juice: 1.8kg FV Addition, Milk Sugars (Lactose): 500g\n\nFørst brygget: 2019"}', '{"id":393,"name":"Pulp Patriot V3","tagline":"Raspberry Dry Hop Edition.","first_brewed":"2019","description":"A 9.5% Raspberry dry hopped NEDIPA, brewed for Fanzine January issue.","image":"393.png","abv":9.5,"ibu":10,"target_fg":1018,"target_og":1092,"ebc":15,"srm":8,"ph":4.4,"attenuation_level":80,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":46}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Raspberry Juice: 1.8kg FV Addition, Milk Sugars (Lactose): 500g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.04,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Dry Malt Extract","amount":{"value":0.5,"unit":"kilograms"}}],"hops":[{"name":"Citra","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Ahtanum","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":120,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":80,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Ahtanum","amount":{"value":80,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Honey-Roasted Ham with Cranberry","Sweet and Sticky BBQ Ribs","New York Cheesecake"],"brewers_tips":"The best fruit juice to use will have the pectin removed.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-394', 'diydog', '394', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/394.json', 'Half Eagle 2.7%', 'Half Pale Ale.', 'pale', 2.7, 50, 1.029, 1.008, 8, 20, 'half eagle 2.7% half pale ale. pale ale pale ale wheat malt carapils malt munich malt flaked oat malt simcoe chinook chinook simcoe simcoe mosaic centennial wyeast 1272', '{"schemaVersion":1,"name":"Half Eagle 2.7%","style":"Pale ale","description":"Half Pale Ale.\n\nA low ABV version of an American pale ale. Retaining the hop profile but dialling down the basic malts. The addition of wheat and oats adds structure to support the lower pale malt base. The hop levels are still in line with our pale and hoppy core beers.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":65,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":1.32},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.18},{"id":"f3","name":"Carapils Malt","type":"grain","amountKg":0.18},{"id":"f4","name":"Munich Malt","type":"grain","amountKg":0.18},{"id":"f5","name":"Flaked Oat Malt","type":"grain","amountKg":0.06}],"hops":[{"id":"h1","name":"Simcoe","amountG":10,"use":"boil","timeMin":65},{"id":"h2","name":"Chinook","amountG":10,"use":"boil","timeMin":10},{"id":"h3","name":"Chinook","amountG":20,"use":"boil","timeMin":0},{"id":"h4","name":"Simcoe","amountG":20,"use":"boil","timeMin":0},{"id":"h5","name":"Simcoe","amountG":40,"use":"dry_hop"},{"id":"h6","name":"Mosaic","amountG":40,"use":"dry_hop"},{"id":"h7","name":"Centennial","amountG":40,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":72}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":63,"durationMin":35}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.029,"fg":1.008,"ibu":50,"abvPct":2.7,"colorEbc":8},"notes":"Bryggetips: In any low ABV fermentation after primary fermentation has finished if the beer smells or tastes like wort, allow it to condition on the yeast for an extra 24 - 48 hours. This can round the profile off well.\n\nFørst brygget: 2019"}', '{"id":394,"name":"Half Eagle 2.7%","tagline":"Half Pale Ale.","first_brewed":"2019","description":"A low ABV version of an American pale ale. Retaining the hop profile but dialling down the basic malts. The addition of wheat and oats adds structure to support the lower pale malt base. The hop levels are still in line with our pale and hoppy core beers.","image":"keg.png","abv":2.7,"ibu":50,"target_fg":1008,"target_og":1029,"ebc":8,"srm":4,"ph":4.32,"attenuation_level":72,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":63,"unit":"celsius"},"duration":35}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":1.32,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.18,"unit":"kilograms"}},{"name":"Carapils Malt","amount":{"value":0.18,"unit":"kilograms"}},{"name":"Munich Malt","amount":{"value":0.18,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.06,"unit":"kilograms"}}],"hops":[{"name":"Simcoe","amount":{"value":10,"unit":"grams"},"add":"65","attribute":"Bitter"},{"name":"Chinook","amount":{"value":10,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Chinook","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Centennial","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Feta and Greens Salad with Citrus Dressing","Fried Calamari","Poached Eggs on Toast"],"brewers_tips":"In any low ABV fermentation after primary fermentation has finished if the beer smells or tastes like wort, allow it to condition on the yeast for an extra 24 - 48 hours. This can round the profile off well.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Malt og OG i kilden gir 104 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-395', 'diydog', '395', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/395.json', 'Two Way Street (BD vs Brygghuset Finn)', 'New England IPA.', 'ipa', 5.5, 30, 1.052, 1.01, 15, 20, 'two way street (bd vs brygghuset finn) new england ipa. ipa pale ale wheat malt flaked oat malt  chinook chinook amarillo simcoe mosaic citra simcoe amarillo mosaic wyeast 1272', '{"schemaVersion":1,"name":"Two Way Street (BD vs Brygghuset Finn)","style":"IPA","description":"New England IPA.\n\nA collaboration beer created for the Malmö beer and whisky festival in March. When deciding how best to celebrate this opportunity, we agreed to collaborate with one of Malmö''s own, Brygghuset Finn - an award winning brewery that works according to traditional craft methods combined with innovative engineering skills.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":77,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3.48},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.72},{"id":"f3","name":"Flaked Oat Malt","type":"grain","amountKg":0.48}],"hops":[{"id":"h1","name":"Chinook","amountG":1,"use":"boil","timeMin":10},{"id":"h2","name":"Chinook","amountG":10,"use":"boil","timeMin":0},{"id":"h3","name":"Amarillo","amountG":10,"use":"boil","timeMin":0},{"id":"h4","name":"Simcoe","amountG":10,"use":"boil","timeMin":0},{"id":"h5","name":"Mosaic","amountG":10,"use":"boil","timeMin":0},{"id":"h6","name":"Citra","amountG":50,"use":"dry_hop"},{"id":"h7","name":"Simcoe","amountG":50,"use":"dry_hop"},{"id":"h8","name":"Amarillo","amountG":50,"use":"dry_hop"},{"id":"h9","name":"Mosaic","amountG":50,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":81}],"miscs":[],"mashSteps":[],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.052,"fg":1.01,"ibu":30,"abvPct":5.5,"colorEbc":15},"notes":"Bryggetips: Don''t cool the beer too cold after fermentation or you will loose the haze, 3°C should do.\n\nTwist: Pectin Powder: 2g\n\nFørst brygget: 2019"}', '{"id":395,"name":"Two Way Street (BD vs Brygghuset Finn)","tagline":"New England IPA.","first_brewed":"2019","description":"A collaboration beer created for the Malmö beer and whisky festival in March. When deciding how best to celebrate this opportunity, we agreed to collaborate with one of Malmö''s own, Brygghuset Finn - an award winning brewery that works according to traditional craft methods combined with innovative engineering skills.","image":"395.png","abv":5.5,"ibu":30,"target_fg":1010,"target_og":1052,"ebc":15,"srm":8,"ph":4.2,"attenuation_level":81,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":0,"unit":"celsius"},"duration":15}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Pectin Powder: 2g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3.48,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.72,"unit":"kilograms"}},{"name":"Flaked Oat Malt ","amount":{"value":0.48,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":1,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Chinook","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Scallops with Apricot Salsa","Lemon Thyme Roasted Chicken","Raspberry Cheesecake with Mango Sorbet"],"brewers_tips":"Don''t cool the beer too cold after fermentation or you will loose the haze, 3°C should do.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 har ingen gyldig temperatur i kilden; utelatt."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-396', 'diydog', '396', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/396.json', 'Fight Club', 'Transatlantic IPA.', 'ipa', 4.5, 15, 1.044, 1.009, 15, 20, 'fight club transatlantic ipa. ipa pale ale wheat malt flaked oat malt chinook ahtanum citra simcoe ahtanum citra simcoe wyeast 1272', '{"schemaVersion":1,"name":"Fight Club","style":"IPA","description":"Transatlantic IPA.\n\nBrewed to celebrate the world''s first craft beer airline, this beer is best enjoyed at altitude. As pale and hazy yellow as a transatlantic sunrise. Floral, citrus and freshly cut grass aromas fill the cabin. Orange, lemon and white grapes disembark in rapid succession, all resting on a malted fuselage. Sit back, relax and enjoy the Flight Club.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":80,"efficiencyPct":69,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3.6},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.6},{"id":"f3","name":"Flaked Oat Malt","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"Chinook","amountG":4,"use":"boil","timeMin":15},{"id":"h2","name":"Ahtanum","amountG":10,"use":"boil","timeMin":0},{"id":"h3","name":"Citra","amountG":10,"use":"boil","timeMin":0},{"id":"h4","name":"Simcoe","amountG":10,"use":"boil","timeMin":0},{"id":"h5","name":"Ahtanum","amountG":4,"use":"boil","timeMin":80},{"id":"h6","name":"Citra","amountG":3,"use":"boil","timeMin":60},{"id":"h7","name":"Simcoe","amountG":2,"use":"boil","timeMin":40}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":80}],"miscs":[],"mashSteps":[],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.044,"fg":1.009,"ibu":15,"abvPct":4.5,"colorEbc":15},"notes":"Bryggetips: Nothing harmful will happen if this beer is consumed at sea level.\n\nTwist: Pectin Powder: 5g, Wheat flour: 60g\n\nFørst brygget: 2019"}', '{"id":396,"name":"Fight Club","tagline":"Transatlantic IPA.","first_brewed":"2019","description":"Brewed to celebrate the world''s first craft beer airline, this beer is best enjoyed at altitude. As pale and hazy yellow as a transatlantic sunrise. Floral, citrus and freshly cut grass aromas fill the cabin. Orange, lemon and white grapes disembark in rapid succession, all resting on a malted fuselage. Sit back, relax and enjoy the Flight Club.","image":"396.png","abv":4.5,"ibu":15,"target_fg":1009,"target_og":1044,"ebc":15,"srm":8,"ph":4.2,"attenuation_level":80,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":0,"unit":"celsius"},"duration":16}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Pectin Powder: 5g, Wheat flour: 60g"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3.6,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"Chinook","amount":{"value":4,"unit":"grams"},"add":"15","attribute":"Flavour"},{"name":"Ahtanum","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Citra","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Ahtanum","amount":{"value":4,"unit":"grams"},"add":"80","attribute":"Dry Hop"},{"name":"Citra","amount":{"value":3,"unit":"grams"},"add":"60","attribute":"Dry Hop"},{"name":"Simcoe","amount":{"value":2,"unit":"grams"},"add":"40","attribute":"Dry Hop"}],"yeast":"Wyeast 1272"},"food_pairing":["Packet of Nuts","Bag of Crisps","Ham and Cheese Toastie"],"brewers_tips":"Nothing harmful will happen if this beer is consumed at sea level.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","Meskesteg 1 har ingen gyldig temperatur i kilden; utelatt."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-397', 'diydog', '397', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/397.json', 'Paradox Islay', 'Whisky Cask Aged.', 'other', 14, 40, 1.112, 1.015, 250, 20, 'paradox islay whisky cask aged. annet pale ale caramalt munich malt extra dark crystal malt carafa special type 1 carafa special type 3 flaked oat malt caramalt caramalt saaz hallertauer mittelfruh wyeast 1272', '{"schemaVersion":1,"name":"Paradox Islay","description":"Whisky Cask Aged.\n\nOur latest Paradox embraces time like no other. Aged in Islay casks from islands that cling to the edge of Scotland it can trace a lineage back ten thousand years. Underground, out of sight, but never out of mind, peat lies recumbent until called upon. The intense, smoky peated whiskies of our home nation are unique and inspiring - and they now give their flavour to our latest Paradox.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":75,"efficiencyPct":72,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":6.24},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.84},{"id":"f3","name":"Munich Malt","type":"grain","amountKg":0.48},{"id":"f4","name":"Extra Dark Crystal Malt","type":"grain","amountKg":0.84},{"id":"f5","name":"Carafa Special Type 1","type":"grain","amountKg":0.24},{"id":"f6","name":"Carafa Special Type 3","type":"grain","amountKg":0.24},{"id":"f7","name":"Flaked Oat Malt","type":"grain","amountKg":1.92}],"hops":[{"id":"h3","name":"Saaz","amountG":20,"use":"boil","timeMin":0},{"id":"h4","name":"Hallertauer Mittelfruh","amountG":20,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":87}],"miscs":[{"id":"x1","name":"Caramalt","amount":60,"unit":"g","use":"boil","timeMin":75},{"id":"x2","name":"Caramalt","amount":20,"unit":"g","use":"boil","timeMin":30}],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":115}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.112,"fg":1.015,"ibu":40,"abvPct":14,"colorEbc":250},"notes":"Bryggetips: The intensity of peated whiskies varies from mild to hardcore. When you choose a barrel or wood chips try to find out which whisky was stored in it. Get a sample of that whisky, taste it (that’s the best part) and decide if it will go well with the beer.\n\nTwist: Islay Whisky Soaked Oak Chips: 200g FV Addition\n\nFørst brygget: 2019"}', '{"id":397,"name":"Paradox Islay","tagline":"Whisky Cask Aged.","first_brewed":"2019","description":"Our latest Paradox embraces time like no other. Aged in Islay casks from islands that cling to the edge of Scotland it can trace a lineage back ten thousand years. Underground, out of sight, but never out of mind, peat lies recumbent until called upon. The intense, smoky peated whiskies of our home nation are unique and inspiring - and they now give their flavour to our latest Paradox.","image":"397.png","abv":14,"ibu":40,"target_fg":1015,"target_og":1112,"ebc":250,"srm":127,"ph":4.4,"attenuation_level":87,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":115}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Islay Whisky Soaked Oak Chips: 200g FV Addition"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":6.24,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.84,"unit":"kilograms"}},{"name":"Munich Malt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Extra Dark Crystal Malt","amount":{"value":0.84,"unit":"kilograms"}},{"name":"Carafa Special Type 1","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Carafa Special Type 3","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":1.92,"unit":"kilograms"}}],"hops":[{"name":"Caramalt","amount":{"value":60,"unit":"grams"},"add":"75","attribute":"Bitter"},{"name":"Caramalt","amount":{"value":20,"unit":"grams"},"add":"30","attribute":"Flavour"},{"name":"Saaz","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Flavour"},{"name":"Hallertauer Mittelfruh","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Strong Vintage Cheddar","Haggis","Dark Chili Chocolate"],"brewers_tips":"The intensity of peated whiskies varies from mild to hardcore. When you choose a barrel or wood chips try to find out which whisky was stored in it. Get a sample of that whisky, taste it (that’s the best part) and decide if it will go well with the beer.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
