INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-399', 'diydog', '399', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/399.json', 'Zombie Cake', 'Chocolate Praline Porter.', 'stout', 5, 25, 1.062, 1.02, 90, 20, 'zombie cake chocolate praline porter. stout og porter pale ale caramalt simpsons t50 brown malt carafa special type 3 amarillo bramling cross amarillo wyeast 1272', '{"schemaVersion":1,"name":"Zombie Cake","style":"Stout og porter","description":"Chocolate Praline Porter.\n\nDark forces are at work in this devilishly good Praline Porter. Toffee and chocolate unite and come a-knocking. Open up to layers of smooth roasty character, with notes of vanilla, mellow coffee and a subtle nuttiness. And a bittersweet cliff-hanger finale. Zombie Cake - Bittersweet, engaging and rewarding.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":87,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3.12},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.84},{"id":"f3","name":"Simpsons T50","type":"grain","amountKg":0.36},{"id":"f4","name":"Brown Malt","type":"grain","amountKg":0.48},{"id":"f5","name":"Carafa Special Type 3","type":"grain","amountKg":0.12}],"hops":[{"id":"h1","name":"Amarillo","amountG":6,"use":"boil","timeMin":60},{"id":"h2","name":"Bramling Cross","amountG":20,"use":"boil","timeMin":30},{"id":"h3","name":"Amarillo","amountG":4,"use":"boil","timeMin":30}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":68}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":45}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.062,"fg":1.02,"ibu":25,"abvPct":5,"colorEbc":90},"notes":"Bryggetips: Add the honey close to the end of the whirlpool to ensure the aroma stays in the beer.\n\nTwist: Vanilla Extract: 65g FV Addition, Milk Sugars (Lactose): 360g, Honey: 240g Whirlpool\n\nFørst brygget: 2019"}', '{"id":399,"name":"Zombie Cake","tagline":"Chocolate Praline Porter.","first_brewed":"2019","description":"Dark forces are at work in this devilishly good Praline Porter. Toffee and chocolate unite and come a-knocking. Open up to layers of smooth roasty character, with notes of vanilla, mellow coffee and a subtle nuttiness. And a bittersweet cliff-hanger finale. Zombie Cake - Bittersweet, engaging and rewarding.","image":"399.png","abv":5,"ibu":25,"target_fg":1020,"target_og":1062,"ebc":90,"srm":46,"ph":4.2,"attenuation_level":68,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":45}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Vanilla Extract: 65g FV Addition, Milk Sugars (Lactose): 360g, Honey: 240g Whirlpool"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3.12,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.84,"unit":"kilograms"}},{"name":"Simpsons T50","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Brown Malt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Carafa Special Type 3","amount":{"value":0.12,"unit":"kilograms"}}],"hops":[{"name":"Amarillo","amount":{"value":6,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Bramling Cross","amount":{"value":20,"unit":"grams"},"add":"30","attribute":"Flavour"},{"name":"Amarillo","amount":{"value":4,"unit":"grams"},"add":"30","attribute":"Flavour"}],"yeast":"Wyeast 1272"},"food_pairing":["Mimolette","Almond Milk Pudding","Pumpkin Cheesecake"],"brewers_tips":"Add the honey close to the end of the whirlpool to ensure the aroma stays in the beer.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-400', 'diydog', '400', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/400.json', 'Dog H', '12th Anniversary Imperial Stout.', 'stout', 15.5, 90, 1.12, 1.02, 300, 20, 'dog h 12th anniversary imperial stout. stout og porter pale ale wheat malt extra dark crystal malt chocolate wheat brown malt rye malt flaked oat malt simcoe fuggles fuggles wyeast 1272', '{"schemaVersion":1,"name":"Dog H","style":"Stout og porter","description":"12th Anniversary Imperial Stout.\n\nDog H is our liquid milestone, brewed to celebrate our twelfth anniversary. So what else could we do but turn it up to that number?","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":75,"efficiencyPct":68,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":7.68},{"id":"f2","name":"Wheat Malt","type":"grain","amountKg":0.96},{"id":"f3","name":"Extra Dark Crystal Malt","type":"grain","amountKg":0.84},{"id":"f4","name":"Chocolate Wheat","type":"grain","amountKg":0.6},{"id":"f5","name":"Brown Malt","type":"grain","amountKg":0.6},{"id":"f6","name":"Rye Malt","type":"grain","amountKg":0.48},{"id":"f7","name":"Flaked Oat Malt","type":"grain","amountKg":0.96}],"hops":[{"id":"h1","name":"Simcoe","amountG":40,"use":"boil","timeMin":75},{"id":"h2","name":"Fuggles","amountG":20,"use":"boil","timeMin":0},{"id":"h3","name":"Fuggles","amountG":20,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":83}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":115}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.12,"fg":1.02,"ibu":90,"abvPct":15.5,"colorEbc":300},"notes":"Bryggetips: For this beer to be successful a few key points need to be followed. The first is picking the correct yeast strain, one that is known to be able to have high alcohol tolerance. The second is that by starting the brew with all the sugar necessary to gain +12% beers subjects the yeast to high osmotic stress and will hinder fermentation, so it is best to start with wort just over 1.100. And finally once fermentation has decreased and moving approximately 1SG point per 24hrs, it is time to start adding dextrose to achieve target ABV.\n\nTwist: Dextrose: 1.2kg Dry Hop, Coffee: 40g Dry Hop, Cocoa Nibs: 40g Dry Hop, Habanero Powder: 1g Dry Hop, Cognac Soaked Oak Chips: 200g FV Addition\n\nFørst brygget: 2019"}', '{"id":400,"name":"Dog H","tagline":"12th Anniversary Imperial Stout.","first_brewed":"2019","description":"Dog H is our liquid milestone, brewed to celebrate our twelfth anniversary. So what else could we do but turn it up to that number?","image":"400.png","abv":15.5,"ibu":90,"target_fg":1020,"target_og":1120,"ebc":300,"srm":152,"ph":4.2,"attenuation_level":83,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":115}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Dextrose: 1.2kg Dry Hop, Coffee: 40g Dry Hop, Cocoa Nibs: 40g Dry Hop, Habanero Powder: 1g Dry Hop, Cognac Soaked Oak Chips: 200g FV Addition"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":7.68,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.96,"unit":"kilograms"}},{"name":"Extra Dark Crystal Malt","amount":{"value":0.84,"unit":"kilograms"}},{"name":"Chocolate Wheat","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Brown Malt","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Rye Malt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.96,"unit":"kilograms"}}],"hops":[{"name":"Simcoe","amount":{"value":40,"unit":"grams"},"add":"75","attribute":"Bitter"},{"name":"Fuggles","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Bitter"},{"name":"Fuggles","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Roquefort","Venison and Mushroom Stroganoff","Orange Dark Chocolate"],"brewers_tips":"For this beer to be successful a few key points need to be followed. The first is picking the correct yeast strain, one that is known to be able to have high alcohol tolerance. The second is that by starting the brew with all the sugar necessary to gain +12% beers subjects the yeast to high osmotic stress and will hinder fermentation, so it is best to start with wort just over 1.100. And finally once fermentation has decreased and moving approximately 1SG point per 24hrs, it is time to start adding dextrose to achieve target ABV.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger.","OG/FG i kilden gir 13.1 % ABV, men oppgitt ABV er 15.5 % — sjekk tallene.","12.1 kg malt til 20 L er urealistisk — trolig en feil i kilden."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-401', 'diydog', '401', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/401.json', 'Mangopolis', 'Mango Brut IPA.', 'ipa', 6, 20, 1.05, 1.003, 9, 20, 'mangopolis mango brut ipa. ipa pilsner malt hallertauer taurus saphir saphir aurora mosaic wyeast 1272', '{"schemaVersion":1,"name":"Mangopolis","style":"IPA","description":"Mango Brut IPA.\n\nA sophisticated Brut. Pours vibrant pale yellowy-orange. Tropical fruit on the nose. Lemon citrus, white grapes and floral notes with a big juicy mango hit and a deft touch of spice. Delivered Sahara dry with champagne like effervescence.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":87,"fermentables":[{"id":"f1","name":"Pilsner Malt","type":"grain","amountKg":3.96}],"hops":[{"id":"h1","name":"Hallertauer Taurus","amountG":5,"use":"boil","timeMin":70},{"id":"h2","name":"Saphir","amountG":30,"use":"boil","timeMin":0},{"id":"h3","name":"Saphir","amountG":40,"use":"dry_hop"},{"id":"h4","name":"Aurora","amountG":80,"use":"dry_hop"},{"id":"h5","name":"Mosaic","amountG":40,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":94}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":90}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.05,"fg":1.003,"ibu":20,"abvPct":6,"colorEbc":9},"notes":"Bryggetips: Dextrose is used to reach a very high attenuation in order to get that dry feeling.\n\nTwist: Mango Concentrate: 360g, Amyloglucosidase: 1g, Dextrose: 240g\n\nFørst brygget: 2019"}', '{"id":401,"name":"Mangopolis","tagline":"Mango Brut IPA.","first_brewed":"2019","description":"A sophisticated Brut. Pours vibrant pale yellowy-orange. Tropical fruit on the nose. Lemon citrus, white grapes and floral notes with a big juicy mango hit and a deft touch of spice. Delivered Sahara dry with champagne like effervescence.","image":"401.png","abv":6,"ibu":20,"target_fg":1003,"target_og":1050,"ebc":9,"srm":5,"ph":4.4,"attenuation_level":94,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":90}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":"Mango Concentrate: 360g, Amyloglucosidase: 1g, Dextrose: 240g"},"ingredients":{"malt":[{"name":"Pilsner Malt","amount":{"value":3.96,"unit":"kilograms"}}],"hops":[{"name":"Hallertauer Taurus","amount":{"value":5,"unit":"grams"},"add":"70","attribute":"Bitter"},{"name":"Saphir","amount":{"value":30,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Saphir","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Aurora","amount":{"value":80,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Mosaic","amount":{"value":40,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Parmesan Baked Parsnips","Ceviche","Lime Sorbet"],"brewers_tips":"Dextrose is used to reach a very high attenuation in order to get that dry feeling.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-402', 'diydog', '402', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/402.json', 'Baltic Bandit', 'Baltic Porter.', 'stout', 6.5, 10, 1.06, 1.01, 145, 20, 'baltic bandit baltic porter. stout og porter pilsner malt vienna malt extra dark crystal malt amber malt chocolate wheat carafa special type 3 munich malt hallertauer taurus tettnang w34/70', '{"schemaVersion":1,"name":"Baltic Bandit","style":"Stout og porter","description":"Baltic Porter.\n\nSlip anchor and set sail with this silky smooth porter. Toffee and chocolate on the nose. Delivering a rich and chewy decadent cargo. Melted caramel and dark chocolate layer onto a rich dark oaky hull.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":60,"efficiencyPct":78,"fermentables":[{"id":"f1","name":"Pilsner Malt","type":"grain","amountKg":3},{"id":"f2","name":"Vienna Malt","type":"grain","amountKg":0.6},{"id":"f3","name":"Extra Dark Crystal Malt","type":"grain","amountKg":0.24},{"id":"f4","name":"Amber Malt","type":"grain","amountKg":0.48},{"id":"f5","name":"Chocolate Wheat","type":"grain","amountKg":0.36},{"id":"f6","name":"Carafa Special Type 3","type":"grain","amountKg":0.06},{"id":"f7","name":"Munich Malt","type":"grain","amountKg":0.6}],"hops":[{"id":"h1","name":"Hallertauer Taurus","amountG":10,"use":"boil","timeMin":60},{"id":"h2","name":"Tettnang","amountG":20,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"W34/70","form":"dry","amount":1,"unit":"pkg","attenuationPct":83}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":85}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":12}],"targets":{"og":1.06,"fg":1.01,"ibu":10,"abvPct":6.5,"colorEbc":145},"notes":"Bryggetips: Mash in at a higher temperature to leave more unfermentable sugars in the wort. This gives the beer a sweeter porter profile.\n\nTwist: French Oak Chips: 50g FV Addition\n\nFørst brygget: 2019"}', '{"id":402,"name":"Baltic Bandit","tagline":"Baltic Porter.","first_brewed":"2019","description":"Slip anchor and set sail with this silky smooth porter. Toffee and chocolate on the nose. Delivering a rich and chewy decadent cargo. Melted caramel and dark chocolate layer onto a rich dark oaky hull.","image":"402.png","abv":6.5,"ibu":10,"target_fg":1010,"target_og":1060,"ebc":145,"srm":74,"ph":4.4,"attenuation_level":83,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":85}],"fermentation":{"temp":{"value":12,"unit":"celsius"}},"twist":"French Oak Chips: 50g FV Addition"},"ingredients":{"malt":[{"name":"Pilsner Malt","amount":{"value":3,"unit":"kilograms"}},{"name":"Vienna Malt","amount":{"value":0.6,"unit":"kilograms"}},{"name":"Extra Dark Crystal Malt","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Amber Malt","amount":{"value":0.48,"unit":"kilograms"}},{"name":"Chocolate Wheat","amount":{"value":0.36,"unit":"kilograms"}},{"name":"Carafa Special Type 3","amount":{"value":0.06,"unit":"kilograms"}},{"name":"Munich Malt","amount":{"value":0.6,"unit":"kilograms"}}],"hops":[{"name":"Hallertauer Taurus","amount":{"value":10,"unit":"grams"},"add":"60","attribute":"Bitter"},{"name":"Tettnang","amount":{"value":20,"unit":"grams"},"add":"0","attribute":"Aroma"}],"yeast":"W34/70"},"food_pairing":["Spicy BBQ Seitan","Aged Gouda","Pecan Pie"],"brewers_tips":"Mash in at a higher temperature to leave more unfermentable sugars in the wort. This gives the beer a sweeter porter profile.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-403', 'diydog', '403', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/403.json', 'Transatlantic Telegram', 'New England West Coast IPA.', 'ipa', 8.5, 63, 1.085, 1.015, 18, 20, 'transatlantic telegram new england west coast ipa. ipa pale ale caramalt wheat malt munich malt flaked oat malt simcoe co2 extract columbus simcoe columbus simcoe cascade columbus simcoe cascade chinook amarillo columbus simcoe wyeast 1272', '{"schemaVersion":1,"name":"Transatlantic Telegram","style":"IPA","description":"New England West Coast IPA.\n\nPart of our brewer built series, showcasing beers designed and chosen by our brewers. This beer was created and crafted by Patrick Robb.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":75,"efficiencyPct":83,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":5.354},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.369},{"id":"f3","name":"Wheat Malt","type":"grain","amountKg":0.462},{"id":"f4","name":"Munich Malt","type":"grain","amountKg":0.369},{"id":"f5","name":"Flaked Oat Malt","type":"grain","amountKg":0.554}],"hops":[{"id":"h1","name":"Simcoe CO2 Extract","amountG":3,"use":"boil","timeMin":75},{"id":"h2","name":"Columbus","amountG":6,"use":"boil","timeMin":10},{"id":"h3","name":"Simcoe","amountG":6,"use":"boil","timeMin":10},{"id":"h4","name":"Columbus","amountG":15,"use":"boil","timeMin":0},{"id":"h5","name":"Simcoe","amountG":15,"use":"boil","timeMin":0},{"id":"h6","name":"Cascade","amountG":15,"use":"boil","timeMin":0},{"id":"h7","name":"Columbus","amountG":36,"use":"dry_hop"},{"id":"h8","name":"Simcoe","amountG":36,"use":"dry_hop"},{"id":"h9","name":"Cascade","amountG":36,"use":"dry_hop"},{"id":"h10","name":"Chinook","amountG":24,"use":"dry_hop"},{"id":"h11","name":"Amarillo","amountG":24,"use":"dry_hop"},{"id":"h12","name":"Columbus","amountG":36,"use":"dry_hop"},{"id":"h13","name":"Simcoe","amountG":36,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":82}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":55}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.085,"fg":1.015,"ibu":63,"abvPct":8.5,"colorEbc":18},"notes":"Bryggetips: This beer is meant to be hazy so no sweat!\n\nFørst brygget: 2019"}', '{"id":403,"name":"Transatlantic Telegram","tagline":"New England West Coast IPA.","first_brewed":"2019","description":"Part of our brewer built series, showcasing beers designed and chosen by our brewers. This beer was created and crafted by Patrick Robb.","image":"403.png","abv":8.5,"ibu":63,"target_fg":1015,"target_og":1085,"ebc":18,"srm":9,"ph":4.2,"attenuation_level":82,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":55}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":5.354,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.369,"unit":"kilograms"}},{"name":"Wheat Malt","amount":{"value":0.462,"unit":"kilograms"}},{"name":"Munich Malt","amount":{"value":0.369,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.554,"unit":"kilograms"}}],"hops":[{"name":"Simcoe CO2 Extract","amount":{"value":3,"unit":"grams"},"add":"75","attribute":"Bitter"},{"name":"Columbus","amount":{"value":6,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Simcoe","amount":{"value":6,"unit":"grams"},"add":"10","attribute":"Flavour"},{"name":"Columbus","amount":{"value":15,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":15,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Cascade","amount":{"value":15,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Columbus","amount":{"value":36,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":36,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Cascade","amount":{"value":36,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Chinook","amount":{"value":24,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Amarillo","amount":{"value":24,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Columbus","amount":{"value":36,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Simcoe","amount":{"value":36,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Lamb Kofta","Prawn Pad Thai","Mushroom Tacos"],"brewers_tips":"This beer is meant to be hazy so no sweat!","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-404', 'diydog', '404', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/404.json', 'Bounty Hunter (Fanzine)', 'Coconut Porter.', 'stout', 6.1, 25, 1.063, 1.016, 150, 20, 'bounty hunter (fanzine) coconut porter. stout og porter pale ale caramalt munich malt simpsons dark crystal malt brown malt chocolate malt special type 3 flaked oat malt east kent golding fuggles wyeast 1272', '{"schemaVersion":1,"name":"Bounty Hunter (Fanzine)","style":"Stout og porter","description":"Coconut Porter.\n\nPart of our brewer built series, showcasing beers designed and chosen by our brewers. This beer was created and crafted by Andrew Hamilton.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":76,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":4.08},{"id":"f2","name":"Caramalt","type":"grain","amountKg":0.3},{"id":"f3","name":"Munich Malt","type":"grain","amountKg":0.24},{"id":"f4","name":"Simpsons Dark Crystal Malt","type":"grain","amountKg":0.3},{"id":"f5","name":"Brown Malt","type":"grain","amountKg":0.18},{"id":"f6","name":"Chocolate Malt","type":"grain","amountKg":0.18},{"id":"f7","name":"Special Type 3","type":"grain","amountKg":0.18},{"id":"f8","name":"Flaked Oat Malt","type":"grain","amountKg":0.24}],"hops":[{"id":"h1","name":"East Kent Golding","amountG":10,"use":"boil","timeMin":70},{"id":"h2","name":"Fuggles","amountG":20,"use":"boil","timeMin":10}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":75}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":64,"durationMin":45}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":21}],"targets":{"og":1.063,"fg":1.016,"ibu":25,"abvPct":6.1,"colorEbc":150},"notes":"Bryggetips: The key is to use toasted coconut, toasting it will help bring out the flavour and sanitize it. Spread the coconut on a baking sheet and place it in the oven until the coconut starts to turn golden brown at the ends. Then place it in a muslin bag and steep it in the cold conditioning phase until you get the desired flavour. A few days should do.\n\nTwist: Coconut Extract: 2g FV Addition\n\nFørst brygget: 2019"}', '{"id":404,"name":"Bounty Hunter (Fanzine)","tagline":"Coconut Porter.","first_brewed":"2019","description":"Part of our brewer built series, showcasing beers designed and chosen by our brewers. This beer was created and crafted by Andrew Hamilton.","image":"404.png","abv":6.1,"ibu":25,"target_fg":1016,"target_og":1063,"ebc":150,"srm":76,"ph":4.3,"attenuation_level":75,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":64,"unit":"celsius"},"duration":45}],"fermentation":{"temp":{"value":21,"unit":"celsius"}},"twist":"Coconut Extract: 2g FV Addition"},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":4.08,"unit":"kilograms"}},{"name":"Caramalt","amount":{"value":0.3,"unit":"kilograms"}},{"name":"Munich Malt","amount":{"value":0.24,"unit":"kilograms"}},{"name":"Simpsons Dark Crystal Malt","amount":{"value":0.3,"unit":"kilograms"}},{"name":"Brown Malt","amount":{"value":0.18,"unit":"kilograms"}},{"name":"Chocolate Malt","amount":{"value":0.18,"unit":"kilograms"}},{"name":"Special Type 3","amount":{"value":0.18,"unit":"kilograms"}},{"name":"Flaked Oat Malt","amount":{"value":0.24,"unit":"kilograms"}}],"hops":[{"name":"East Kent Golding","amount":{"value":10,"unit":"grams"},"add":"70","attribute":"Bitter"},{"name":"Fuggles","amount":{"value":20,"unit":"grams"},"add":"10","attribute":"Flavour"}],"yeast":"Wyeast 1272"},"food_pairing":["Thai Fishcakes","Beef Rendang","Coconut Flour Blueberry Pancakes"],"brewers_tips":"The key is to use toasted coconut, toasting it will help bring out the flavour and sanitize it. Spread the coconut on a baking sheet and place it in the oven until the coconut starts to turn golden brown at the ends. Then place it in a muslin bag and steep it in the cold conditioning phase until you get the desired flavour. A few days should do.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-405', 'diydog', '405', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/405.json', 'Prime Time', 'Euro-Hopped Session IPA.', 'ipa', 4, 40, 1.04, 1.01, 10, 20, 'prime time euro-hopped session ipa. ipa pale ale hallertauer taurus hallertauer blanc hallertauer blanc huell melon ariana hallertauer blanc huell melon ariana wyeast 1272', '{"schemaVersion":1,"name":"Prime Time","style":"IPA","description":"Euro-Hopped Session IPA.\n\nPart of our brewer built series, showcasing beers designed and chosen by our brewers. This beer was created and crafted by Pietro Maltinti.","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":70,"efficiencyPct":79,"fermentables":[{"id":"f1","name":"Pale Ale","type":"grain","amountKg":3.48}],"hops":[{"id":"h1","name":"Hallertauer Taurus","amountG":7,"use":"boil","timeMin":70},{"id":"h2","name":"Hallertauer Blanc","amountG":10,"use":"boil","timeMin":30},{"id":"h3","name":"Hallertauer Blanc","amountG":10,"use":"boil","timeMin":0},{"id":"h4","name":"Huell Melon","amountG":10,"use":"boil","timeMin":0},{"id":"h5","name":"Ariana","amountG":10,"use":"boil","timeMin":0},{"id":"h6","name":"Hallertauer Blanc","amountG":50,"use":"dry_hop"},{"id":"h7","name":"Huell Melon","amountG":50,"use":"dry_hop"},{"id":"h8","name":"Ariana","amountG":50,"use":"dry_hop"}],"cultures":[{"id":"y1","name":"Wyeast 1272","form":"liquid","amount":1,"unit":"pkg","attenuationPct":75}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":45}],"fermentationSteps":[{"id":"fs1","name":"Primærgjæring","temperatureC":19}],"targets":{"og":1.04,"fg":1.01,"ibu":40,"abvPct":4,"colorEbc":10},"notes":"Bryggetips: Because you''re using a new generation of German hops (which age very quickly), the key for having very intense, pleasant aroma is to use very fresh hops, or your result can be disappointing.\n\nFørst brygget: 2019"}', '{"id":405,"name":"Prime Time","tagline":"Euro-Hopped Session IPA.","first_brewed":"2019","description":"Part of our brewer built series, showcasing beers designed and chosen by our brewers. This beer was created and crafted by Pietro Maltinti.","image":"405.png","abv":4,"ibu":40,"target_fg":1010,"target_og":1040,"ebc":10,"srm":5,"ph":4.6,"attenuation_level":75,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":45}],"fermentation":{"temp":{"value":19,"unit":"celsius"}},"twist":null},"ingredients":{"malt":[{"name":"Pale Ale","amount":{"value":3.48,"unit":"kilograms"}}],"hops":[{"name":"Hallertauer Taurus","amount":{"value":7,"unit":"grams"},"add":"70","attribute":"Bitter"},{"name":"Hallertauer Blanc","amount":{"value":10,"unit":"grams"},"add":"30","attribute":"Flavour"},{"name":"Hallertauer Blanc","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Huell Melon","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Ariana","amount":{"value":10,"unit":"grams"},"add":"0","attribute":"Aroma"},{"name":"Hallertauer Blanc","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Huell Melon","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"},{"name":"Ariana","amount":{"value":50,"unit":"grams"},"add":"Dry Hop","attribute":"Aroma"}],"yeast":"Wyeast 1272"},"food_pairing":["Roasted Red Pepper Hummus","Garlic and Rosemary Focaccia","Chicken Salad"],"brewers_tips":"Because you''re using a new generation of German hops (which age very quickly), the key for having very intense, pleasant aroma is to use very fresh hops, or your result can be disappointing.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Kilden oppgir ikke alfasyre. IBU vises fra oppskriftens mål; legg inn alfasyre for egne beregninger."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-406', 'diydog', '406', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/406.json', 'Cosmic Crush Cherry', 'Scottish Sour Ale.', 'sour', 5.8, 15, 1.058, 1.004, 15, 20, 'cosmic crush cherry scottish sour ale. surøl weyernmann pils wheat flaked oats magnum h. blanc h. mittelfruh house brett blend', '{"schemaVersion":1,"name":"Cosmic Crush Cherry","style":"Surøl","description":"Scottish Sour Ale.\n\nCosmic Crush is Overworks year round available sour beer range focusing on single fruit additions. This one''s cherry!","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":90,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Weyernmann Pils","type":"grain","amountKg":1.9},{"id":"f2","name":"Wheat","type":"grain","amountKg":1.2},{"id":"f3","name":"Flaked Oats","type":"grain","amountKg":0.3}],"hops":[{"id":"h1","name":"Magnum","amountG":1.5,"alphaPct":14,"use":"boil","timeMin":90},{"id":"h2","name":"H. Blanc","amountG":7,"alphaPct":10,"use":"boil","timeMin":0},{"id":"h3","name":"H. Mittelfruh","amountG":4,"alphaPct":3,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"House Brett Blend","form":"other","amount":1,"unit":"pkg"}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":55}],"fermentationSteps":[],"targets":{"og":1.058,"fg":1.004,"ibu":15,"abvPct":5.8,"colorEbc":15},"notes":"Bryggetips: It is best to remove the stems and stones from the cherries to avoid spicy flavours, allowing the bright fruit character to shine through.\n\nTwist: Cherry Juice: 1.1kg, Sour Cherries: 1.7kg\n\nFørst brygget: 2018"}', '{"id":406,"name":"Cosmic Crush Cherry","tagline":"Scottish Sour Ale.","first_brewed":"2018","description":"Cosmic Crush is Overworks year round available sour beer range focusing on single fruit additions. This one''s cherry!","image":"406.png","abv":5.8,"ibu":15,"target_fg":1004,"target_og":1058,"ebc":15,"srm":null,"ph":null,"attenuation_level":null,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":55}],"fermentation":{"temp":{"value":null,"unit":"celsius"}},"twist":"Cherry Juice: 1.1kg, Sour Cherries: 1.7kg"},"ingredients":{"malt":[{"name":"Weyernmann Pils","amount":{"value":1.9,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":1.2,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.3,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":1.5,"unit":"grams"},"add":"90","attribute":"14% Alpha"},{"name":"H. Blanc","amount":{"value":7,"unit":"grams"},"add":"Flame Out","attribute":"10% Alpha"},{"name":"H. Mittelfruh","amount":{"value":4,"unit":"grams"},"add":"Flame Out","attribute":"3% Alpha"}],"yeast":"House Brett Blend"},"food_pairing":["Ogleshield Jersey Cows Milk Cheese","Cherry Cheesecake","Seared Duck Breast"],"brewers_tips":"It is best to remove the stems and stones from the cherries to avoid spicy flavours, allowing the bright fruit character to shine through.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Malt og OG i kilden gir 118 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %."]', 1790238832282);
INSERT OR REPLACE INTO recipe_library (id, source, source_ref, source_url, name, tagline, category, abv, ibu, og, fg, ebc, batch_size_l, search_text, data, source_data, warnings, imported_at) VALUES ('diydog-407', 'diydog', '407', 'https://github.com/alxiw/punkapi/blob/86bfa446c0fd69b49e291dbe6bd8e5080597b53d/data/407.json', 'Cosmic Crush Quince', 'Scottish Sour Ale.', 'sour', 5.8, 15, 1.058, 1.004, 15, 20, 'cosmic crush quince scottish sour ale. surøl weyernmann pils wheat flaked oats magnum h. blanc h. mittelfruh house brett blend', '{"schemaVersion":1,"name":"Cosmic Crush Quince","style":"Surøl","description":"Scottish Sour Ale.\n\nCosmic Crush is Overworks year round available sour beer range focusing on single fruit additions. This one''s quince!","author":"BrewDog (DIY Dog)","batchSizeL":20,"boilTimeMin":90,"efficiencyPct":75,"fermentables":[{"id":"f1","name":"Weyernmann Pils","type":"grain","amountKg":1.9},{"id":"f2","name":"Wheat","type":"grain","amountKg":1.2},{"id":"f3","name":"Flaked Oats","type":"grain","amountKg":0.3}],"hops":[{"id":"h1","name":"Magnum","amountG":1.9,"alphaPct":14,"use":"boil","timeMin":90},{"id":"h2","name":"H. Blanc","amountG":1.2,"alphaPct":10,"use":"boil","timeMin":0},{"id":"h3","name":"H. Mittelfruh","amountG":0.3,"alphaPct":3,"use":"boil","timeMin":0}],"cultures":[{"id":"y1","name":"House Brett Blend","form":"other","amount":1,"unit":"pkg"}],"miscs":[],"mashSteps":[{"id":"ms1","name":"Mesk","temperatureC":65,"durationMin":55}],"fermentationSteps":[],"targets":{"og":1.058,"fg":1.004,"ibu":15,"abvPct":5.8,"colorEbc":15},"notes":"Bryggetips: Freezing and thawing the fruit before adding it to the beer will rupture the cell walls, enabling more of the fruit character to develop within the beer.\n\nTwist: Quince Puree: 700g\n\nFørst brygget: 2018"}', '{"id":407,"name":"Cosmic Crush Quince","tagline":"Scottish Sour Ale.","first_brewed":"2018","description":"Cosmic Crush is Overworks year round available sour beer range focusing on single fruit additions. This one''s quince!","image":"407.png","abv":5.8,"ibu":15,"target_fg":1004,"target_og":1058,"ebc":15,"srm":null,"ph":null,"attenuation_level":null,"volume":{"value":20,"unit":"litres"},"boil_volume":{"value":25,"unit":"litres"},"method":{"mash_temp":[{"temp":{"value":65,"unit":"celsius"},"duration":55}],"fermentation":{"temp":{"value":null,"unit":"celsius"}},"twist":"Quince Puree: 700g"},"ingredients":{"malt":[{"name":"Weyernmann Pils","amount":{"value":1.9,"unit":"kilograms"}},{"name":"Wheat","amount":{"value":1.2,"unit":"kilograms"}},{"name":"Flaked Oats","amount":{"value":0.3,"unit":"kilograms"}}],"hops":[{"name":"Magnum","amount":{"value":1.9,"unit":"grams"},"add":"90","attribute":"14% Alpha"},{"name":"H. Blanc","amount":{"value":1.2,"unit":"grams"},"add":"Flame Out","attribute":"10% Alpha"},{"name":"H. Mittelfruh","amount":{"value":0.3,"unit":"grams"},"add":"Flame Out","attribute":"3% Alpha"}],"yeast":"House Brett Blend"},"food_pairing":["Chili and Tomato Soup","Red Wine and Spice Poached Quince with Mascarpone","Goats Cheese Tart with caramelized Onions"],"brewers_tips":"Freezing and thawing the fruit before adding it to the beer will rupture the cell walls, enabling more of the fruit character to develop within the beer.","contributed_by":"Alexander Ivanovsky <alxiw>"}', '["Malt og OG i kilden gir 118 % effektivitet, som ikke er realistisk — trolig en feil i kilden. Bruker 75 %."]', 1790238832282);
